/**
 * @packageDocumentation
 *
 * JS-engine `InjectedBackend` — the OPT-IN soft-fallback for
 * {@link loadAuthoritativeWasm}/{@link createCauslWasm} when the caller
 * passes `{ fallbackToJs: true }` AND the wasm artefact/snippet cannot be
 * resolved or instantiated.
 *
 * The DEFAULT for an explicit wasm request is **throw-loud** (a consumer
 * that asked for wasm must never silently run on JS). This backend exists
 * only so a caller who has EXPLICITLY opted into the soft path still gets
 * a fully-working engine — backed by the pure-TS `createCausl()` graph —
 * rather than a hard failure.
 *
 * It realises the {@link InjectedBackend} structural contract by wrapping
 * a private `createCausl()` graph: `registerInput` / `registerDerived`
 * mint TS handles keyed by the adopter's `NodeId`, and
 * `commit`/`read`/`subscribe` route through those handles. The semantics
 * are the canonical TS-engine semantics — the same engine
 * `createCausl()` returns by default — so the fallback is correct, just
 * NOT wasm.
 *
 * @internal
 */

import type {
  Commit,
  CreateCauslOptions,
  Graph,
  GraphTime,
  InputNode,
  Node,
  NodeId,
  Observer,
  Unsubscribe,
} from '../src/types.js'
import type { InjectedBackend } from '../src/types.js'
// CUT (epic #31 / issue #34) — `createCauslTs` is no longer re-exported from
// the PUBLIC `@causl/core` barrel, so this internal backend imports it from
// `../src/graph.js` directly. The JS fallback wraps the TS floor by
// definition (see the `#graph` note below).
import { createCauslTs } from '../src/graph.js'

/**
 * A JS-engine implementation of {@link InjectedBackend}. Constructed by
 * the loader ONLY on the opt-in `{ fallbackToJs: true }` path.
 *
 * ISSUE #150 — reconciled with the `AuthoritativeWasmEngine` surface it
 * substitutes for so a degrading adopter sees the SAME registration /
 * commit / subscribe SEMANTICS as the wasm engine, and the wrapped graph is
 * built with the adopter's construction options (not a bare default):
 *
 *   - the wrapped `#graph` receives the caller's {@link CreateCauslOptions}
 *     (name / retention caps / observer-error hook), mirroring the retention
 *     caps + graph name the real backend threads into its engine;
 *   - {@link commit} MINTS an input for a write to an unregistered id
 *     (matching the wasm engine's lazy slot allocation), instead of throwing;
 *   - {@link subscribe} DORMANT-registers an observer for an unregistered id
 *     (matching the wasm engine, which tolerates it), instead of throwing.
 *
 * The remaining listed asymmetries are deliberately left as-is because the
 * TS-floor wrapper is ALREADY contract-faithful for them: duplicate
 * `registerInput` / `registerDerived` never reach this backend (the wrapped
 * TS engine rejects a duplicate declaration upstream, and the wasm engine's
 * self-re-registration on a §10.3 dynamic-dep rewire is engine-internal — the
 * TS floor tracks the widened dep set NATIVELY, so the facade never re-drives
 * it); and the `deps` list is intentionally advisory rather than enforced,
 * because the wasm engine likewise ADMITS reads beyond the initial declared
 * set (it rewires, causl-client#103) rather than rejecting them — the TS
 * floor's native read-tracking is the same tolerance.
 */
export class JsFallbackBackend implements InjectedBackend {
  // A plain TS engine — the §18A value-of-record floor. Built with
  // `createCauslTs` (NOT `createCausl`): post-FLIP (epic #31 / issue #33)
  // `createCausl()` routes to the wasm engine when a module is preloaded, so a
  // `createCausl()` here — inside the wasm subpath, which is only loaded once a
  // wasm path is in play — would re-enter the wasm factory and recurse. This
  // fallback wraps the TS floor by definition.
  readonly #graph: Graph
  readonly #inputs = new Map<NodeId, InputNode<unknown>>()
  readonly #deriveds = new Map<NodeId, Node<unknown>>()
  // #150 — dormant observers subscribed to a not-yet-registered id. The wasm
  // engine tolerates a subscribe to an unregistered node (it records the
  // observer without arming a Phase-G fire); we mirror that inert tolerance
  // rather than throwing. Kept so the returned unsubscribe stays correct and
  // the set does not leak.
  readonly #dormant = new Map<NodeId, Set<Observer<unknown>>>()

  /**
   * @param options adopter construction options threaded into the wrapped TS
   *  engine — the retention caps / graph name / observer-error hook the real
   *  {@link import('./authoritative.js').AuthoritativeWasmEngine} would carry.
   *  `name` defaults to the fallback marker when the caller supplies none.
   */
  constructor(options: CreateCauslOptions = {}) {
    this.#graph = createCauslTs({ name: 'causl.wasm.js-fallback', ...options })
  }

  get now(): GraphTime {
    return this.#graph.now
  }

  has(id: NodeId): boolean {
    return this.#inputs.has(id) || this.#deriveds.has(id)
  }

  registerInput(id: NodeId, initial?: unknown): void {
    if (this.has(id)) return
    this.#inputs.set(id, this.#graph.input<unknown>(id, initial))
  }

  registerDerived(
    id: NodeId,
    deps: readonly NodeId[],
    compute: (get: (dep: NodeId) => unknown) => unknown,
  ): void {
    if (this.#deriveds.has(id)) return
    // Bridge the NodeId-keyed compute the contract declares onto the
    // handle-based `get` the TS engine drives. Deps are looked up by
    // NodeId in the input/derived registries (registered first, in
    // topological order — same discipline the wasm engine requires).
    const node = this.#graph.derived<unknown>(id, (get) =>
      compute((dep) => {
        const handle = this.#nodeFor(dep)
        return get(handle)
      }),
    )
    this.#deriveds.set(id, node)
  }

  commit(intent: string, writes: ReadonlyMap<NodeId, unknown>): Commit {
    // #150 — MINT an input for a write to an id that has never been registered,
    // matching the wasm engine (its commit path lazily slots an unregistered
    // write id via `#slotFor(id, true)`), instead of throwing. Done before the
    // tx opens so the freshly minted handle is set inside the same commit.
    for (const id of writes.keys()) {
      if (!this.#inputs.has(id)) this.registerInput(id)
    }
    return this.#graph.commit(intent, (tx) => {
      for (const [id, value] of writes) {
        // `#inputs.get(id)` is defined for every write id after the mint pass
        // above; a `undefined` here means the id is a DERIVED (writing a
        // derived is illegal on both engines), which the TS `tx.set` rejects.
        tx.set(this.#nodeForInput(id), value)
      }
    })
  }

  read(id: NodeId): unknown {
    return this.#graph.read(this.#nodeFor(id))
  }

  subscribe<T>(id: NodeId, observer: Observer<T>): Unsubscribe {
    const node = this.#inputs.get(id) ?? this.#deriveds.get(id)
    if (node !== undefined) {
      return this.#graph.subscribe(node as Node<T>, observer)
    }
    // #150 — DORMANT-register a subscribe to an unregistered id, matching the
    // wasm engine (it records the observer but never arms a Phase-G fire for a
    // node it has no slot for), instead of throwing. The observer stays inert;
    // the returned unsubscribe removes it from the dormant registry.
    const obs = observer as Observer<unknown>
    let set = this.#dormant.get(id)
    if (set === undefined) {
      set = new Set()
      this.#dormant.set(id, set)
    }
    set.add(obs)
    return () => {
      const s = this.#dormant.get(id)
      if (s !== undefined) {
        s.delete(obs)
        if (s.size === 0) this.#dormant.delete(id)
      }
    }
  }

  #nodeFor(id: NodeId): Node<unknown> {
    const node = this.#inputs.get(id) ?? this.#deriveds.get(id)
    if (node === undefined) {
      throw new Error(
        `JsFallbackBackend: no node registered for NodeId '${id}'.`,
      )
    }
    return node
  }

  #nodeForInput(id: NodeId): InputNode<unknown> {
    const node = this.#inputs.get(id)
    if (node === undefined) {
      throw new Error(
        `JsFallbackBackend.commit(): NodeId '${id}' is not a writable input.`,
      )
    }
    return node
  }
}
