/**
 * @packageDocumentation
 *
 * causl-client#129 (write-SSOT cutover) — the `graph.simulate` reroute BODY.
 *
 * Behind the fully-mirrored gate (rust-ssot + the causl/causl-core-rs#320
 * `simulate_commands` extern + no commit-metadata derived) the §5 dry-run no
 * longer runs the TS structural walk (Phases A–E over the TS cells + the
 * #105 mirrored-cell refresh): the engine runs the identical pipeline
 * against a discarded clone of its state and the client assembles the
 * `SimulateResult` from the decoded diff. This module hosts the reroute
 * closure so the main-bundle `createCausl` cell stays inside its SPEC
 * §14.2.2 budget — `graph.ts` supplies only the small
 * {@link SimulateRerouteContext} hook bag and delegates (the same
 * bundle-hygiene split the #129 commitLog window construction rode).
 *
 * ## Byte-identity with the TS dry-run (the pre-#129 wasm-path behaviour)
 *
 * - `stagedDiff` is reconstructed CLIENT-side with the exact TS floor
 *   semantics: the `#994` fast-path (no-dependent) rows first in
 *   first-write order with the Phase-A.5 revert filter, then the staged
 *   slow-path rows in first-write order with the Phase-B `Object.is`
 *   publish gate — both fire-gated by the #151 wire cutoff. The cutoff
 *   BASELINE re-sources from the authoritative backend (`#valueCache`,
 *   write-through on the commit path), which the live pipeline keeps
 *   byte-identical to the TS floor's cell. The fast/slow class flag is
 *   read AT WRITE TIME, mirroring the floor's classification moment.
 * - `derivedDiff` comes from the engine diff (the changed deriveds, in
 *   emission order — the same order the live commit publishes).
 * - the predicted `Commit.changedNodes` is `stagedDiff ⧺ derivedDiff`, the
 *   exact TS `simulate` assembly (`changed` insertion order).
 * - failed arms surface the SAME typed errors: a `run(tx)` throw is
 *   captured client-side before the engine is driven; an engine rejection
 *   re-inflates through the existing verdict classifier (`CycleError`, the
 *   host-identity `DerivedComputeError`) and lands on the `'failed'` arm
 *   with the client-computed `stagedDiff`.
 *
 * OBSERVER-INVISIBLE: the engine clone is discarded (no clock tick, no
 * retention, no commit-log row, zero Phase-G/H crossings — cw#320) and the
 * backend's mirror journals roll back unconditionally; TS-side, nothing is
 * ever staged onto the cells (the recording tx only collects writes), so
 * there is nothing to roll back.
 *
 * Re-entrancy is byte-identical to the TS `simulate`: the `committing`
 * guard throws the structural {@link CommitInProgressError} up front, and a
 * nested `commit` / `simulate` from inside the `run` callback is captured
 * onto the `'failed'` arm exactly as the TS catch arm does.
 */

import {
  CommitInProgressError,
  StaleTxError,
  WasmInstancePoisonedError,
} from '../src/errors.js'
import type {
  Commit,
  GraphTime,
  InputNode,
  NodeId,
  SimulateResult,
  SimulateRerouteContext,
  Tx,
} from '../src/types.js'

/**
 * Build the rerouted `graph.simulate` closure over the engine-closure hooks
 * (`ctx`) and the backend seams (`engineSimulate` — the cw#320 dry-run
 * entry; `readCommitted` — the `#valueCache`-first committed baseline).
 *
 * @internal
 */
export function buildSimulateRerouteImpl(
  ctx: SimulateRerouteContext,
  engineSimulate: (
    intent: string,
    writes: ReadonlyMap<NodeId, unknown>,
  ) => { readonly time: GraphTime; readonly changedNodes: readonly NodeId[] },
  readCommitted: (id: NodeId) => unknown,
): (intent: string, run: (tx: Tx) => void) => SimulateResult {
  return function simulateViaEngine(
    intent: string,
    run: (tx: Tx) => void,
  ): SimulateResult {
    if (ctx.isCommitting()) throw new CommitInProgressError()
    ctx.setCommitting(true)
    // Transient recording buffer — first-write order with in-place re-write
    // dedupe, mirroring the split-staged `tx.set` semantics WITHOUT
    // touching the cells or the per-entry sentinels. `rowFast[i]` captures
    // the #994 class flag at WRITE time (the floor's classification
    // moment).
    const rowIds: NodeId[] = []
    const rowValues: unknown[] = []
    const rowFast: boolean[] = []
    const rowIndex = new Map<NodeId, number>()
    // The FULL write map for the engine (every distinct id's last value,
    // first-write insertion order) — the same shape the live commit
    // facade's recording tx captures; the engine applies its own cutoffs.
    const writes = new Map<NodeId, unknown>()
    let txAlive = true
    const tx: Tx = {
      set<T>(node: InputNode<T>, value: T): void {
        if (!txAlive) throw new StaleTxError()
        // #165 — collapse `undefined` to `null` (the wire-NULL
        // value-domain decision), mirroring the live `tx.set`.
        if (value === undefined) value = null as T
        const id = (node as { readonly id: NodeId }).id
        const entry = ctx.resolveInputEntry(id)
        writes.set(id, value)
        const idx = rowIndex.get(id)
        if (idx !== undefined) {
          // Re-write within the same simulate — update in place (last
          // write wins), preserving the row's first-write position.
          rowValues[idx] = value
          return
        }
        // First tracked write: mirror the TS floor's staging skip — a
        // first write `Object.is`-equal to the COMMITTED value is not
        // tracked (both the #994 fast arm and the #972 slow arm skip it).
        // The committed baseline is the authoritative backend's value,
        // byte-identical to the TS cell the floor compares against.
        if (Object.is(readCommitted(id), value)) return
        rowIndex.set(id, rowIds.length)
        rowIds.push(id)
        rowValues.push(value)
        rowFast.push(!entry.hasDependents)
      },
    }

    const stagedDiff: NodeId[] = []
    let predicted:
      | { readonly time: GraphTime; readonly changedNodes: readonly NodeId[] }
      | null = null
    let predictedError: unknown = null
    try {
      run(tx)
      txAlive = false
      // Reconstruct the TS floor's fire-gated `changedInputIds` partition:
      // fast-path (#994 no-dependent) rows first (the Phase-A.5 walk
      // order), then slow-path rows (the Phase-B walk order), each in
      // first-write order. A row whose final value `Object.is`-reverted
      // to the committed baseline is dropped (the A.5 revert filter /
      // Phase-B publish gate), and the FIRE decision follows the #151
      // wire cutoff.
      for (let pass = 0; pass < 2; pass++) {
        const wantFast = pass === 0
        for (let i = 0; i < rowIds.length; i++) {
          if (rowFast[i] !== wantFast) continue
          const baseline = readCommitted(rowIds[i]!)
          const v = rowValues[i]
          if (Object.is(baseline, v)) continue
          if (ctx.inputValueChanged(baseline, v)) stagedDiff.push(rowIds[i]!)
        }
      }
      // Materialise any pending registrations so the dry-run's compute
      // crossings resolve settled upstream cells (parity with the live
      // commit facade, which flushes before driving the backend).
      ctx.flushSeed()
      predicted = engineSimulate(intent, writes)
    } catch (err) {
      // #127 — a poisoned instance is structural, not transactional: every
      // subsequent operation on this graph fails loud, and `simulate` must
      // not launder it onto the recoverable `'failed'` arm.
      if (err instanceof WasmInstancePoisonedError) {
        ctx.setCommitting(false)
        throw err
      }
      // Everything else — a `run(tx)` throw (including a nested
      // commit/simulate's `CommitInProgressError`), a predicted engine
      // rejection re-inflated by the verdict classifier (`CycleError`, the
      // host-identity `DerivedComputeError`) — surfaces on the `'failed'`
      // arm, exactly as the TS catch arm captures it.
      predictedError = err
    } finally {
      txAlive = false
      ctx.setCommitting(false)
    }

    if (predictedError === null && predicted !== null) {
      // Partition the engine's predicted change-set: the deriveds, in DIFF
      // emission order (the same order the live commit publishes). Inputs
      // are re-sourced from the client-side reconstruction above so the
      // published triple is byte-identical to the TS dry-run's.
      const derivedDiff: NodeId[] = []
      for (const id of predicted.changedNodes) {
        if (ctx.isDerived(id)) derivedDiff.push(id)
      }
      const changedNodes = [...stagedDiff, ...derivedDiff]
      const c: Commit = Object.freeze({
        time: predicted.time,
        intent,
        changedNodes: ctx.freezeIfDev(changedNodes) as readonly NodeId[],
        originatedAt: undefined,
      })
      return {
        status: 'clean',
        commit: c,
        stagedDiff: Object.freeze(stagedDiff.slice()) as readonly NodeId[],
        derivedDiff: Object.freeze(derivedDiff) as readonly NodeId[],
      }
    }
    return {
      status: 'failed',
      error: predictedError,
      stagedDiff: Object.freeze(stagedDiff.slice()) as readonly NodeId[],
    }
  }
}
