/**
 * @packageDocumentation
 *
 * Shared wire-format overflow trip-wires for the TS-side encoders
 * (`cmd-buf.ts`, `value-buf.ts`, `authoritative.ts`).
 *
 * The fixed-width count / length / size / id fields of the cmd-buf and
 * value-buf wire formats are `u8` / `u16` / `u32`. Historically the
 * encoders wrote them with a silent narrowing mask (`v & 0xff`,
 * `v >>> 0`) — an out-of-range value wrapped, silently corrupting the
 * record (a mis-correlated `intent_id`, a truncated `slot`, a wrong
 * `value_kind`) and surfacing — if at all — as an unrelated decode error
 * on the Rust side (a generic `PayloadLenMismatch`), never naming the
 * field that actually overflowed.
 *
 * This module replaces the silent mask with a LOUD, SPECIFIC throw: the
 * checked-write helpers below validate the value against its datatype cap
 * BEFORE writing and throw {@link WireFieldOverflowError} — naming the
 * field, the offending value, the datatype cap, the wire format, and the
 * record/op — instead of masking. For every IN-RANGE value the helpers
 * produce BYTE-IDENTICAL output to the prior `setUintN(off, v & MASK)` /
 * `setUintN(off, v >>> 0)` write, so every existing byte-identity fixture
 * and the cross-backend determinism gate stay green unchanged; they ONLY
 * add a throw on the out-of-range path that previously corrupted silently.
 *
 * See `.causl-bench-research/interop/WIRE-TRIPWIRE-DESIGN.md` for the
 * locked site inventory and the shared-guard design this implements.
 *
 * @internal Wire-level surface — adopters use the `WasmBackend` methods.
 */

/** `u8` datatype cap — the largest value a single wire byte can hold. */
export const U8_MAX = 0xff
/** `u16` datatype cap — the largest value a 2-byte LE wire word can hold. */
export const U16_MAX = 0xffff
/** `u32` datatype cap — the largest value a 4-byte LE wire word can hold. */
export const U32_MAX = 0xffffffff

/**
 * Thrown when a count / length / size / id destined for a fixed-width wire
 * field exceeds that field's datatype cap (or is not a non-negative
 * integer). Carries the field name, the offending value, the datatype
 * cap, the wire format, and the record/op so the failure is actionable —
 * never a generic truncation surfaced downstream.
 *
 * Extends `RangeError` (the value is out of the representable range) so
 * existing `instanceof RangeError` handlers still catch it.
 */
export class WireFieldOverflowError extends RangeError {
  override readonly name = 'WireFieldOverflowError'

  constructor(
    /** Fully-qualified field name, e.g. `'BEGIN_COMMIT::intent_id'`. */
    readonly field: string,
    /** The offending value that did not fit the field. */
    readonly value: number,
    /** Datatype cap the value busted (`0xff` / `0xffff` / `0xffffffff`). */
    readonly max: number,
    /** Wire format the field belongs to, e.g. `'cmd-buf'` / `'value-buf'`. */
    readonly format: string,
    /** Record/op or call-site context, e.g. `'REGISTER_DERIVED'`. */
    readonly context?: string,
  ) {
    super(
      `wire overflow: ${format} field "${field}" value ${value} ` +
        `exceeds ${max} (datatype cap)${context ? ` [${context}]` : ''}`,
    )
  }
}

/**
 * Throw {@link WireFieldOverflowError} when `v` is not a non-negative
 * integer within `[0, max]`. Cheap (a few comparisons) on the in-range
 * path; the throw path is cold.
 */
function checkRange(
  v: number,
  max: number,
  field: string,
  fmt: string,
  ctx?: string,
): void {
  if (!Number.isInteger(v) || v < 0 || v > max) {
    throw new WireFieldOverflowError(field, v, max, fmt, ctx)
  }
}

/**
 * Validate `v` against its `u8` cap, then `setUint8(off, v)`. For any
 * in-range `v` this is byte-identical to the prior `setUint8(off, v &
 * 0xff)`; an out-of-range `v` throws {@link WireFieldOverflowError}
 * instead of masking.
 */
export function writeU8Checked(
  view: DataView,
  off: number,
  v: number,
  field: string,
  ctx?: string,
  fmt = 'cmd-buf',
): void {
  checkRange(v, U8_MAX, field, fmt, ctx)
  view.setUint8(off, v)
}

/**
 * Validate `v` against its `u16` cap, then `setUint16(off, v, true)`
 * (little-endian). For any in-range `v` this is byte-identical to the
 * prior `setUint16(off, v, true)`; an out-of-range `v` throws
 * {@link WireFieldOverflowError} instead of masking.
 */
export function writeU16Checked(
  view: DataView,
  off: number,
  v: number,
  field: string,
  ctx?: string,
  fmt = 'cmd-buf',
): void {
  checkRange(v, U16_MAX, field, fmt, ctx)
  view.setUint16(off, v, true)
}

/**
 * Validate `v` against its `u32` cap, then `setUint32(off, v, true)`
 * (little-endian). For any in-range `v` this is byte-identical to the
 * prior `setUint32(off, v >>> 0, true)`; an out-of-range `v` throws
 * {@link WireFieldOverflowError} instead of truncating.
 */
export function writeU32Checked(
  view: DataView,
  off: number,
  v: number,
  field: string,
  ctx?: string,
  fmt = 'cmd-buf',
): void {
  checkRange(v, U32_MAX, field, fmt, ctx)
  view.setUint32(off, v, true)
}

/**
 * Validate a value destined for a wire field WITHOUT writing it — for the
 * intern-id case where the id is captured into a `bigint` inline payload
 * rather than written through a `DataView`. Throws
 * {@link WireFieldOverflowError} on overflow; returns `v` unchanged when
 * in range so it composes inline (`checkU32(id, field, fmt, ctx)`).
 */
export function checkU32(
  v: number,
  field: string,
  fmt = 'cmd-buf',
  ctx?: string,
): number {
  checkRange(v, U32_MAX, field, fmt, ctx)
  return v
}
