/**
 * @packageDocumentation
 *
 * TS-side decoders for the §12 read-side STRUCTURAL externs — the
 * Commit/Write Rust-SSOT cutover (causl/causl-core-rs#169, promote-read).
 *
 * Mirrors the Rust-side encoders in
 * `causl-wasm/tools/engine-rs-bridge/src/lib.rs`:
 *
 *   - {@link decodeNodeIdPairs} ← `encode_node_id_pairs` (ffi-1) — the
 *     identity-pair codec the `dependencies` / `dependents` externs return:
 *     `(slot u32, gen u32)` LE pairs, no header.
 *   - {@link decodeCommitLog} ← `encode_commit_log` (ffi-2) — the
 *     self-describing commit-log buffer: `commit_count u32 | per commit:
 *     12-byte interned intent value record | time u64 | changed_count u32 |
 *     changed[(slot u32, gen u32)…]`, oldest-first.
 *   - {@link decodeStats} ← `EngineStats::encode` (ffi-4) — the fixed-width
 *     telemetry buffer: `STATS_FIELD_COUNT (=7) × u32` LE counters in the
 *     `STATS_IDX_*` order.
 *
 * Each decoder takes a `(slot, gen) → NodeId` resolver (the engine's
 * `#slotToIdIndex`) so the wire-level generational handles project back
 * onto the canonical NodeId strings the JS facade returns. The intent
 * string of a commit-log record routes through the SAME 12-byte
 * value-record decoder the read path uses (a `STRING_ID` interned into the
 * shared bridge `INTERN_TABLE`).
 *
 * These decoders live on the `@causl/client-ts/wasm` subpath / authoritative
 * engine, NOT the main bundle — the #689 bundle-no-wasm-leak gate and the
 * §14.2 size gate stay green.
 *
 * @internal Wire-level surface — adopters use the `Graph` facade methods.
 */

import type { GraphTime, NodeId, RetentionResult } from '../src/types.js'
import type { TemporalLike } from './tagged-types.js'
import {
  CONTENT_HASH_FROM_CACHE,
  decodeValueRecord,
  VALUE_BUF_RECORD_LEN,
  type ValueBufBridge,
} from './value-buf.js'

/**
 * #139 — the typed error every STRUCTURAL decoder throws when the wire it is
 * handed does not match the record grammar it decodes: a record truncated
 * mid-field, OR a buffer whose length the decoder did not fully consume
 * (trailing bytes a version-skewed encoder appended a section this decoder
 * does not read). Both are encoder/decoder drift — a genuine wire-schema
 * mismatch that MUST fail loud rather than decode a silently-ignored prefix
 * or tail. Carries the byte offset the decode reached and the total buffer
 * length so a diagnostic can localise the drift.
 *
 * Extends `Error` (not `RangeError`) — the fault is a malformed/skewed wire,
 * not an out-of-range value. Branch on `instanceof StructuralDecodeError`.
 */
export class StructuralDecodeError extends Error {
  override readonly name = 'StructuralDecodeError'

  constructor(
    message: string,
    /** Byte offset the decode had reached when it detected the drift. */
    readonly offset: number,
    /** Total length of the buffer being decoded. */
    readonly bufferLength: number,
  ) {
    super(message)
  }
}

/**
 * #139 — debug-mode drop counter. Each STRUCTURAL decoder SILENTLY drops a
 * `(slot, gen)` identity pair the live slot→id index cannot resolve (a
 * disposed / stale-gen handle has no canonical NodeId). That silent drop is
 * correct for a live engine but masks genuine slot-table drift: a decoder
 * out of step with the encoder resolves NOTHING and drops the whole batch
 * with no signal. When debug mode is enabled the decoders tally every drop
 * into {@link structuralDecodeDropCount}, so a conformance test / diagnostic
 * can assert the drift is zero (or observe exactly how many pairs fell out).
 * Disabled by default: the counting is gated so the production hot path pays
 * nothing.
 */
let structuralDecodeDebugEnabled = false
let structuralDecodeDroppedPairs = 0

/**
 * #139 — enable/disable the debug-mode unresolved-pair drop counter.
 * Enabling resets the tally to zero so a test brackets a single decode.
 */
export function setStructuralDecodeDebug(enabled: boolean): void {
  structuralDecodeDebugEnabled = enabled
  if (enabled) structuralDecodeDroppedPairs = 0
}

/**
 * #139 — read the number of unresolved `(slot, gen)` pairs the decoders have
 * dropped since debug mode was last enabled. Always `0` when debug mode is
 * disabled (the drop sites do not count).
 */
export function structuralDecodeDropCount(): number {
  return structuralDecodeDroppedPairs
}

/**
 * #139 — tally one dropped unresolved pair when debug mode is on. Called at
 * every `resolve(...) === undefined` drop site — in these decoders AND in the
 * engine's Phase-G fire dispatch (`#onFire`), which drops a fired node whose
 * `(slot, gen)` the live slot→id index no longer resolves. A no-op (one
 * boolean test) on the production path.
 */
export function noteUnresolvedPairDrop(): void {
  if (structuralDecodeDebugEnabled) structuralDecodeDroppedPairs += 1
}

/**
 * ffi-1 — width of one `(slot u32, gen u32)` LE identity pair, mirroring
 * the Rust `NODE_ID_PAIR_LEN`. Distinct from {@link VALUE_BUF_RECORD_LEN}
 * (the 12-byte value channel) — an identity pair carries NO value.
 */
export const NODE_ID_PAIR_LEN = 8

/**
 * Detach-safety enforcement for the INTERLEAVING structural decoders (issue
 * causl/causl-client-ts#137).
 *
 * {@link decodeCommitLog}, {@link decodeExportModel}, and
 * {@link decodeCommitRecord} re-enter the wasm bridge — `read_interned_string`
 * / `read_pool_value` via {@link decodeValueRecord} — BETWEEN successive
 * `DataView` reads over the SAME buffer. That interleaving is only safe while
 * the read externs obey the Vec-copy contract: today every read extern
 * returns a `Vec<u8>` that wasm-bindgen COPIES out of linear memory into a
 * fresh, JS-owned `ArrayBuffer`, so a re-entrant bridge call — even one that
 * triggers a `memory.grow` — can never detach the buffer these decoders are
 * mid-read on.
 *
 * That invariant was implicit and unenforced. A planned zero-copy read
 * variant (a `string_byte_range`-style extern returning a `Uint8Array`
 * SUBARRAY that ALIASES wasm linear memory rather than a copy) would break it
 * silently: a `read_interned_string` re-entry could grow linear memory,
 * DETACH the aliased buffer, and the next `getUint32` would throw a bare,
 * context-free `TypeError` mid-record.
 *
 * This helper pins the contract at each decoder mouth: it takes an OWNED
 * snapshot of the buffer (`slice()` copies into a fresh, non-shared,
 * non-growable `ArrayBuffer`) BEFORE the first bridge re-entry, so every
 * interleaved read is provably immune to detachment REGARDLESS of what shape
 * the read externs return. Under the current Vec-copy contract the snapshot is
 * a redundant copy of an already-owned buffer; it is the price of not letting
 * a future zero-copy extern silently reintroduce the hazard. A buffer that
 * arrives ALREADY detached (byteLength 0) snapshots to an empty buffer, which
 * the decoder's own length guards reject with a typed, actionable truncation
 * error rather than a bare `TypeError`.
 *
 * @param buf - The raw extern buffer at the decoder mouth.
 * @returns A detach-immune, JS-owned copy of `buf`.
 */
function snapshotDecodeBuffer(buf: Uint8Array): Uint8Array {
  // `slice()` (unlike `subarray`) allocates a fresh backing `ArrayBuffer` and
  // copies the bytes — the result aliases NO wasm linear memory, so no
  // `memory.grow` from a re-entrant bridge call can detach or resize it.
  return buf.slice()
}

/**
 * One decoded commit-log record — the wire-shaped mirror of the JS
 * `Commit` shape the `commitLog` derived publishes (intent / time /
 * changed-node identities). `originatedAt` is always `undefined` here: the
 * Rust `commit_log` is the live commit ring, not a hydrate-replayed log.
 */
export interface DecodedCommitLogRecord {
  readonly intent: string
  readonly time: number
  readonly changedNodes: readonly NodeId[]
}

/**
 * The 7 per-engine telemetry counters the `stats` extern emits, in the
 * canonical `STATS_IDX_*` order. Field-for-field the subset of the TS
 * `EngineTelemetry` shape the Rust core tracks (the remaining
 * `EngineTelemetry` fields — `commitObservers` / `commitMetadataDeriveds`
 * / `commitLogConsumerCount` / `entries` / `nodeVersion` — are TS-closure
 * bookkeeping with no Rust mirror; the facade keeps those TS-sourced).
 */
export interface DecodedStats {
  readonly inputs: number
  readonly deriveds: number
  readonly subscribersTotal: number
  readonly subscribersByNodeKeys: number
  readonly transientSubscribers: number
  readonly nodeVersions: number
  readonly pending: number
}

/** ffi-4 — number of `u32` counters in the canonical telemetry buffer. */
export const STATS_FIELD_COUNT = 7

/**
 * Decode an identity-pair buffer (`encode_node_id_pairs`) into the NodeIds
 * the `(slot, gen)` pairs resolve to, via the supplied `resolve` index. A
 * pair absent from the live index is silently dropped (mirroring the
 * changed-set silent-drop policy in `authoritative.ts`) — a stale-gen or
 * never-registered handle has no canonical NodeId on this engine.
 *
 * @param buf - The raw extern buffer (`dependencies` / `dependents`).
 * @param resolve - `(slot, gen) → NodeId | undefined` — the engine's
 *   `#slotToIdIndex` lookup.
 * @returns The resolved NodeIds in WIRE order (the encoder's adjacency
 *   order). The facade sorts where it needs a diffable projection.
 */
export function decodeNodeIdPairs(
  buf: Uint8Array,
  resolve: (slot: number, gen: number) => NodeId | undefined,
): NodeId[] {
  if (buf.length % NODE_ID_PAIR_LEN !== 0) {
    throw new Error(
      `@causl/client-ts/wasm: node-id-pair buffer length ${buf.length} is not a ` +
        `multiple of the ${NODE_ID_PAIR_LEN}-byte pair width`,
    )
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  const out: NodeId[] = []
  for (let off = 0; off < buf.length; off += NODE_ID_PAIR_LEN) {
    const slot = view.getUint32(off, true)
    const gen = view.getUint32(off + 4, true)
    const id = resolve(slot, gen)
    if (id !== undefined) out.push(id)
  }
  return out
}

/**
 * Decode a commit-log buffer (`encode_commit_log`) into its records,
 * oldest-first (the `State::commit_log` insertion order). The per-commit
 * `intent` routes through {@link decodeValueRecord} (a `STRING_ID` interned
 * into the shared bridge table); each changed `(slot, gen)` pair resolves
 * via `resolve`, silently dropping a pair absent from the live index.
 *
 * @param buf - The raw `commit_log(engine_id)` extern buffer.
 * @param bridge - The value-buf bridge (intern-table resolver) the intent
 *   record decodes against.
 * @param resolve - `(slot, gen) → NodeId | undefined` — the `#slotToIdIndex`.
 */
export function decodeCommitLog(
  buf: Uint8Array,
  bridge: ValueBufBridge,
  resolve: (slot: number, gen: number) => NodeId | undefined,
): DecodedCommitLogRecord[] {
  // Detach-safety (#137): own the buffer BEFORE the interleaved
  // `decodeValueRecord` bridge re-entry, so a future zero-copy read extern
  // cannot detach a linear-memory view mid-record.
  buf = snapshotDecodeBuffer(buf)
  if (buf.length < 4) {
    throw new Error(
      `@causl/client-ts/wasm: commit-log buffer truncated header ` +
        `(need 4 bytes, got ${buf.length})`,
    )
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  const count = view.getUint32(0, true)
  let pos = 4
  const records: DecodedCommitLogRecord[] = []
  for (let i = 0; i < count; i++) {
    // intent — 12-byte interned STRING_ID value record.
    if (pos + VALUE_BUF_RECORD_LEN > buf.length) {
      throw new Error(
        `@causl/client-ts/wasm: commit-log truncated intent record at offset ${pos} ` +
          `(record ${i} of ${count})`,
      )
    }
    const decoded = decodeValueRecord(buf, pos, bridge)
    // An interned intent is always a string; defend the contract by
    // coercing a content-hash sentinel / non-string to a stable string.
    const intent =
      typeof decoded === 'string'
        ? decoded
        : decoded === CONTENT_HASH_FROM_CACHE || decoded == null
          ? ''
          : String(decoded)
    pos += VALUE_BUF_RECORD_LEN
    // time u64 LE — the GraphTime clock value (safe-integer range in any
    // honest engine; `Number` of the bigint matches the TS GraphTime).
    if (pos + 8 > buf.length) {
      throw new Error(
        `@causl/client-ts/wasm: commit-log truncated time at offset ${pos} ` +
          `(record ${i} of ${count})`,
      )
    }
    const time = Number(view.getBigUint64(pos, true))
    pos += 8
    // changed_count u32 LE + identity-pair tail.
    if (pos + 4 > buf.length) {
      throw new Error(
        `@causl/client-ts/wasm: commit-log truncated changed-count at offset ${pos} ` +
          `(record ${i} of ${count})`,
      )
    }
    const changedCount = view.getUint32(pos, true)
    pos += 4
    const changedNodes: NodeId[] = []
    for (let j = 0; j < changedCount; j++) {
      if (pos + NODE_ID_PAIR_LEN > buf.length) {
        throw new Error(
          `@causl/client-ts/wasm: commit-log truncated changed-node tail at offset ` +
            `${pos} (record ${i}, node ${j} of ${changedCount})`,
        )
      }
      const slot = view.getUint32(pos, true)
      const gen = view.getUint32(pos + 4, true)
      pos += NODE_ID_PAIR_LEN
      const id = resolve(slot, gen)
      if (id !== undefined) changedNodes.push(id)
    }
    records.push({ intent, time, changedNodes })
  }
  return records
}

/**
 * #129 / causl/causl-core-rs#318 — the decoded `commit_log_meta(engine_id)`
 * payload: the §12.1 commit-log rows (oldest-first, WIDENED with the
 * hydrate-aware `originatedAt` column) plus the eviction-horizon header
 * pair. `cap` is `undefined` for an uncapped log (the wire's
 * `COMMIT_LOG_META_CAP_UNBOUNDED` sentinel). `totalCommitsEver` is the
 * monotonic push counter that survives FIFO eviction, so a reader can
 * detect a passed horizon (`totalCommitsEver > records.length`) instead of
 * silently serving a truncated audit trail.
 */
export interface DecodedCommitLogMeta {
  readonly cap: number | undefined
  readonly totalCommitsEver: number
  readonly records: readonly DecodedExportCommit[]
}

/**
 * #129 / causl/causl-core-rs#318 — the `commit_log_meta` header sentinel
 * flagging an UNCAPPED engine commit log (mirrors the Rust
 * `COMMIT_LOG_META_CAP_UNBOUNDED = u32::MAX`; a real cap at or above it is
 * clamped engine-side to `u32::MAX - 1`, so the sentinel is unambiguous).
 */
export const COMMIT_LOG_META_CAP_UNBOUNDED = 0xffffffff

/**
 * Decode the #318 `commit_log_meta(engine_id)` buffer:
 *
 * ```text
 *   cap                : u32 LE  (COMMIT_LOG_META_CAP_UNBOUNDED = uncapped)
 *   total_commits_ever : u64 LE  (monotonic across FIFO eviction)
 *   commit_count       : u32 LE
 *   per commit, oldest-first (byte-identical to the export_model commit
 *   block):
 *       intent     : 12-byte value record (STRING_ID)
 *       time       : u64 LE
 *       orig_status: u8 | _pad u8[3]
 *       orig_at    : u64 LE
 *       n_changed  : u32 LE + n_changed × (slot u32, gen u32) LE
 * ```
 *
 * The per-commit `intent` routes through {@link decodeValueRecord} (the
 * shared intern table); each changed `(slot, gen)` pair resolves via
 * `resolve`, silently dropping a pair absent from the live index (the
 * changed-set silent-drop policy).
 *
 * @param buf - The raw `commit_log_meta(engine_id)` extern buffer.
 * @param bridge - The value-buf bridge the intent records decode against.
 * @param resolve - `(slot, gen) → NodeId | undefined` — the `#slotToIdIndex`.
 */
export function decodeCommitLogMeta(
  buf: Uint8Array,
  bridge: ValueBufBridge,
  resolve: (slot: number, gen: number) => NodeId | undefined,
): DecodedCommitLogMeta {
  // Detach-safety (#137): own the buffer BEFORE the interleaved
  // `decodeValueRecord` bridge re-entry.
  buf = snapshotDecodeBuffer(buf)
  if (buf.length < 16) {
    throw new Error(
      `@causl/client-ts/wasm: commit_log_meta buffer truncated header ` +
        `(need 16 bytes, got ${buf.length})`,
    )
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  const capWord = view.getUint32(0, true)
  const cap = capWord === COMMIT_LOG_META_CAP_UNBOUNDED ? undefined : capWord
  const totalCommitsEver = Number(view.getBigUint64(4, true))
  const count = view.getUint32(12, true)
  let pos = 16
  const need = (n: number, what: string): void => {
    if (pos + n > buf.length) {
      throw new StructuralDecodeError(
        `@causl/client-ts/wasm: commit_log_meta truncated ${what} at offset ` +
          `${pos} (need ${n} more bytes, have ${buf.length - pos})`,
        pos,
        buf.length,
      )
    }
  }
  const records: DecodedExportCommit[] = []
  for (let i = 0; i < count; i++) {
    need(VALUE_BUF_RECORD_LEN, 'commit intent')
    const decoded = decodeValueRecord(buf, pos, bridge)
    const intent =
      typeof decoded === 'string'
        ? decoded
        : decoded === CONTENT_HASH_FROM_CACHE || decoded == null
          ? ''
          : String(decoded)
    pos += VALUE_BUF_RECORD_LEN
    need(8, 'commit time')
    const time = Number(view.getBigUint64(pos, true))
    pos += 8
    need(4 + 8, 'commit originated_at')
    const origStatus = view.getUint8(pos)
    // bytes pos+1..pos+4 are pad.
    const origAt = Number(view.getBigUint64(pos + 4, true))
    pos += 4 + 8
    let originatedAt: number | undefined
    if (origStatus === EXPORT_ORIGINATED_SOME) {
      originatedAt = origAt
    } else if (origStatus === EXPORT_ORIGINATED_NONE) {
      originatedAt = undefined
    } else {
      throw new Error(
        `@causl/client-ts/wasm: commit_log_meta commit carries unknown ` +
          `originated status byte ${origStatus} (expected ` +
          `${EXPORT_ORIGINATED_NONE} none / ${EXPORT_ORIGINATED_SOME} some)`,
      )
    }
    need(4, 'commit changed_count')
    const changedCount = view.getUint32(pos, true)
    pos += 4
    const changedNodes: NodeId[] = []
    for (let j = 0; j < changedCount; j++) {
      need(NODE_ID_PAIR_LEN, 'commit changed-node')
      const cSlot = view.getUint32(pos, true)
      const cGen = view.getUint32(pos + 4, true)
      pos += NODE_ID_PAIR_LEN
      const cId = resolve(cSlot, cGen)
      if (cId !== undefined) changedNodes.push(cId)
      else noteUnresolvedPairDrop()
    }
    records.push({ intent, time, originatedAt, changedNodes })
  }
  if (pos !== buf.length) {
    throw new StructuralDecodeError(
      `@causl/client-ts/wasm: commit_log_meta buffer has ${buf.length - pos} ` +
        `trailing bytes after ${count} records (encoder/decoder drift)`,
      pos,
      buf.length,
    )
  }
  return { cap, totalCommitsEver, records }
}

/**
 * lift-export (causl/causl-core-rs#170) — one decoded exported cell (input
 * or derived) from the §18A.3 `export_model` buffer. The `value` is the
 * decoded Rust value record (a `STRING_ID` resolves through the intern
 * table; an `ARRAY_REF` / `OBJECT_REF` through the value pool; a
 * `CONTENT_HASH` surfaces as {@link CONTENT_HASH_FROM_CACHE} so the
 * marshaling shim can serve the original container from its value cache).
 * `deps` is the forward dep adjacency (empty for an input), in declaration
 * order, resolved to NodeIds via the slot→id index.
 */
export interface DecodedExportCell {
  readonly id: NodeId
  readonly value: unknown
  readonly deps: readonly NodeId[]
}

/**
 * lift-export (causl/causl-core-rs#170) — one decoded exported commit from
 * the §18A.3 `export_model` buffer. Mirrors {@link DecodedCommitLogRecord}
 * but carries the hydrate-aware `originatedAt` breadcrumb: `undefined` for
 * a live `commit(...)` record (TS `originatedAt` undefined), a number for a
 * `hydrate(...)`-replayed record (the originating snapshot's GraphTime).
 */
export interface DecodedExportCommit {
  readonly intent: string
  readonly time: number
  readonly originatedAt: number | undefined
  readonly changedNodes: readonly NodeId[]
}

/**
 * lift-export (causl/causl-core-rs#170) — one decoded exported subscription
 * event from the §18A.3 `export_model` buffer. `target` is the subscribed
 * node's NodeId; `subscribedAt` is the registration-time breadcrumb (the TS
 * `SubscriptionEntry.subscribedAt`). The events appear in subscribe-call
 * (insertion) order — byte-identical to the TS `exportModel` events drain.
 */
export interface DecodedExportEvent {
  readonly target: NodeId
  readonly subscribedAt: number
}

/**
 * lift-export (causl/causl-core-rs#170) — the structural payload the
 * §18A.3 `export_model` extern carries, decoded from its self-describing
 * buffer. The {@link DecodedExportModel.time} is the engine GraphTime at
 * export (the IR top-level `time`).
 *
 * This is the WIRE-level projection — the `AuthoritativeWasmEngine`
 * assembles the full `CauslModel` IR over it (stamping `graphId` from the
 * marshaling layer, running the thin `serializable` shim over the
 * Rust-provided values, and synthesising the default `scopes`). The node
 * values here are the Rust-authoritative values; the engine's marshaling
 * value cache resolves the original container for a `CONTENT_HASH` cell.
 */
export interface DecodedExportModel {
  readonly time: number
  readonly inputs: readonly DecodedExportCell[]
  readonly deriveds: readonly DecodedExportCell[]
  readonly commits: readonly DecodedExportCommit[]
  readonly events: readonly DecodedExportEvent[]
}

/**
 * lift-export (#170) — `originatedAt` discriminant byte for a LIVE commit
 * (TS `originatedAt` undefined), mirroring the Rust
 * `EXPORT_ORIGINATED_NONE`.
 */
export const EXPORT_ORIGINATED_NONE = 0

/**
 * lift-export (#170) — `originatedAt` discriminant byte for a
 * HYDRATE-replayed commit carrying the originating snapshot's GraphTime,
 * mirroring the Rust `EXPORT_ORIGINATED_SOME`.
 */
export const EXPORT_ORIGINATED_SOME = 1

/**
 * lift-export (#170) — byte width of one exported event (subscription)
 * record: `target slot u32 | gen u32 | subscribed_at u64` LE. Mirrors the
 * Rust `EXPORT_EVENT_RECORD_LEN`.
 */
export const EXPORT_EVENT_RECORD_LEN = 16

/**
 * Decode the §18A.3 `export_model(engine_id)` buffer into its structural
 * {@link DecodedExportModel} payload. Mirrors the Rust-side
 * `resolve_export_model` (`causl-wasm/tools/engine-rs-bridge/src/lib.rs`):
 *
 * ```text
 *   time          : u64 LE   (engine GraphTime at export)
 *   input_count   : u32 LE
 *   per input:   slot u32 | gen u32 | 12-byte value record | dep_count u32 (=0)
 *   derived_count : u32 LE
 *   per derived: slot u32 | gen u32 | 12-byte value record | dep_count u32
 *                + dep_count × (slot u32, gen u32) LE
 *   commit_count  : u32 LE
 *   per commit, oldest-first:
 *       intent     : 12-byte value record (STRING_ID)
 *       time       : u64 LE
 *       orig_status: u8 | _pad u8[3]
 *       orig_at    : u64 LE
 *       n_changed  : u32 LE + n_changed × (slot u32, gen u32) LE
 *   event_count   : u32 LE
 *   per event:   target slot u32 | gen u32 | subscribed_at u64 LE
 * ```
 *
 * The cell value / commit intent route through {@link decodeValueRecord}
 * (the SAME intern-table / value-pool surfaces the read externs use), so a
 * retained string / container resolves identically to the live read path.
 * A `(slot, gen)` pair absent from the live index is silently dropped
 * (mirroring the changed-set silent-drop policy) — a stale-gen handle has
 * no canonical NodeId on this engine.
 *
 * @param buf - The raw `export_model(engine_id)` extern buffer.
 * @param bridge - The value-buf bridge (intern-table / value-pool resolver)
 *   the cell values + commit intents decode against.
 * @param resolve - `(slot, gen) → NodeId | undefined` — the engine's
 *   `#slotToIdIndex` lookup.
 * @param temporal - #165 — the PER-ENGINE Temporal impl the cell-value
 *   tagged-type revive uses (falls back module-level, then global).
 */
export function decodeExportModel(
  buf: Uint8Array,
  bridge: ValueBufBridge,
  resolve: (slot: number, gen: number) => NodeId | undefined,
  temporal?: TemporalLike,
): DecodedExportModel {
  // Detach-safety (#137): own the buffer BEFORE the interleaved
  // `decodeValueRecord` bridge re-entry, so a future zero-copy read extern
  // cannot detach a linear-memory view mid-record.
  buf = snapshotDecodeBuffer(buf)
  if (buf.length < 8) {
    throw new Error(
      `@causl/client-ts/wasm: export_model buffer truncated header ` +
        `(need 8 bytes, got ${buf.length})`,
    )
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  let pos = 0
  const need = (n: number, what: string): void => {
    if (pos + n > buf.length) {
      throw new StructuralDecodeError(
        `@causl/client-ts/wasm: export_model truncated ${what} at offset ${pos} ` +
          `(need ${n} more bytes, have ${buf.length - pos})`,
        pos,
        buf.length,
      )
    }
  }

  // IR top-level `time`.
  const time = Number(view.getBigUint64(pos, true))
  pos += 8

  // Decode one cell (input or derived): slot/gen + value record + dep tail.
  const decodeCell = (): DecodedExportCell | undefined => {
    need(8 + VALUE_BUF_RECORD_LEN + 4, 'export cell header')
    const slot = view.getUint32(pos, true)
    const gen = view.getUint32(pos + 4, true)
    const value = decodeValueRecord(buf, pos + 8, bridge, temporal)
    const depCount = view.getUint32(pos + 8 + VALUE_BUF_RECORD_LEN, true)
    pos += 8 + VALUE_BUF_RECORD_LEN + 4
    const deps: NodeId[] = []
    for (let j = 0; j < depCount; j++) {
      need(NODE_ID_PAIR_LEN, 'export cell dep')
      const dSlot = view.getUint32(pos, true)
      const dGen = view.getUint32(pos + 4, true)
      pos += NODE_ID_PAIR_LEN
      const depId = resolve(dSlot, dGen)
      if (depId !== undefined) deps.push(depId)
      else noteUnresolvedPairDrop()
    }
    const id = resolve(slot, gen)
    if (id === undefined) {
      noteUnresolvedPairDrop()
      return undefined
    }
    return { id, value, deps }
  }

  need(4, 'input_count')
  const inputCount = view.getUint32(pos, true)
  pos += 4
  const inputs: DecodedExportCell[] = []
  for (let i = 0; i < inputCount; i++) {
    const cell = decodeCell()
    if (cell !== undefined) inputs.push(cell)
  }

  need(4, 'derived_count')
  const derivedCount = view.getUint32(pos, true)
  pos += 4
  const deriveds: DecodedExportCell[] = []
  for (let i = 0; i < derivedCount; i++) {
    const cell = decodeCell()
    if (cell !== undefined) deriveds.push(cell)
  }

  need(4, 'commit_count')
  const commitCount = view.getUint32(pos, true)
  pos += 4
  const commits: DecodedExportCommit[] = []
  for (let i = 0; i < commitCount; i++) {
    need(VALUE_BUF_RECORD_LEN, 'commit intent')
    const decoded = decodeValueRecord(buf, pos, bridge)
    const intent =
      typeof decoded === 'string'
        ? decoded
        : decoded === CONTENT_HASH_FROM_CACHE || decoded == null
          ? ''
          : String(decoded)
    pos += VALUE_BUF_RECORD_LEN
    need(8, 'commit time')
    const cTime = Number(view.getBigUint64(pos, true))
    pos += 8
    need(4 + 8, 'commit originated_at')
    const origStatus = view.getUint8(pos)
    // bytes pos+1..pos+4 are pad.
    const origAt = Number(view.getBigUint64(pos + 4, true))
    pos += 4 + 8
    let originatedAt: number | undefined
    if (origStatus === EXPORT_ORIGINATED_SOME) {
      originatedAt = origAt
    } else if (origStatus === EXPORT_ORIGINATED_NONE) {
      originatedAt = undefined
    } else {
      throw new Error(
        `@causl/client-ts/wasm: export_model commit carries unknown originated ` +
          `status byte ${origStatus} (expected ${EXPORT_ORIGINATED_NONE} ` +
          `none / ${EXPORT_ORIGINATED_SOME} some)`,
      )
    }
    need(4, 'commit changed_count')
    const changedCount = view.getUint32(pos, true)
    pos += 4
    const changedNodes: NodeId[] = []
    for (let j = 0; j < changedCount; j++) {
      need(NODE_ID_PAIR_LEN, 'commit changed-node')
      const cSlot = view.getUint32(pos, true)
      const cGen = view.getUint32(pos + 4, true)
      pos += NODE_ID_PAIR_LEN
      const cId = resolve(cSlot, cGen)
      if (cId !== undefined) changedNodes.push(cId)
      else noteUnresolvedPairDrop()
    }
    commits.push({ intent, time: cTime, originatedAt, changedNodes })
  }

  need(4, 'event_count')
  const eventCount = view.getUint32(pos, true)
  pos += 4
  const events: DecodedExportEvent[] = []
  for (let i = 0; i < eventCount; i++) {
    need(EXPORT_EVENT_RECORD_LEN, 'export event')
    const slot = view.getUint32(pos, true)
    const gen = view.getUint32(pos + 4, true)
    const subscribedAt = Number(view.getBigUint64(pos + 8, true))
    pos += EXPORT_EVENT_RECORD_LEN
    const target = resolve(slot, gen)
    // A subscription whose target slot is absent from the live index is
    // dropped (a disposed / stale-gen target has no canonical NodeId).
    if (target !== undefined) events.push({ target, subscribedAt })
    else noteUnresolvedPairDrop()
  }

  // #139 — the events section is the LAST section of the wire. Assert the
  // decode consumed the WHOLE buffer: a version-skewed encoder that appends a
  // new section after `events` would otherwise decode 'successfully' with its
  // tail silently ignored, hiding the drift. Reject the trailing bytes loud.
  if (pos !== buf.length) {
    throw new StructuralDecodeError(
      `@causl/client-ts/wasm: export_model decoded ${pos} of ${buf.length} bytes ` +
        `— ${buf.length - pos} trailing byte(s) remain after the events ` +
        `section (encoder/decoder drift: a version-skewed encoder appended a ` +
        `section this decoder does not read)`,
      pos,
      buf.length,
    )
  }

  return { time, inputs, deriveds, commits, events }
}

/**
 * Decode the fixed-width telemetry buffer (`EngineStats::encode`) into its
 * 7 counters in the canonical `STATS_IDX_*` order. The buffer is exactly
 * `STATS_FIELD_COUNT * 4` bytes — self-describing by length, no header.
 *
 * @param buf - The raw `stats(engine_id)` extern buffer.
 */
export function decodeStats(buf: Uint8Array): DecodedStats {
  const want = STATS_FIELD_COUNT * 4
  if (buf.length < want) {
    throw new Error(
      `@causl/client-ts/wasm: stats buffer truncated (need ${want} bytes, ` +
        `got ${buf.length})`,
    )
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  return {
    inputs: view.getUint32(0, true),
    deriveds: view.getUint32(4, true),
    subscribersTotal: view.getUint32(8, true),
    subscribersByNodeKeys: view.getUint32(12, true),
    transientSubscribers: view.getUint32(16, true),
    nodeVersions: view.getUint32(20, true),
    pending: view.getUint32(24, true),
  }
}

/**
 * lift-readat (causl/causl-core-rs#170) — fixed width of the discriminated
 * `read_at_result` record. Mirrors the Rust
 * `READ_AT_RESULT_RECORD_LEN` (a 12-byte `status u8 | _pad u8[3] |
 * graph_time u64` header + a trailing 12-byte value record).
 */
export const READ_AT_RESULT_RECORD_LEN = 12 + VALUE_BUF_RECORD_LEN

/**
 * lift-readat (#170) — `status` discriminant byte for the retained arm,
 * mirroring the Rust `READ_AT_STATUS_RETAINED`.
 */
export const READ_AT_STATUS_RETAINED = 0

/**
 * lift-readat (#170) — `status` discriminant byte for the evicted arm,
 * mirroring the Rust `READ_AT_STATUS_EVICTED`.
 */
export const READ_AT_STATUS_EVICTED = 1

/**
 * Decode the 24-byte discriminated `read_at_result` record (the
 * `read_at_result(engine_id, slot, gen, time)` extern output) into the
 * exact {@link RetentionResult} discriminated union the TS engine's
 * `readAt(node, t)` / `snapshotAt(t)` return.
 *
 * Mirrors the Rust-side `encode_read_at_result`
 * (`causl-wasm/tools/engine-rs-bridge/src/lib.rs`):
 *
 * ```text
 *   byte 0      : status (0 = retained, 1 = evicted)
 *   bytes 1..4  : padding
 *   bytes 4..12 : graph_time u64 LE
 *                   - retained: the chosen row's commit time
 *                   - evicted : oldestRetainedTime
 *   bytes 12..24: 12-byte value record (retained value; NULL when evicted)
 * ```
 *
 * The retained arm's `value` routes through {@link decodeValueRecord}
 * (STRING_ID → intern table, ARRAY_REF / OBJECT_REF → value pool), so a
 * retained string / array / object resolves through the SAME bridge
 * surfaces the live-read path uses. The `time` it carries is the chosen
 * row's commit time — byte-identical to the TS `chosen.time` breadcrumb.
 *
 * @param buf - The raw `read_at_result(...)` extern buffer (24 bytes).
 * @param bridge - The value-buf bridge the retained value record decodes
 *   against.
 * @param temporal - #165 — the PER-ENGINE Temporal impl the retained-value
 *   tagged-type revive uses (falls back module-level, then global).
 * @returns A `RetentionResult<unknown>` structurally identical to the TS
 *   engine's `readAt` / `snapshotAt` return.
 */
export function decodeReadAtResult(
  buf: Uint8Array,
  bridge: ValueBufBridge,
  temporal?: TemporalLike,
): RetentionResult<unknown> {
  if (buf.length < READ_AT_RESULT_RECORD_LEN) {
    throw new Error(
      `@causl/client-ts/wasm: read_at_result buffer truncated ` +
        `(need ${READ_AT_RESULT_RECORD_LEN} bytes, got ${buf.length})`,
    )
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  const status = view.getUint8(0)
  // bytes 1..4 are pad; graph_time u64 at byte 4.
  const graphTime = Number(view.getBigUint64(4, true)) as GraphTime
  if (status === READ_AT_STATUS_EVICTED) {
    return { status: 'evicted', oldestRetainedTime: graphTime }
  }
  if (status !== READ_AT_STATUS_RETAINED) {
    throw new Error(
      `@causl/client-ts/wasm: read_at_result carries unknown status byte ${status} ` +
        `(expected ${READ_AT_STATUS_RETAINED} retained / ${READ_AT_STATUS_EVICTED} evicted)`,
    )
  }
  // Retained — the trailing 12-byte value record holds the value.
  const value = decodeValueRecord(buf, 12, bridge, temporal)
  return { status: 'retained', value, time: graphTime }
}

/**
 * lift-subscribecommits (causl-wasm#170) — one decoded §5.5 commit-level
 * record carried by the `__causl_on_commit` crossing, mirroring the
 * adopter-facing `Commit` shape (`time` / `intent` / `changedNodes` /
 * `originatedAt`). `originatedAt` is `undefined` for a live `commit(...)`
 * record (TS `originatedAt` undefined), a number for a hydrate-replayed
 * commit carrying the originating snapshot's GraphTime.
 */
export interface DecodedCommitRecord {
  readonly time: number
  readonly intent: string
  readonly originatedAt: number | undefined
  readonly changedNodes: readonly NodeId[]
}

/**
 * lift-subscribecommits (causl-wasm#170) — decode the §5.5 commit-level
 * record the `__causl_on_commit(engineId, commitBuf)` crossing delivers ONCE
 * per commit (after the Phase-G per-node firing). The wire is the per-commit
 * block of {@link decodeExportModel} — HEADER-FREE (no `commit_count`),
 * since the crossing carries exactly ONE record. Mirrors the Rust
 * `encode_commit_record` (`causl-wasm/tools/engine-rs-bridge/src/compute_bridge.rs`):
 *
 * ```text
 *   intent     : 12-byte value record (STRING_ID via encode_value_record)
 *   time       : u64 LE
 *   orig_status: u8 (EXPORT_ORIGINATED_NONE | EXPORT_ORIGINATED_SOME)
 *   _pad       : u8[3]
 *   orig_at    : u64 LE (snap time; ignored when orig_status = NONE)
 *   n_changed  : u32 LE + n_changed × (slot u32, gen u32) LE
 * ```
 *
 * The intent routes through {@link decodeValueRecord} (a `STRING_ID`
 * interned into the shared bridge table — the SAME surface the commit-log /
 * export-model intents decode against). Each changed `(slot, gen)` pair
 * resolves via `resolve`, silently dropping a pair absent from the live
 * index (mirroring the changed-set silent-drop policy the `commit()` path
 * and `decodeCommitLog` already use).
 *
 * @param buf - The raw `__causl_on_commit` commit buffer.
 * @param bridge - The value-buf bridge (intern-table resolver) the intent
 *   record decodes against.
 * @param resolve - `(slot, gen) → NodeId | undefined` — the `#slotToIdIndex`.
 */
export function decodeCommitRecord(
  buf: Uint8Array,
  bridge: ValueBufBridge,
  resolve: (slot: number, gen: number) => NodeId | undefined,
): DecodedCommitRecord {
  // Detach-safety (#137): own the buffer BEFORE the interleaved
  // `decodeValueRecord` bridge re-entry, so a future zero-copy read extern
  // cannot detach a linear-memory view mid-record.
  buf = snapshotDecodeBuffer(buf)
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  let pos = 0
  const need = (n: number, what: string): void => {
    if (pos + n > buf.length) {
      throw new StructuralDecodeError(
        `@causl/client-ts/wasm: __causl_on_commit truncated ${what} at offset ${pos} ` +
          `(need ${n} more bytes, have ${buf.length - pos})`,
        pos,
        buf.length,
      )
    }
  }

  // intent — 12-byte interned STRING_ID value record.
  need(VALUE_BUF_RECORD_LEN, 'commit intent')
  const decoded = decodeValueRecord(buf, pos, bridge)
  const intent =
    typeof decoded === 'string'
      ? decoded
      : decoded === CONTENT_HASH_FROM_CACHE || decoded == null
        ? ''
        : String(decoded)
  pos += VALUE_BUF_RECORD_LEN

  // time u64 LE — the commit's GraphTime.
  need(8, 'commit time')
  const time = Number(view.getBigUint64(pos, true))
  pos += 8

  // orig_status u8 | _pad u8[3] | orig_at u64 LE — the hydrate-aware
  // `originatedAt` discriminant (`undefined` for a live commit).
  need(4 + 8, 'commit originated_at')
  const origStatus = view.getUint8(pos)
  const origAt = Number(view.getBigUint64(pos + 4, true))
  pos += 4 + 8
  let originatedAt: number | undefined
  if (origStatus === EXPORT_ORIGINATED_SOME) {
    originatedAt = origAt
  } else if (origStatus === EXPORT_ORIGINATED_NONE) {
    originatedAt = undefined
  } else {
    throw new Error(
      `@causl/client-ts/wasm: __causl_on_commit record carries unknown originated ` +
        `status byte ${origStatus} (expected ${EXPORT_ORIGINATED_NONE} ` +
        `none / ${EXPORT_ORIGINATED_SOME} some)`,
    )
  }

  // n_changed u32 LE + identity-pair tail.
  need(4, 'commit changed_count')
  const changedCount = view.getUint32(pos, true)
  pos += 4
  const changedNodes: NodeId[] = []
  for (let j = 0; j < changedCount; j++) {
    need(NODE_ID_PAIR_LEN, 'commit changed-node')
    const slot = view.getUint32(pos, true)
    const gen = view.getUint32(pos + 4, true)
    pos += NODE_ID_PAIR_LEN
    const id = resolve(slot, gen)
    if (id !== undefined) changedNodes.push(id)
    else noteUnresolvedPairDrop()
  }

  // #139 — the changed-node tail is the LAST section of the (header-free,
  // exactly-one-record) commit wire. Assert the decode consumed the WHOLE
  // buffer so a version-skewed encoder that appends a section cannot decode
  // 'successfully' with its tail silently ignored.
  if (pos !== buf.length) {
    throw new StructuralDecodeError(
      `@causl/client-ts/wasm: __causl_on_commit decoded ${pos} of ${buf.length} ` +
        `bytes — ${buf.length - pos} trailing byte(s) remain after the ` +
        `changed-node tail (encoder/decoder drift: a version-skewed encoder ` +
        `appended a section this decoder does not read)`,
      pos,
      buf.length,
    )
  }

  return { time, intent, originatedAt, changedNodes }
}

/**
 * #139 — one parsed record of the `__causl_fire` Phase-G firing batch: the
 * fired node's `(slot, gen)` identity, the firing observer id, and the byte
 * offset of that record's 12-byte value record within the batch buffer (the
 * caller decodes the value lazily — only on a value-cache miss — so the
 * parse stays a cheap byte-walk).
 */
export interface FireBatchRecord {
  readonly nodeSlot: number
  readonly nodeGen: number
  readonly observerId: string
  readonly valueOffset: number
}

/** #139 — the UTF-8 decoder for fire-batch observer ids. */
const fireBatchTextDecoder = new TextDecoder()

/**
 * #139 — decode the `__causl_fire` Phase-G firing batch into its records.
 * The wire (mirroring the Rust fire encoder) is a `u32` record count
 * followed by that many records, each:
 *
 * ```text
 *   engine_id u32 | node_slot u32 | node_gen u32
 *   observer_len u32 | observer bytes (UTF-8)
 *   value_record (12 bytes)
 * ```
 *
 * A batch buffer shorter than the 4-byte header carries NO firings (the
 * empty crossing) and decodes to `[]`. But a record truncated MID-BATCH is
 * encoder/decoder drift — the Rust fire encoder and this decoder disagree on
 * the record grammar — and MUST fail loud with {@link StructuralDecodeError}
 * rather than silently fire only the prefix that fit and drop the truncated
 * tail (the old `break` that hid the drift, #139).
 *
 * Pure (no engine state): the caller resolves `(slot, gen)` → NodeId and
 * decodes the value record at `valueOffset` itself, so this parse is unit-
 * testable in isolation.
 *
 * @param buf - The raw `__causl_fire` batch buffer (already copied off WASM
 *   linear memory by the caller).
 */
export function decodeFireBatch(buf: Uint8Array): FireBatchRecord[] {
  if (buf.length < 4) return []
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  const count = view.getUint32(0, true)
  let pos = 4
  const truncated = (i: number, n: number, what: string): never => {
    throw new StructuralDecodeError(
      `@causl/client-ts/wasm: __causl_fire batch truncated ${what} at offset ` +
        `${pos} (record ${i} of ${count}; need ${n} more bytes, have ` +
        `${buf.length - pos}) — encoder/decoder drift`,
      pos,
      buf.length,
    )
  }
  const records: FireBatchRecord[] = []
  for (let i = 0; i < count; i++) {
    // engine_id u32 | node_slot u32 | node_gen u32
    if (pos + 12 > buf.length) truncated(i, 12, 'record header')
    const nodeSlot = view.getUint32(pos + 4, true)
    const nodeGen = view.getUint32(pos + 8, true)
    pos += 12
    // observer_len u32 + observer bytes
    if (pos + 4 > buf.length) truncated(i, 4, 'observer length')
    const observerLen = view.getUint32(pos, true)
    pos += 4
    if (pos + observerLen > buf.length) truncated(i, observerLen, 'observer id')
    const observerId = fireBatchTextDecoder.decode(
      buf.subarray(pos, pos + observerLen),
    )
    pos += observerLen
    // value_record (12 bytes)
    if (pos + VALUE_BUF_RECORD_LEN > buf.length)
      truncated(i, VALUE_BUF_RECORD_LEN, 'value record')
    const valueOffset = pos
    pos += VALUE_BUF_RECORD_LEN
    records.push({ nodeSlot, nodeGen, observerId, valueOffset })
  }
  return records
}

/**
 * del-final (causl/causl-core-rs#170) — width of the fixed `node_meta`
 * record, mirroring the Rust `NODE_META_RECORD_LEN`:
 *
 * ```text
 *   kind           : u8       (NODE_META_KIND_*)
 *   _pad           : u8[3]
 *   computed_at    : u64 LE
 *   contributed_at : u64 LE
 * ```
 *
 * `1` (kind) + `3` (pad) + `8` (`computed_at`) + `8` (`contributed_at`)
 * = `20` bytes.
 */
export const NODE_META_RECORD_LEN = 4 + 8 + 8

/** del-final — `kind` discriminant for an INPUT node (Rust `NODE_META_KIND_INPUT`). */
export const NODE_META_KIND_INPUT = 0
/** del-final — `kind` discriminant for a DERIVED node (Rust `NODE_META_KIND_DERIVED`). */
export const NODE_META_KIND_DERIVED = 1
/** del-final — `kind` for a node absent / disposed / stale-gen on this engine (Rust `NODE_META_KIND_MISSING`). */
export const NODE_META_KIND_MISSING = 2

/**
 * del-final (causl/causl-core-rs#170) — one decoded `node_meta` record: the
 * per-node EXPLAIN metadata `buildExplanation` (graph.ts) previously sourced
 * from the TS `entries` map. `kind` is the structural input/derived
 * discriminant (`'missing'` for an id the engine no longer owns); `computedAt`
 * is the node's `Explanation.computedAt` source (the input `lastWriteTime` /
 * the derived `lastTime`), and `contributedAt` the per-dep value
 * (byte-identical to `computedAt` — the TS per-dep `contributedAt` reads the
 * same field off the CHILD entry).
 */
export interface DecodedNodeMeta {
  readonly kind: 'input' | 'derived' | 'missing'
  readonly computedAt: GraphTime
  readonly contributedAt: GraphTime
}

/**
 * del-final (causl/causl-core-rs#170) — decode the 20-byte `node_meta(engine_id,
 * slot, gen)` record (the LAST TS-closure read `explain` carried). Mirrors the
 * Rust `encode_node_meta` (`causl-wasm/tools/engine-rs-bridge/src/lib.rs`):
 * `kind u8 | _pad u8[3] | computed_at u64 LE | contributed_at u64 LE`. Pure
 * scalar record — no value channel, no intern-table hop.
 */
export function decodeNodeMeta(buf: Uint8Array): DecodedNodeMeta {
  if (buf.length < NODE_META_RECORD_LEN) {
    throw new Error(
      `@causl/client-ts/wasm: node_meta buffer truncated ` +
        `(need ${NODE_META_RECORD_LEN} bytes, got ${buf.length})`,
    )
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  const kindByte = view.getUint8(0)
  // bytes 1..4 are pad; computed_at u64 at byte 4, contributed_at u64 at byte 12.
  const computedAt = Number(view.getBigUint64(4, true)) as GraphTime
  const contributedAt = Number(view.getBigUint64(12, true)) as GraphTime
  const kind =
    kindByte === NODE_META_KIND_INPUT
      ? 'input'
      : kindByte === NODE_META_KIND_DERIVED
        ? 'derived'
        : kindByte === NODE_META_KIND_MISSING
          ? 'missing'
          : undefined
  if (kind === undefined) {
    throw new Error(
      `@causl/client-ts/wasm: node_meta carries unknown kind byte ${kindByte} ` +
        `(expected ${NODE_META_KIND_INPUT} input / ${NODE_META_KIND_DERIVED} derived / ` +
        `${NODE_META_KIND_MISSING} missing)`,
    )
  }
  return { kind, computedAt, contributedAt }
}
