/**
 * @packageDocumentation
 *
 * TS-side value-buffer codec — wasm-engine fork CUTOVER (full-fidelity
 * value bridge).
 *
 * Mirrors the Rust-side `encode_value_record` / `decode_value_record`
 * (DESIGN §5.3) in `causl-wasm/tools/engine-rs-bridge/src/lib.rs`. A
 * value-buffer record is a fixed 12-byte little-endian frame:
 *
 *   value_kind u8 | _pad u8[3] | value u64
 *
 * The `value` field is INDEPENDENT of the kind byte (no bits stolen), so
 * f64 numbers round-trip bit-exact. Per kind:
 *
 *   NULL       → value = 0                        (ignored)
 *   BOOL       → value = 0 | 1
 *   NUMBER     → value = f64::to_bits()           (FULL 8 bytes)
 *   STRING_ID  → value = StringId u32 (low 32)    (intern table)
 *   ARRAY_REF  → value = payload_id u32 (low 32)  (value pool)
 *   OBJECT_REF → value = payload_id u32 (low 32)  (value pool)
 *
 * This is the EXACT codec `__causl_compute` uses for dep values and the
 * shape the new `read_cell_value(slot, gen, is_input) -> Uint8Array`
 * extern returns. Encoding a string interns it via `intern_string`;
 * encoding an array/object pools it via `register_value_buf` (the
 * serde-free binary value-pool ingest). Decoding resolves STRING_ID via
 * `read_interned_string` and ARRAY_REF / OBJECT_REF via `read_pool_value`
 * (which returns canonical JSON bytes for the pooled value).
 *
 * @internal Wire-level surface — adopters use the `WasmBackend` methods.
 */

import { kind } from './cmd-buf.js'
import { contentHashMarker } from './content-hash.js'
import { guardEncodeDepth } from './cyclic-guard.js'
import {
  encodeTagged,
  hasTaggedTypes,
  reviveTagged,
  type TemporalLike,
} from './tagged-types.js'
import { checkU32 } from './wire-guard.js'

/** The fixed value-buffer record width (DESIGN §5.3). */
export const VALUE_BUF_RECORD_LEN = 12

/**
 * The wasm-bindgen extern surface this codec needs. A subset of
 * `WasmBridgeExports` — declared locally so the codec has no import cycle
 * with `index.ts`.
 */
export interface ValueBufBridge {
  /** Intern a UTF-8 byte string; returns the `StringId` (u32). */
  readonly intern_string: (utf8: Uint8Array) => number
  /** Resolve a previously-interned `StringId` back to its string. */
  readonly read_interned_string: (stringId: number) => string | undefined
  /**
   * Register a self-describing binary value-buffer (an `Array` / `Object`
   * encoded by {@link encodeContainerValueBuf}) into the value pool;
   * returns the `payload_id` (u32).
   */
  readonly register_value_buf: (valueBuf: Uint8Array) => number
  /**
   * Resolve a pooled `payload_id` to its canonical JSON bytes (UTF-8).
   * Returns `undefined` for an out-of-range id.
   */
  readonly read_pool_value: (payloadId: number) => Uint8Array | undefined
}

const textEncoder = new TextEncoder()
const textDecoder = new TextDecoder()

/**
 * Bounded LRU value cache — the large-grid marshaling fix
 * (feat/value-read-cache).
 *
 * THE PROBLEM (measured). A container derived's value (xldatagrid's
 * `processedData` = the whole row array) lives in the wasm value pool.
 * Every DECODE of it does `read_pool_value(id)` → `JSON.parse` of the
 * WHOLE array — O(rows) — on BOTH the Phase-D recompute (decoding dep
 * values for dependent lambdas) AND the post-commit `read()`. At 5000
 * rows that O(rows) parse dominated a single data change.
 *
 * THE FIX. The engine already holds the ORIGINAL JS value at two points:
 * when it INGESTS an input write (the committed JS reference) and when a
 * derived's compute lambda RETURNS its result (the JS reference the
 * lambda produced). Cache that original reference keyed by NodeId; serve
 * it back on `read()` and on Phase-D dep resolution, skipping
 * `read_cell_value` / `read_pool_value` + `JSON.parse` + `reviveTagged`
 * entirely.
 *
 * ### Why NodeId, not the value-pool id
 * The fork's codec mints a pool id via `register_value_buf` on ingest,
 * but the consolidated wasm engine RE-POOLS internally: `read_cell_value`
 * and the Phase-D dep encoder return a FRESH, monotonically-growing pool
 * id on every call — never the ingest id. So an ingest-id-keyed cache can
 * never be hit against this artifact (verified empirically: ingest ids
 * and read-back ids are disjoint and strictly increasing). NodeId, by
 * contrast, is stable across a cell's lifetime, so it is the correct
 * cache key here. (Keying directly on the engine's internal pool id —
 * "values never entering wasm", cutoff via content-hash — is the deeper
 * value-handle follow-up.)
 *
 * ### Correctness
 * The cached value is, for every NodeId, structurally equal to the cell's
 * value:
 *   - input write  → cache holds the exact committed JS value;
 *   - derived      → cache holds the compute lambda's result. If the
 *     engine's structural-equality cutoff keeps the prior cell value, the
 *     new result is structurally equal to it (that is WHY cutoff fired),
 *     so the cache stays correct;
 *   - a node whose deps did not change does not recompute, so its cached
 *     value is unchanged and still correct.
 * A recompute that genuinely changes the value calls the compute handler,
 * which overwrites the cache — there are no stale reads. A MISS (a value
 * the cache never saw — `__snapshot` / `hydrate`, or an LRU-evicted entry)
 * is ALWAYS safe: the caller falls back to the wasm read path, which is
 * correct, just slower. SPEC §15.1 makes `read()` reference identity
 * non-contractual, so serving the cached reference (possibly the same ref
 * across reads) is conformant — and matches the JS engine's behavior more
 * closely.
 *
 * ### Eviction
 * Bounded LRU (insertion-ordered `Map`): a `get` promotes the entry to
 * most-recently-used; on overflow the least-recently-used entry is
 * evicted. Cleared on the engine's value-pool reset. Because a miss is
 * always safe, eviction never corrupts — it only costs a fallback read.
 */
export class ValueHandleCache<K = NodeIdKey> {
  readonly #map = new Map<K, unknown>()
  readonly #cap: number

  /**
   * @param capacity Max entries before LRU eviction (default 4096). Pass
   *   `Number.MAX_SAFE_INTEGER` (or any value ≥ 2^31) for an effectively
   *   unbounded cache — the authoritative engine uses this so a live
   *   container cell's value (the ONLY copy, post content-hash) never ages
   *   out. `Math.floor` (not `| 0`, which truncates to 32 bits and would
   *   wrap a large capacity to a tiny one) keeps a large cap large.
   */
  constructor(capacity = 4096) {
    this.#cap = Math.max(1, Math.floor(capacity))
  }

  /** Cache the original JS value for `key` (most-recently-used). */
  set(key: K, value: unknown): void {
    // Re-insert at the tail (MRU) so a refresh also promotes.
    if (this.#map.has(key)) this.#map.delete(key)
    this.#map.set(key, value)
    if (this.#map.size > this.#cap) {
      // Evict the least-recently-used (the Map's first / oldest key). A
      // miss on the evicted key later falls back to the wasm read path.
      const oldest = this.#map.keys().next().value
      if (oldest !== undefined) this.#map.delete(oldest)
    }
  }

  /**
   * Return the cached value for `key`, or the {@link MISS} sentinel when
   * absent (distinct from a cached `undefined` / `null`). A hit promotes
   * the entry to most-recently-used.
   */
  get(key: K): unknown {
    if (!this.#map.has(key)) return ValueHandleCache.MISS
    const value = this.#map.get(key)
    this.#map.delete(key)
    this.#map.set(key, value)
    return value
  }

  /** Drop a single entry (e.g. a disposed node). */
  delete(key: K): void {
    this.#map.delete(key)
  }

  /** Drop every entry (the value-pool reset / bridge reset). */
  clear(): void {
    this.#map.clear()
  }

  /** Current entry count (test / diagnostics). */
  get size(): number {
    return this.#map.size
  }

  /** Sentinel distinguishing a MISS from a cached `undefined` / `null`. */
  static readonly MISS: unique symbol = Symbol('value-handle-cache-miss')
}

/** The cache key type the engine uses (a NodeId is a branded string). */
type NodeIdKey = string

/**
 * Encode a single JS value into a 12-byte value-buffer record, appending
 * the bytes to `out`. Strings intern; arrays/objects pool. The bridge
 * mutations (intern / pool) are idempotent for the codec's purposes —
 * the same content re-interns to the same id; arrays/objects push a
 * fresh pool entry each time (matching the Rust pool's no-dedup
 * contract).
 */
export function encodeValueRecord(
  value: unknown,
  bridge: ValueBufBridge,
  out: number[],
): void {
  // Tagged-type bridge (issue #28): replace any Set/Map/Date/Temporal
  // reachable in `value` with a JSON-carryable tagged object BEFORE the
  // value-pool path sees it, so they survive the JSON-only round-trip.
  // The `hasTaggedTypes` probe keeps the common pure-JSON path
  // allocation-free (no clone when nothing needs tagging).
  if (hasTaggedTypes(value)) {
    value = encodeTagged(value)
  }
  let kindByte: number
  // The 8-byte payload, assembled as two u32 halves (lo, hi) so we avoid
  // BigInt churn on the scalar paths; NUMBER fills both halves.
  let lo = 0
  let hi = 0

  if (value === null || value === undefined) {
    kindByte = kind.NULL
  } else if (typeof value === 'boolean') {
    kindByte = kind.BOOL
    lo = value ? 1 : 0
  } else if (typeof value === 'number') {
    kindByte = kind.NUMBER
    const buf = new ArrayBuffer(8)
    const view = new DataView(buf)
    view.setFloat64(0, value, true)
    lo = view.getUint32(0, true)
    hi = view.getUint32(4, true)
  } else if (typeof value === 'string') {
    kindByte = kind.STRING_ID
    lo = checkU32(
      bridge.intern_string(textEncoder.encode(value)),
      'value-buf::string_intern_id',
      'value-buf',
      'STRING_ID',
    )
  } else if (Array.isArray(value) || typeof value === 'object') {
    // feat/content-hash-values — a container (Array / Object) ships as a
    // DETERMINISTIC structural content-hash MARKER, NOT the whole encoded
    // value. The marker is O(n)-cheap to compute (one traversal) and
    // interns as a tiny string, replacing the O(n) binary encode +
    // `register_value_buf` FFI cross of the entire container. The engine
    // stores the marker (a `JsonValue::String`) so its cutoff /
    // `State::hash` operate over the hash; the real value is served from
    // the JS NodeId cache on read. `value` is already tagged above (so
    // `contentHashMarker` re-tagging is a clone-free no-op here).
    kindByte = kind.CONTENT_HASH
    lo = checkU32(
      bridge.intern_string(textEncoder.encode(contentHashMarker(value))),
      'value-buf::content_hash_intern_id',
      'value-buf',
      'CONTENT_HASH',
    )
  } else {
    // bigint / symbol / function — not representable as a graph value;
    // encode NULL so the wire stays well-defined.
    kindByte = kind.NULL
  }

  out.push(kindByte, 0, 0, 0)
  // value u64, little-endian (lo then hi).
  out.push(lo & 0xff, (lo >>> 8) & 0xff, (lo >>> 16) & 0xff, (lo >>> 24) & 0xff)
  out.push(hi & 0xff, (hi >>> 8) & 0xff, (hi >>> 16) & 0xff, (hi >>> 24) & 0xff)
}

/** Encode a single JS value as a standalone 12-byte value-buffer. */
export function encodeValueBuf(
  value: unknown,
  bridge: ValueBufBridge,
): Uint8Array {
  const out: number[] = []
  encodeValueRecord(value, bridge, out)
  return Uint8Array.from(out)
}

/**
 * Encode an `Array` / `Object` container into the SELF-DESCRIBING binary
 * value-buffer that `register_value_buf` ingests serde-free (causl-wasm
 * #125). The Rust decoder reads a tagged tree:
 *
 *   tag u8 — 0 Null, 1 Bool, 2 Number, 3 String, 4 Array, 5 Object
 *   Null    → (no body)
 *   Bool    → u8 (0|1)
 *   Number  → f64 bits, 8 bytes LE
 *   String  → len u32 LE, utf-8 bytes
 *   Array   → len u32 LE, then len child values
 *   Object  → len u32 LE, then len (key-string, child value) pairs
 *
 * NOTE: This must match the `register_value_buf` decoder in causl-wasm
 * `lib.rs`. Object key insertion order is preserved (causl-wasm #123).
 */
export function encodeContainerValueBuf(
  value: unknown,
  _bridge: ValueBufBridge,
): Uint8Array {
  // Tagged-type bridge (issue #28): a direct caller may pass a container
  // that still holds Set/Map/Date/Temporal. Tagging here is idempotent —
  // when `encodeValueRecord` already tagged the value, `hasTaggedTypes`
  // finds nothing and no clone happens.
  if (hasTaggedTypes(value)) {
    value = encodeTagged(value)
  }
  const out: number[] = []
  writeSelfDescribing(value, out)
  return Uint8Array.from(out)
}

const SD = {
  NULL: 0,
  BOOL: 1,
  NUMBER: 2,
  STRING: 3,
  ARRAY: 4,
  OBJECT: 5,
} as const

/**
 * Append a `u32` LE length/count to the self-describing container value-buf
 * (the wire `register_value_buf` ingests). `checkU32` names-and-checks the
 * length against the `u32` cap BEFORE the byte-decomposition, so a container
 * with `> u32::MAX` elements/bytes throws {@link WireFieldOverflowError}
 * naming the field rather than silently wrapping; the `& 0xff` / `>>> N`
 * extraction below then provably operates on an already-checked u32 (the
 * allow-listed byte-decomposition) and is byte-identical for in-range `n`.
 */
function pushU32(out: number[], n: number, field: string): void {
  checkU32(n, field, 'value-buf', 'register_value_buf')
  out.push(n & 0xff, (n >>> 8) & 0xff, (n >>> 16) & 0xff, (n >>> 24) & 0xff)
}

function pushString(out: number[], s: string, field: string): void {
  const bytes = textEncoder.encode(s)
  pushU32(out, bytes.length, field)
  for (let i = 0; i < bytes.length; i++) out.push(bytes[i]!)
}

function writeSelfDescribing(value: unknown, out: number[], depth = 0): void {
  if (value === null || value === undefined) {
    out.push(SD.NULL)
    return
  }
  if (typeof value === 'boolean') {
    out.push(SD.BOOL, value ? 1 : 0)
    return
  }
  if (typeof value === 'number') {
    out.push(SD.NUMBER)
    const buf = new ArrayBuffer(8)
    new DataView(buf).setFloat64(0, value, true)
    const u8 = new Uint8Array(buf)
    for (let i = 0; i < 8; i++) out.push(u8[i]!)
    return
  }
  if (typeof value === 'string') {
    out.push(SD.STRING)
    pushString(out, value, 'value-buf::string_len')
    return
  }
  // Bound the descent — see `cyclic-guard.ts` (#133). A cyclic value that
  // reached the self-describing encoder would recurse forever; the cap
  // throws a typed `CyclicValueError` before the stack overflows.
  guardEncodeDepth(depth, 'writeSelfDescribing')
  if (Array.isArray(value)) {
    out.push(SD.ARRAY)
    pushU32(out, value.length, 'value-buf::array_len')
    for (const el of value) writeSelfDescribing(el, out, depth + 1)
    return
  }
  if (typeof value === 'object') {
    const entries = Object.entries(value as Record<string, unknown>)
    out.push(SD.OBJECT)
    pushU32(out, entries.length, 'value-buf::object_len')
    for (const [k, v] of entries) {
      pushString(out, k, 'value-buf::object_key_len')
      writeSelfDescribing(v, out, depth + 1)
    }
    return
  }
  // bigint / symbol / function — encode NULL.
  out.push(SD.NULL)
}

/**
 * Sentinel kind byte the bridge never emits in a value-buffer record;
 * used by the read path to flag a missing/stale cell. The full-fidelity
 * `read_cell_value` extern encodes missing/stale as a NULL record, so
 * this is reserved for callers that want an explicit miss signal.
 */
export const VALUE_BUF_SENTINEL_MISSING = 0xff

/**
 * Sentinel returned by {@link decodeValueRecord} for a `CONTENT_HASH`
 * record (feat/content-hash-values). A content-hash record carries only
 * the structural hash MARKER of a container — the engine deliberately
 * holds NO copy of the container value — so the record cannot be decoded
 * back into the original JS value. The real value lives in the JS NodeId
 * read cache (authoritative for live cells), which every caller consults
 * BEFORE decoding; this sentinel therefore signals "resolve from the
 * NodeId cache" and is only ever observed on a cache MISS, which for a
 * live (registered, non-disposed) container cell cannot happen.
 */
export const CONTENT_HASH_FROM_CACHE: unique symbol = Symbol(
  'causl-content-hash-from-cache',
)

/**
 * Decode a 12-byte value-buffer record (at `offset` within `buf`) into a
 * JS value. STRING_ID resolves through the intern table; ARRAY_REF /
 * OBJECT_REF resolve through the value pool (JSON bytes → `JSON.parse`).
 *
 * `temporal` (#165) is the PER-ENGINE Temporal impl the tagged-type
 * revive uses for `Temporal.*` reconstruction; when omitted the revive
 * falls back to the module-level injection, then `globalThis.Temporal`.
 */
export function decodeValueRecord(
  buf: Uint8Array,
  offset: number,
  bridge: ValueBufBridge,
  temporal?: TemporalLike,
): unknown {
  if (offset + VALUE_BUF_RECORD_LEN > buf.length) {
    throw new Error(
      `@causl/client-ts/wasm: value-buf record truncated at offset ${offset} ` +
        `(need ${VALUE_BUF_RECORD_LEN}, have ${buf.length - offset})`,
    )
  }
  const view = new DataView(buf.buffer, buf.byteOffset + offset, VALUE_BUF_RECORD_LEN)
  const kindByte = view.getUint8(0)
  // bytes 1..4 are pad; payload u64 at byte 4.
  const lo = view.getUint32(4, true)

  switch (kindByte) {
    case kind.NULL:
      return null
    case kind.BOOL:
      return lo !== 0
    case kind.NUMBER:
      return view.getFloat64(4, true)
    case kind.STRING_ID: {
      const resolved = bridge.read_interned_string(lo >>> 0)
      if (resolved === undefined) {
        // #165 — a STRING_ID record names an interned string by id; a miss
        // means the engine handed us an unknown/stale id. Coercing that to
        // `null` silently substitutes null for what is by kind a string
        // value, hiding the marshalling bug. Fail loudly instead.
        throw new Error(
          `@causl/client-ts/wasm: value-buf STRING_ID references unknown ` +
            `interned string id ${lo >>> 0} (stale or corrupt record)`,
        )
      }
      return resolved
    }
    case kind.CONTENT_HASH:
    case kind.INPUT_EPOCH:
      // A content-hash / input-epoch (#221/#115) record carries only the
      // container's structural hash / `(slot, epoch)` change-token marker —
      // never a copy of the value, which lives in the JS NodeId cache.
      // Signal the caller to resolve from the cache (only reached on a cache
      // miss, which a live container cell never has).
      return CONTENT_HASH_FROM_CACHE
    case kind.ARRAY_REF:
    case kind.OBJECT_REF: {
      const bytes = bridge.read_pool_value(lo >>> 0)
      if (bytes === undefined) return null
      const parsed = JSON.parse(textDecoder.decode(bytes)) as unknown
      // Tagged-type bridge (issue #28): reconstruct any Set/Map/Date/
      // Temporal the encode side replaced with a tagged object. Plain
      // JSON values (and adopter objects that are not tags) pass through.
      return reviveTagged(parsed, temporal)
    }
    default:
      // Unsupported kind (PENDING / ERROR / STRING_EXTREF / sentinel).
      return null
  }
}

/** Decode a standalone 12-byte value-buffer into a JS value. */
export function decodeValueBuf(
  buf: Uint8Array,
  bridge: ValueBufBridge,
  temporal?: TemporalLike,
): unknown {
  return decodeValueRecord(buf, 0, bridge, temporal)
}
