  writeU32Checked(view, 8, gen, 'SUBSCRIBE::gen', 'SUBSCRIBE')
  writeU32Checked(view, 12, engineId, 'SUBSCRIBE::engine_id', 'SUBSCRIBE')
  writeU32Checked(view, 16, callbackId, 'SUBSCRIBE::callback_id', 'SUBSCRIBE')
