/**
 * Sentinel `payload_len` value (causl-wasm #133) that escapes to a trailing
 * `u32 extended_len`. `0xFFFF` is never a legitimate literal length for the
 * only variable-length record (`RegisterDerived`'s `8 + 8*N` is a multiple
 * of 8; `65535` is not), so the sentinel is unambiguous. Mirror of
 * `cmd_decoder::PAYLOAD_LEN_ESCAPE_SENTINEL`.
 */
export const PAYLOAD_LEN_ESCAPE_SENTINEL = 0xffff

/**
 * Largest declared length expressible LITERALLY in the `u16` `payload_len`
 * field — one below the sentinel. Lengths in `[0, 65534]` ride literally
 * (4-byte header, byte-identical to pre-#133); a length of exactly `65535`
 * or above must use the sentinel-escape (8-byte header). Mirror of
 * `cmd_decoder::MAX_LITERAL_PAYLOAD_LEN`.
 */
export const MAX_LITERAL_PAYLOAD_LEN = PAYLOAD_LEN_ESCAPE_SENTINEL - 1 // 65534

/**
 * Largest `dep_count` describable on the wire (causl-wasm #133).
 *
 * The declared length is `8 + 8 * dep_count`. Pre-#133 this was capped at
 * `u16::MAX` by the literal `payload_len` header (`(0xFFFF - 8) / 8 =
 * 8190`); #133's sentinel-escape routes any declared length `>= 0xFFFF`
 * through a trailing `u32 extended_len`, so the ceiling widens to the
 * largest `dep_count` whose `8 + 8 * dep_count` still fits in a `u32`:
 * `(2**32 - 1 - 8) / 8`, floored. Counts above THAT cannot have an honest
 * `u32` declared length and the encoder throws (mirror of
 * `cmd_decoder::REGISTER_DERIVED_MAX_DEP_COUNT`). Deriveds in `[8191,
 * REGISTER_DERIVED_MAX_DEP_COUNT]` now encode via the escape instead of
 * throwing as they did pre-#133.
 */
export const REGISTER_DERIVED_MAX_DEP_COUNT = Math.floor(
  (0xffffffff - 8) / 8,
) // 536870911

/**
 * Encode a `RegisterDerived { derived_slot, derived_gen, fn_id, deps }`
 * record (op 10, issue #101). Variable length:
 *   4 header + 8 pre-payload (derived_slot u32, derived_gen u32) +
 *   declared payload (`8 + 8*dep_count`): dep_count u32, fn_id u32, then
 *   dep_count × (slot u32, gen u32).
 *
 * `dep_count` is a `u32` LE word (causl-wasm #131). It previously was a
 * `u8` plus a 3-byte reserved pad; widening to a full `u32` reclaims that
 * pad and is wire-size-preserving and BYTE-IDENTICAL for `dep_count <
 * 256` (the low byte sits where the old `u8` did, and the pad bytes the
 * old encoder zero-initialised ARE the u32's high bytes).
 *
 * The declared `payload_len` field counts ONLY the post-pre-payload
 * bytes (`8 + 8*dep_count`) — mirroring `SetInput`'s convention where the
 * 8-byte `(slot, gen)` pre-payload is excluded from `payload_len`.
 *
 * Header framing (causl-wasm #133):
 *   - `declared <= 65534`: 4-byte header (`op u16` @0, `declared u16` @2),
 *     payload @4. BYTE-IDENTICAL to the pre-#133 encoding — every existing
 *     fixture and the cross-backend determinism gate depend on this for
 *     `dep_count <= 8190`.
 *   - `declared >= 65535`: 8-byte header (`op u16` @0, `0xFFFF u16` @2,
 *     `declared u32` @4), payload @8 — the sentinel-escape, so the real
 *     length rides in the trailing `u32 extended_len`.
 *
 * `dep_count` is capped at {@link REGISTER_DERIVED_MAX_DEP_COUNT} (the
 * `u32` declared-length ceiling); beyond it the declared length cannot be
 * carried in the `u32 extended_len` and we throw rather than emit a record
 * the Rust decoder would reject as `PayloadLenMismatch`.
 */
export function encodeRegisterDerived(
  derivedSlot: number,
  derivedGen: number,
  fnId: number,
  deps: readonly { slot: number; gen: number }[],
): Uint8Array {
  const depCount = deps.length
  // The declared length counts only the post-pre-payload bytes
  // (`8 + 8*dep_count`), exactly as before. This is what rides in the
  // header's `payload_len` (literal) or the escaped `u32 extended_len`.
  const declared = 8 + 8 * depCount
  // The declared length rides in a `u32 extended_len` when escaped. Refuse
  // to emit a record whose declared length overflows even that — the Rust
  // decoder rejects it as PayloadLenMismatch. Name the cap so the failure
  // is actionable (mirror of `cmd_decoder::REGISTER_DERIVED_MAX_DEP_COUNT`).
  if (depCount > REGISTER_DERIVED_MAX_DEP_COUNT) {
    throw new Error(
      `encodeRegisterDerived: dep_count ${depCount} exceeds the maximum ` +
        `${REGISTER_DERIVED_MAX_DEP_COUNT} describable by the u32 declared ` +
        `length (8 + 8*dep_count must fit a u32).`,
    )
  }
  // Sentinel-escape framing (causl-wasm #133): a declared length above the
  // literal u16 ceiling needs an 8-byte header carrying a trailing u32;
  // otherwise the 4-byte header stays byte-identical to pre-#133.
  const escaped = declared > MAX_LITERAL_PAYLOAD_LEN
  const headerLen = escaped ? 8 : 4
  const total = headerLen + 8 + declared
  const buf = new Uint8Array(total)
  const view = new DataView(buf.buffer)
  view.setUint16(0, op.REGISTER_DERIVED, true)
  if (escaped) {
    // op u16 @0, 0xFFFF sentinel u16 @2, declared u32 @4 (LE), payload @8.
    // `declared` is bounded by the REGISTER_DERIVED_MAX_DEP_COUNT throw above
    // (it fits a u32), so the checked write only ADDS a named trip-wire — it
    // is byte-identical for the in-range declared length.
    view.setUint16(2, PAYLOAD_LEN_ESCAPE_SENTINEL, true)
    writeU32Checked(
      view,
      4,
      declared,
      'REGISTER_DERIVED::extended_len',
      'REGISTER_DERIVED',
    )
  } else {
    // op u16 @0, declared u16 @2 (LE), payload @4. `escaped` is false only
    // when `declared <= MAX_LITERAL_PAYLOAD_LEN` (65534), so this literal
    // u16 payload_len is already guarded by the branch and never overflows.
    view.setUint16(2, declared, true)
  }
  // pre-payload: derived (slot, gen) — starts right after the header.
  writeU32Checked(
    view,
    headerLen,
    derivedSlot,
    'REGISTER_DERIVED::derived_slot',
    'REGISTER_DERIVED',
  )
  writeU32Checked(
    view,
    headerLen + 4,
    derivedGen,
    'REGISTER_DERIVED::derived_gen',
    'REGISTER_DERIVED',
  )
  // declared payload header: dep_count u32 (LE) + fn_id u32 (#131 — was a
  // u8 count + 3 pad bytes; byte-identical for dep_count < 256). dep_count is
  // additionally bounded by the REGISTER_DERIVED_MAX_DEP_COUNT throw above.
  writeU32Checked(
    view,
    headerLen + 8,
    depCount,
    'REGISTER_DERIVED::dep_count',
    'REGISTER_DERIVED',
  )
  writeU32Checked(
    view,
    headerLen + 12,
    fnId,
    'REGISTER_DERIVED::fn_id',
    'REGISTER_DERIVED',
  )
  // deps
  let off = headerLen + 16
  for (const d of deps) {
    writeU32Checked(view, off, d.slot, 'REGISTER_DERIVED::dep_slot', 'REGISTER_DERIVED')
    writeU32Checked(
      view,
      off + 4,
      d.gen,
      'REGISTER_DERIVED::dep_gen',
      'REGISTER_DERIVED',
    )
    off += 8
  }
  return buf
}

/**
 * Concatenate a list of encoded cmd records into a single buffer
 * suitable for `apply_commands(cmd_buf)`. The bridge's `CmdDecoder`
 * accepts the raw record stream directly — there is no outer envelope
 * header to prepend.
 */
export function concatCmds(parts: readonly Uint8Array[]): Uint8Array {
  let total = 0
  for (const p of parts) total += p.length
  const out = new Uint8Array(total)
  let offset = 0
  for (const p of parts) {
    out.set(p, offset)
    offset += p.length
  }
  return out
}

/**
 * Build a complete commit cmd-buf for a `(intent, writes)` pair: one
 * `BeginCommit` + one `SetInput` per write + one `EndCommit`.
 *
 * `slotFor` resolves each `NodeId` string to a stable `(slot, gen)`
 * pair — the WasmBackend mints these monotonically from its
 * `#wasmSlotRegistry` so the SAME NodeId always resolves to the SAME
 * (slot, gen) on a given engine instance. The Rust side then
 * auto-extends its `state.inputs` Vec up to `slot` on the first
 * `SetInput`.
 *
 * Performance note: the cmd-buf encoding is JS-side overhead. For
 * scenarios that issue many tiny commits the encoding cost may exceed
 * the savings from running the engine in wasm; the streaming
 * cmd-buf-batches-across-commits optimisation from the original epic
 * is out of scope for this round (separate work).
 */
export function buildCommitCmdBuf(
  intentId: number,
  writes: ReadonlyMap<
    string,
    { slot: number; gen: number; value: unknown; containerMarker?: string }
  >,
  bridge?: CmdBufValueBridge,
  intent?: string,
  originatedAt?: number,
): Uint8Array {
  // promote-commit (causl/causl-core-rs#169) — transmit the adopter's REAL
  // intent STRING into the commit window so the Rust commit-log carries it
  // (today Rust synthesises `cmd-intent-{intent_id}` from the numeric id —
  // promote-read flagged that as the commitLog-routing blocker). Intern the
  // string via the SAME bridge intern table the `SetInput` STRING_ID path uses
  // (a universal, non-cfg-gated intern id resolvable Rust-side via
  // `INTERN_TABLE.lookup`), and ride its id in the widened `BeginCommit`. With
  // no bridge (legacy scalar-only shadow path) or no intent there is nothing to
  // intern — the legacy 4-byte `BeginCommit` is emitted byte-identically.
  let intentStringId: number | undefined
  if (bridge !== undefined && intent !== undefined) {
    // #165 — memoised per bridge: an adopter re-using the same intent
    // string across commits (the common labelled-commit pattern) pays the
    // encode + FFI cross once.
    intentStringId = internStringMemo(
      bridge,
      intent,
      'BEGIN_COMMIT::intent_intern_id',
      'BEGIN_COMMIT',
    )
  }
  // #129 / #318 — the hydrate breadcrumb rides ONLY when the intent string
  // was interned (the 16-byte body includes the string-id slot); with no
  // bridge the legacy shapes are emitted byte-identically.
  const parts: Uint8Array[] = [
    encodeBeginCommit(
      intentId,
      intentStringId,
      intentStringId !== undefined ? originatedAt : undefined,
    ),
  ]
  for (const [, w] of writes) {
    const { kind: k, inline } = packInlineValue(w.value, bridge, w.containerMarker)
    parts.push(encodeSetInput(w.slot, w.gen, k, inline))
  }
  parts.push(encodeEndCommit())
  return concatCmds(parts)
}
