/**
 * @packageDocumentation
 *
 * TS-side diff-buf decoder — wasm-engine fork Round 14d.
 *
 * Mirrors the Rust-side `DiffEncoder` in
 * `causl-wasm/tools/engine-rs-bridge/src/diff_encoder.rs`. Parses the
 * binary diff stream returned by `apply_commands(cmd_buf)` so the
 * WasmBackend can assert + reconstruct the SSOT `Commit` shape.
 *
 * ## Wire shape (per epic §E.7)
 *
 * Every record is `u16 tag` + `u16 payload_len` + `payload_len` bytes of
 * payload-LE. There is no outer envelope.
 *
 * | tag | record           | payload (LE)                                                        |
 * |-----|------------------|---------------------------------------------------------------------|
 * | 1   | NodeAdded        | (skeleton today — not exercised by apply_commands)                  |
 * | 2   | NodeDisposed     | slot u32, gen u32                                                   |
 * | 3   | Committed        | time u64, intent_id u32, n_changes u32                              |
 * | 4   | NodeChanged      | slot u32, gen u32, kind u32, opaque payload[…]                      |
 * | 5   | SubscriberFired  | (skeleton today)                                                    |
 * | 6   | DerivedRecomputed| step_index u32, node_slot u32, node_gen u32, value_before VALUE_RECORD(12), value_after VALUE_RECORD(12), n_added u16, n_removed u16, added[(slot u32,gen u32)…], removed[(slot u32,gen u32)…] |
 * | 7   | Error            | code u16, _pad u16, slot u32, message_string_id u32                 |
 * | 8   | Snapshot         | (skeleton today)                                                    |
 * | 9   | ChangeTokens     | n_tokens u32, token[n] u64 (sentinel-escaped `len`; discarded)      |
 * | 10  | DerivedUnchanged | step_index u32, node_slot u32, node_gen u32 (fixed 12 B, no value/dep columns) |
 *
 * The `len` field measures payload bytes only, excluding the 4-byte
 * header. `apply_commands_inner` (Rust side) emits exactly one
 * `Committed` record per closed commit window plus N `NodeChanged`
 * records (one per node in `last_commit.changed_nodes`). The host-shim
 * today emits `kind=0` and an empty payload for `NodeChanged` — the
 * value payload is informational and the TS-side SSOT engine already
 * carries the canonical value, so the decoder treats the payload bytes
 * as opaque.
 *
 * @internal Wire-level surface — adopters use the `WasmBackend` methods.
 */

/** Diff-record tag constants — mirrors `diff_encoder::tag`. */
export const tag = {
  NODE_ADDED: 1,
  NODE_DISPOSED: 2,
  COMMITTED: 3,
  NODE_CHANGED: 4,
  SUBSCRIBER_FIRED: 5,
  DERIVED_RECOMPUTED: 6,
  ERROR: 7,
  SNAPSHOT: 8,
  // gap-1 (causl-wasm#169) — per-write §12 change-token column emitted
  // AFTER a commit's Committed + NodeChanged trail. Decoded to `unknown`
  // and discarded today (an internal wasm→JS transport detail); the
  // constant pins the tag so the sentinel-escape skip + tests can name
  // it. Mirrors `diff_encoder::tag::CHANGE_TOKENS`.
  CHANGE_TOKENS: 9,
  // causl-wasm#286 (#223 follow-up) — the value-payload-gated sibling of
  // tag-6 `DerivedRecomputed`. A Phase-D drain iteration whose derived
  // value did NOT change and whose dep set did NOT flip (the B.4
  // cutoff-skip / SameValue arm) emits this lean record in place of the
  // full tag-6 row: a fixed 12-byte payload carrying only the step-trace
  // triple (`step_index | node_slot | node_gen`), with NO value_before /
  // value_after columns and NO dep-delta columns. Mirrors
  // `diff_encoder::tag::DERIVED_UNCHANGED`.
  DERIVED_UNCHANGED: 10,
} as const

/** Decoded diff record — discriminated union per `tag`. */
export type DiffRecord =
  | {
      readonly kind: 'committed'
      readonly time: bigint
      /**
       * The JS-minted numeric commit ordinal — the same value the adopter
       * passed in the matching `BeginCommit` cmd. It is an OPAQUE ordinal,
       * NOT an interned `StringId`: do not feed it to a string-resolver
       * (the former name `intentStringId` invited exactly that mis-read,
       * which resolves a garbage string / null). The adopter's real intent
       * string is carried separately in the SSOT `Commit`. Mirrors the Rust
       * `Committed.intent_id` field (causl-wasm#239).
       */
      readonly intentId: number
      readonly nChanges: number
    }
  | {
      readonly kind: 'nodeChanged'
      readonly slot: number
      readonly gen: number
      readonly valueKind: number
      /** Opaque trailing bytes — value-kind-specific decoding handled upstream. */
      readonly payload: Uint8Array
    }
  | {
      readonly kind: 'nodeDisposed'
      readonly slot: number
      readonly gen: number
    }
  | {
      /**
       * Tag-6 `DerivedRecomputed` — one row per Phase D Kahn-drain
       * iteration whose derived value CHANGED or whose dep set flipped.
       * Mirrors the Rust `PhaseStep::RecomputeAffected` sextuple emitted by
       * `DiffEncoder::write_recompute_affected`. Since causl-wasm#286 a
       * cutoff-skip / SameValue iteration (value unchanged, dep set stable)
       * no longer rides this tag: it emits the lean tag-10
       * `DerivedUnchanged` record instead (see `findUnchanged`).
       */
      readonly kind: 'derivedRecomputed'
      readonly stepIndex: number
      readonly slot: number
      readonly gen: number
      /** 12-byte VALUE_RECORD — decode via `decodeValueRecord`. */
      readonly before: Uint8Array
      /** 12-byte VALUE_RECORD — decode via `decodeValueRecord`. */
      readonly after: Uint8Array
      readonly depsAdded: readonly { readonly slot: number; readonly gen: number }[]
      readonly depsRemoved: readonly { readonly slot: number; readonly gen: number }[]
    }
  | {
      /**
       * Tag-10 `DerivedUnchanged` (causl-wasm#286) — the lean,
       * value-payload-gated sibling of tag-6 `DerivedRecomputed`. Emitted
       * for a Phase-D Kahn-drain iteration whose derived value did NOT
       * change and whose dep set did NOT flip (the B.4 cutoff-skip /
       * SameValue arm). Carries ONLY the step-trace triple: the wire drops
       * the two value columns (`value_before == value_after`, so a
       * redundant refresh) and both dep-delta columns (empty). The node's
       * value is unchanged from what the mirror already holds, so the
       * decoder resolves the node by `(slot, gen)` and materialises the
       * before/after value from the live cell rather than the wire. Mirrors
       * the Rust `DiffEncoder::write_derived_unchanged` 12-byte record.
       */
      readonly kind: 'derivedUnchanged'
      readonly stepIndex: number
      readonly slot: number
      readonly gen: number
    }
  | {
      readonly kind: 'error'
      readonly code: number
      readonly slot: number
      readonly messageStringId: number
    }
  | {
      readonly kind: 'unknown'
      readonly tag: number
      readonly payload: Uint8Array
    }

/**
 * Decode a single diff buffer into a list of records. Returns the
 * records in their wire order so the caller can pair the `Committed`
 * record with its trailing `NodeChanged` window.
 *
 * Throws on a truncated header or a declared payload that overruns the
 * buffer — both indicate a wire-protocol break on the bridge side.
 */
export function decodeDiff(buf: Uint8Array): readonly DiffRecord[] {
  const records: DiffRecord[] = []
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  let pos = 0
  while (pos < buf.length) {
    if (buf.length - pos < 4) {
      throw new Error(
        `@causl/client-ts/wasm: diff-buf truncated header at offset ${pos} ` +
          `(need 4 bytes, got ${buf.length - pos})`,
      )
    }
    const recordTag = view.getUint16(pos, true)
    const rawLen = view.getUint16(pos + 2, true)
    // `payload_len` sentinel-escape (causl-wasm#169, mirrors the cmd-buf
    // #133 RegisterDerived fan-in escape): the `u16` `len` field caps a
    // record's literal payload at 65534 bytes. A `len` of `0xFFFF` is the
    // SENTINEL — the real payload length rides in a trailing `u32
    // extended_len`, growing the header from 4 to 8 bytes. Lengths in
    // [0, 65534] are literal (byte-identical to pre-widen). The escape is
    // currently only emitted by the ChangeTokens (tag 9) record on a
    // large commit (> 8191 changed nodes); since ChangeTokens is routed
    // to `unknown`/discarded, this is purely correct SKIPPING so a
    // FOLLOWING record in a multi-commit/batched-flush buffer still
    // decodes past the widened span.
    const PAYLOAD_LEN_ESCAPE_SENTINEL = 0xffff
    let payloadLen: number
    let headerLen: number
    if (rawLen === PAYLOAD_LEN_ESCAPE_SENTINEL) {
      if (buf.length - pos < 8) {
        throw new Error(
          `@causl/client-ts/wasm: diff-buf truncated escaped header at offset ${pos} ` +
            `(need 8 bytes for the 0xFFFF sentinel + u32 extended_len, ` +
            `got ${buf.length - pos})`,
        )
      }
      payloadLen = view.getUint32(pos + 4, true)
      headerLen = 8
    } else {
      payloadLen = rawLen
      headerLen = 4
    }
    const after = pos + headerLen
    if (after + payloadLen > buf.length) {
      throw new Error(
        `@causl/client-ts/wasm: diff-buf truncated payload at offset ${pos} ` +
          `(tag=${recordTag}, declared=${payloadLen}, available=${buf.length - after})`,
      )
    }
    const payload = buf.subarray(after, after + payloadLen)
    const pView = new DataView(
      payload.buffer,
      payload.byteOffset,
      payload.byteLength,
    )
    switch (recordTag) {
      case tag.COMMITTED:
        records.push({
          kind: 'committed',
          time: pView.getBigUint64(0, true),
          // Offset 8: opaque numeric commit ordinal, NOT a StringId
          // (causl-wasm#239). Wire bytes unchanged — name-only fix.
          intentId: pView.getUint32(8, true),
          nChanges: pView.getUint32(12, true),
        })
        break
      case tag.NODE_CHANGED:
        records.push({
          kind: 'nodeChanged',
          slot: pView.getUint32(0, true),
          gen: pView.getUint32(4, true),
          valueKind: pView.getUint32(8, true),
          payload: payload.slice(12),
        })
        break
      case tag.NODE_DISPOSED:
        records.push({
          kind: 'nodeDisposed',
          slot: pView.getUint32(0, true),
          gen: pView.getUint32(4, true),
        })
        break
      case tag.DERIVED_RECOMPUTED: {
        // Sextuple payload (LE), offsets within the payload:
        //   0  step_index   u32
        //   4  node_slot    u32
        //   8  node_gen     u32
        //   12 value_before VALUE_RECORD (12 B)
        //   24 value_after  VALUE_RECORD (12 B)
        //   36 deps_added_count   u16
        //   38 deps_removed_count u16
        //   40 deps_added[]   added × (slot u32, gen u32)
        //   …  deps_removed[] removed × (slot u32, gen u32)
        const stepIndex = pView.getUint32(0, true)
        const slot = pView.getUint32(4, true)
        const gen = pView.getUint32(8, true)
        // `slice` (not `subarray`) so the 12-byte records are detached
        // copies that survive a later WASM-memory growth/detach.
        const before = payload.slice(12, 24)
        const after = payload.slice(24, 36)
        const addedCount = pView.getUint16(36, true)
        const removedCount = pView.getUint16(38, true)
        // Validate the declared dep counts against the payload span BEFORE
        // driving the `getUint32` loops. The 40-byte fixed prefix carries
        // the sextuple header; each dep row is `(slot u32, gen u32)` = 8
        // bytes. A wire-drift / corruption that inflates a count would
        // otherwise walk `off` past `payload.byteLength` and surface a raw
        // `RangeError: Offset is outside the bounds of the DataView` instead
        // of this module's coherent truncated-payload throw. Mirrors the
        // Rust-side count-vs-remaining guards in
        // `engine-rs-bridge/src/value_buf_ingest.rs` + `compute_bridge.rs`.
        const declaredDepBytes = 40 + 8 * (addedCount + removedCount)
        if (declaredDepBytes > payloadLen) {
          throw new Error(
            `@causl/client-ts/wasm: diff-buf truncated DerivedRecomputed record at offset ${pos} ` +
              `(added=${addedCount}, removed=${removedCount} declare ${declaredDepBytes} ` +
              `payload bytes, available=${payloadLen})`,
          )
        }
        const depsAdded: { slot: number; gen: number }[] = []
        let off = 40
        for (let i = 0; i < addedCount; i++) {
          depsAdded.push({
            slot: pView.getUint32(off, true),
            gen: pView.getUint32(off + 4, true),
          })
          off += 8
        }
        const depsRemoved: { slot: number; gen: number }[] = []
        for (let i = 0; i < removedCount; i++) {
          depsRemoved.push({
            slot: pView.getUint32(off, true),
            gen: pView.getUint32(off + 4, true),
          })
          off += 8
        }
        records.push({
          kind: 'derivedRecomputed',
          stepIndex,
          slot,
          gen,
          before,
          after,
          depsAdded,
          depsRemoved,
        })
        break
      }
      case tag.DERIVED_UNCHANGED: {
        // causl-wasm#286 — fixed 12-byte payload (no escape path, no value
        // or dep-delta columns):
        //   0  step_index u32
        //   4  node_slot  u32
        //   8  node_gen   u32
        // The declared `len` is unconditionally 12 on the Rust side. Guard
        // it before reading so a wire-drift that mis-frames the record
        // surfaces this module's coherent throw rather than a silent
        // short-read that would resolve a garbage node. Mirrors the
        // Rust-side `read_derived_unchanged` `len != 12` rejection.
        if (payloadLen !== 12) {
          throw new Error(
            `@causl/client-ts/wasm: diff-buf malformed DerivedUnchanged record at offset ${pos} ` +
              `(declared ${payloadLen} payload bytes, expected the fixed 12)`,
          )
        }
        records.push({
          kind: 'derivedUnchanged',
          stepIndex: pView.getUint32(0, true),
          slot: pView.getUint32(4, true),
          gen: pView.getUint32(8, true),
        })
        break
      }
      case tag.ERROR:
        records.push({
          kind: 'error',
          code: pView.getUint16(0, true),
          // _pad u16 at offset 2 — skipped
          slot: pView.getUint32(4, true),
          messageStringId: pView.getUint32(8, true),
        })
        break
      default:
        records.push({
          kind: 'unknown',
          tag: recordTag,
          payload: payload.slice(0),
        })
        break
    }
    pos = after + payloadLen
  }
  return records
}

/**
 * Convenience accessor — pull the single `Committed` record (if any)
 * out of a decoded diff. `apply_commands_inner` always emits at most
 * one `Committed` per buffer (or one per closed commit window for
 * batched flows), so the helper returns the FIRST occurrence — call
 * `decodeDiff` directly if multi-commit buffers need to be walked.
 */
export function findCommitted(
  records: readonly DiffRecord[],
): Extract<DiffRecord, { kind: 'committed' }> | undefined {
  for (const r of records) if (r.kind === 'committed') return r
  return undefined
}

/**
 * Convenience accessor — pull every `NodeChanged` record out of a
 * decoded diff, in wire order. The bridge emits one record per node
 * in `last_commit.changed_nodes`, so this is the wire-shaped mirror
 * of `Commit.changedNodes`.
 */
export function findChangedNodes(
  records: readonly DiffRecord[],
): readonly Extract<DiffRecord, { kind: 'nodeChanged' }>[] {
  return records.filter(
    (r): r is Extract<DiffRecord, { kind: 'nodeChanged' }> =>
      r.kind === 'nodeChanged',
  )
}

/**
 * Convenience accessor — pull every `DerivedRecomputed` (tag 6) record
 * out of a decoded diff, in wire order. The bridge emits one record per
 * Phase D Kahn-drain iteration, so this is the wire-shaped mirror of the
 * Rust `PhaseStep::RecomputeAffected` sextuple stream. The filter is
 * position-agnostic: per-step rows precede the terminal `Committed`
 * summary, and this accessor keys on record kind, not position.
 */
export function findRecomputed(
  records: readonly DiffRecord[],
): readonly Extract<DiffRecord, { kind: 'derivedRecomputed' }>[] {
  return records.filter(
    (r): r is Extract<DiffRecord, { kind: 'derivedRecomputed' }> =>
      r.kind === 'derivedRecomputed',
  )
}

/**
 * Convenience accessor — pull every `DerivedUnchanged` (tag 10) record
 * out of a decoded diff, in wire order (causl-wasm#286). The bridge emits
 * one per Phase-D Kahn-drain iteration whose derived value did NOT change
 * and whose dep set did NOT flip — the value-payload-gated sibling of the
 * tag-6 `DerivedRecomputed` rows `findRecomputed` returns. Together the
 * two accessors reconstruct the full Kahn-drain trace the pre-gating wire
 * carried in a single tag-6 stream.
 */
export function findUnchanged(
  records: readonly DiffRecord[],
): readonly Extract<DiffRecord, { kind: 'derivedUnchanged' }>[] {
  return records.filter(
    (r): r is Extract<DiffRecord, { kind: 'derivedUnchanged' }> =>
      r.kind === 'derivedUnchanged',
  )
}

/**
 * Unpack the bigint returned by the `read_input` / `read_derived`
 * wasm-bindgen externs into a `(kind, inline)` pair. Mirrors the
 * Rust-side `pack_value` / `unpack_value` helpers in `lib.rs`.
 *
 * Layout:
 *   - bits 63..56 — `value_kind` byte (one of `cmd-buf.ts::kind`, or
 *                   0xFF for the missing/stale-generation sentinel).
 *   - bits 55..0  — `value_inline` payload (kind-specific interpretation).
 *
 * @see `cmd-buf.ts::kind` for the discriminator constants.
 * @see `cmd-buf.ts::packInlineValue` for the inverse packing.
 */
export function unpackReadResult(
  packed: bigint,
): { kind: number; inline: bigint } {
  const k = Number((packed >> 56n) & 0xffn)
  const inline = packed & 0x00ffffffffffffffn
  return { kind: k, inline }
}

/** Sentinel `value_kind` byte returned when the slot is missing or stale. */
export const READ_SENTINEL_MISSING_OR_STALE = 0xff

/**
 * Decode a packed `read_input` / `read_derived` result into a JS value.
 * Returns `undefined` for the missing/stale sentinel, `null` /
 * `boolean` / `number` for the inline-decodable kinds, and a string
 * placeholder `'[wasm: string slot — not inline-decodable]'` for the
 * STRING_ID / ARRAY_REF / OBJECT_REF kinds (whose payloads live in the
 * intern table / value pool that the WasmBackend does not yet thread).
 */
export function decodeReadResult(packed: bigint): unknown {
  const { kind, inline } = unpackReadResult(packed)
  if (kind === READ_SENTINEL_MISSING_OR_STALE) return undefined
  switch (kind) {
    case 0: // NULL
      return null
    case 1: // BOOL
      return inline !== 0n
    case 2: {
      // NUMBER — reinterpret the 8 low bytes as IEEE-754 f64. Note the
      // documented lossy edge case in `lib.rs::pack_json_value` — the
      // high 8 bits of `f.to_bits()` are overwritten by the kind tag,
      // so any ordinary-magnitude f64 loses information through this
      // packing on the WASM side. Adopters who need bit-exact f64
      // reads must take a slow path.
      const buf = new ArrayBuffer(8)
      const view = new DataView(buf)
      view.setBigUint64(0, inline, true)
      return view.getFloat64(0, true)
    }
    default:
      // STRING_ID / ARRAY_REF / OBJECT_REF / STRING_EXTREF / PENDING /
      // ERROR — slow-path TODO. The TS-side SSOT engine is the
      // canonical value source today; this branch is reachable only
      // when adopters drive `read_input` / `read_derived` directly.
      return undefined
  }
}
