/**
 * Options accepted by `loadWasmBackend()`.
 */
export interface WasmBackendOptions {
  /**
   * Override the bridge picker. Defaults to `detectBridge()` —
   * probes the host and picks the fastest supported artifact.
   *
   * Adopters with a known target (e.g. internal Node 24 service
   * with WasmGC) can pin a bridge to skip detection cost and
   * shrink the build.
   */
  readonly bridge?: BridgeId

  /**
   * Override the base URL the WASM artifact is fetched from.
   *
   * Defaults to the package-relative URL resolved through the
   * bundler's `import.meta.url` mechanism (works in webpack 5 +
   * `experiments.asyncWebAssembly`, Vite 5 + `vite-plugin-wasm`,
   * esbuild 0.20 + `--loader:.wasm=file`, and Node 22+ ESM).
   *
   * Set this to a CDN URL (e.g.
   * `https://cdn.jsdelivr.net/npm/@causl/core@<ver>/wasm/`) when
   * the host CSP `connect-src` directive forbids same-origin
   * fetches of `.wasm` blobs. Adopters MUST whitelist the chosen
   * origin explicitly — the loader does not auto-fallback.
   */
  readonly wasmBaseUrl?: string

  /**
   * `fetch` override for non-browser/non-Node environments
   * (Cloudflare Workers, Deno without `--allow-net`, test
   * harnesses). Defaults to the global `fetch`.
   */
  readonly fetch?: typeof fetch

  /**
   * Optional `name` passed through to the underlying engine when
   * constructing the wrapped `Graph`. Used by the cross-backend
   * determinism gate (#685) and the migration round-trip suite
   * (#687): two backends must share a `graphId` for byte-equal IR
   * comparison, and the gate works around it by threading the same
   * name through both engines.
   *
   * Defaults to `'@causl/client-ts/wasm:<bridge>'` so unrelated callers
   * cannot accidentally collide with a TS-engine instance that uses
   * the default-minted name. Adopters who want migration between TS
   * and WASM backends pass the same `name` to `createCausl({ name })`
   * and `loadWasmBackend({ graphName: name })`.
   */
  readonly graphName?: string

  /**
   * C.4 (#1505) — per-graph batched-flush opt-in. Omitting this is
   * byte-identical to dev `b15069fa` (the load-bearing C.4 acceptance
   * property — no queue installed, pre-C.3 per-commit shadow path
   * unchanged). When supplied, a {@link BatchedFlush} queue is
   * installed on the returned backend with the configured `afterN` /
   * `intervalMs`. Per-graph, not global (option-c doc §2.3). No
   * adopter-visible perf change at v1.x even when opted in — the JS
   * engine remains SSOT; scaffolding for a future v2.x Rust-SSOT
   * cutover.
   */
  readonly batchedFlush?: BatchedFlushOptions

  /**
   * V2.1 (#1519) — per-graph Rust-SSOT cutover opt-in (epic #1515,
   * V2-DESIGN §2). Selects which side's post-state the WASM-side
   * mirror trusts at the batched-flush boundary:
   *
   *   - `'js-ssot'` (default) — the current behaviour: the TS engine
   *     is canonical, the Rust `commit_batch` result is discarded
   *     into the shadow mirror (the F-marshal.5 / #1493 C.3 path).
   *   - `'rust-ssot'` — opt in to the v2.x cutover surface: the Rust
   *     post-state is the candidate canonical for the WASM-side
   *     mirror at flush, validated byte-identical against the
   *     always-on JS-SSOT shadow first (the compare guard lands in
   *     V2.2; promotion is gated to V2.4 — V2.1 only adds the
   *     surface + threading).
   *
   * **Omitting `engine` (or passing `'js-ssot'`) is byte-identical
   * to dev `97da8420`** — the load-bearing V2.1 acceptance property
   * (V2-DESIGN §2.2). `engine: 'rust-ssot'` is purely additive,
   * per-graph, zero-codemod, zero-deprecation, default-off.
   *
   * `engine: 'rust-ssot'` does NOT imply a batched-flush window.
   * #163 — the shipped rust-ssot engine ({@link AuthoritativeWasmEngine})
   * crosses the wire per commit and never consults `batchedFlush`, so
   * auto-baking a default `afterN` here advertised amortised batching the
   * default path does not perform (dead configuration). `batchedFlush`
   * stays a purely explicit per-graph wire-tempo opt-in (it drives the
   * shadow/marshaler queue exercised by the cross-backend gate), never a
   * rust-ssot default.
   *
   * **No adopter-visible perf change and no perf win at v2.x.** The
   * Rust-engine-in-WASM per-commit execution cost is ~85x the TS
   * engine at current WASM maturity (#1479 comment 4455257530), a
   * property of today's runtime (no GC GA, limited JIT, no SIMD)
   * that #1493's batching provably cannot amortise. v2.x is
   * future-facing infrastructure behind this opt-in plus the
   * V2-DESIGN §3 maturity tripwire; the #1133 falsification is NOT
   * refuted. Promotion of the default to `'rust-ssot'` is a
   * tripwire-gated future decision explicitly out of epic #1515
   * scope (V2-DESIGN §2.2 / §5 point 6).
   */
  readonly engine?: WasmEngineMode

  /**
   * lift-readat (causl/causl-core-rs#170) — bound on the wrapped TS
   * `#graph`'s commit-history retention ring. Mirrors
   * {@link import('../src/types.js').CreateCauslOptions.commitHistoryCap}.
   * Threaded into the wrapped engine so the same-timeline TS oracle
   * mirrors the Rust engine's retention window — load-bearing for the
   * `readAt` / `snapshotAt` byte-identity invariant (the js-ssot oracle
   * vs the rust-ssot Rust extern on the IDENTICAL seed-inclusive
   * commit timeline). Omitting it keeps the pre-lift-readat default
   * (cap 0 — dead retention).
   */
  readonly commitHistoryCap?: number

  /**
   * lift-readat (#170) — bound on the wrapped TS `#graph`'s per-commit
   * snapshot retention buffer (the `readAt` / `snapshotAt` window).
   * Mirrors
   * {@link import('../src/types.js').CreateCauslOptions.snapshotRetentionCap}.
   * See {@link commitHistoryCap}.
   */
  readonly snapshotRetentionCap?: number
}

/**
 * V2.1 (#1519) — the per-graph engine-canonicality discriminant.
 *
 *   - `'rust-ssot'` — DEFAULT (since the §18A.7 GO flip). The Rust
 *     post-state is the canonical authority for the WASM-side mirror
 *     and the adopter-facing `Commit`; it is applied UNCONDITIONALLY
 *     at the batched-flush boundary (§18A.8 fail-safe-removal,
 *     causl/causl-core-rs#169 — no per-flush TS-vs-Rust byte-compare,
 *     no rollback, no sticky-downgrade). The cross-backend
 *     determinism gate (§18A.1.1) is the sole correctness guarantee.
 *   - `'js-ssot'` — the explicit TS-engine FLOOR opt (§18A.7
 *     Criterion 5). Routes commit through the wrapped TS engine
 *     directly; byte-identical to dev `97da8420`. Retained as a
 *     supported adopter option (and the value-of-record in
 *     `causl-ts-wasm-engine`).
 *
 * Mirrors the existing `backend: 'js' | 'auto'` discriminant shape
 * (`packages/core/src/types.ts:754`) — an `engine` sibling on the
 * WASM path adopters already program against. NOT a flag on
 * `batchedFlush` (that knob is contractually a wire-tempo control,
 * not an SSOT switch — V2-DESIGN §2.1 reason 1) and NOT an
 * env/build flag (must be per-graph + a runtime config flip for the
 * Decision 6 rollback story — V2-DESIGN §2.1 reason 3).
 */
export type WasmEngineMode = 'js-ssot' | 'rust-ssot'

/**
 * V2.1 (#1519) — the default engine canonicality when `engine` is
 * omitted. Pinned as a named constant so the load-bearing
 * byte-identity acceptance test (`wasm-v2.1-byte-identity.test.ts`)
 * and the `instantiateBackend` threading reference one source of
 * truth.
 *
 * **promote-default (causl/causl-core-rs#169) — FLIPPED to `'rust-ssot'`
 * 2026-06-21; fail-safe REMOVED (§18A.8, causl/causl-core-rs#169).** The
 * §18A.7 GO/NO-GO promotion gate is met (all five criteria GO; SPEC
 * §18A.7.amendment / §17.6 Commitment 15), so the default value-of-record
 * for the WASM path is the Rust engine: `createCausl()` /
 * `createCauslWasm()` route commit through the Rust engine by default and
 * the Rust post-state is applied UNCONDITIONALLY at the batched-flush
 * boundary. The §18A.8 fail-safe-removal amendment retired the TS-vs-Rust
 * per-flush byte-compare ORACLE and the V2.5 (#1544) sticky-downgrade
 * fail-safe: there is no per-flush compare, no rollback, and no demotion
 * back to `js-ssot`; rust-ssot is now the unconditional canonical engine.
 * The CI-blocking cross-backend determinism gate (§18A.1.1, 0-divergence)
 * is the sole guarantee that the Rust engine matches the TS reference.
 * The wrapped TS `#graph` is RETAINED as the SSOT for `read`/`subscribe`/
 * `exportModel` and for structural/disposal validation (its commit is no
 * longer the byte-compare oracle). The `'js-ssot'` floor stays available
 * as an explicit per-graph opt (`engine: 'js-ssot'`) and as the
 * value-of-record in `causl-ts-wasm-engine` (§18A.7 Criterion 5).
 */
export const DEFAULT_WASM_ENGINE_MODE: WasmEngineMode = 'rust-ssot'

/**
 * Concurrent-safe module-level cache: multiple callers racing
 * `loadWasmBackend()` share one compile.
 *
 * Per-bridge keyed; pinning a different bridge across calls forces
 * a new compile (a deliberate choice — adopters who pin should
 * pin once at bootstrap).
 */
const modulePromiseByBridge = new Map<BridgeId, Promise<BackendEngine>>()

/**
 * Public reset hook for tests. Not part of the supported API; kept
 * out of the production barrel intentionally (no `export *` from
 * here).
 *
 * @internal
 */
export function __resetWasmBackendCacheForTests(): void {
  // #111 — dispose every still-live engine BEFORE dropping the shared instance,
  // so each engine's per-`engineId` handler registrations are removed from the
  // sidecar's module-level maps (which survive this reset — they live in the
  // separately-imported compute-imports snippet). Previously the reset dropped
  // the compile/instance caches but LEAKED the live engines, so a fresh preload
  // + construct still shared a sidecar map polluted with dead engines' handlers.
  for (const ref of liveWasmBackends) {
    ref.deref()?.disposeAuthoritativeEngine()
  }
  liveWasmBackends.clear()
  modulePromiseByBridge.clear()
  // §18A.12 — also drop the preload caches (in-flight compile, resolved
  // slot, default-bridge pointer) so a subsequent preloadCauslWasm() /
  // createCauslWasmSync() call is observed in isolation. This is also the
  // seam an HMR-dispose hook wires into.
  compiledModuleByBridge.clear()
  // #144 — drop the preload fingerprints in lockstep with the compile cache
  // so a post-reset re-preload is never misjudged a conflicting re-preload.
  preloadFingerprintByBridge.clear()
  resolvedModuleByBridge.clear()
  defaultPreloadedBridge = undefined
  // #146 — advance the cache GENERATION so any handle resolved before this reset
  // is now STALE: the sync factory rejects it (its shared instance + glue are
  // torn down below) instead of re-instantiating over the dead ESM glue.
  cacheEpoch += 1
  // mux-6b — drop the ONE shared wasm instance per bridge so the next
  // preload+construct rebuilds a fresh instance (fresh glue heap + clean
  // ENGINE_STATES / INTERN_TABLE / VALUE_POOL). Cleared in lockstep with the
  // compile caches so an HMR-dispose / test reset is observed in isolation.
  sharedInstanceByKey.clear()
  sharedInstancesReset.clear()
  // #147 — drop the imported-glue-href log so the leak-confinement gate observes
  // each reset generation in isolation. `sidecarCompileEpoch` is deliberately
  // NOT reset: it advances monotonically so the post-reset recompile busts to a
  // pristine-heap glue (epoch > 0) rather than re-pointing the stale ESM-cached
  // epoch-0 glue.
  importedSidecarHrefs.length = 0
}

/**
 * Pick the bridge the loader instantiates. This is the wasm-artefact SELECTOR
 * (distinct from the main-bundle host-capability probe `detectBridge()` /
 * `detectFeatures()` in `src/bridge.ts`).
 *
 * `wasmgc-classic` is the SOLE bridge shipped in the default tarball, so this
 * selector resolves to it unconditionally. Its `classic-strings` build needs no
 * `wasm:js-string` host support, so it instantiates on every WasmGC-capable host
 * we ship for — making it the only defensible default target. The
 * `wasmgc-builtins` tree is NO LONGER packed by default (#147): it was
 * unreachable through this selector (it was never returned here) yet added
 * ~712 KB + a sidecar to every install. It remains an OPT-IN target — an adopter
 * who vendors the `wasm-pkg/gc-builtins-bundler` tree and serves it can still
 * reach it by explicitly pinning `{ bridge: 'wasmgc-builtins' }`.
 *
 * The chosen bridge string is what `wasmUrlFor()` keys on; the two artifact
 * directories (`gc-builtins`, `gc-classic`) mirror the {@link BridgeId} values
 * exactly. The legacy `serde-json` bridge was retired with the split-crate
 * `engine_rs` lineage (issue #10) — the consolidated `causl-engine-bridge` crate
 * produces only the two WasmGC feature variants.
 *
 * A full host-capability artefact probe (WasmGC + `wasm:js-string` detection to
 * auto-prefer `wasmgc-builtins` where BOTH the host supports it AND the tree is
 * vendored) is the cross-cutting #691 / #692 scope; it would only earn its keep
 * once a second bridge is shipped by default again. This selector deliberately
 * does NOT probe on the hot path (the loader awaits it) — a genuinely
 * WasmGC-incapable host is surfaced instead by the #108 preload path, where the
 * loader's `WebAssembly.compile` reject is caught as the §18A.13.1 capability
 * failure (loud one-time warn/telemetry + capability marker) rather than guessed
 * at here.
 */
export async function detectBridge(): Promise<BridgeId> {
  return 'wasmgc-classic'
}

/**
 * The wasm artefact filename `wasm-pack` emits for the consolidated
 * `causl-engine-bridge` crate (`[lib].name = causl_engine_bridge`),
 * identical for both feature variants. Replaces the legacy split-crate
 * per-bridge `engine_rs_bg.wasm` filename (issue #10).
 */
export const CONSOLIDATED_BRIDGE_ARTEFACT_FILENAME =
  'causl_engine_bridge_bg.wasm'

/**
 * Resolve the URL of the `.wasm` artifact for a bridge.
 *
 * The two artifact paths mirror the directories produced by the
 * `wasm-pack` build pipeline (issue #10), both emitting the
 * consolidated `causl_engine_bridge_bg.wasm`:
 *
 *   - `wasmgc-builtins` → `./pkg/gc-builtins/causl_engine_bridge_bg.wasm`
 *   - `wasmgc-classic`  → `./pkg/gc-classic/causl_engine_bridge_bg.wasm`
 *
 * The `new URL(..., import.meta.url)` pattern is the lowest common
 * denominator across webpack 5, Vite 5, esbuild, and Node ESM —
 * it survives every bundler we ship for without per-bundler
 * configuration.
 *
 * @internal exported for tests + the documented `wasmBaseUrl`
 * override path.
 */
export function wasmUrlFor(bridge: BridgeId, baseUrl?: string): URL {
  const segment = bridgeArtifactSegment(bridge)
  const file = `${segment}/${CONSOLIDATED_BRIDGE_ARTEFACT_FILENAME}`
  if (baseUrl) {
    // Trailing slash: be lenient.
    const base = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`
    // A root-relative (`/wasm/`) or relative (`./wasm/`) base carries no
    // scheme, so `new URL(file, base)` would throw `TypeError: Invalid
    // base URL` — surfacing as an opaque `WasmEngineUnavailableError`.
    // Browsers must resolve such a base the way an `<img src>` would:
    // against `document.baseURI` / `location.href`. Resolve the base
    // first (against the document/location URL in the browser, or the
    // module URL under Node ESM), then resolve the artefact file against
    // that. An already-absolute base (`https://…`, `file:…`) is returned
    // verbatim by this first `new URL`, so the CDN path is unchanged.
    // Node callers still need an absolute `file:`/`http(s)` base when no
    // `location` exists (a bare relative base resolves against the
    // loader's own module URL, which is rarely what they want).
    const resolvedBase = new URL(base, resolveBaseOrigin())
    return new URL(file, resolvedBase)
  }
  // Bundler-resolved path. Each bundler rewrites this to the
  // emitted asset URL (webpack: asset module; Vite: ?url; esbuild:
  // file loader; Node: file:// URL).
  return new URL(`./pkg/${file}`, import.meta.url)
}

/**
 * The document/location URL a scheme-less {@link WasmBackendOptions.wasmBaseUrl}
 * (e.g. the natural same-origin `'/wasm/'`) is resolved against, mirroring how a
 * browser resolves an `<img src>` or `<script src>` — `document.baseURI` when a
 * DOM is present, else `location.href`. Under Node ESM (no `location`) it falls
 * back to this loader module's own URL, so an absolute `file:`/`http(s)` base is
 * still required there for a meaningful result.
 */
function resolveBaseOrigin(): string {
  const doc = (globalThis as { document?: { baseURI?: string } }).document
  if (typeof doc?.baseURI === 'string' && doc.baseURI.length > 0) {
    return doc.baseURI
  }
  const loc = (globalThis as { location?: { href?: string } }).location
  if (typeof loc?.href === 'string' && loc.href.length > 0) {
    return loc.href
  }
  return import.meta.url
}

function bridgeArtifactSegment(bridge: BridgeId): string {
  switch (bridge) {
    case 'wasmgc-builtins':
      return 'gc-builtins'
    case 'wasmgc-classic':
      return 'gc-classic'
    default:
      // Forward-compat: future bridges (e.g. SharedMemoryBridge)
      // ship a directory whose name matches the id verbatim. The
      // loader is happy to resolve that without code change.
      return bridge
  }
}

/**
 * #146 — collapse every alias/segment spelling of a bridge to ONE canonical id
 * so the preload caches hold exactly ONE instance per underlying artefact.
 *
 * `resolveDefaultWasmBase` rewrites a requested id to its on-disk artefact
 * SEGMENT (`wasmgc-classic` → `gc-classic-bundler`), and the resolved handle was
 * historically STAMPED with that segment while the compile cache stayed keyed by
 * the requested id. So an adopter who preloaded the requested id and then
 * re-preloaded what they read back off `handle.bridge` MISSED the cache and
 * compiled a SECOND shared instance whose resolution overwrote the first
 * handle's slot — after which the first, still-valid handle was spuriously
 * rejected by the sync factory's handle-validation seam.
 *
 * Canonicalising the cache key, the stamped `handle.bridge`, AND every public
 * lookup argument to the same value removes the alias entirely: one requested
 * spelling ⇔ one canonical id ⇔ one cached instance. The canonical form is the
 * artefact segment with the layout-B `-bundler` suffix stripped, so the
 * requested alias (`wasmgc-classic`), the bare segment (`gc-classic`) and the
 * bundler segment (`gc-classic-bundler`) all collapse to `gc-classic`.
 * `bridgeArtifactSegment(<canonical>)` is a fixed point, so the artefact still
 * resolves under both on-disk layouts and `wasmUrlFor` yields the identical URL.
 *
 * @internal
 */
function canonicalBridgeId(bridge: BridgeId): BridgeId {
  const segment = bridgeArtifactSegment(bridge)
  const BUNDLER_SUFFIX = '-bundler'
  return segment.endsWith(BUNDLER_SUFFIX)
    ? segment.slice(0, -BUNDLER_SUFFIX.length)
    : segment
}

/**
 * #146 — the CACHE-GENERATION counter (the handle "epoch"). Bumped every time
 * the preload caches are cleared (`__resetWasmBackendCacheForTests` and the
 * HMR-dispose / test-arming seams that drop the resolved slot). Every
 * {@link CauslWasmModule} is stamped with the generation it was compiled under;
 * {@link createCauslWasmSync} rejects a handle whose stamp is STALE (from a
 * cleared generation) BEFORE it can re-instantiate over a torn-down shared wasm
 * instance / stale ESM `_bg.js` glue. A handle from the CURRENT generation is
 * never rejected — so a valid handle is never spuriously invalidated.
 *
 * Distinct from {@link sidecarCompileEpoch} (a per-COMPILE glue-cache-bust
 * counter that only ever advances): this counts cache GENERATIONS and is the
 * identity a handle is validated against.
 */
let cacheEpoch = 0

/**
 * Lazy-load a bare {@link WasmBackend} `BackendEngine`.
 *
 * @remarks
 * Concurrent calls share a single module compile (per chosen bridge) via
 * `modulePromiseByBridge`.
 *
 * **IMPORTANT — this is NOT the authoritative Rust engine.** The
 * `WasmBackend` this returns wraps a plain `createCauslTs()` engine as its
 * `#graph` and does NOT attach wasm exports or enable the authoritative
 * engine (that wiring — `__attachWasmExportsForTests` +
 * `__enableAuthoritativeWasm` — lives in {@link loadAuthoritativeWasm} /
 * {@link createCauslWasm} / {@link createCauslWasmSync}). It is a legacy
 * `BackendEngine` shim used by the cross-backend determinism gate (#685) and
 * the snapshot/hydrate round-trip (#687), where the wrapped TS engine is the
 * SPEC-faithful oracle by construction.
 *
 * **Do NOT route the real wasm engine through this.** In particular, an
 * adopter reaching the Rust engine must go through `preloadCauslWasm()` + the
 * authoritative construct — never `loadWasmBackend()`. #122 retired the
 * `createCausl({ backend: 'auto' })` auto-migration that used to "migrate" onto
 * this loader: because the target is a TS wrap, that migration swapped one TS
 * engine for another under the wasm banner and never reached Rust. `'auto'` is
 * now a documented alias for the registry FLIP (wasm-when-preloaded), so this
 * loader is no longer on any adopter engine-selection path.
 *
 * The `WasmBackendUnavailableError` class is retained for the narrow case
 * where the loader is asked for a bridge id whose host preconditions are not
 * met.
 *
 * @example
 * ```ts
 * import { loadWasmBackend } from '@causl/client-ts/wasm'
 *
 * // Legacy determinism-gate shim only — NOT the Rust engine.
 * const backend = await loadWasmBackend()
 * const commit = backend.commit('intent', new Map([['x', 1]]))
 * ```
 */
export async function loadWasmBackend(
  options: WasmBackendOptions = {},
): Promise<BackendEngine> {
  const bridge = options.bridge ?? (await detectBridge())
  let cached = modulePromiseByBridge.get(bridge)
  if (cached) return cached
  cached = instantiateBackend(bridge, options)
  modulePromiseByBridge.set(bridge, cached)
  // If instantiation fails, drop the cache so the next call retries
  // (a transient fetch failure shouldn't poison the engine forever).
  cached.catch(() => modulePromiseByBridge.delete(bridge))
  return cached
}

/**
 * Async wasm-engine factory — the `@causl/client-ts/wasm` member of the explicit
 * engine trio: `createCauslTs()` (sync, the TS floor) · `createCauslWasm()`
 * (async, the wasm engine) · `createCausl()` (sync wrapper → `createCauslTs`).
 * Returns a public seven-method `Graph` whose commit / read / subscribe /
 * derived-compute run through the wasm backend for the resolved bridge.
 *
 * Shipped: the returned `Graph` runs over the REAL Rust engine via the FFI
 * bridge — the epic-B `#32` loader port (artefact loader + true
 * compile/instantiate split) has LANDED, and every adopter operation
 * resolves from Rust (§18A.3 lift, causl/causl-core-rs#170).
 *
 * §18A.12 — the factory is expressed as `preload ∘ sync`: ONE instantiate
 * codepath, provably equal to `preloadCauslWasm(); createCauslWasmSync()`,
 * zero drift. The async {@link preloadCauslWasm} resolves the artefact +
 * per-graph backend params (the ONE async seam — the real
 * `WebAssembly.compile`); the synchronous {@link createCauslWasmSync}
 * instantiates and builds the `Graph` with ZERO await. The signature is
 * back-compat-shaped against the rest of the trio so callers keep awaiting
 * it.
 *
 * @example
 * ```ts
 * import { createCauslWasm } from '@causl/client-ts/wasm'
 * const graph = await createCauslWasm()
 * const a = graph.input('a', 1)
 * graph.commit('set', (tx) => tx.set(a, 2)) // a === 2
 *
 * // Opt-in soft path — TS engine if the wasm path can't resolve (no throw):
 * const soft = await createCauslWasm({ fallbackToTs: true })
 * ```
 */
export async function createCauslWasm(
  options: AuthoritativeWasmOptions & {
    readonly create?: import('../src/types.js').CreateCauslOptions
  } = {},
): Promise<Graph> {
  // §18A.12 directive #3 — the existing async factory is re-expressed as
  // `preload ∘ sync`: ONE construct codepath, provably equal to
  // `preloadCauslWasm(); createCauslWasmSync()`, zero drift. The async
  // `preloadCauslWasm` pays the artefact resolution + compile + per-graph
  // param resolution (the ONE async seam); the synchronous
  // `createCauslWasmSync` performs the instantiate + the `Graph` wrap. The
  // signature/return are byte-identical at the public contract to the rest
  // of the engine trio.
  const { create, ...loadOpts } = options
  try {
    const handle = await preloadCauslWasm(loadOpts)
    // #82 — the preload cache reuses the COMPILE, not the per-graph params:
    // the handle's baked params are the PRELOAD caller's (the documented
    // boot inheritance for bare `createCauslWasmSync()`), while this call
    // resolves its OWN engine / graphName / batchedFlush / retention caps
    // from its own options bag. Pre-#82 the cached handle's params leaked
    // into every subsequent graph on the bridge (a `js-ssot` graph
    // constructed after a rust-ssot preload was ACTUALLY rust-ssot, and
    // vice versa).
    return constructWasmGraphSync(
      handle,
      resolvePerGraphBackendParams(loadOpts, handle.bridge),
      create ?? {},
    )
  } catch (err) {
    // The `{ fallbackToTs: true }` soft-path contract (shared flag name
    // with the sync factory): on a wasm-path resolution failure return a
    // fully-working pure-TS `Graph` instead of throwing. `preloadCauslWasm`
    // already normalised the failure to a loud `WasmEngineUnavailableError`.
    //
    // #150 — honour the fork-source-compat `fallbackToJs` ALIAS here too. The
    // async loader (`loadAuthoritativeWasm`) already accepts both spellings;
    // pre-#150 this catch consulted ONLY `fallbackToTs`, so fork-ported code
    // that passes `{ fallbackToJs: true }` threw instead of degrading.
    if (loadOpts.fallbackToTs === true || loadOpts.fallbackToJs === true) {
      return createCauslTs(create)
    }
    throw err
  }
}

/**
 * Internal entry the auto-adapt wrapper calls after it dynamically
 * `import('@causl/client-ts/wasm')`.
 *
 * The wrapper is statically reachable from `createCausl`, so any symbol it
 * names by hand lands in a consumer's MAIN bundle chunk. Calling
 * `loadWasmBackend` directly from the wrapper therefore leaks the
 * `loadWasmBackend` identifier into main and trips the bundle-no-wasm-leak
 * gate (#689 / SPEC §14.2). Routing through this thin re-export keeps the
 * `loadWasmBackend` name confined to this lazily-loaded chunk; the wrapper
 * only ever names `activateAutoMigrationBackend`, which is not a wasm-leak
 * sentinel. Behaviour is identical — it forwards straight to
 * `loadWasmBackend`.
 */
export async function activateAutoMigrationBackend(
  options: WasmBackendOptions = {},
): Promise<BackendEngine> {
  return loadWasmBackend(options)
}

/**
 * Thrown when the loader is asked for a bridge whose artefact is not
 * resolvable on this host (missing/unserved artefact tree, unmet host
 * preconditions).
 *
 * Adopters can branch on `error.code === 'CAUSL_WASM_NOT_BUILT'` (the
 * historical code value, kept stable for existing dispatch) to fall
 * back to the TS engine.
 */
export class WasmBackendUnavailableError extends Error {
  readonly code = 'CAUSL_WASM_NOT_BUILT' as const
  constructor(bridge: BridgeId) {
    super(
      `@causl/client-ts/wasm: the wasm artefact for bridge '${bridge}' is not ` +
        `resolvable on this host. The Rust engine artefact must be ` +
        `reachable at load time — on a browser/bundler host, vendor the ` +
        `wasm-pkg/<bridge>-bundler/ tree, serve it, and pass ` +
        `{ wasmBaseUrl, computeImportsUrl }; on Node, a source/linked ` +
        `checkout resolves wasm-pkg/ zero-config (see wasm/README.md).`,
    )
    this.name = 'WasmBackendUnavailableError'
  }
}

// ---------------------------------------------------------------------------
// §18A.12 — preload + sync-factory split (epic causl-client#29, issue #30).
//
// Mirrors the fork's (`causl-ts-wasm-engine`) §18A.12 public surface so the
// API is consistent across both repos (xldatagrid + future consumers see ONE
// contract): `preloadCauslWasm` (the ONE async seam, idempotent),
// `createCauslWasmSync` (FULLY SYNCHRONOUS — zero await at the construct
// site, suitable for synchronous React render/hooks and synchronous SSR),
// the synchronous peeks `isCauslWasmPreloaded` / `getPreloadedCauslWasm`,
// the `CauslWasmModule` handle, and the `CauslWasmNotPreloadedError`
// loud-fail.
//
// SHIPPED REALITY (issue #68 doc refresh) — the epic-B #32 loader port has
// LANDED. This loader is the authoritative one; nothing here wraps the TS
// engine on the explicit wasm path:
//
//   - `preloadCauslWasm` resolves the artefact base (Vite-safe), runs the ONE
//     true async `WebAssembly.compile` over the real Rust→wasm bridge bytes,
//     dynamic-imports the wasm-bindgen `_bg.js` sidecar + the
//     `causl-compute-imports.js` snippet, and resolves the per-graph backend
//     params — the frozen handle carries `module` / `sidecar` / `imports` /
//     `computeImports` (the `#35`-style compile/instantiate split:
//     `compileConsolidatedBridge` / `instantiateConsolidatedBridgeSync`).
//   - `createCauslWasmSync` runs the synchronous `new WebAssembly.Instance`
//     link + the authoritative flip with ZERO await and returns a public
//     seven-method `Graph` whose every adopter operation resolves from Rust
//     (§18A.3 lift, causl/causl-core-rs#170).
// ---------------------------------------------------------------------------

/**
 * §18A.12 — options accepted by {@link preloadCauslWasm} / the re-expressed
 * {@link createCauslWasm} / the soft path of {@link createCauslWasmSync}.
 *
 * Extends {@link WasmBackendOptions} (bridge / wasmBaseUrl / fetch / graphName
 * / batchedFlush / engine) with the one opt-in the authoritative-shaped path
 * additionally exposes: `fallbackToTs`.
 *
 * (Naming vs the fork: the fork's `loadAuthoritativeWasm` / `createCauslWasm`
 * call the soft-path flag `fallbackToJs`; here it is `fallbackToTs`, matching
 * the synchronous factory's `{ fallbackToTs: true }` contract, with
 * `fallbackToJs` accepted as a source-compat alias. `computeImportsUrl` is
 * carried here too — the #32 loader port landed, so the artefact + snippet
 * resolution paths are real.)
 */
export interface AuthoritativeWasmOptions extends WasmBackendOptions {
  /**
   * WIRE (epic #31 / issue #32) — explicit URL of the
   * `causl-compute-imports.js` snippet module. When omitted the factory
   * resolves it relative to the wasm artefact's directory by scanning
   * `<bridge>/snippets/<hash>/` (the wasm-pack bundler-target layout).
   * Supply this when your bundler emits the snippet at a known asset URL.
   */
  readonly computeImportsUrl?: string | URL

  /**
   * Opt-in soft fallback to the pure-TS engine when the wasm path cannot
   * be resolved.
   *
   * **DEFAULT `false` — an explicit wasm request THROWS LOUD on failure.**
   * A consumer that asked for the wasm engine must never silently run on
   * TS, so an unresolvable path raises a {@link WasmEngineUnavailableError}
   * (or, on the sync factory with nothing preloaded, a
   * {@link CauslWasmNotPreloadedError}) — NOT a silent degrade.
   *
   * Set `true` only when you TRULY want the soft path: a wasm-path failure
   * returns a fully-working pure-TS `Graph` (`createCauslTs()`) instead of
   * throwing. The TS floor is NOT byte-identical to rust-ssot — its derived
   * containers are fresh JS references, not the engine's stored markers — but
   * it matches the engine's observable commit/notify SEMANTICS: identical
   * `changedNodes` and subscriber fire-counts, including the structural
   * derived-container cutoff (#125), so a reference-fresh but structurally-
   * equal container recompute notifies the same on both engines. The legacy
   * `createCausl({ backend: 'js' | 'auto' })` paths are unaffected by this
   * flag.
   */
  readonly fallbackToTs?: boolean

  /**
   * Fork source-compat alias for {@link fallbackToTs}. The fork's
   * `loadAuthoritativeWasm` / `createCauslWasm` name the soft-path flag
   * `fallbackToJs`; accept it here so code written against the fork's
   * surface keeps working. `fallbackToTs` takes precedence when both are
   * supplied.
   */
  readonly fallbackToJs?: boolean
}

/**
 * wasm load robustness — thrown when the wasm engine was EXPLICITLY
 * requested ({@link preloadCauslWasm} / {@link createCauslWasm} /
 * {@link createCauslWasmSync}) but the wasm path could not be resolved AND
 * the caller did NOT opt into the soft path (`{ fallbackToTs: true }`).
 *
 * The whole point of this error is HONESTY: a consumer that asked for the
 * wasm engine must never silently end up running on TS. Adopters who truly
 * want the soft path pass `{ fallbackToTs: true }`.
 *
 * The {@link CauslWasmNotPreloadedError} thrown by the synchronous factory
 * is a subclass of this family; branch on `error.code` (the base carries
 * `'CAUSL_WASM_ENGINE_UNAVAILABLE'`, the not-preloaded subclass overrides
 * it to `'CAUSL_WASM_NOT_PRELOADED'`).
 */
export class WasmEngineUnavailableError extends CauslError {
  override name = 'WasmEngineUnavailableError'
  // The declared type admits the §18A.12 subclass code so
  // {@link CauslWasmNotPreloadedError} can `override` it (the base
  // instances still carry the literal `'CAUSL_WASM_ENGINE_UNAVAILABLE'`
  // value — branching on `error.code === 'CAUSL_WASM_ENGINE_UNAVAILABLE'`
  // is unchanged).
  readonly code:
    | 'CAUSL_WASM_ENGINE_UNAVAILABLE'
    | 'CAUSL_WASM_NOT_PRELOADED' = 'CAUSL_WASM_ENGINE_UNAVAILABLE'
  /** The underlying resolution failure, if any. */
  readonly cause?: unknown
  constructor(detail: string, cause?: unknown) {
    super(
      `@causl/client-ts/wasm: the wasm engine was explicitly requested but ` +
        `could not be loaded — refusing to silently fall back to the TS ` +
        `engine.\n\n${detail}\n\n` +
        `The wasm engine is the REAL Rust engine (rust-ssot, the production ` +
        `default); this failure means the artefact was not resolvable or ` +
        `not instantiable on THIS host — not that wasm support is ` +
        `unshipped. On a browser/bundler host (e.g. Vite), vendor the ` +
        `wasm-pkg/<bridge>-bundler/ tree, serve it, and pass ` +
        `{ wasmBaseUrl, computeImportsUrl } to preloadCauslWasm(). To opt ` +
        `into the soft path (a pure-TS Graph instead of this throw), pass ` +
        `{ fallbackToTs: true }.`,
    )
    this.name = 'WasmEngineUnavailableError'
    if (cause !== undefined) this.cause = cause
  }
}

/**
 * §18A.12 — thrown by {@link createCauslWasmSync} when NOTHING has been
 * preloaded for the resolved bridge and the caller did NOT opt into the
 * `{ fallbackToTs: true }` soft path.
 *
 * The sync factory MUST NOT silently await: a wasm-authoritative graph and
 * a TS graph differ in `read()`-identity / commit-clock (§15.1), so a silent
 * swap is a glitch-freedom hazard. Rather than block on an unresolved
 * promise mid-render, the factory throws this clear, actionable error naming
 * the remedy (`preloadCauslWasm()`) and the bridge — preserving the §18A
 * loud-fail discipline.
 *
 * Subclass of the {@link WasmEngineUnavailableError} family; branch on
 * `error.code === 'CAUSL_WASM_NOT_PRELOADED'`.
 */
export class CauslWasmNotPreloadedError extends WasmEngineUnavailableError {
  override readonly code = 'CAUSL_WASM_NOT_PRELOADED' as const
  /** The bridge the sync factory tried to resolve a handle for. */
  readonly bridge: BridgeId
  constructor(bridge: BridgeId) {
    super(
      `createCauslWasmSync() found no preloaded wasm module for bridge ` +
        `'${bridge}'. The sync factory never silently awaits — call\n` +
        `    await preloadCauslWasm({ bridge: '${bridge}' })\n` +
        `ONCE at app init (before first render that builds a wasm graph), ` +
        `then createCauslWasmSync() is fully synchronous thereafter. To ` +
        `degrade to the pure-TS engine instead of throwing, pass ` +
        `createCauslWasmSync(undefined, { fallbackToTs: true }).`,
    )
    this.name = 'CauslWasmNotPreloadedError'
    this.bridge = bridge
  }
}

/**
 * #144 — thrown by {@link preloadCauslWasm} when a bridge is re-preloaded with
 * artefact-resolution options (`wasmBaseUrl` / `computeImportsUrl` / `fetch`)
 * that CONFLICT with the options the bridge was FIRST preloaded under.
 *
 * The preload cache is keyed by resolved {@link BridgeId} and holds the FIRST
 * caller's resolved handle (the compiled module + snippet). Before this guard,
 * a second `preloadCauslWasm({ wasmBaseUrl: B })` after a
 * `preloadCauslWasm({ wasmBaseUrl: A })` short-circuited on the bridge key and
 * SILENTLY returned A's bytes — the differing artefact location / fetch was
 * dropped without a sound. (Per-graph params — `graphName` / `engine` /
 * `batchedFlush` / retention caps — are NOT a conflict: #82 has
 * `createCauslWasm` re-apply its own on every call, so they may legitimately
 * differ across calls on one bridge.)
 *
 * Re-preloading with the SAME options stays idempotent (the shared resolution
 * is returned, unchanged); only a CONFLICTING re-preload is rejected loudly so
 * the caller learns their second location/fetch/params were never honored. The
 * remedy is to reset in-process (the artefact for a given bridge is fixed for
 * the process lifetime) or to pin a DISTINCT `bridge` per artefact location.
 *
 * Subclass of {@link CauslError}; branch on
 * `error.code === 'CAUSL_WASM_PRELOAD_CONFLICT'`.
 */
export class CauslWasmPreloadConflictError extends CauslError {
  override name = 'CauslWasmPreloadConflictError'
  readonly code = 'CAUSL_WASM_PRELOAD_CONFLICT' as const
  /** The resolved bridge the conflicting re-preload targeted. */
  readonly bridge: BridgeId
  /** The option names whose values differ from the first preload. */
  readonly conflictingOptions: readonly string[]
  constructor(bridge: BridgeId, conflictingOptions: readonly string[]) {
    super(
      `@causl/client-ts/wasm: preloadCauslWasm() was called again for bridge ` +
        `'${bridge}' with option(s) that CONFLICT with the options it was ` +
        `first preloaded under: ${conflictingOptions.join(', ')}.\n\n` +
        `The preload cache is keyed by bridge and holds the FIRST caller's ` +
        `resolved module + params; a differing later call would be silently ` +
        `dropped (you would keep getting the first artefact/params), so it ` +
        `is rejected here instead. A given bridge resolves ONE artefact for ` +
        `the process lifetime — pin a DISTINCT bridge per artefact location, ` +
        `or (in tests/HMR) reset the cache before re-preloading. Re-preload ` +
        `with the IDENTICAL options is still idempotent.`,
    )
    this.name = 'CauslWasmPreloadConflictError'
    this.bridge = bridge
    this.conflictingOptions = conflictingOptions
  }
}

/**
 * §18A.12 — the opaque, frozen handle {@link preloadCauslWasm} resolves and
 * {@link createCauslWasmSync} consumes. It carries EVERYTHING the synchronous
 * backend construct needs so that step holds ZERO awaits:
 *
 *   - `bridge` — the resolved {@link BridgeId} this handle was prepared for.
 *     `createCauslWasmSync` validates this against the bridge it resolves the
 *     handle under and throws on a mismatch.
 *   - `module` — the compiled `WebAssembly.Module` (from the one async
 *     `WebAssembly.compile`).
 *   - `imports` — the resolved `WebAssembly.Imports`, already matched to the
 *     module's import descriptors (sidecar `__wbg_*` glue on the sidecar
 *     path; throw-on-call stubs on the legacy raw path).
 *   - `sidecar` — the wasm-bindgen `_bg.js` sidecar module when the sidecar
 *     path was taken (its `__wbg_set_wasm` re-point binds the instance
 *     exports + its marshaled surface IS the {@link WasmBridgeExports});
 *     `undefined` on the legacy raw path.
 *   - `computeImports` — the `causl-compute-imports.js` snippet module the
 *     authoritative engine installs its `__causl_compute` / `__causl_fire`
 *     handlers into.
 *   - the resolved per-graph backend params (`graphName`, `engineMode`,
 *     `batchedFlush`) the {@link WasmBackend} constructor needs, computed
 *     async in {@link preloadCauslWasm} so the sync factory has nothing to
 *     resolve.
 *
 * WIRE (epic #31 / issue #32) — the real loader port. The handle now carries
 * `module` / `sidecar` / `imports` / `computeImports`; `createCauslWasmSync`
 * runs the synchronous `new WebAssembly.Instance` link and the authoritative
 * flip, then `createCausl({ injectedBackend })`.
 */
export interface CauslWasmModule {
  readonly bridge: BridgeId
  /** @internal The compiled Rust→wasm bridge module. */
  readonly module: WebAssembly.Module
  /** @internal Wasm-bindgen `_bg.js` sidecar (sidecar path), else undefined. */
  readonly sidecar: BridgeSidecarModule | undefined
  /**
   * @internal mux-5/mux-6 — the `_bg.js` glue href, so each instantiation can
   * bind its OWN fresh glue (pristine externref heap). `undefined` on the raw
   * path.
   */
  readonly sidecarHref: string | undefined
  /** @internal Resolved imports object for the synchronous instantiate. */
  readonly imports: WebAssembly.Imports
  /** @internal The `causl-compute-imports.js` snippet handler-installers. */
  readonly computeImports: ComputeImportsModule
  /** @internal Resolved per-graph backend params for the sync construct. */
  readonly graphName: string
  /** @internal */
  readonly engineMode: WasmEngineMode
  /** @internal */
  readonly batchedFlush: BatchedFlushOptions | undefined
  /**
   * @internal lift-readat (causl/causl-core-rs#170) — the adopter's retention
   * caps, threaded into the wrapped TS `#graph` so the same-timeline oracle
   * mirrors the Rust retention window. `undefined` ⇒ the pre-lift-readat
   * cap-0 default.
   */
  readonly retentionCaps:
    | {
        readonly commitHistoryCap?: number
        readonly snapshotRetentionCap?: number
      }
    | undefined
  /**
   * @internal #108 — set (with the raw host-shaped WasmGC compile-reject
   * `cause`) when this handle STANDS IN for a host where the WasmGC engine
   * cannot VALIDATE the module. A capability-unavailable handle carries no live
   * `module` (its other fields are inert placeholders): every construct path
   * gates on this marker FIRST — explicit factories throw loud, the implicit
   * `createCausl()` path degrades loudly to the TS floor. Absent on a real,
   * instantiable handle.
   */
  readonly capabilityUnavailable?: { readonly cause: unknown }
  /**
   * #146 — the cache GENERATION this handle was compiled under (see
   * {@link cacheEpoch}). {@link createCauslWasmSync} rejects a handle whose stamp
   * does not match the CURRENT generation: a handle carried ACROSS a cache reset
   * points at a torn-down shared instance / stale `_bg.js` glue and MUST NOT
   * re-instantiate. A handle from the live generation matches and is never
   * spuriously rejected.
   */
  readonly epoch: number
}

/**
 * §18A.12 — the preload cache. Keyed by resolved {@link BridgeId}, holds the
 * IN-FLIGHT resolve promise so concurrent {@link preloadCauslWasm} calls
 * SHARE one resolution (idempotent). DISTINCT from the live-instance
 * {@link modulePromiseByBridge} (which caches a `BackendEngine`): this caches
 * the resolved-but-not-instantiated {@link CauslWasmModule} handle.
 *
 * Transient-failure DROPS the entry (mirrors `loadWasmBackend`'s
 * `cached.catch(() => map.delete(bridge))`) so a flaky resolution does not
 * poison the cache forever.
 */
const compiledModuleByBridge = new Map<BridgeId, Promise<CauslWasmModule>>()

/**
 * #144 — the artefact-resolution options a bridge was FIRST preloaded under,
 * kept in lockstep with {@link compiledModuleByBridge} so a later re-preload
 * can detect a CONFLICTING options bag. The cache is keyed by bridge alone
 * (many downstream sync lookups — {@link resolvedModuleByBridge},
 * {@link defaultPreloadedBridge}, the sync factory — resolve by bridge), so
 * rather than silently returning the first caller's bytes for a differing later
 * call, we compare fingerprints and throw {@link CauslWasmPreloadConflictError}
 * on a mismatch. Same-options re-preload stays idempotent. Dropped in lockstep
 * on a transient-failure eviction.
 */
const preloadFingerprintByBridge = new Map<BridgeId, PreloadFingerprint>()

/**
 * #144 — the salient subset of {@link AuthoritativeWasmOptions} that changes
 * the resolved-and-compiled artefact the handle carries: the artefact-
 * resolution inputs `wasmBaseUrl` / `computeImportsUrl` / `fetch`. These pick
 * WHICH bytes/snippet the cached module holds, so two preloads that differ on
 * them cannot share one resolution.
 *
 * Deliberately EXCLUDED:
 *   - `bridge` — it is the cache key itself.
 *   - the per-graph params (`graphName` / `engine` / `batchedFlush` / retention
 *     caps): #82 made `createCauslWasm` re-apply ITS OWN per-graph params on
 *     every call regardless of the cached handle (the handle reuses the
 *     COMPILE, not the params), and `createCauslWasm` reaches this cache via an
 *     internal `preloadCauslWasm(loadOpts)` carrying those very params — so
 *     differing per-graph params on one bridge are LEGITIMATE, not a conflict.
 *   - `fallbackToTs` / `fallbackToJs` — {@link preloadCauslWasm} never consults
 *     them, so they cannot change the resolved handle.
 *
 * @internal
 */
interface PreloadFingerprint {
  readonly wasmBaseUrl: string | undefined
  readonly computeImportsUrl: string | undefined
  /** Compared by reference identity (a function cannot be serialised). */
  readonly fetch: typeof fetch | undefined
}

/**
 * #144 — project an options bag onto its {@link PreloadFingerprint}. `URL`
 * `computeImportsUrl` values are normalised to their `href` so two calls that
 * pass an equivalent string/URL do not spuriously conflict.
 *
 * @internal
 */
function preloadFingerprintOf(
  options: AuthoritativeWasmOptions,
): PreloadFingerprint {
  const ci = options.computeImportsUrl
  return {
    wasmBaseUrl: options.wasmBaseUrl,
    computeImportsUrl:
      ci === undefined ? undefined : typeof ci === 'string' ? ci : ci.href,
    fetch: options.fetch,
  }
}

/**
 * #144 — the option names whose fingerprint values differ between the first
 * preload (`first`) and a later re-preload (`next`). Empty ⇒ the two calls are
 * equivalent and the cached resolution may be reused idempotently.
 *
 * @internal
 */
function conflictingPreloadOptions(
  first: PreloadFingerprint,
  next: PreloadFingerprint,
): string[] {
  const keys: (keyof PreloadFingerprint)[] = [
    'wasmBaseUrl',
    'computeImportsUrl',
    'fetch',
  ]
  return keys.filter((k) => first[k] !== next[k])
}

/**
 * §18A.12 — the SYNCHRONOUSLY-readable resolved slot. Set in the preload
 * promise's `.then` (NOT merely the in-flight promise) so
 * {@link isCauslWasmPreloaded} / {@link getPreloadedCauslWasm} can detect
 * resolved-ness WITHOUT awaiting — which is what makes the sync factory's
 * zero-await handle lookup possible.
 */
const resolvedModuleByBridge = new Map<BridgeId, CauslWasmModule>()

/**
 * §18A.12 — the most-recently-resolved bridge, so the no-argument
 * {@link getPreloadedCauslWasm} / {@link isCauslWasmPreloaded} (and the
 * `createCauslWasmSync()` default-handle path) resolve a bridge
 * SYNCHRONOUSLY — `detectBridge()` is async and cannot run on the sync
 * factory's hot path.
 */
let defaultPreloadedBridge: BridgeId | undefined

/**
 * §18A.12 directive #1 — the ONE async seam. Resolve the bridge (via
 * {@link detectBridge} unless pinned) and the per-graph backend params, and
 * return an opaque, frozen {@link CauslWasmModule} the synchronous
 * {@link createCauslWasmSync} consumes with zero further await.
 *
 * Call ONCE per process+bridge at app init (in the browser: BEFORE the first
 * render that builds a wasm graph). Idempotent — concurrent calls share one
 * resolution via {@link compiledModuleByBridge}; a transient failure drops
 * the cache entry so the next call retries.
 *
 * LOUD-FAIL: an unresolvable bridge/artefact throws a
 * {@link WasmEngineUnavailableError} (this is an explicit wasm request — it
 * never silently degrades). The #32 loader port LANDED: this resolves the
 * artefact base, runs the one true async `WebAssembly.compile`, and imports
 * the sidecar + compute-imports snippet. The resolution `await` happens
 * OUTSIDE any commit envelope (the §18A.6 single-tick invariant is
 * untouched — it is hoisted to bootstrap).
 *
 * @example
 * ```ts
 * import { preloadCauslWasm, createCauslWasmSync } from '@causl/client-ts/wasm'
 * const handle = await preloadCauslWasm()       // once, at app init
 * const graph = createCauslWasmSync(handle)     // sync, at every render
 * ```
 */
export async function preloadCauslWasm(
  options: AuthoritativeWasmOptions = {},
): Promise<CauslWasmModule> {
  // #146 — canonicalise the requested id BEFORE consulting the cache so every
  // alias spelling (`wasmgc-classic` / `gc-classic` / `gc-classic-bundler`)
  // shares ONE compile + ONE resolved instance. The handle is stamped with this
  // same canonical id, and the public lookups canonicalise their argument, so
  // `getPreloadedCauslWasm(handle.bridge)` (the sync factory's validation seam)
  // and any original-id lookup resolve to the identical handle — no
  // double-registration, no alias-clobber. #144 — the fingerprint conflict
  // check keys off this same canonical bridge, so a conflicting re-preload is
  // detected regardless of which alias spelling either caller used; the conflict
  // error still names the id THIS caller passed (`requested`), which they
  // recognise.
  const requested = options.bridge ?? (await detectBridge())
  const bridge = canonicalBridgeId(requested)
  const fingerprint = preloadFingerprintOf(options)
  const cached = compiledModuleByBridge.get(bridge)
  if (cached) {
    // #144 — the cache is keyed by bridge alone; a re-preload with CONFLICTING
    // artefact-/instance-resolution options would silently get the FIRST
    // caller's bytes/params. Compare the salient options and reject loudly on a
    // mismatch instead of dropping the later call's location/fetch/params.
    // Same-options re-preload stays idempotent (shared resolution returned).
    const first = preloadFingerprintByBridge.get(bridge)
    if (first !== undefined) {
      const conflicts = conflictingPreloadOptions(first, fingerprint)
      if (conflicts.length > 0) {
        throw new CauslWasmPreloadConflictError(requested, conflicts)
      }
    }
    return cached
  }
  // #108 — a WasmGC compile reject (`WebAssembly.CompileError`) is a HOST-
  // capability failure, NOT a transient/deployment one. Rejecting here throws
  // at app init on the implicit boot path (or, if caught, leaves the benign
  // not-preloaded branch to run the TS floor SILENTLY). Instead the compile is
  // wrapped so a capability failure RESOLVES a capability-unavailable sentinel
  // handle recorded as the resolved slot: `isCauslWasmPreloaded()` is then true,
  // so the implicit `createCausl()` path routes through the registry's
  // capability catch — which fires the loud one-time warn + telemetry and
  // degrades to the TS floor — rather than the SILENT not-preloaded branch.
  // (The §18A.13.1 emit is thus raised at the first `createCausl()`, the
  // amendment's permitted "there or at first createCausl()" seam, keeping the
  // main-bundle telemetry surface untouched.) Every explicit construct path
  // gates on the sentinel and still throws loud. Non-capability failures
  // (missing/unserved artefact) reject as before — a deployment problem must
  // never silently degrade.
  const compiling = compileCauslWasmModuleOrCapabilitySentinel(bridge, options)
  compiledModuleByBridge.set(bridge, compiling)
  // #144 — record the options this bridge was FIRST preloaded under, in
  // lockstep with the cache, so a later re-preload can detect a conflict.
  preloadFingerprintByBridge.set(bridge, fingerprint)
  // Record resolved-ness SYNCHRONOUSLY in the `.then` (not merely the
  // in-flight promise) so the sync factory can peek it without awaiting.
  compiling.then(
    (handle) => {
      // #146 — the cache key, `handle.bridge`, and the default-bridge pointer
      // are ALL the one canonical id, so a single `set` under `bridge` is the
      // whole registration. (`handle.bridge === bridge` by construction — see
      // `compileCauslWasmModule` — so the pre-#146 double-registration under a
      // divergent on-disk segment is gone, and with it the alias-clobber.)
      resolvedModuleByBridge.set(bridge, handle)
      defaultPreloadedBridge = bridge
    },
    // Transient-failure guard — drop the in-flight entry so the next call
    // retries (mirrors loadWasmBackend's cache-poison guard). #144 — drop the
    // fingerprint in lockstep so the retry is not judged a conflict.
    () => {
      compiledModuleByBridge.delete(bridge)
      preloadFingerprintByBridge.delete(bridge)
    },
  )
  return compiling
}

/**
 * #108 — run {@link compileCauslWasmModule} but divert a WasmGC-unavailable
 * CAPABILITY failure (`WebAssembly.CompileError` / `LinkError`, detected via
 * {@link isWasmCapabilityError}) into a resolved
 * {@link makeCapabilityUnavailableHandle} sentinel instead of a rejection. The
 * sentinel becomes the resolved slot, so the implicit `createCausl()` path
 * routes through the registry's capability catch (loud one-time warn +
 * telemetry) rather than the silent not-preloaded branch. Any OTHER failure
 * (missing/unserved artefact, wiring bug) propagates so the explicit paths keep
 * failing loud on a deployment problem.
 *
 * @internal
 */
async function compileCauslWasmModuleOrCapabilitySentinel(
  bridge: BridgeId,
  options: AuthoritativeWasmOptions,
): Promise<CauslWasmModule> {
  try {
    return await compileCauslWasmModule(bridge, options)
  } catch (err) {
    if (!isWasmCapabilityError(err)) throw err
    const cause =
      err instanceof WasmEngineUnavailableError ? (err.cause ?? err) : err
    return makeCapabilityUnavailableHandle(bridge, cause)
  }
}

/**
 * #108 — build the frozen capability-unavailable SENTINEL handle
 * {@link preloadCauslWasm} resolves when the WasmGC engine cannot compile on
 * this host. It carries the `capabilityUnavailable` marker (with the raw
 * host-shaped compile-reject `cause`) and inert placeholders for the live-
 * module fields: every construct path gates on `capabilityUnavailable` BEFORE
 * reading any placeholder, so they are never dereferenced.
 *
 * @internal
 */
function makeCapabilityUnavailableHandle(
  bridge: BridgeId,
  cause: unknown,
): CauslWasmModule {
  return Object.freeze({
    bridge,
    epoch: cacheEpoch,
    capabilityUnavailable: { cause },
    // Inert placeholders — never read (all construct paths gate on
    // `capabilityUnavailable` first). Present only to satisfy the handle shape.
    module: undefined as unknown as WebAssembly.Module,
    sidecar: undefined,
    sidecarHref: undefined,
    imports: {} as WebAssembly.Imports,
    computeImports: undefined as unknown as ComputeImportsModule,
    graphName: `causl.wasm.${bridge}`,
    engineMode: 'js-ssot' as WasmEngineMode,
    batchedFlush: undefined,
    retentionCaps: undefined,
  })
}

/**
 * The raw compile step behind {@link preloadCauslWasm}: resolve the artefact
 * base + the compute-imports snippet URL, compile the bridge
 * ({@link compileConsolidatedBridge}), dynamic-import the snippet, resolve the
 * per-graph backend params, and freeze the handle. Throws the underlying
 * error on any failure; the public {@link preloadCauslWasm} normalises it to a
 * loud {@link WasmEngineUnavailableError}.
 *
 * WIRE (epic #31 / issue #32) — ported from the fork's authoritative loader.
 * This now resolves the real Rust→wasm artefact (Vite-safe base resolution),
 * compiles the consolidated bridge, and dynamic-imports the
 * `causl-compute-imports.js` snippet so the synchronous {@link
 * createCauslWasmSync} can instantiate a REAL wasm-backed graph with zero
 * await left.
 *
 * @internal
 */
async function compileCauslWasmModule(
  bridge: BridgeId,
  options: AuthoritativeWasmOptions,
): Promise<CauslWasmModule> {
  try {
    // Vite-safe default base resolution so the zero-config (`wasmBaseUrl`
    // omitted) path resolves the vendored artefact under `wasm-pkg/`.
    let resolvedBridge: BridgeId = bridge
    let wasmBaseUrl = options.wasmBaseUrl
    if (wasmBaseUrl === undefined) {
      const base = await resolveDefaultWasmBase(bridge)
      if (base !== undefined) {
        wasmBaseUrl = base.wasmBaseUrl
        resolvedBridge = base.bridgeSegment
      }
    }
    const wasmUrl = wasmUrlFor(resolvedBridge, wasmBaseUrl)
    const compiled = await compileConsolidatedBridge(wasmUrl, options.fetch)
    if (compiled === undefined) {
      throw new WasmEngineUnavailableError(
        `the consolidated bridge artefact for bridge '${resolvedBridge}' ` +
          `could not be read or compiled (resolved URL: ${wasmUrl.href}).`,
      )
    }
    const computeImportsUrl =
      options.computeImportsUrl ??
      (await resolveComputeImportsUrl(resolvedBridge, wasmBaseUrl))
    // #121 — compute the href into ONE variable BEFORE `import(...)`. A
    // ternary AS the import argument (`import(cond ? a : b)`) is rewritten by
    // esbuild (tsup's bundler) into `cond ? import(a) : import(b)`, which
    // DETACHES the leading annotation so neither call carries it. Both magic
    // comments live inside the parens, on the single computed href: webpack 5
    // (`webpackIgnore: true`) leaves the runtime URL alone instead of building
    // an unresolvable ContextModule; Vite/esbuild (`@vite-ignore`) skip static
    // analysis of the same expression.
    const computeImportsHref =
      typeof computeImportsUrl === 'string'
        ? computeImportsUrl
        : computeImportsUrl.href
    const computeImports = (await import(
      /* webpackIgnore: true */ /* @vite-ignore */ computeImportsHref
    )) as ComputeImportsModule
    // Resolve the per-graph backend params exactly as instantiateBackend
    // does, so createCauslWasmSync has nothing async left to compute.
    // V2.1 (#1519) — `resolveWasmEngineMode` throws a RangeError on an
    // unrecognised `engine` value (fail-closed); surfaced here at preload.
    // #82 — the handle's baked per-graph params are the PRELOAD caller's
    // (consumed by the handle-driven sync factory — the documented boot
    // inheritance). Resolved through the SAME helper `createCauslWasm`
    // uses for its per-call params so the two sites can never drift.
    // #146 — the handle's default per-graph params (and its stamped id) use the
    // CANONICAL bridge, not the on-disk `resolvedBridge` segment, so
    // `handle.bridge` is coherent with the cache key and every lookup.
    const perGraph = resolvePerGraphBackendParams(options, bridge)
    return Object.freeze({
      bridge,
      epoch: cacheEpoch,
      module: compiled.module,
      sidecar: compiled.sidecar,
      sidecarHref: compiled.sidecarHref,
      imports: compiled.imports,
      computeImports,
      graphName: perGraph.graphName,
      engineMode: perGraph.engineMode,
      batchedFlush: perGraph.batchedFlush,
      retentionCaps: perGraph.retentionCaps,
    })
  } catch (err) {
    if (err instanceof WasmEngineUnavailableError) throw err
    throw new WasmEngineUnavailableError(
      err instanceof Error ? err.message : String(err),
      err,
    )
  }
}

// ---------------------------------------------------------------------------
// WIRE (epic #31 / issue #32) — the authoritative Rust→wasm loader helpers,
// ported from the fork. These resolve the vendored artefact base (Vite-safe),
// read + compile the `.wasm`, dynamic-import the wasm-bindgen `_bg.js`
// sidecar, build the import object, and (synchronously) instantiate + bind.
// ---------------------------------------------------------------------------

/**
 * Resolve the `causl-compute-imports.js` snippet URL for a bridge.
 *
 * wasm-pack's bundler target emits the snippet under
 * `<bridge>/snippets/<crate-hash>/causl-compute-imports.js` AND, in the
 * `_bg.js` glue next to the `.wasm`, statically imports that exact specifier.
 * The `<crate-hash>` segment is content-addressed and not known statically.
 *
 * #148 — we resolve the snippet from the GLUE's OWN import specifier (read the
 * `_bg.js` sidecar, match its `from './snippets/<hash>/causl-compute-
 * imports.js'`), NOT by returning the first `readdir` hit. A vendor step that
 * merges destinations without purging can leave a STALE sibling
 * `snippets/<hash>/` behind; globbing could then hand the loader snippet A
 * while the glue dispatches through snippet B, installing the per-`engineId`
 * handlers into A's module while `__causl_compute` looks them up in B — a
 * split registry that makes every derived compute return a THREW out-buffer.
 * Resolving from the glue's own specifier guarantees the loader's dynamic
 * import URL matches the glue's static import EXACTLY, so ESM dedupes both to
 * ONE snippet module and the registry can never split. Directory enumeration
 * remains only as a fallback for the (real-artefact-impossible) case where the
 * glue carries no such import.
 *
 * For non-file URLs (and for hosts whose `node:*` builtins are browser-bundler
 * stubs, issue #68) the caller must pass `computeImportsUrl` explicitly (a
 * bundler cannot read a remote directory or file) — the throw names that
 * remedy.
 *
 * @internal exported for tests (the #68 browser-stub gate).
 */
export async function resolveComputeImportsUrl(
  bridge: BridgeId,
  baseUrl: string | undefined,
): Promise<URL> {
  const wasmUrl = wasmUrlFor(bridge, baseUrl)
  // The snippets dir is a sibling of the `.wasm` file.
  const snippetsDir = new URL('./snippets/', wasmUrl)
  if (snippetsDir.protocol !== 'file:') {
    throw new Error(
      `@causl/client-ts/wasm: cannot auto-resolve causl-compute-imports.js under ` +
        `${snippetsDir.href} — the snippets/<crate-hash>/ segment is ` +
        `content-addressed and a non-file URL cannot be enumerated. Pass ` +
        `{ computeImportsUrl } pointing at the served snippet (vendor the ` +
        `wasm-pkg/<bridge>-bundler/ tree and serve it alongside ` +
        `{ wasmBaseUrl }).`,
    )
  }
  const fs = await import('node:fs/promises')
  const url2 = await import('node:url')
  // issue #68 — Vite-stubbed builtins: the imports succeed in a browser
  // bundle but the members are `undefined`. Fail with the explicit-URL
  // remedy instead of a bare TypeError.
  if (
    typeof url2.fileURLToPath !== 'function' ||
    typeof fs.readFile !== 'function' ||
    typeof fs.readdir !== 'function' ||
    typeof fs.access !== 'function'
  ) {
    throw new Error(
      `@causl/client-ts/wasm: cannot auto-resolve causl-compute-imports.js — ` +
        `this host has no usable node:fs/node:url (browser/bundler stubs). ` +
        `Pass { computeImportsUrl } pointing at the served snippet (vendor ` +
        `the wasm-pkg/<bridge>-bundler/ tree and serve it alongside ` +
        `{ wasmBaseUrl }).`,
    )
  }
  // #148 — authoritative resolution: parse the glue's own snippet import.
  const sidecarHref = sidecarHrefFor(wasmUrl)
  if (sidecarHref !== undefined) {
    const fromSidecar = await resolveSnippetFromSidecarGlue(
      new URL(sidecarHref),
      fs.readFile,
      url2.fileURLToPath,
    )
    if (fromSidecar !== undefined) return fromSidecar
  }
  // Fallback (the glue carries no `causl-compute-imports.js` import — not
  // possible for a real wasm-pack artefact, so this cannot re-introduce the
  // #148 split-registry hazard): enumerate the snippets/ dir.
  const dirPath = url2.fileURLToPath(snippetsDir)
  const hashDirs = await fs.readdir(dirPath, { withFileTypes: true })
  for (const entry of hashDirs) {
    if (!entry.isDirectory()) continue
    const candidate = new URL(
      `${entry.name}/causl-compute-imports.js`,
      snippetsDir,
    )
    const candidatePath = url2.fileURLToPath(candidate)
    try {
      await fs.access(candidatePath)
      return candidate
    } catch {
      // try next hash dir
    }
  }
  throw new Error(
    `@causl/client-ts/wasm: could not resolve causl-compute-imports.js under ` +
      `${dirPath}. Pass { computeImportsUrl } explicitly, or rebuild the ` +
      `artefact with the wasm:build pipeline.`,
  )
}

/**
 * The wasm-bindgen `_bg.js` glue's own `causl-compute-imports.js` snippet
 * import. wasm-pack's bundler target emits a single
 *   import * as … from './snippets/<crate-hash>/causl-compute-imports.js'
 * at the top of the glue (single- or double-quoted). This is the SINGLE
 * source of truth for which content-addressed hash dir the RUNNING instance
 * dispatches its `__causl_compute` / `__causl_fire` crossings through, so it is
 * what the loader must dynamic-import as `computeImports`.
 */
const SIDECAR_SNIPPET_IMPORT_RE =
  /from\s*['"]([^'"]*snippets\/[^'"]*causl-compute-imports\.js)['"]/

/**
 * #148 — resolve the `causl-compute-imports.js` snippet URL from the
 * wasm-bindgen `_bg.js` glue's OWN static import specifier, rather than by
 * enumerating the `snippets/` directory (which could return a STALE sibling
 * hash dir and split the per-`engineId` handler registry — handlers in snippet
 * A, dispatch through snippet B).
 *
 * Reads the glue file at `sidecarUrl` (a `file:` URL), matches its
 * `from './snippets/<hash>/causl-compute-imports.js'` specifier, and resolves
 * it relative to the glue. Because the loader's resulting dynamic import URL is
 * byte-identical to the specifier the glue statically imports, ESM dedupes the
 * two to ONE snippet module and the registry can never split.
 *
 * Returns `undefined` when the glue cannot be read or carries no such import
 * (the caller then falls back to directory enumeration).
 *
 * @internal exported for tests (#148 regression).
 */
export async function resolveSnippetFromSidecarGlue(
  sidecarUrl: URL,
  readFile: (path: string, encoding: 'utf8') => Promise<string>,
  fileURLToPath: (url: URL) => string,
): Promise<URL | undefined> {
  if (sidecarUrl.protocol !== 'file:') return undefined
  let source: string
  try {
    source = await readFile(fileURLToPath(sidecarUrl), 'utf8')
  } catch {
    // The glue is not readable at this path (e.g. an artefact tree that ships
    // only the `.wasm` + `snippets/`); let the caller fall back to enumeration.
    return undefined
  }
  const match = SIDECAR_SNIPPET_IMPORT_RE.exec(source)
  const specifier = match?.[1]
  if (specifier === undefined) return undefined
  return new URL(specifier, sidecarUrl)
}

/**
 * Vite-safe resolver for the default wasm artefact base URL.
 *
 * `wasmUrlFor` resolves the artefact via `new URL('./pkg/…',
 * import.meta.url)` — the lowest-common-denominator bundler pattern. But
 * Vite / Vitest SPECIALLY REWRITE the `new URL(literalString,
 * import.meta.url)` form into a static asset reference at transform time,
 * which mangles the dynamic per-bridge path. To keep the loader zero-config
 * under a Vite-based adopter, we compute the base directory here with
 * `node:url.fileURLToPath` + `node:path` — string operations Vite does NOT
 * rewrite — and probe the two filesystem layouts:
 *
 *   - layout A (opt-in): `<dir-of-wasm.js>/pkg/<bridge>/…` — materialised
 *     locally by `tools/wasm-build/link-dist-pkg.mjs`; the published npm
 *     tarball deliberately ships NO artefacts here (issue #68 — see
 *     `wasm/README.md` § artefact layouts).
 *   - layout B: `<pkg-root>/wasm-pkg/<bridge>-bundler/…` — the artefact
 *     trees committed in the source tree; the zero-config path for a
 *     source/linked checkout on Node.
 *
 * Returns the resolved `{ wasmBaseUrl, bridgeSegment }` or `undefined` when
 * neither layout is reachable (non-Node host, Vite-stubbed builtins, or
 * neither directory present) — the caller then falls back to the `new URL`
 * default, which still works in plain Node ESM, and browser hosts take the
 * explicit `{ wasmBaseUrl }` path.
 *
 * @internal
 */
async function resolveDefaultWasmBase(
  bridge: BridgeId,
): Promise<{ wasmBaseUrl: string; bridgeSegment: BridgeId } | undefined> {
  // Non-Node / no-fs environments fall back to the `new URL` default.
  let path: typeof import('node:path')
  let urlMod: typeof import('node:url')
  let fs: typeof import('node:fs')
  try {
    path = await import('node:path')
    urlMod = await import('node:url')
    fs = await import('node:fs')
  } catch {
    return undefined
  }
  // issue #68 — an import-throw is NOT a reliable non-Node signal: Vite (and
  // Vite-based hosts like a Storybook dev server) resolve `node:*` builtins
  // in the browser as STUBS, so the imports above SUCCEED and the members are
  // `undefined` — calling `urlMod.fileURLToPath(...)` then dies with a
  // TypeError instead of the clean fallback. Capability-check every member
  // this probe calls, and require a `file:` self-URL (a dev server serves
  // this module over http(s), where a filesystem probe is meaningless).
  if (
    !import.meta.url.startsWith('file:') ||
    typeof path.dirname !== 'function' ||
    typeof path.join !== 'function' ||
    typeof urlMod.fileURLToPath !== 'function' ||
    typeof urlMod.pathToFileURL !== 'function' ||
    typeof fs.existsSync !== 'function'
  ) {
    return undefined
  }
  const selfDir = path.dirname(urlMod.fileURLToPath(import.meta.url))
  const segment = bridgeArtifactSegment(bridge)
  const filename = CONSOLIDATED_BRIDGE_ARTEFACT_FILENAME
  // Layout A — built package: `<selfDir>/pkg/<segment>/<artefact>`.
  const builtBase = path.join(selfDir, 'pkg')
  if (fs.existsSync(path.join(builtBase, segment, filename))) {
    return {
      wasmBaseUrl: urlMod.pathToFileURL(builtBase + path.sep).href,
      bridgeSegment: bridge,
    }
  }
  // Layout B — source tree: `<pkgRoot>/wasm-pkg/<segment>-bundler/`.
  // `selfDir` is `<pkgRoot>/wasm` in source; `<pkgRoot>/wasm-pkg` is its
  // sibling. The bundler-target dirs carry a `-bundler` suffix.
  const srcBase = path.join(selfDir, '..', 'wasm-pkg')
  const bundlerSegment = `${segment}-bundler`
  if (fs.existsSync(path.join(srcBase, bundlerSegment, filename))) {
    return {
      wasmBaseUrl: urlMod.pathToFileURL(srcBase + path.sep).href,
      bridgeSegment: bundlerSegment,
    }
  }
  return undefined
}

/**
 * WIRE — the compiled-but-not-yet-instantiated handle
 * {@link compileConsolidatedBridge} returns and
 * {@link instantiateConsolidatedBridgeSync} consumes. It carries everything
 * the synchronous instantiate needs so that step holds ZERO awaits.
 *
 * @internal
 */
interface CompiledConsolidatedBridge {
  readonly module: WebAssembly.Module
  readonly imports: WebAssembly.Imports
  readonly sidecar: BridgeSidecarModule | undefined
  /**
   * mux-6b (causl-client#42) — the resolved `_bg.js` glue URL (sidecar path
   * only). The loader instantiates the bridge ONCE per glue href and routes
   * every engine through that single shared {@link WasmBridgeExports} (the
   * Rust side multiplexes N engines within one instance by `engine_id`), so
   * this also doubles as the shared-instance cache key. `undefined` on the
   * legacy raw-exports path.
   */
  readonly sidecarHref: string | undefined
}

/**
 * WIRE — the ASYNC compile step. Reads the artefact bytes, compiles them to a
 * `WebAssembly.Module`, dynamic-imports the wasm-bindgen `_bg.js` sidecar, and
 * resolves the import object — i.e. EVERY `await` the live-instantiate path
 * needs. Returns a {@link CompiledConsolidatedBridge} handle (or `undefined`
 * on a missing artefact).
 *
 * The byte-buffer externs (`apply_commands(&[u8])`, `read_cell_value(...)`,
 * …) cannot be called on the RAW `instance.exports`: the wasm-bindgen ABI
 * lowers a `&[u8]` arg into a `(ptr, len)` pair the caller materialises in
 * linear memory via `__wbindgen_malloc` + `passArray8ToWasm0`, and lifts a
 * `Vec<u8>` return out of a stack-allocated retptr — all of which lives in the
 * wasm-pack-generated `_bg.js` SIDECAR. So the sidecar is wired for real:
 *   1. dynamic-import the `_bg.js` sidecar module,
 *   2. build the import object from its `__wbg_*` exports (matched to the
 *      module's import descriptors),
 *   3. (instantiate + bind, done synchronously by
 *      {@link instantiateConsolidatedBridgeSync}).
 *
 * LOUD-FAIL (#107): the wasm-bindgen `_bg.js` sidecar is MANDATORY on the
 * authoritative path — the byte-buffer externs cannot be called on the raw
 * `instance.exports` (their ABI is the lowered `(retptr, engine_id, ptr, len)`
 * form the sidecar materialises). A sidecar that cannot be resolved, imported,
 * or shape-matched therefore raises a {@link WasmEngineUnavailableError} (with
 * the underlying failure attached as `cause`); it must NEVER silently
 * instantiate the raw ABI and feed coerced garbage into `apply_commands` at
 * first use. The prior "fail-safe" raw-exports/throw-stub fallback is removed
 * from the production loader.
 *
 * @internal
 */
async function compileConsolidatedBridge(
  url: URL,
  fetchImpl: typeof fetch | undefined,
): Promise<CompiledConsolidatedBridge | undefined> {
  const read = await readArtefactBytes(url, fetchImpl)
  if (read.bytes === undefined) {
    // #165 — a THROWN read (ENOENT, permission, network) carries a cause:
    // raise the loud error HERE with that cause attached so the failure is
    // attributable instead of degrading to the caller's causeless generic
    // miss. An HTTP-non-ok read has no JS cause; fall through to the
    // caller's `compiled === undefined` branch, which keeps naming the
    // resolved bridge + URL.
    if (read.cause !== undefined) {
      // Keep the canonical `could not be read or compiled` phrasing the
      // loader's miss error (compileCauslWasmModule) uses, so the contract
      // is stable, and ATTACH the underlying read cause (ENOENT /
      // permission / network) the old `catch { return undefined }` dropped.
      throw new WasmEngineUnavailableError(
        `the consolidated bridge artefact could not be read or compiled ` +
          `(resolved URL: ${url.href}).`,
        read.cause,
      )
    }
    return undefined
  }
  const bytes = read.bytes
  // #108 test seam — force the WasmGC-unavailable VALIDATION failure at the
  // exact boundary a real incapable host raises it (`WebAssembly.compile`),
  // BEFORE any module is compiled. Off in production.
  if (forcedCompileThrow !== undefined) {
    throw forcedCompileThrow()
  }
  const module = await WebAssembly.compile(bytes as Uint8Array<ArrayBuffer>)

  // #107 — the `_bg.js` sidecar URL is derived from the `.wasm` URL by the
  // `_bg.wasm` → `_bg.js` rename. A hashed / query-carrying / non-`_bg.wasm`
  // asset URL makes it underivable — refuse to instantiate the raw ABI.
  const baseSidecarHref = sidecarHrefFor(url)
  if (baseSidecarHref === undefined) {
    throw new WasmEngineUnavailableError(
      `the wasm-bindgen '_bg.js' sidecar URL could not be derived from the ` +
        `artefact URL '${url.href}' (expected a '…_bg.wasm' name). A hashed, ` +
        `query-carrying, or otherwise rewritten asset URL makes the sidecar ` +
        `unresolvable; the raw wasm exports use the lowered wasm-bindgen ABI ` +
        `and MUST NOT be called directly. Serve the '_bg.js' glue next to the ` +
        `'.wasm' under an unrewritten '…_bg.wasm' name (or pass an explicit ` +
        `{ wasmBaseUrl } whose artefact keeps that name).`,
    )
  }

  const loaded = await tryLoadBridgeSidecar(baseSidecarHref)
  if (!loaded.ok) {
    throw new WasmEngineUnavailableError(
      `the wasm-bindgen '_bg.js' sidecar next to the artefact could not be ` +
        `loaded (resolved glue href: '${baseSidecarHref}'). The marshaled ` +
        `byte-buffer externs (apply_commands, read_cell_value, …) live in ` +
        `this sidecar; without it only the raw lowered-ABI exports remain, ` +
        `which must NEVER be called directly. Ensure the wasm-bindgen ` +
        `'…_bg.js' glue ships and is served next to the '.wasm'.`,
      loaded.cause,
    )
  }

  const { sidecar, href: sidecarHref } = loaded
  const imports = buildBridgeImportsFromSidecar(module, sidecar)
  if (imports === undefined) {
    throw new WasmEngineUnavailableError(
      `the wasm-bindgen '_bg.js' sidecar at '${sidecarHref}' does not expose ` +
        `every import the compiled module requires (a required '__wbg_*' glue ` +
        `export or the host 'wasm:js-string' surface is missing) — the ` +
        `sidecar ABI does not match the artefact. Rebuild the artefact + ` +
        `sidecar together with the wasm:build pipeline.`,
    )
  }
  // mux-6b (causl-client#42) — ONE glue to ONE wasm instance for the whole
  // compile. The synchronous instantiate links this single glue + module
  // exactly once and every engine routes through the resulting shared
  // {@link WasmBridgeExports}, multiplexed by `engine_id` on the Rust side. No
  // per-engine fresh-glue pool is needed (and none would be safe): a second
  // `new WebAssembly.Instance` re-pointing this glue would corrupt the first
  // instance's externref heap. Keeping ONE instance is what makes unbounded
  // concurrent coexistence sound. The cache-busted `sidecarHref` (one fresh
  // glue per compile) doubles as the shared-instance cache key in
  // `instantiateConsolidatedBridgeSync`.
  return { module, imports, sidecar, sidecarHref }
}

/** Resolve the `_bg.js` glue href next to the `.wasm` at `url`. */
function sidecarHrefFor(wasmUrl: URL): string | undefined {
  const href = wasmUrl.href.replace(/_bg\.wasm$/, '_bg.js')
  return href === wasmUrl.href ? undefined : href
}

/**
 * mux-6b (causl-client#42) — the ONE shared wasm instance per bridge, keyed
 * by `_bg.js` glue href (sidecar path) or by the compiled `WebAssembly.Module`
 * (legacy raw path). The Rust side multiplexes N engines within a single
 * instance by `engine_id` (`ENGINE_STATES` is an unbounded `BTreeMap` keyed by
 * `engine_id`; `INTERN_TABLE` / `VALUE_POOL` are deliberately shared per-wasm
 * instance; compute/fire handlers are a per-`engine_id` registry), so the
 * loader instantiates ONCE per bridge and every `AuthoritativeWasmEngine`
 * routes through that single shared {@link WasmBridgeExports}.
 *
 * This is the mux-6b fix for the mux-7 trap: the prior loader bound a fresh
 * `WebAssembly.Instance` + fresh `_bg.js` glue per engine and corrupted the
 * shared externref heap once a same-tick burst drained the depth-4 pool. ONE
 * instance — never re-instantiated — makes that corruption impossible and
 * makes unbounded concurrent coexistence sound.
 *
 * Cleared by {@link __resetWasmBackendCacheForTests} (the HMR-dispose seam)
 * in lockstep with the compile caches, so a subsequent preload rebuilds a
 * fresh shared instance.
 */
const sharedInstanceByKey = new Map<string | WebAssembly.Module, WasmBridgeExports>()

/**
 * mux-6b (causl-client#42) — the set of shared {@link WasmBridgeExports}
 * surfaces whose whole-instance state has already been reset
 * (`__resetEngineState` / `__resetInternTable` / `__resetValuePool`). The
 * reset fires EXACTLY ONCE per shared instance (in {@link
 * WasmBackend.__enableAuthoritativeWasm}, on the FIRST engine), never per
 * engine — those externs clear ALL `engine_id`s + the shared tables, so a
 * per-engine reset would wipe the other live engines coexisting on the one
 * instance. Cleared in lockstep with {@link sharedInstanceByKey} on the
 * test/HMR reset seam.
 */
const sharedInstancesReset = new Set<WasmBridgeExports>()

/**
 * WIRE — the SYNCHRONOUS instantiate step. Takes a compiled
 * {@link CompiledConsolidatedBridge} handle and returns the bridge's ONE
 * shared {@link WasmBridgeExports}, running the synchronous primitive
 * `new WebAssembly.Instance(module, imports)` (NOT `await
 * WebAssembly.instantiate`) the FIRST time per bridge and reusing the cached
 * exports on every subsequent engine construct. This function is deliberately
 * NON-`async`.
 *
 * mux-6b (causl-client#42) — ONE instance, multiplexed by `engine_id`. The
 * first call per bridge links the single glue + module (binding the raw
 * exports into the sidecar's module-level `wasm` slot via
 * `__wbg_set_wasm(instance.exports)`) and caches the resulting surface; every
 * later `createCauslWasmSync()` / `loadAuthoritativeWasm()` reuses it. No
 * fresh-glue-per-engine pool: re-pointing the glue with a second instance
 * would corrupt the first instance's externref heap (the cap that trapped
 * mux-7 at the 5th concurrent engine). Each engine isolates its own state via
 * the `engine_id` it threads through `apply_commands` / `read_cell_value` and
 * the per-`engine_id` handler it registers.
 *
 * @internal
 */
/**
 * §18A.13.1 test seam — when set, {@link instantiateConsolidatedBridgeSync}
 * throws the factory's result INSTEAD of running `new WebAssembly.Instance`,
 * simulating a host where the WasmGC engine cannot instantiate. `undefined`
 * (the production default) ⇒ the real instantiate runs. The throw is shaped
 * like the raw `WebAssembly.CompileError` a genuinely-incapable host raises,
 * so the production normalisation path in `createCauslWasmSync` (raw throw →
 * `WasmEngineUnavailableError`) is exercised verbatim — the test does NOT
 * pre-bake the structured error.
 *
 * @internal — set only by tests via
 * {@link __forceWasmInstantiateUnavailableForTests}.
 */
let forcedInstantiateThrow: (() => unknown) | undefined

/**
 * #165 — refuse to ARM a wasm-instantiation-sabotage test seam in a
 * production build. These seams exist so the test suite can simulate a
 * WasmGC-incapable host; armed in production they would break the wasm
 * engine for every adopter. The export cannot be tree-shaken away (tests
 * import it), so guard the arming path: disarming (`undefined`) is always
 * allowed, arming throws when `process.env.NODE_ENV === 'production'`.
 *
 * The `process`/`process.env` reach is defensive (browser hosts, hostile
 * Proxy) mirroring {@link ./flags.ts}'s env access.
 */
function assertTestSeamAllowed(seam: string): void {
  let isProduction = false
  try {
    const proc = (
      globalThis as { process?: { env?: Record<string, string | undefined> } }
    ).process
    isProduction = proc?.env?.NODE_ENV === 'production'
  } catch {
    // A hostile Proxy on `process.env` can throw on access; treat an
    // unreadable env as non-production so the test suite is never wedged.
    isProduction = false
  }
  if (isProduction) {
    throw new Error(
      `@causl/client-ts/wasm: ${seam} is a test-only seam and cannot be armed ` +
        `in a production build (NODE_ENV=production)`,
    )
  }
}

/**
 * §18A.13.1 test control — arm/disarm the WasmGC-unavailable instantiation
 * throw. Pass a factory that returns the error to throw (default: a
 * `WebAssembly.CompileError`-shaped error mimicking a real incapable host);
 * pass `undefined` to disarm. Not part of any supported API.
 *
 * @internal
 */
export function __forceWasmInstantiateUnavailableForTests(
  makeError?: () => unknown,
): void {
  if (makeError === undefined) {
    forcedInstantiateThrow = undefined
    return
  }
  assertTestSeamAllowed('__forceWasmInstantiateUnavailableForTests')
  forcedInstantiateThrow = makeError
  // Drop the shared-instance cache so the next construct re-enters the
  // instantiate path (and hits the armed throw) rather than returning a
  // previously-cached live instance.
  sharedInstanceByKey.clear()
  sharedInstancesReset.clear()
}

/**
 * #108 test seam — when set, {@link compileConsolidatedBridge} throws the
 * factory's result INSTEAD of running `WebAssembly.compile`, simulating a host
 * where the WasmGC engine cannot VALIDATE the module. WasmGC support is a
 * validation-time property, so this — NOT the instantiate seam — is the failure
 * mode a genuinely-incapable host (Safari < 18 / macOS < 15, policy-pinned
 * pre-119 Chromium/WebView2, Node ≤ 20) actually produces. `undefined` (the
 * production default) ⇒ the real `WebAssembly.compile` runs.
 *
 * @internal — set only by tests via
 * {@link __forceWasmCompileUnavailableForTests}.
 */
let forcedCompileThrow: (() => unknown) | undefined

/**
 * #108 test control — arm/disarm the WasmGC-unavailable COMPILE throw. Pass a
 * factory returning the error to throw (typically a `WebAssembly.CompileError`
 * mimicking a real incapable host); pass `undefined` to disarm. Not part of any
 * supported API.
 *
 * @internal
 */
export function __forceWasmCompileUnavailableForTests(
  makeError?: () => unknown,
): void {
  if (makeError !== undefined) {
    assertTestSeamAllowed('__forceWasmCompileUnavailableForTests')
  }
  forcedCompileThrow = makeError
  // Drop the compile caches so the next preload re-enters the compile path
  // (and hits the armed throw) rather than returning a previously-resolved
  // handle.
  compiledModuleByBridge.clear()
  // #144 — drop the preload fingerprints in lockstep with the compile cache
  // so a post-reset re-preload is never misjudged a conflicting re-preload.
  preloadFingerprintByBridge.clear()
  resolvedModuleByBridge.clear()
  defaultPreloadedBridge = undefined
  // #146 — a resolved-slot drop is a cache-generation boundary; stale handles
  // from before it must fail the sync factory's epoch guard.
  cacheEpoch += 1
  sharedInstanceByKey.clear()
  sharedInstancesReset.clear()
}

/**
 * #107 test seam — when set, {@link tryLoadBridgeSidecar} reports the sidecar
 * as unresolvable (returning the factory's error as the load `cause`) INSTEAD
 * of dynamic-importing the real `_bg.js` glue. This reproduces the realistic
 * triggers (a hashed / query-carrying asset URL, a webpack context-module
 * import throw, an unserved / signed-CDN glue) on a HEALTHY host, so the
 * loud-fail path (`WasmEngineUnavailableError`, never a silent raw-ABI engine)
 * can be exercised without a broken artefact tree. `undefined` (the production
 * default) ⇒ the real dynamic import runs.
 *
 * @internal — set only by tests via {@link __forceSidecarUnavailableForTests}.
 */
let forcedSidecarThrow: (() => unknown) | undefined

/**
 * #107 test control — arm/disarm the sidecar-unresolvable failure. Pass a
 * factory returning the error to surface as the load `cause` (default: a plain
 * `Error` mimicking a swallowed dynamic-import throw); pass `undefined` to
 * disarm. Not part of any supported API.
 *
 * @internal
 */
export function __forceSidecarUnavailableForTests(
  makeError?: () => unknown,
): void {
  // Convention matches {@link __forceWasmCompileUnavailableForTests}: pass a
  // factory to ARM, pass `undefined` to DISARM.
  forcedSidecarThrow = makeError
  // Drop the compile + shared-instance caches so the next preload re-enters
  // the compile path (and hits the armed failure) rather than returning a
  // previously-resolved handle.
  compiledModuleByBridge.clear()
  // #144 — drop the preload fingerprints in lockstep with the compile cache
  // so a post-reset re-preload is never misjudged a conflicting re-preload.
  preloadFingerprintByBridge.clear()
  resolvedModuleByBridge.clear()
  defaultPreloadedBridge = undefined
  // #146 — a resolved-slot drop is a cache-generation boundary; stale handles
  // from before it must fail the sync factory's epoch guard.
  cacheEpoch += 1
  sharedInstanceByKey.clear()
  sharedInstancesReset.clear()
}

/**
 * #108 — classify an error as the WasmGC-unavailable CAPABILITY failure a real
 * incapable host raises: a `WebAssembly.CompileError` (validation-time — the
 * common case) or `WebAssembly.LinkError` (import-binding-time). This is a
 * HOST-capability problem, distinct from a deployment problem (missing/unserved
 * artefact tree), which surfaces as a plain {@link WasmEngineUnavailableError}
 * / {@link WasmBackendUnavailableError} with no such cause and MUST keep
 * failing loud rather than degrading. Unwraps one level of
 * `WasmEngineUnavailableError.cause` so the normalised wrapper is transparent.
 *
 * @internal exported for tests.
 */
export function isWasmCapabilityError(err: unknown): boolean {
  const w = WebAssembly as unknown as {
    CompileError?: new (...args: never[]) => Error
    LinkError?: new (...args: never[]) => Error
  }
  const isCapabilityShaped = (e: unknown): boolean =>
    (w.CompileError !== undefined && e instanceof w.CompileError) ||
    (w.LinkError !== undefined && e instanceof w.LinkError)
  if (isCapabilityShaped(err)) return true
  // The loader normalises raw throws to `WasmEngineUnavailableError(msg, cause)`
  // — look through one `cause` level for the host-shaped original.
  if (err instanceof WasmEngineUnavailableError) {
    return isCapabilityShaped(err.cause)
  }
  return false
}

function instantiateConsolidatedBridgeSync(
  compiled: CompiledConsolidatedBridge,
): WasmBridgeExports {
  // §18A.13.1 test seam — force the WasmGC-unavailable instantiation throw so
  // the implicit-path capability fallback + the explicit-path loud-fail can be
  // exercised without a host that genuinely lacks WasmGC. When armed, this
  // throws BEFORE any `new WebAssembly.Instance` runs, exactly as a real
  // WasmGC-incapable host would at the `new WebAssembly.Instance` boundary.
  // Off in production (the override is only set by tests via
  // {@link __forceWasmInstantiateUnavailableForTests}).
  if (forcedInstantiateThrow !== undefined) {
    throw forcedInstantiateThrow()
  }
  const { module, imports, sidecar, sidecarHref } = compiled
  const key: string | WebAssembly.Module = sidecarHref ?? module
  const existing = sharedInstanceByKey.get(key)
  if (existing !== undefined) return existing

  let exports: WasmBridgeExports
  if (sidecar !== undefined && sidecarHref !== undefined) {
    // Sidecar path — bind this ONE glue to its ONE instance. The glue's
    // marshaled surface (`apply_commands`, `read_cell_value`, …) IS the
    // {@link WasmBridgeExports}; its `import './snippets/…/causl-compute-
    // imports.js'` ESM-dedupes to the stable snippet the loader hands the
    // engine as `computeImports`, so the per-`engineId` handler registry stays
    // shared between the glue's `__causl_compute` dispatch and engine
    // registration (mux-6).
    const instance = new WebAssembly.Instance(module, imports)
    sidecar.__wbg_set_wasm(instance.exports)
    exports = sidecar as unknown as WasmBridgeExports
  } else {
    const instance = new WebAssembly.Instance(module, imports)
    if (sidecar !== undefined) {
      sidecar.__wbg_set_wasm(instance.exports)
      exports = sidecar as unknown as WasmBridgeExports
    } else {
      exports = instance.exports as unknown as WasmBridgeExports
    }
  }
  // #107 — cheap ABI smoke-probe at LOAD (once per shared instance, before it
  // is cached or handed to any engine). A wrong-ABI surface (e.g. the raw
  // lowered exports mistaken for the marshaled sidecar) fails HERE — loud, at
  // load, with a coherent diagnostic — instead of silently corrupting linear
  // memory at the first `apply_commands` call far from the root cause.
  assertBridgeAbiSmokeProbe(exports)
  sharedInstanceByKey.set(key, exports)
  return exports
}

/**
 * #107 — the cheap ABI smoke-probe run once at bind on a freshly-instantiated
 * bridge surface, BEFORE it is cached or driven. The marshaled string externs
 * round-trip a single UTF-8 byte through the intern table:
 * `read_interned_string(intern_string([0x61])) === 'a'`. On the correct
 * (sidecar) ABI this holds; on the RAW wasm-bindgen lowered ABI —
 * `intern_string(retptr, ptr, len)` etc. — the arguments are shifted/coerced
 * and the round-trip either throws or returns a non-`'a'` value, so a
 * wrong-ABI engine fails LOUD at load ({@link WasmEngineUnavailableError})
 * rather than corrupting memory at first commit.
 *
 * The probe interns the byte on the shared instance; the immediately-following
 * `__enableAuthoritativeWasm` `__resetInternTable()` (once per shared instance)
 * clears it, so it leaves no observable residue.
 *
 * @internal exported for tests.
 */
export function assertBridgeAbiSmokeProbe(exports: WasmBridgeExports): void {
  const intern = exports.intern_string
  const read = exports.read_interned_string
  // Completeness (presence) is the caller's gate (`__enableAuthoritativeWasm`);
  // the probe only validates the ABI of the externs that ARE present.
  if (typeof intern !== 'function' || typeof read !== 'function') return
  let roundTripped: unknown
  try {
    const stringId = intern(new Uint8Array([0x61])) // 'a'
    roundTripped = read(stringId)
  } catch (err) {
    throw new WasmEngineUnavailableError(
      `the wasm bridge surface failed its load-time ABI smoke-probe: calling ` +
        `intern_string / read_interned_string threw. This is the signature of ` +
        `a WRONG ABI — e.g. the raw wasm-bindgen lowered exports mistaken for ` +
        `the marshaled '_bg.js' sidecar surface. Refusing to hand a ` +
        `corrupt-on-first-use engine to the caller.`,
      err,
    )
  }
  if (roundTripped !== 'a') {
    throw new WasmEngineUnavailableError(
      `the wasm bridge surface failed its load-time ABI smoke-probe: ` +
        `read_interned_string(intern_string('a')) returned ` +
        `${JSON.stringify(roundTripped)} instead of 'a'. This is the ` +
        `signature of a WRONG ABI (the raw lowered wasm-bindgen exports coerce ` +
        `the Uint8Array argument to 0 and shift the return), so the engine ` +
        `would corrupt linear memory at the first commit. Refusing to hand it ` +
        `to the caller.`,
    )
  }
}

/**
 * WIRE — the wasm-bindgen sidecar module surface this loader binds. The
 * wasm-pack `bundler` target emits a `<artefact>_bg.js` next to the `.wasm`;
 * it exports `__wbg_set_wasm` (binds the instantiated exports into its
 * module-level `wasm` slot), the `__wbg_*` import-glue functions the wasm
 * imports, and the MARSHALED extern functions (which do the ptr/len buffer
 * dance).
 *
 * @internal
 */
interface BridgeSidecarModule {
  __wbg_set_wasm: (exports: WebAssembly.Exports) => void
  [name: string]: unknown
}

/**
 * mux-6b (causl-client#42) — per-COMPILE fresh-glue counter for the
 * wasm-bindgen `_bg.js` glue import.
 *
 * The generated glue holds a MODULE-LEVEL externref heap that
 * `__wbg_set_wasm(exports)` re-points but does NOT reset, and ESM caches the
 * glue module by URL. The loader instantiates the bridge ONCE per compile and
 * routes EVERY engine through that one shared instance (multiplexed by
 * `engine_id`), so WITHIN a compile session no re-instantiation occurs and the
 * heap can never be corrupted by a second `new WebAssembly.Instance`.
 *
 * The one place a glue would be re-pointed is ACROSS a compile boundary — the
 * `__resetWasmBackendCacheForTests` / HMR-dispose seam clears the compile cache
 * so the next `preloadCauslWasm` recompiles and re-instantiates. Re-pointing
 * the ESM-cached glue from the prior session would inherit its stale heap and
 * trap ("The encoded data was not valid for encoding utf-8" → `unreachable`).
 * So, ACROSS a reset, we mint a FRESH glue per COMPILE (one fresh glue per
 * shared instance — NOT per engine) by appending a unique cache-bust query. The
 * resolved FILE is identical, so the glue's `import
 * './snippets/…/causl-compute-imports.js'` ESM-dedupes to the ONE stable snippet
 * the loader hands the engine as `computeImports`; the per-`engineId` handler
 * registry therefore stays shared.
 *
 * #147 — the counter starts at 0 and the epoch-0 (FIRST-ever) compile imports
 * the glue at its NATURAL, query-free href. A production host runs exactly that
 * one compile — the recompile-forcing cache-drop seam is dev/test/HMR-only — so
 * production mints ONE glue module for the process lifetime and the ESM registry
 * never accumulates a stranded glue. The `?__causlCompile=<epoch>` cache-bust
 * (and its ESM-module churn) is gated to epoch > 0, i.e. to compiles that follow
 * a dev/test/HMR reset, where a pristine-heap glue is genuinely required.
 */
let sidecarCompileEpoch = 0

/**
 * #147 test observability — the ordered list of `_bg.js` glue hrefs the loader
 * has dynamic-imported since the last cache reset. Lets the leak-confinement
 * gate assert that the epoch-0 (production, never-reset) compile imports the
 * glue at its NATURAL query-free href — the observable proxy for "ESM caches
 * ONE glue module, no per-compile leak". Cleared by
 * {@link __resetWasmBackendCacheForTests} in lockstep with the compile caches.
 *
 * @internal
 */
const importedSidecarHrefs: string[] = []

/**
 * #147 — snapshot the glue hrefs imported since the last reset. Not part of any
 * supported API; used only by the leak-confinement regression test.
 *
 * @internal
 */
export function __sidecarImportHrefsForTests(): readonly string[] {
  return importedSidecarHrefs.slice()
}

/**
 * #107 — the discriminated result of a sidecar load. `ok: true` carries the
 * imported glue module + its cache-busted href; `ok: false` carries the
 * underlying `cause` (the swallowed dynamic-import throw, or a synthesized
 * shape-mismatch error) so the caller can attach it to the loud
 * {@link WasmEngineUnavailableError} rather than discarding it.
 *
 * @internal
 */
type SidecarLoadResult =
  | { readonly ok: true; readonly sidecar: BridgeSidecarModule; readonly href: string }
  | { readonly ok: false; readonly cause: unknown }

/**
 * Resolve + dynamic-import the wasm-bindgen `_bg.js` sidecar that sits next to
 * the `.wasm` at `wasmUrl`. Returns a {@link SidecarLoadResult}: `ok: false`
 * (with the failure `cause`) when the sidecar is absent, throws on import, or
 * does not expose `__wbg_set_wasm`. The caller ({@link
 * compileConsolidatedBridge}) turns that into a loud
 * {@link WasmEngineUnavailableError} (#107) — it NO LONGER falls back to the
 * raw-exports path. The sidecar filename is the `.wasm` name with `.wasm` →
 * `.js` (`causl_engine_bridge_bg.wasm` → `causl_engine_bridge_bg.js`).
 *
 * Called ONCE per compile (from {@link compileConsolidatedBridge}); the cache
 * key returned is the cache-busted href and doubles as the shared-instance
 * key in {@link instantiateConsolidatedBridgeSync}, so each compile session
 * gets exactly one fresh glue to one shared instance.
 *
 * @internal
 */
async function tryLoadBridgeSidecar(
  sidecarHref: string,
): Promise<SidecarLoadResult> {
  // #107 test seam — force the sidecar-unresolvable failure (a hashed /
  // query-carrying asset URL, a Vite context-module import throw, an unserved
  // glue) WITHOUT a broken artefact tree, so the loud-fail path can be
  // exercised on a healthy host. Off in production.
  if (forcedSidecarThrow !== undefined) {
    return { ok: false, cause: forcedSidecarThrow() }
  }
  let href = sidecarHref
  try {
    // #147 — the FIRST compile (epoch 0) imports the sidecar at its NATURAL,
    // query-free href. That is the ONLY compile a production process ever runs
    // (the cache-drop seam that forces a recompile — `__resetWasmBackendCache-
    // ForTests` / an HMR-dispose hook — is dev/test-only), so a production host
    // mints EXACTLY ONE glue module + one `WebAssembly.Instance` for its whole
    // lifetime: no per-compile ESM-module leak. Only a SUBSEQUENT compile
    // (epoch > 0 — i.e. after a dev/test/HMR cache drop) appends the
    // `?__causlCompile=<epoch>` cache-bust to mint a pristine-heap glue (a fresh
    // externref heap is REQUIRED across a reset — re-pointing the ESM-cached
    // stale glue via `__wbg_set_wasm` would trap). The unavoidable ESM-registry
    // accumulation is therefore confined to the dev/test/HMR reset boundary
    // instead of stranding a fresh glue on every compile. Fresh glue per COMPILE
    // (own pristine externref heap), NOT per engine: every engine in a compile
    // session shares this one glue to one wasm instance.
    const epoch = sidecarCompileEpoch
    sidecarCompileEpoch += 1
    if (epoch > 0) {
      const bust = `${sidecarHref.includes('?') ? '&' : '?'}__causlCompile=${epoch}`
      href = sidecarHref + bust
    }
    // #147 test observability — record every glue href the loader imports so the
    // "epoch-0 compile is query-free" invariant (no per-compile leak) is
    // assertable. Cleared by the reset seam in lockstep with the compile caches.
    importedSidecarHrefs.push(href)
    // #121 — `href` is a single runtime-computed string; both magic comments
    // ride INSIDE the parens so the annotations survive the build.
    // `webpackIgnore: true` stops webpack 5 turning this fully-dynamic import
    // into a doomed ContextModule (which would throw, be swallowed below, and
    // silently drop the loader to the raw ABI); `@vite-ignore` is the Vite /
    // esbuild equivalent.
    const mod = (await import(
      /* webpackIgnore: true */ /* @vite-ignore */ href
    )) as Record<string, unknown>
    if (typeof mod.__wbg_set_wasm !== 'function') {
      return {
        ok: false,
        cause: new Error(
          `@causl/client-ts/wasm: the module at '${href}' does not export ` +
            `'__wbg_set_wasm' — it is not a valid wasm-bindgen '_bg.js' glue ` +
            `sidecar.`,
        ),
      }
    }
    return { ok: true, sidecar: mod as unknown as BridgeSidecarModule, href }
  } catch (err) {
    return { ok: false, cause: err }
  }
}

/**
 * Build the `WebAssembly.Imports` for the consolidated bridge from the
 * wasm-bindgen sidecar's `__wbg_*` exports (the REAL import glue). Each of the
 * module's function imports is matched to the identically-named export on the
 * sidecar; `wasm:js-string` members still come from the host. Returns
 * `undefined` if any required import has no matching sidecar export.
 *
 * @internal
 */
function buildBridgeImportsFromSidecar(
  module: WebAssembly.Module,
  sidecar: BridgeSidecarModule,
): WebAssembly.Imports | undefined {
  const imports: WebAssembly.Imports = {}
  const wasmString = (
    WebAssembly as unknown as { String?: Record<string, unknown> }
  ).String
  for (const desc of WebAssembly.Module.imports(module)) {
    const ns = (imports[desc.module] ??= {}) as Record<string, unknown>
    if (desc.module === 'wasm:js-string') {
      const member =
        wasmString !== undefined ? wasmString[desc.name] : undefined
      if (member !== undefined) {
        ns[desc.name] = member
        continue
      }
      // No host `wasm:js-string` — let the instantiate fail and the caller
      // fall back (the gc-classic build does not need it).
      return undefined
    }
    if (desc.kind === 'function') {
      const glue = sidecar[desc.name]
      if (typeof glue !== 'function') {
        // A required import has no sidecar export — bail to the raw path.
        return undefined
      }
      ns[desc.name] = glue
    }
  }
  return imports
}

/**
 * The outcome of an artefact read. `bytes` present ⇒ the artefact was
 * read. `bytes` absent carries the underlying `cause` when the read
 * FAILED (a thrown `fs.readFile` / `fetch`, e.g. ENOENT or a network
 * error); the `cause` is absent only when the fetch itself succeeded but
 * the HTTP status was non-ok (a legitimate "artefact not served here"
 * with no JS error to attribute).
 */
export interface ArtefactReadResult {
  /** The artefact bytes, or `undefined` when the read did not produce them. */
  readonly bytes: Uint8Array | undefined
  /**
   * The underlying read failure when `bytes` is absent because the read
   * THREW (ENOENT / permission / network). Absent when the read succeeded,
   * or when it was an HTTP-non-ok miss (no JS error to attribute).
   */
  readonly cause?: unknown
}

/**
 * #165 — read the artefact bytes, THREADING the read-failure cause out
 * instead of swallowing every error into a bare `undefined`. The prior
 * `catch { return undefined }` collapsed ENOENT, a permission error and a
 * network failure into the SAME opaque miss, so the loud
 * {@link WasmEngineUnavailableError} the caller raises could not name why
 * the artefact was unreadable. The HTTP-non-ok arm still returns a bare
 * miss (no JS error exists to attribute); a thrown read attaches the real
 * cause the compile path re-raises.
 *
 * Exported (`@internal`) so the #165 loader-cleanup test can pin the
 * cause-threading contract directly without instantiating a wasm module.
 *
 * @internal
 */
export async function readArtefactBytes(
  url: URL,
  fetchImpl: typeof fetch | undefined,
): Promise<ArtefactReadResult> {
  try {
    if (url.protocol === 'file:') {
      const fs = await import('node:fs/promises')
      const url2 = await import('node:url')
      const filePath = url2.fileURLToPath(url)
      const buf = await fs.readFile(filePath)
      return { bytes: new Uint8Array(buf) }
    }
    const f = fetchImpl ?? fetch
    const resp = await f(url.href, { method: 'GET' })
    if (!resp.ok) return { bytes: undefined }
    const buf = await resp.arrayBuffer()
    return { bytes: new Uint8Array(buf) }
  } catch (cause) {
    return { bytes: undefined, cause }
  }
}

/**
 * WIRE (epic #31 / issue #32) — load + instantiate the wasm engine and return
 * a live, authoritative {@link InjectedBackend} (an
 * {@link AuthoritativeWasmEngine}).
 *
 * This is the async seam for the synchronous `createCausl` factory: do the
 * `await` here, then inject the returned engine into
 * `createCausl({ injectedBackend })` (or call {@link createCauslWasm}, which
 * does both in one step). The returned engine is the SSOT for commit / read /
 * subscribe / derived-compute.
 *
 * LOUD-FAIL CONTRACT: this is an EXPLICIT wasm request, so an unresolvable
 * artefact/snippet THROWS a {@link WasmEngineUnavailableError} — it never
 * silently returns a JS engine. Pass `{ fallbackToTs: true }` (or the fork
 * alias `{ fallbackToJs: true }`) to opt into the soft path, in which case a
 * load failure returns a fully-working {@link JsFallbackBackend} instead.
 */
export async function loadAuthoritativeWasm(
  options: AuthoritativeWasmOptions = {},
): Promise<InjectedBackend> {
  try {
    return await loadAuthoritativeWasmEngine(options)
  } catch (err) {
    if (options.fallbackToTs === true || options.fallbackToJs === true) {
      // #150 — thread the adopter's construction options into the fallback
      // engine (the retention caps + graph name the real backend would carry),
      // so a degrading adopter does not silently lose them. Mirrors
      // `resolveRetentionCaps` / `resolvePerGraphBackendParams` field-for-field.
      const retentionCaps = resolveRetentionCaps(options)
      return new JsFallbackBackend({
        ...(options.graphName !== undefined ? { name: options.graphName } : {}),
        ...(retentionCaps?.commitHistoryCap !== undefined
          ? { commitHistoryCap: retentionCaps.commitHistoryCap }
          : {}),
        ...(retentionCaps?.snapshotRetentionCap !== undefined
          ? { snapshotRetentionCap: retentionCaps.snapshotRetentionCap }
          : {}),
      })
    }
    if (err instanceof WasmEngineUnavailableError) throw err
    throw new WasmEngineUnavailableError(
      err instanceof Error ? err.message : String(err),
      err,
    )
  }
}

/**
 * The raw wasm-engine load — resolves the artefact + snippet and instantiates
 * the authoritative engine, throwing the underlying error on any failure. The
 * public {@link loadAuthoritativeWasm} wraps this with the loud-fail / opt-in-
 * fallback contract.
 *
 * @internal
 */
async function loadAuthoritativeWasmEngine(
  options: AuthoritativeWasmOptions = {},
): Promise<AuthoritativeWasmEngine> {
  const bridge = options.bridge ?? (await detectBridge())
  const handle = await compileCauslWasmModule(bridge, options)
  const exports = instantiateConsolidatedBridgeSync({
    module: handle.module,
    imports: handle.imports,
    sidecar: handle.sidecar,
    sidecarHref: handle.sidecarHref,
  })
  const backend = new WasmBackend(
    handle.bridge,
    handle.graphName,
    handle.batchedFlush,
    handle.engineMode,
    handle.retentionCaps,
  )
  backend.__attachWasmExportsForTests(exports)
  backend.__enableAuthoritativeWasm(handle.computeImports)
  const engine = backend.getAuthoritativeEngine()
  if (engine === undefined) {
    throw new Error(
      '@causl/client-ts/wasm: authoritative engine was not installed after ' +
        '__enableAuthoritativeWasm(). This is a wiring bug.',
    )
  }
  return engine
}

/**
 * §18A.12 — `true` iff a wasm module is PRELOADED (RESOLVED, not merely
 * in-flight) for `bridge` (or, when omitted, the most-recently-resolved
 * bridge). Synchronous — reads the resolved slot, never awaits. The exact
 * predicate {@link createCauslWasmSync} uses to decide whether to throw
 * {@link CauslWasmNotPreloadedError}.
 */
export function isCauslWasmPreloaded(bridge?: BridgeId): boolean {
  return getPreloadedCauslWasm(bridge) !== undefined
}

/**
 * §18A.12 — synchronously peek the preloaded {@link CauslWasmModule} for
 * `bridge` (or, when omitted, the most-recently-resolved bridge), or
 * `undefined` when nothing is RESOLVED yet (it returns `undefined` while a
 * preload is still in-flight — resolved-ness is recorded in the preload's
 * `.then`, not its in-flight promise).
 */
export function getPreloadedCauslWasm(
  bridge?: BridgeId,
): CauslWasmModule | undefined {
  // #146 — canonicalise a supplied id so every alias spelling resolves the ONE
  // instance (`getPreloadedCauslWasm('wasmgc-classic')`,
  // `getPreloadedCauslWasm('gc-classic-bundler')`, and
  // `getPreloadedCauslWasm(handle.bridge)` all hit the same slot). The default
  // pointer is already canonical.
  const key = bridge !== undefined ? canonicalBridgeId(bridge) : defaultPreloadedBridge
  if (key === undefined) return undefined
  return resolvedModuleByBridge.get(key)
}

/**
 * §18A.12 directive #2 — the FULLY-SYNCHRONOUS factory. ZERO await: it
 * constructs the backend for the preloaded bridge and wraps the live engine
 * in a public `Graph` — all in one tick, suitable for synchronous React
 * render/hooks and synchronous SSR.
 *
 * Handle resolution: the `handle` arg, else the preloaded handle for the
 * default bridge ({@link getPreloadedCauslWasm}). When NOTHING is preloaded
 * it either (a) throws {@link CauslWasmNotPreloadedError} (the DEFAULT — the
 * sync factory NEVER silently awaits an unresolved promise), or (b) with
 * `{ fallbackToTs: true }` synchronously returns `createCauslTs(create)` (the
 * §18A.4 TS floor — safe while both engines ship because js-ssot is
 * byte-identical per §18A.1.1).
 *
 * epic-B #32 (LANDED) — the body runs the `#35`-style synchronous
 * `new WebAssembly.Instance` link (`instantiateConsolidatedBridgeSync`) +
 * the authoritative flip + `createCausl({ injectedBackend })`, so the
 * `Graph` this returns drives the REAL Rust engine.
 *
 * @example
 * ```ts
 * await preloadCauslWasm()              // once, at app init
 * const g = createCauslWasmSync()       // sync, at every render/hook
 * const a = g.input('a', 1)
 * g.commit('set', (tx) => tx.set(a, 2)) // a === 2, no await
 * ```
 */
export function createCauslWasmSync(
  handle?: CauslWasmModule,
  create?: import('../src/types.js').CreateCauslOptions & {
    readonly fallbackToTs?: boolean
    // #150 — fork-source-compat alias for `fallbackToTs`, matching the async
    // factories (`createCauslWasm` / `loadAuthoritativeWasm`). Either spelling
    // opts into the sync soft path.
    readonly fallbackToJs?: boolean
  },
): Graph {
  const { fallbackToTs, fallbackToJs, ...createOpts } = create ?? {}
  // #150 — one predicate for BOTH soft-path failure modes: the caller opted in
  // via either spelling.
  const softFallback = fallbackToTs === true || fallbackToJs === true
  // Resolve the bridge SYNCHRONOUSLY: the passed handle's bridge, else the
  // most-recently-preloaded default. `detectBridge()` is async and is
  // deliberately NOT on this hot path.
  const resolvedBridge =
    handle?.bridge ?? defaultPreloadedBridge ?? UNRESOLVED_BRIDGE
  const resolved = handle ?? getPreloadedCauslWasm(resolvedBridge)
  if (resolved === undefined) {
    if (softFallback) {
      // Synchronous degrade to the §18A.4 TS floor — NEVER an await.
      return createCauslTs(createOpts)
    }
    throw new CauslWasmNotPreloadedError(resolvedBridge)
  }
  // #146 — reject a handle carried ACROSS a cache reset. Its `epoch` stamp is
  // from a generation that has since been cleared, so its `module` / shared wasm
  // instance / ESM `_bg.js` glue were torn down; re-instantiating over the stale
  // glue would re-point a dead externref heap and trap. This guard runs BEFORE
  // the identity check below (which is skipped after a reset, because the
  // resolved slot is empty and `getPreloadedCauslWasm` returns `undefined`) so a
  // stale handle can never reach the instantiate. A handle from the LIVE
  // generation matches `cacheEpoch` and is never rejected here — so a valid
  // handle is never spuriously invalidated.
  if (resolved.epoch !== cacheEpoch) {
    if (softFallback) return createCauslTs(createOpts)
    throw new WasmEngineUnavailableError(
      `createCauslWasmSync(): the supplied handle for bridge ` +
        `'${resolved.bridge}' is STALE — it was preloaded under a previous ` +
        `cache generation that has since been cleared (its shared wasm ` +
        `instance and '_bg.js' glue were torn down). Re-run preloadCauslWasm() ` +
        `and construct from the handle it returns.`,
    )
  }
  // Validate the handle came from a genuine preload for its OWN bridge
  // (guards a hand-rolled / cross-bridge handle being instantiated).
  const preloadedForBridge = getPreloadedCauslWasm(resolved.bridge)
  if (preloadedForBridge !== undefined && preloadedForBridge !== resolved) {
    throw new WasmEngineUnavailableError(
      `createCauslWasmSync(): the supplied handle for bridge ` +
        `'${resolved.bridge}' does not match the preloaded module for ` +
        `that bridge. A handle must be the value returned by ` +
        `preloadCauslWasm() for its own bridge.`,
    )
  }
  // PRELOAD-BOOT INHERITANCE (documented): with NO per-call `engine`, the
  // handle-driven sync factory constructs with the per-graph params resolved
  // at preload time (the sanctioned `preloadCauslWasm(opts)` once →
  // sync-construct-many boot).
  //
  // #118 — a per-call `engine` OVERRIDES the preload handle's baked mode (the
  // implicit `createCausl()` FLIP passes `engine: undefined` ⇒ pure
  // inheritance, unchanged; an explicit `engine: 'rust-ssot' | 'js-ssot'`
  // wins). Only `engine` (and the rust-ssot batched-flush default it implies)
  // is per-call here; `graphName` + retention caps stay inherited from the
  // handle (the sync factory's `create` bag carries no `graphName`, and
  // dropping the baked retention caps would regress boot inheritance). The
  // async `createCauslWasm` resolves ALL of its params per call (#82).
  // #150 — cover the SAME failure modes the async `createCauslWasm` soft path
  // catches. Pre-#150 the sync factory consulted the fallback flag ONLY on the
  // nothing-preloaded branch above, so a soft-path caller whose preloaded
  // module could not INSTANTIATE/LINK (the WasmGC-incapable-host failure
  // `constructWasmGraphSync` normalises to `WasmEngineUnavailableError`) threw
  // — whereas the async factory, whose whole body sits inside the try, degraded.
  // Wrapping the construct closes that sync/async soft-path asymmetry.
  try {
    return constructWasmGraphSync(
      resolved,
      perGraphParamsForSync(createOpts, resolved),
      createOpts,
    )
  } catch (err) {
    if (softFallback) return createCauslTs(createOpts)
    throw err
  }
}

/**
 * #118 / #141 — resolve the {@link PerGraphBackendParams} for the SYNC factory,
 * honouring per-call options while preserving the documented preload-boot
 * inheritance for every field the call omits.
 *
 * `engine` (#118): `createOpts.engine === undefined` ⇒ inherit the handle's
 * baked mode (the boot-inheritance default; the implicit `createCausl()` FLIP
 * passes `engine: undefined`). A per-call `engine` recomputes the mode, exactly
 * as {@link resolvePerGraphBackendParams} does.
 *
 * Retention caps (#141): resolved PER-CALL with a per-FIELD fallback to the
 * handle. On the implicit `createCausl({ snapshotRetentionCap, commitHistoryCap
 * })` path the per-call caps MUST win — the backend the Rust engine drives (it
 * owns input-node `readAt`) has to carry the SAME window the TS closure (it
 * owns derived-node `readAt`, from the same `createOpts`) does, or the one
 * graph answers history queries with two windows split by node kind. A field
 * the call omits still inherits the preload's baked cap, so a bare
 * `createCauslWasmSync()` after `preloadCauslWasm({ … caps … })` keeps its boot
 * inheritance, and a call that supplies only one cap inherits the other.
 *
 * `graphName` stays inherited from the handle (the sync `create` bag carries no
 * `graphName`); `batchedFlush` keeps its existing #163 handling.
 *
 * @internal
 */
function perGraphParamsForSync(
  createOpts: import('../src/types.js').CreateCauslOptions,
  handle: PerGraphBackendParams,
): PerGraphBackendParams {
  // #141 — per-call retention caps win; absent caps inherit the handle's baked
  // window (boot inheritance), resolved field-for-field.
  const retentionCaps = mergePerCallRetentionCaps(createOpts, handle.retentionCaps)
  if (createOpts.engine === undefined) return { ...handle, retentionCaps }
  const engineMode = resolveWasmEngineMode(createOpts.engine)
  // #163 — mirror resolvePerGraphBackendParams: `batchedFlush` is a purely
  // explicit per-graph wire-tempo opt-in. Neither engine mode implies a
  // default window (the shipped rust-ssot AuthoritativeWasmEngine crosses
  // per commit and never consults it), so thread ONLY the caller's explicit
  // value through.
  return { ...handle, engineMode, batchedFlush: createOpts.batchedFlush, retentionCaps }
}

/**
 * #141 — merge a per-call options bag's retention caps over an inherited
 * (preload-baked) window, PER FIELD: a cap the call supplies wins; a cap it
 * omits inherits the handle's. Returns `undefined` when neither source carries
 * either cap (the pre-lift-readat cap-0 default), so it stays byte-compatible
 * with {@link resolveRetentionCaps} and `exactOptionalPropertyTypes` (no
 * `undefined` VALUES on the wire).
 *
 * @internal
 */
function mergePerCallRetentionCaps(
  createOpts: {
    readonly commitHistoryCap?: number
    readonly snapshotRetentionCap?: number
  },
  inherited: PerGraphBackendParams['retentionCaps'],
): PerGraphBackendParams['retentionCaps'] {
  const commitHistoryCap =
    createOpts.commitHistoryCap ?? inherited?.commitHistoryCap
  const snapshotRetentionCap =
    createOpts.snapshotRetentionCap ?? inherited?.snapshotRetentionCap
  if (commitHistoryCap === undefined && snapshotRetentionCap === undefined) {
    return undefined
  }
  return {
    ...(commitHistoryCap !== undefined ? { commitHistoryCap } : {}),
    ...(snapshotRetentionCap !== undefined ? { snapshotRetentionCap } : {}),
  }
}

/**
 * #82 — the per-graph backend params one wasm `Graph` construct applies:
 * the validated engine canonicality mode, the IR `graphId` graph name, the
 * per-graph batched-flush opt-in, and the retention caps threaded into the
 * wrapped TS `#graph`. A {@link CauslWasmModule} carries one such bag
 * (resolved from the PRELOAD caller's options — the documented boot
 * inheritance for the handle-driven sync factory); the async
 * `createCauslWasm` resolves a fresh bag from ITS OWN options on every call
 * via {@link resolvePerGraphBackendParams}.
 *
 * @internal
 */
interface PerGraphBackendParams {
  readonly graphName: string
  readonly engineMode: WasmEngineMode
  readonly batchedFlush: BatchedFlushOptions | undefined
  readonly retentionCaps:
    | {
        readonly commitHistoryCap?: number
        readonly snapshotRetentionCap?: number
      }
    | undefined
}

/**
 * #82 — resolve the {@link PerGraphBackendParams} for ONE graph construct
 * from an options bag. Extracted from (and shared with) the preload's
 * param resolution so the two sites can never drift: `preloadCauslWasm`
 * bakes the preload caller's bag into the handle (the documented boot
 * inheritance for bare `createCauslWasmSync()` / implicit `createCausl()`),
 * and `createCauslWasm` resolves a fresh bag from its own options on every
 * call — the compile cache is reused, the params are not.
 *
 * `resolveWasmEngineMode` throws a `RangeError` on an unrecognised
 * `engine` value — fail-closed on EVERY call, including calls that hit the
 * preload cache (pre-#82 a typo'd `engine` on a cache-hit call was
 * silently swallowed).
 *
 * @internal
 */
function resolvePerGraphBackendParams(
  options: AuthoritativeWasmOptions,
  resolvedBridge: BridgeId,
): PerGraphBackendParams {
  const engineMode = resolveWasmEngineMode(options.engine)
  // #163 — `batchedFlush` is a purely explicit per-graph wire-tempo opt-in.
  // The shipped rust-ssot engine (AuthoritativeWasmEngine) crosses the wire
  // per commit and never consults it, so auto-baking a default window on the
  // rust-ssot path advertised amortised batching the default path does not
  // perform (dead configuration). Thread ONLY the adopter's explicit opt-in.
  const batchedFlush = options.batchedFlush
  // GRAPH_ID_REGEX is /^[A-Za-z0-9_.:-]{1,256}$/ — no `/`, `@`, or other
  // non-id chars. Mint the default with the dot-separated form that
  // survives the validator (matches instantiateBackend).
  const graphName = options.graphName ?? `causl.wasm.${resolvedBridge}`
  return {
    graphName,
    engineMode,
    batchedFlush,
    // lift-readat (#170) — carry the adopter's retention caps so the
    // construct threads them into the wrapped TS `#graph`.
    retentionCaps: resolveRetentionCaps(options),
  }
}

/**
 * The ONE synchronous construct codepath (directive #3) shared by the
 * handle-driven {@link createCauslWasmSync} (per-graph params from the
 * handle — preload-boot inheritance) and the async {@link createCauslWasm}
 * (per-graph params re-resolved from the CALL's own options, #82). WIRE
 * (epic #31 / issue #32): the real wasm instantiate + authoritative flip.
 * `instantiateConsolidatedBridgeSync` runs the §18A.12 synchronous
 * primitive `new WebAssembly.Instance` (NOT `await WebAssembly.instantiate`)
 * against the already-compiled module, then `__enableAuthoritativeWasm`
 * installs the `__causl_compute` / `__causl_fire` snippet handlers and
 * mints the live `AuthoritativeWasmEngine`. That engine is injected into
 * `createCausl({ injectedBackend })` so commit / read / subscribe /
 * derived-compute run through the REAL Rust→wasm engine.
 *
 * §18A.13.1 — `new WebAssembly.Instance` throws (CompileError / LinkError /
 * RangeError) on a host where the WasmGC engine cannot instantiate (Safari
 * < 18 / macOS < 15, policy-pinned pre-119 Chromium/WebView2, Node ≤ 20).
 * Normalise that raw throw to the structured `WasmEngineUnavailableError`
 * family so BOTH call sites discriminate it on the stable `code`:
 *   - EXPLICIT callers (createCauslWasm* / engine:'rust-ssot') re-throw it
 *     loud (`CAUSL_WASM_ENGINE_UNAVAILABLE`) — a consumer that asked for
 *     wasm must never silently run on JS.
 *   - the IMPLICIT createCausl() path (via wasm-registry's
 *     `isCapabilityFailure`) degrades LOUDLY to the TS floor.
 *
 * @internal
 */
function constructWasmGraphSync(
  resolved: CauslWasmModule,
  perGraph: PerGraphBackendParams,
  createOpts: import('../src/types.js').CreateCauslOptions,
): Graph {
  // #108 — a capability-unavailable sentinel handle (WasmGC could not COMPILE
  // on this host) carries no live module. Throw the SAME structured
  // `WasmEngineUnavailableError` (`CAUSL_WASM_ENGINE_UNAVAILABLE`) the
  // instantiate-time failure produces, so BOTH construct entrypoints
  // discriminate it identically: EXPLICIT callers re-throw loud; the IMPLICIT
  // `createCausl()` path (via the registry's `isCapabilityFailure` catch)
  // degrades loud to the TS floor. This is the §18A.13.1 fallback wired at the
  // validation boundary a real incapable host actually fails at.
  if (resolved.capabilityUnavailable !== undefined) {
    throw new WasmEngineUnavailableError(
      `the WasmGC engine could not COMPILE on this host (bridge ` +
        `'${resolved.bridge}'). This is the §18A.13.1 WasmGC-unavailable ` +
        `capability failure (validation-time — the mode real incapable hosts ` +
        `produce).`,
      resolved.capabilityUnavailable.cause,
    )
  }
  let exports: WasmBridgeExports
  try {
    exports = instantiateConsolidatedBridgeSync({
      module: resolved.module,
      imports: resolved.imports,
      sidecar: resolved.sidecar,
      sidecarHref: resolved.sidecarHref,
    })
  } catch (err) {
    if (err instanceof WasmEngineUnavailableError) throw err
    throw new WasmEngineUnavailableError(
      `createCauslWasmSync(): the WasmGC engine could not instantiate on ` +
        `this host (bridge '${resolved.bridge}'). This is the §18A.13.1 ` +
        `WasmGC-unavailable capability failure.`,
      err,
    )
  }
  const backend = new WasmBackend(
    resolved.bridge,
    perGraph.graphName,
    perGraph.batchedFlush,
    perGraph.engineMode,
    perGraph.retentionCaps,
  )
  backend.__attachWasmExportsForTests(exports)
  backend.__enableAuthoritativeWasm(resolved.computeImports)
  const engine = backend.getAuthoritativeEngine()
  if (engine === undefined) {
    throw new WasmEngineUnavailableError(
      'createCauslWasmSync(): the authoritative engine was not installed ' +
        'after __enableAuthoritativeWasm(). This is a wiring bug.',
    )
  }
  // #141 — the wasm `Graph` is a WasmBackend (Rust-owned input `readAt`) wrapped
  // by a TS closure (JS-owned derived `readAt`, from THIS `createOpts`). Feed
  // BOTH the ONE resolved `perGraph.retentionCaps` window so a graph never
  // answers history queries with two windows split by node kind: overwrite the
  // TS closure's raw cap fields with the resolved caps (which already folded any
  // per-call caps over the preload's on the sync path — #82 re-resolves them
  // per call on the async path). The two sites cannot drift.
  const graph = createCausl(
    withInjectedBackend(
      withResolvedRetentionCaps(createOpts, perGraph.retentionCaps),
      engine,
    ),
  )
  wasmBackendByGraph.set(graph, backend)
  // #111 — wire the reachable per-graph teardown (public `dispose()` /
  // `Symbol.dispose` + finalizer backstop + live-registry tracking) so a
  // retired graph frees its engine instead of leaking it via the sidecar's
  // module-level handler maps.
  registerWasmGraphTeardown(graph, backend)
  return graph
}

/**
 * #141 — replace an options bag's raw retention-cap fields with the ONE
 * resolved {@link PerGraphBackendParams.retentionCaps} window, so the TS closure
 * `createCausl` builds (it owns derived-node `readAt`) shares the exact window
 * the {@link WasmBackend} carries (it owns input-node `readAt`). Absent keys are
 * omitted rather than set to `undefined` (`exactOptionalPropertyTypes`); every
 * OTHER field on the bag — including the private `INJECTED_BACKEND` symbol if
 * present — is preserved verbatim.
 *
 * @internal
 */
function withResolvedRetentionCaps<
  T extends {
    readonly commitHistoryCap?: number
    readonly snapshotRetentionCap?: number
  },
>(options: T, retentionCaps: PerGraphBackendParams['retentionCaps']): T {
  const { commitHistoryCap: _c, snapshotRetentionCap: _s, ...rest } = options
  return {
    ...rest,
    ...(retentionCaps?.commitHistoryCap !== undefined
      ? { commitHistoryCap: retentionCaps.commitHistoryCap }
      : {}),
    ...(retentionCaps?.snapshotRetentionCap !== undefined
      ? { snapshotRetentionCap: retentionCaps.snapshotRetentionCap }
      : {}),
  } as unknown as T
}

/**
 * #82 — test-only registry mapping every wasm-constructed public `Graph` to
 * the `WasmBackend` behind its injected engine, so the per-graph-params
 * fidelity gate can observe WHICH engine mode / graph name / batched-flush /
 * retention caps a construct actually applied (the js-ssot / rust-ssot
 * contract is byte-identity, so no public behavioural probe can durably
 * distinguish the modes — the probe must be structural). A `WeakMap` keeps
 * the registry leak-free: entries die with the graph.
 *
 * @internal
 */
const wasmBackendByGraph = new WeakMap<Graph, WasmBackend>()

/**
 * #111 — per-graph teardown closures, keyed weakly by the public `Graph`. The
 * closure removes the engine's per-`engineId` sidecar handler registrations
 * (freeing the module-level handler maps that otherwise pin the whole engine),
 * frees its Rust slot, and drops the graph from the live registry. `Symbol.dispose`
 * / `graph.dispose` and {@link disposeCauslWasmGraph} both route here.
 *
 * @internal
 */
const wasmGraphTeardowns = new WeakMap<Graph, () => void>()

/**
 * #111 — the set of live wasm backends, held through {@link WeakRef} so
 * tracking a backend for the HMR/test reset never pins its engine (a strong
 * Set would re-introduce the very leak). {@link __resetWasmBackendCacheForTests}
 * iterates and disposes each still-live engine before dropping the shared
 * instance.
 *
 * @internal
 */
const liveWasmBackends = new Set<WeakRef<WasmBackend>>()

/**
 * #111 — the finalizer backstop. When a wasm `Graph` becomes unreachable
 * WITHOUT an explicit `dispose()`, its engine would still be pinned forever by
 * the sidecar's module-level per-`engineId` handler maps (the closures registered
 * in {@link AuthoritativeWasmEngine} capture `this`). Registering the graph here
 * with the backend as the held value lets the collector run the same teardown on
 * GC. The held value references the backend but NOT the graph, so it never keeps
 * the graph alive; guarded for hosts without `FinalizationRegistry`.
 *
 * @internal
 */
interface WasmGraphDisposeToken {
  readonly backend: WasmBackend
  readonly ref: WeakRef<WasmBackend>
}
const wasmGraphFinalizers =
  typeof FinalizationRegistry === 'function'
    ? new FinalizationRegistry<WasmGraphDisposeToken>((token) => {
        token.backend.disposeAuthoritativeEngine()
        liveWasmBackends.delete(token.ref)
      })
    : undefined

/**
 * #111 — wire the per-graph teardown for a freshly constructed wasm `Graph`:
 * track the backend in the live registry, register the finalizer backstop, and
 * attach a public `graph.dispose()` + `graph[Symbol.dispose]` (so `using` frees
 * it). The teardown is idempotent (the engine's own `dispose()` guards on
 * `#handlersInstalled`; the map/registry deletes are no-ops on the second call).
 */
function registerWasmGraphTeardown(graph: Graph, backend: WasmBackend): void {
  const ref = new WeakRef(backend)
  liveWasmBackends.add(ref)
  const teardown = (): void => {
    backend.disposeAuthoritativeEngine()
    wasmBackendByGraph.delete(graph)
    wasmGraphTeardowns.delete(graph)
    liveWasmBackends.delete(ref)
    wasmGraphFinalizers?.unregister(graph)
  }
  wasmGraphTeardowns.set(graph, teardown)
  wasmGraphFinalizers?.register(graph, { backend, ref }, graph)
  // The facade is an extensible object literal with no `dispose` member; attach
  // the teardown as a non-enumerable method + the well-known disposal symbol.
  const attach = (key: PropertyKey): void => {
    Object.defineProperty(graph, key, {
      value: teardown,
      configurable: true,
      writable: true,
      enumerable: false,
    })
  }
  attach('dispose')
  if (typeof Symbol.dispose === 'symbol') attach(Symbol.dispose)
}

/**
 * #111 — public per-graph teardown. Releases the wasm engine behind a
 * `Graph` constructed by this module: removes its per-`engineId` handler
 * registrations from the sidecar (the module-level maps that otherwise pin the
 * whole engine — its unbounded value cache, fn-table, and observers), frees its
 * Rust slot (when the artefact carries the per-engine free extern), and drops
 * it from the live registry. Idempotent; a no-op for a graph this module did
 * not construct (e.g. a pure-TS `createCauslTs` fallback). Equivalent to
 * `graph.dispose()` / `using graph = createCauslWasmSync(...)`.
 */
export function disposeCauslWasmGraph(graph: Graph): void {
  wasmGraphTeardowns.get(graph)?.()
}

/**
 * #82 — resolve the `WasmBackend` behind a wasm-constructed `Graph`, or
 * `undefined` for a graph this module did not construct (e.g. a pure-TS
 * `createCauslTs` fallback graph). Test-only.
 *
 * @internal
 */
export function __wasmBackendForTests(graph: Graph): WasmBackend | undefined {
  return wasmBackendByGraph.get(graph)
}

/**
 * Sentinel bridge id for the {@link CauslWasmNotPreloadedError} message when
 * `createCauslWasmSync()` is called with NOTHING preloaded and no pinned
 * bridge — the sync factory cannot run `detectBridge()` to name a concrete
 * bridge, so the error names this placeholder + the remedy.
 *
 * @internal
 */
const UNRESOLVED_BRIDGE = '<none-preloaded>' as BridgeId

// ---------------------------------------------------------------------------
// FLIP (epic #31 / issue #33) — register the synchronous wasm engine into the
// main-bundle `../src/wasm-registry.js` slot. Side-effect at module top-level:
// importing (or preloading) `@causl/client-ts/wasm` wires `createCausl()` (in
// `../src/graph.ts`) to route to the REAL wasm engine WHEN a module is
// preloaded for the default bridge, and to fall back to `createCauslTs`
// otherwise.
//
// Leak-free by construction. The edge runs wasm-subpath → registry ONLY; the
// main bundle never names `createCauslWasmSync` / `loadWasmBackend` /
// `WasmBackendUnavailableError`. The registered `createSync` builds its
// `Graph` via `createCausl({ injectedBackend })` (inside `createCauslWasmSync`);
// that re-entrant `createCausl` carries an `injectedBackend`, which the FLIP
// guard in `createCausl` treats as an explicit engine choice and routes
// straight to the TS closure — so registration is non-recursive.
//
// `isPreloadedForDefaultBridge` is the no-arg `isCauslWasmPreloaded()`
// (resolved-ness of the most-recently-resolved bridge). `createSync` forwards
// the caller's `CreateCauslOptions` as `createCauslWasmSync`'s `create` arg so
// `name` / history-cap / observer-error handler flow into the wasm engine.
registerWasmSyncEngine({
  isPreloadedForDefaultBridge: () => isCauslWasmPreloaded(),
  createSync: (createOptions) => createCauslWasmSync(undefined, createOptions),
  // §18A.13.1 / #124 — only a POSITIVELY-classified WasmGC host-capability
  // failure degrades the implicit createCausl() path to the TS floor. The base
  // `'CAUSL_WASM_ENGINE_UNAVAILABLE'` code is NOT sufficient on its own:
  // `constructWasmGraphSync` normalises EVERY instantiate-time throw — including
  // genuine wiring bugs ('authoritative engine was not installed') and
  // artefact/sidecar version skew on an otherwise healthy host — into that same
  // base code. Matching the code alone therefore misdiagnosed those failures as
  // 'Safari < 18 / Node <= 20' and silently degraded the whole fleet to the TS
  // floor, contradicting the contract that any non-capability throw propagates.
  //
  // Instead, classify by SHAPE via `isWasmCapabilityError`: a genuine WasmGC
  // host-capability failure is a `WebAssembly.CompileError` / `LinkError`
  // (raw, or wrapped one `cause` level deep inside the normalised
  // `WasmEngineUnavailableError`). The not-preloaded subclass, a missing/unserved
  // artefact, and any wiring/version-skew bug carry no such cause ⇒ classified
  // `false` ⇒ they propagate on every path (loud) instead of degrading.
  isCapabilityFailure: (err) => isWasmCapabilityError(err),
})

async function instantiateBackend(
  bridge: BridgeId,
  options: WasmBackendOptions,
): Promise<BackendEngine> {
  // Phase-1 (#1065): construct a `WasmBackend` whose internal commit
  // pipeline routes through a TS engine produced by `createCausl()`.
  // The TS engine is the canonical SPEC-faithful reference: anything
  // it accepts the future Rust-driven engine must accept, anything it
  // rejects (CycleError, NodeDisposedError, etc.) the Rust engine
  // must reject identically. Wrapping it preserves the determinism
  // contract — `transition_js(s, a) == transition_wasm_serde(s, a)`
  // is true today by construction, which is exactly what the
  // cross-backend determinism gate (#685) needs to fire.
  //
  // Once the wasm-pack artifacts (#682 / #683 / Sub-B #1062) are
  // routinely shipped alongside the JS bundle, the internal commit
  // pipeline can be swapped to call through the bridge's
  // `commit(state, action)` boundary. The public shape this loader
  // returns does not change; the only swap is the `commit`/`hydrate`
  // implementations on the returned `BackendEngine`.
  //
  // `wasmUrlFor()` is still evaluated as a forward-compat sanity
  // check — the URL must be resolvable for the bridge id, even when
  // the artifact itself is not loaded yet. `options.fetch` is touched
  // so the eventual streaming-instantiate path doesn't lose the
  // configuration option at the call site.
  void wasmUrlFor(bridge, options.wasmBaseUrl)
  void options.fetch
  // GRAPH_ID_REGEX is /^[A-Za-z0-9_.:-]{1,256}$/ — no `/`, `@`, or
  // other non-id chars allowed. Mint the default with the
  // dot-separated form that survives the validator.
  const graphName = options.graphName ?? `causl.wasm.${bridge}`
  // C.4 (#1505) — thread the per-graph batchedFlush opt-in through to
  // the backend. `options.batchedFlush === undefined` ⇒ no queue ⇒
  // byte-identical to dev b15069fa (load-bearing).
  //
  // V2.1 (#1519) — thread the per-graph `engine` canonicality opt-in
  // (V2-DESIGN §2). `options.engine === undefined` ⇒ DEFAULT_WASM_
  // ENGINE_MODE ('js-ssot') ⇒ byte-identical to dev `97da8420` (the
  // load-bearing V2.1 acceptance property — V2-DESIGN §2.2). Mirrors
  // the `batchedFlush` threading above.
  const engineMode = resolveWasmEngineMode(options.engine)
  // #163 — `batchedFlush` is a purely explicit per-graph wire-tempo opt-in.
  // The shipped rust-ssot engine (AuthoritativeWasmEngine) crosses the wire
  // per commit and never consults it, so auto-baking a default window on the
  // rust-ssot path advertised amortised batching the default path does not
  // perform (dead configuration). Thread ONLY the adopter's explicit opt-in;
  // omitting it stays byte-identical to the pre-C.3 per-commit shadow path.
  const batchedFlush = options.batchedFlush
  return new WasmBackend(
    bridge,
    graphName,
    batchedFlush,
    engineMode,
    resolveRetentionCaps(options),
  )
}

/**
 * lift-readat (causl/causl-core-rs#170) — build the retention-cap bag the
 * {@link WasmBackend} threads into its wrapped TS `#graph`, omitting absent
 * keys so `exactOptionalPropertyTypes` stays satisfied (no `undefined`
 * VALUES on the wire). Returns `undefined` when neither cap is supplied —
 * the pre-lift-readat cap-0 default.
 */
function resolveRetentionCaps(options: {
  readonly commitHistoryCap?: number
  readonly snapshotRetentionCap?: number
}):
  | { readonly commitHistoryCap?: number; readonly snapshotRetentionCap?: number }
  | undefined {
  if (
    options.commitHistoryCap === undefined &&
    options.snapshotRetentionCap === undefined
  ) {
    return undefined
  }
  return {
    ...(options.commitHistoryCap !== undefined
      ? { commitHistoryCap: options.commitHistoryCap }
      : {}),
    ...(options.snapshotRetentionCap !== undefined
      ? { snapshotRetentionCap: options.snapshotRetentionCap }
      : {}),
  }
}

/**
 * V2.1 (#1519) — validate + normalise the per-graph `engine` opt-in.
 *
 * `undefined` ⇒ {@link DEFAULT_WASM_ENGINE_MODE}. Since the
 * promote-default flip (causl/causl-core-rs#169, §18A.7 GO) that default
 * is `'rust-ssot'` — the WASM path routes commit through the Rust
 * engine by default and applies the Rust post-state UNCONDITIONALLY
 * (§18A.8 fail-safe-removal: no per-flush TS-vs-Rust byte-compare, no
 * rollback, no sticky-downgrade — the cross-backend determinism gate
 * is the sole guarantee). Passing `engine: 'js-ssot'` explicitly
 * selects the floor opt, which remains byte-identical to dev
 * `97da8420`. An unrecognised string throws a
 * `RangeError` at construction (fail-closed: a typo'd `engine` value
 * must NOT silently fall through to the default and mask an adopter
 * intent to opt into rust-ssot). Mirrors the `batchedFlush`
 * validation shape in the {@link WasmBackend} constructor.
 */
export function resolveWasmEngineMode(
  engine: WasmEngineMode | undefined,
): WasmEngineMode {
  if (engine === undefined) return DEFAULT_WASM_ENGINE_MODE
  if (engine !== 'js-ssot' && engine !== 'rust-ssot') {
    throw new RangeError(
      `createCausl({ engine }): engine must be 'js-ssot' or ` +
        `'rust-ssot' (got ${JSON.stringify(engine)})`,
    )
  }
  return engine
}

// ---------------------------------------------------------------------------
// C.3 (#1501) — BatchedFlush queue.
//
// Option (c) batched-commit boundary scaffolding (epic #1493). Per
// `docs/epic-1483/option-c-batched-boundary.md` §2.1 Answer C the JS
// engine is SSOT: `commit()` returns the TS graph's `Commit`
// synchronously; the marshaler runs in a buffered SHADOW mode. The
// only thing this queue batches is the WASM-side WIRE crossing — NOT
// the commit semantics, NOT subscriber dispatch (§4.2 choice (i)), NOT
// `graph.now` advancement (§3.1, one tick per commit always).
//
// **No adopter-visible perf change at v1.x.** With the default
// `afterN = 1` (wired through `createCausl` in C.4) the queue flushes
// immediately on every commit, which is byte-identical to the
// pre-C.3 per-commit shadow path (option-c doc §2.3 / §7). This is
// scaffolding for a future v2.x Rust-SSOT cutover, not a perf win;
// the #1133 boundary-tax falsification is not refuted by this work.
// ---------------------------------------------------------------------------

/**
 * The shadow bridge adapter the {@link BatchedFlush} queue drives. The
 * single-commit `commit(state, action)` is the pre-C.3 F-marshal.5
 * shadow surface (kept for the `afterN === 1` fast path and for
 * adapters that have not adopted `commit_batch` yet); `commit_batch`
 * is the C.1 batched extern (`tools/engine-rs-bridge-{serde,gc}`,
 * PRs #1496/#1497).
 */
export interface BatchedFlushBridge {
  commit(state: unknown, action: unknown): unknown
  /**
   * Optional — the C.1 `commit_batch(state, actions)` extern. When a
   * primed bridge does not expose it (legacy single-commit adapters,
   * older test mocks) the queue degrades to N sequential
   * `commit(state, action)` calls, which is byte-identical by
   * construction (option-c doc §3.1) — the loop body IS the
   * single-envelope path.
   */
  commit_batch?(state: unknown, actions: unknown): unknown
}

/**
 * C.4 (#1505) — per-graph adopter opt-in for batched-flush mode.
 *
 * Passed via `createCausl({ batchedFlush })` (auto-backend path) or
 * `loadWasmBackend({ batchedFlush })` (direct path). Per-graph, NOT
 * global (option-c doc §2.3) — multi-graph adopters (`@causl/sync`,
 * embedded use-cases) opt in per graph without cross-graph coupling.
 *
 * **Omitting `batchedFlush` entirely is byte-identical to dev
 * `b15069fa`** (the load-bearing C.4 acceptance property): no queue
 * is installed, the pre-C.3 per-commit shadow path runs unchanged,
 * and adopter `commit()` / `read()` / `subscribe()` results are
 * exactly what they were before this cascade. Zero codemod, zero
 * deprecation, zero behavioural change unless the adopter explicitly
 * passes this option.
 *
 * **No adopter-visible perf change at v1.x even when opted in** — the
 * JS engine remains SSOT; only the WASM-side wire crossing batches.
 * Scaffolding for a future v2.x Rust-SSOT cutover, not a perf win.
 */
export interface BatchedFlushOptions {
  /**
   * Count-based flush threshold. Default `1` — flush every commit,
   * byte-identical to the pre-C.3 per-commit shadow path
   * (option-c doc §2.3). Adopters who want wire amortisation set
   * `afterN: 100` (production-grade per §1.2) or `312` (the #1484 §3
   * kill-threshold — meets the floor on every contract-bearing cell).
   * Must be an integer ≥ 1.
   */
  readonly afterN?: number
  /**
   * Time-based flush threshold (ms). Default `16` — one 60 Hz frame
   * (option-c doc §2.2). Bounds flush latency when the commit rate is
   * below `afterN / intervalMs`. `0` disables the time trigger
   * (count / manual / implicit only). Must be a finite number ≥ 0.
   */
  readonly intervalMs?: number
}

/**
 * C.3 (#1501) — buffered shadow-flush queue for the WASM wire
 * crossing.
 *
 * Buffers per-commit `(intent, writes)` shadow inputs and flushes them
 * as a single `commit_batch` envelope when a trigger fires:
 *
 *   - **count** — `afterN` commits buffered (this PR);
 *   - **time** — `intervalMs` elapsed since the first buffered commit
 *     (C.3 PR 2);
 *   - **manual** — {@link flush} called explicitly (this PR);
 *   - **implicit** — `snapshot()` / `dispose()` force a flush so the
 *     WASM-side state reflects committed work (C.3 PR 3).
 *
 * The queue NEVER influences the adopter-facing `Commit` — that is the
 * TS graph's synchronous return (Answer C). A flush failure is
 * captured for the cross-backend determinism gate's assertion path
 * exactly as the pre-C.3 shadow path captured per-commit failures;
 * adopter commits do not throw on shadow failures (the TS graph is
 * SSOT).
 */
/**
 * C.3 PR 2 (#1501) — injectable timer surface for the time-based flush
 * trigger. Production wires `setTimeout` / `clearTimeout`; tests inject
 * a fake-clock so the 16 ms interval is exercised deterministically
 * without leaking real timers into the suite.
 */
export interface FlushTimer {
  schedule(callback: () => void, ms: number): unknown
  cancel(handle: unknown): void
}

/**
 * Default {@link FlushTimer} — host `setTimeout` / `clearTimeout`. The
 * `.unref?.()` call (Node) keeps a pending flush timer from holding
 * the event loop open (a buffered shadow flush must never prevent
 * process exit — the TS graph is SSOT, the shadow is best-effort).
 */
const HOST_FLUSH_TIMER: FlushTimer = {
  schedule(callback, ms) {
    const h = setTimeout(callback, ms) as unknown as {
      unref?: () => void
    }
    h.unref?.()
    return h
  },
  cancel(handle) {
    clearTimeout(handle as ReturnType<typeof setTimeout>)
  },
}

/**
 * Buffered-commit flush coordinator for the WASM backend's batch path.
 *
 * @remarks
 * Bridges the per-commit {@link WasmStateMirror} updates onto a single
 * `commit_batch` Rust call when either the count threshold ({@link BatchedFlush.afterN})
 * or the time threshold ({@link BatchedFlush.intervalMs}) trips.
 *
 * Two engine modes (§18A.8 fail-safe-removal, causl/causl-core-rs#169):
 *   - `'rust-ssot'` (the default) — the Rust `commit_batch` post-state is
 *     applied to the mirror UNCONDITIONALLY and the last projected
 *     `Commit` of the window is exposed via {@link lastPromotedCommit} as
 *     the adopter-facing canonical result. There is no per-flush
 *     TS-vs-Rust byte-compare, no rollback, and no sticky-downgrade — the
 *     CI-blocking cross-backend determinism gate (§18A.1.1) is the sole
 *     guarantee the Rust engine matches the TS reference.
 *   - `'js-ssot'` — the explicit TS-engine FLOOR opt (§18A.7 Criterion 5).
 *     The Rust shadow is applied to the mirror exactly as before; the
 *     wrapped TS `#graph` remains the adopter-facing SSOT and
 *     {@link lastPromotedCommit} stays `undefined`. Byte-identical to dev
 *     `97da8420`.
 *
 * @see {@link https://github.com/iasbuilt/causl/issues/1501} — C.3 PR 2 (time-trigger introduction).
 */
export class BatchedFlush {
  /** Count-based flush threshold. `1` = flush every commit (default). */
  readonly afterN: number

  /**
   * C.3 PR 2 (#1501) — time-based flush threshold (ms). Default 16 ms
   * = one animation frame at 60 Hz (option-c doc §2.2). `0` disables
   * the time trigger (count / manual / implicit only). A flush is
   * scheduled when the FIRST commit is buffered and fires after
   * `intervalMs` unless the count threshold flushes first.
   */
  readonly intervalMs: number

  /** Buffered per-commit shadow inputs, in commit order. */
  readonly #buffer: BatchCommitInput[] = []

  /** The mirror the queue marshals against (Decision 1 SSOT — JS-side). */
  readonly #mirror: WasmStateMirror

  /** Shadow bridge adapter (single + optional batched extern). */
  readonly #bridge: BatchedFlushBridge

  /** Captured flush error for the determinism gate's assertion path. */
  #error: Error | undefined

  /**
   * promote-commit (causl/causl-core-rs#169) — the Rust canonical
   * {@link Commit} for the MOST RECENT flush, or `undefined` when there was
   * no rust-ssot flush this turn (`engine: 'js-ssot'`, the degrade
   * no-batched-extern path, or no flush this turn). Set to the LAST projected
   * Rust record of the window UNCONDITIONALLY under `'rust-ssot'` (§18A.8
   * fail-safe-removal — no byte-compare gates the promotion). RESET to
   * `undefined` as the FIRST statement of every {@link flush} (before the
   * buffer splice), so a stale value from a prior flush can NEVER be read as
   * this turn's canonical commit.
   *
   * This is the flush-boundary canonical-commit seam: under
   * `engine: 'rust-ssot'` with the synchronous `afterN === 1` window,
   * {@link WasmBackend.commit} reads this immediately after `enqueue` to RETURN
   * the Rust-derived `Commit` as the canonical authority. When this is
   * `undefined` (a buffered `afterN > 1` window, a timer-deferred flush, or
   * the `'js-ssot'` floor opt) the caller returns the wrapped TS-engine
   * `Commit`.
   */
  #lastPromotedCommit: Commit | undefined

  /**
   * The `mirror.now` value the NEXT flush's envelope must start from
   * (the pre-batch clock). Set when the first commit is buffered so
   * the batch envelope's `state.now` matches what the SSOT TS engine
   * started the first buffered commit from — mirrors the pre-C.3
   * per-commit `mirror.now` sync (index.ts:581).
   */
  #pendingBaseNow: number | undefined

  /** C.3 PR 2 — injectable timer surface. */
  readonly #timer: FlushTimer

  /** C.3 PR 2 — handle of the in-flight interval timer (if any). */
  #timerHandle: unknown

  /**
   * The per-graph engine canonicality mode threaded from
   * {@link WasmBackend.#engineMode}. `'rust-ssot'` (the default) makes
   * `flush()` apply the Rust `commit_batch` post-state to the mirror
   * UNCONDITIONALLY and expose the last projected `Commit` of the window
   * via {@link lastPromotedCommit} (§18A.8 fail-safe-removal — no
   * byte-compare, no rollback). `'js-ssot'` (the explicit floor opt) keeps
   * the Rust shadow applied but leaves {@link lastPromotedCommit}
   * `undefined`, so `WasmBackend.commit()` returns the wrapped TS-engine
   * `Commit` — byte-identical to dev `97da8420`.
   */
  readonly #engineMode: WasmEngineMode

  constructor(
    mirror: WasmStateMirror,
    bridge: BatchedFlushBridge,
    afterN = 1,
    intervalMs = 16,
    timer: FlushTimer = HOST_FLUSH_TIMER,
    engineMode: WasmEngineMode = DEFAULT_WASM_ENGINE_MODE,
  ) {
    if (!Number.isInteger(afterN) || afterN < 1) {
      throw new RangeError(
        `BatchedFlush: afterN must be an integer >= 1 (got ${String(afterN)})`,
      )
    }
    if (!Number.isFinite(intervalMs) || intervalMs < 0) {
      throw new RangeError(
        `BatchedFlush: intervalMs must be a finite number >= 0 (got ${String(intervalMs)})`,
      )
    }
    this.#mirror = mirror
    this.#bridge = bridge
    this.afterN = afterN
    this.intervalMs = intervalMs
    this.#timer = timer
    this.#engineMode = engineMode
  }

  /** Number of commits currently buffered (un-flushed). */
  get pending(): number {
    return this.#buffer.length
  }

  /**
   * promote-commit (causl/causl-core-rs#169) — the Rust canonical
   * {@link Commit} the MOST RECENT flush produced, or `undefined` when there
   * was no rust-ssot flush this turn (see {@link #lastPromotedCommit}).
   * {@link WasmBackend.commit} reads this immediately after a synchronous
   * (`afterN === 1`) `enqueue` to return the Rust-derived `Commit` as the
   * canonical authority under `rust-ssot`. `undefined` is the signal to
   * return the wrapped TS-engine `Commit` (the `'js-ssot'` floor opt).
   *
   * @internal Canonical-commit seam, not adopter-facing surface.
   */
  get lastPromotedCommit(): Commit | undefined {
    return this.#lastPromotedCommit
  }

  /**
   * Captured flush error, if the most recent flush threw. Cleared on
   * the next successful flush. The cross-backend determinism gate
   * asserts this stays `undefined`.
   */
  get error(): Error | undefined {
    return this.#error
  }

  /**
   * Buffer one commit's shadow input. The `baseNow` is the TS graph's
   * PRE-commit clock for the FIRST buffered commit (the value the
   * batch envelope's `state.now` must carry); subsequent commits in
   * the same window do not move it (the Rust extern threads the
   * post-state internally). Triggers a count-based flush when the
   * buffer reaches `afterN`.
   */
  enqueue(input: BatchCommitInput, baseNow: number): void {
    if (this.#buffer.length === 0) {
      this.#pendingBaseNow = baseNow
      // C.3 PR 2 — arm the time-based trigger on the FIRST buffered
      // commit. Prevents arbitrary flush latency when the commit rate
      // is below `afterN / intervalMs` (option-c doc §2.2 + surprise
      // #3: the 60 Hz × N=100 1.67 s latency makes time-based flush
      // non-optional). `intervalMs === 0` disables it.
      if (this.intervalMs > 0) {
        this.#armTimer()
      }
    }
    this.#buffer.push(input)
    if (this.#buffer.length >= this.afterN) {
      this.flush()
    }
  }

  /**
   * C.3 PR 2 — schedule the interval flush. Cancels any prior handle
   * first (defensive — `enqueue` only arms on an empty buffer so this
   * is a single-armed invariant, but a future caller path must not
   * leak overlapping timers).
   */
  #armTimer(): void {
    this.#cancelTimer()
    this.#timerHandle = this.#timer.schedule(() => {
      this.#timerHandle = undefined
      // The timer fires on the macrotask AFTER the buffering commits;
      // `flush()` is a no-op if a count/manual flush already drained
      // the buffer, so the time trigger is safe to fire unconditionally.
      this.flush()
    }, this.intervalMs)
  }

  /** C.3 PR 2 — cancel the in-flight interval timer, if any. */
  #cancelTimer(): void {
    if (this.#timerHandle !== undefined) {
      this.#timer.cancel(this.#timerHandle)
      this.#timerHandle = undefined
    }
  }

  /**
   * C.3 PR 2 — `true` when a time-based flush is currently armed.
   * Exposed for tests and the C.3 PR 3 implicit-flush callers (which
   * must cancel a pending timer when they force a synchronous flush).
   */
  get timerArmed(): boolean {
    return this.#timerHandle !== undefined
  }

  /**
   * C.3 PR 2 — release the interval timer without flushing. Called by
   * the C.3 PR 3 dispose path; idempotent. Does NOT drain the buffer
   * (a caller that needs the bytes on the wire calls {@link flush}
   * first — the implicit-flush wiring in C.3 PR 3 does exactly that).
   */
  cancelTimer(): void {
    this.#cancelTimer()
  }

  /**
   * Flush the buffer as a single `commit_batch` envelope (or, if the
   * bridge lacks the batched extern, as N sequential single-commit
   * calls — byte-identical by construction, option-c doc §3.1). A
   * no-op when the buffer is empty (so implicit/manual flushes are
   * always safe to call). The projected `Commit[]` is returned for
   * the C.3 PR 3 implicit-flush callers; the per-commit subscriber
   * fire is the JS engine's job (Answer C — NOT batched here).
   */
  flush(): Commit[] {
    // C.3 PR 2 — a count/manual/implicit flush supersedes a pending
    // time trigger; cancel it so a stale timer can't double-flush an
    // already-drained (or freshly re-buffered) window.
    this.#cancelTimer()
    if (this.#buffer.length === 0) return []
    // promote-commit (causl/causl-core-rs#169) — CLEAR the canonical-commit
    // seam as the FIRST statement of every non-empty flush (before the
    // splice), so a `'js-ssot'` flush (or the degrade no-batched-extern
    // path, which has no projected window record) provably leaves it
    // `undefined` and `WasmBackend.commit()` can never read a stale value
    // from a prior flush as THIS window's canonical commit.
    this.#lastPromotedCommit = undefined
    const batch = this.#buffer.splice(0, this.#buffer.length)
    // §18A.8 fail-safe-removal (causl/causl-core-rs#169) — under `'rust-ssot'`
    // (the default) the Rust post-state is the UNCONDITIONAL canonical
    // authority for the mirror and the adopter-facing `Commit`; there is no
    // per-flush TS-vs-Rust byte-compare, no rollback, and no sticky-downgrade
    // (the cross-backend determinism gate is the sole guarantee). Under the
    // `'js-ssot'` FLOOR opt the Rust shadow is still applied to the mirror but
    // the wrapped TS `#graph` stays the adopter-facing SSOT, so the
    // canonical-commit seam is left `undefined`.
    const rustSsot = this.#engineMode === 'rust-ssot'
    const baseNow = this.#pendingBaseNow ?? (this.#mirror.now as unknown as number)
    this.#pendingBaseNow = undefined
    try {
      // Sync the mirror clock to the pre-batch base so the envelope's
      // `state.now` matches what the SSOT TS engine started the first
      // buffered commit from (mirrors index.ts:581's per-commit sync,
      // applied once per batch boundary).
      this.#mirror.now = baseNow as unknown as GraphTime
      const envelope = marshalBatchEnvelope(this.#mirror, batch)
      if (typeof this.#bridge.commit_batch === 'function') {
        const result = this.#bridge.commit_batch(
          envelope.state,
          envelope.actions,
        ) as BatchBridgeResult
        // Apply the Rust post-state to the mirror and project the N
        // `Commit`s for the C.3 implicit-flush callers.
        const commits = applyBatchBridgeResult(this.#mirror, result)
        if (rustSsot) {
          // §18A.8 — record the LAST projected Rust `Commit` of this window as
          // the canonical authority `WasmBackend.commit()` returns. With
          // `afterN === 1` (the synchronous window) the batch holds exactly the
          // calling commit, so the last element IS that commit. `commits` is
          // non-empty here (a flush only runs with a buffered window).
          this.#lastPromotedCommit = commits[commits.length - 1]
        }
        this.#error = undefined
        return commits
      }
      // Degrade path: the bridge has no batched extern. Replay the
      // batch as N sequential single-commit shadow calls. This is
      // byte-identical to the batched path by construction — the
      // loop body IS the single-envelope path (option-c doc §3.1).
      const commits: Commit[] = []
      for (const single of batch) {
        const singleEnv = marshalCommitEnvelope(
          this.#mirror,
          single.intent,
          single.writes as ReadonlyMap<NodeId, MarshalerJsonValue>,
        )
        const singleResult = this.#bridge.commit(
          singleEnv.state,
          singleEnv.action,
        ) as BridgeResult
        commits.push(applyBridgeResult(this.#mirror, singleResult))
      }
      this.#error = undefined
      return commits
    } catch (err) {
      // Shadow-path failure — captured for the determinism gate.
      // Adopter commits do not throw (the TS graph is SSOT).
      this.#error = err as Error
      return []
    }
  }
}

/**
 * WIRE (epic #31 / issue #32) — the wasm-bindgen extern surface the
 * consolidated Rust→wasm bridge exposes. Produced by `wasm-bindgen` on the
 * Rust side and surfaced to the {@link WasmBackend} via
 * {@link WasmBackend.__attachWasmExportsForTests}. The authoritative
 * full-fidelity surface (`apply_commands`, `read_cell_value`, `intern_string`,
 * `read_interned_string`) is what `__enableAuthoritativeWasm` requires; the
 * value-pool externs (`register_value_buf` / `read_pool_value`) and the
 * reset/test-isolation externs are optional.
 *
 * @internal
 */
export interface WasmBridgeExports {
  /** Serialises the rust-side thread-local engine state to bytes. */
  readonly __snapshot?: () => Uint8Array
  /** Replaces the rust-side thread-local engine state from bytes. */
  readonly __hydrate?: (bytes: Uint8Array) => void
  /**
   * Apply a binary command buffer against the per-`engine_id` engine state
   * and return the encoded diff buffer. See `./cmd-buf.ts` for the input
   * wire shape and `./diff-buf.ts` for the output diff stream.
   *
   * mux-2 (causl-client#42) — the glue now takes a leading `engine_id u32`
   * selecting the per-engine `ENGINE_STATE` slot. The
   * {@link AuthoritativeWasmEngine} passes its minted id; the rebuilt
   * artefact's `apply_commands_default(cmd_buf)` shim covers the legacy
   * engine-0 byte-identity harness.
   */
  readonly apply_commands?: (
    engine_id: number,
    cmd_buf: Uint8Array,
  ) => Uint8Array
  /** Read the input cell at `(engine_id, slot, gen)` as a packed `u64`. */
  readonly read_input?: (
    engine_id: number,
    slot: number,
    gen: number,
  ) => bigint
  /** Read the derived cell at `(engine_id, slot, gen)`, packed identically. */
  readonly read_derived?: (
    engine_id: number,
    slot: number,
    gen: number,
  ) => bigint
  /**
   * Full-fidelity read. Returns the cell at `(slot, gen)` as a 12-byte
   * value-buffer record (DESIGN §5.3). `is_input` selects the input vs.
   * derived cell table.
   *
   * mux-2 — leading `engine_id u32` selects this engine's cell tables.
   */
  readonly read_cell_value?: (
    engine_id: number,
    slot: number,
    gen: number,
    is_input: boolean,
  ) => Uint8Array
  /** Intern a UTF-8 byte string; returns its `StringId` (u32). */
  readonly intern_string?: (utf8: Uint8Array) => number
  /** Resolve a `StringId` (u32) back to its interned string. */
  readonly read_interned_string?: (string_id: number) => string | undefined
  /** Register a self-describing binary value-buffer; returns its `payload_id`. */
  readonly register_value_buf?: (value_buf: Uint8Array) => number
  /** Resolve a pooled `payload_id` (u32) to canonical JSON bytes (UTF-8). */
  readonly read_pool_value?: (payload_id: number) => Uint8Array | undefined
  /** Test-isolation — reset the thread-local engine state. */
  readonly __resetEngineState?: () => void
  /** Test-isolation — reset the thread-local intern table. */
  readonly __resetInternTable?: () => void
  /** Test-isolation — reset the thread-local value pool. */
  readonly __resetValuePool?: () => void
  /**
   * promote-read (causl/causl-core-rs#169 ffi-1) — depth-1 static dependency
   * adjacency of `(slot, gen)` on `engine_id`, as an identity-pair buffer.
   */
  readonly dependencies?: (
    engine_id: number,
    slot: number,
    gen: number,
  ) => Uint8Array
  /**
   * promote-read (ffi-1) — TRANSITIVE dependent closure of `(slot, gen)` on
   * `engine_id`, as an identity-pair buffer.
   */
  readonly dependents?: (
    engine_id: number,
    slot: number,
    gen: number,
  ) => Uint8Array
  /** promote-read (ffi-2) — per-engine commit-log buffer (oldest-first). */
  readonly commit_log?: (engine_id: number) => Uint8Array
  /**
   * #129 / causl/causl-core-rs#318 — the WIDENED per-engine commit log:
   * `(cap, total_commits_ever)` header pair + rows carrying the
   * hydrate-aware `originated_at` column.
   */
  readonly commit_log_meta?: (engine_id: number) => Uint8Array
  /**
   * causl-client#129 / causl/causl-core-rs#320 — the engine-owned dry-run of
   * a commit-window cmd-buf against a discarded state clone (the
   * `graph.simulate` baseline under the write-SSOT cutover).
   */
  readonly simulate_commands?: (
    engine_id: number,
    cmd_buf: Uint8Array,
  ) => Uint8Array
  /** promote-read (ffi-4) — per-engine telemetry counter buffer. */
  readonly stats?: (engine_id: number) => Uint8Array
  /**
   * lift-readat (causl/causl-core-rs#170) — the DISCRIMINATED historical
   * read of `(slot, gen)` on `engine_id` at GraphTime `time`, as the
   * 24-byte `read_at_result` record (status + graph_time + value record).
   */
  readonly read_at_result?: (
    engine_id: number,
    slot: number,
    gen: number,
    time: bigint,
  ) => Uint8Array
  /**
   * lift-export (causl/causl-core-rs#170) — the §18A.3 DEEP whole-graph
   * export of `engine_id`: the whole `CauslModel` IR (nodes + deps +
   * commit-log-with-originatedAt + the IRSubscribe event stream), as the
   * self-describing `export_model` buffer.
   */
  readonly export_model?: (engine_id: number) => Uint8Array
  /**
   * del-final (causl/causl-core-rs#170) — the per-node EXPLAIN metadata of
   * `(slot, gen)` on `engine_id` (kind + `computedAt` / `contributedAt`), as
   * the 20-byte `node_meta` record — the LAST TS-`entries` read `explain`
   * carried.
   */
  readonly node_meta?: (
    engine_id: number,
    slot: number,
    gen: number,
  ) => Uint8Array
}

/**
 * Phase-1 `BackendEngine` implementation backed by a TS engine.
 *
 * @remarks
 * The class satisfies the wasm-side `BackendEngine` interface
 * (NodeId-keyed read/subscribe/dispose) by maintaining an internal
 * registry that maps `NodeId` strings back to the typed `Node<T>`
 * handles the underlying `Graph` operates on. The `commit()` shape
 * accepts a `ReadonlyMap<NodeId, unknown>` — the desugared form the
 * eventual Rust bridge will receive over the FFI boundary — and walks
 * the map into `tx.set` calls inside a single atomic transaction.
 *
 * The class is exported so adopters can `instanceof`-check the
 * returned backend (e.g. to log which engine path is active) and so
 * the cross-backend determinism test can reach the internal `Graph`
 * for `World`-shaped command playback. The internal-graph accessor
 * is namespaced under a `__` prefix to make it clear it is not part
 * of the supported public surface; the rest of the class is the
 * stable shape adopters program against.
 *
 * @internal The class identity itself is internal; the
 * `BackendEngine` interface it satisfies is the public contract.
 */
class WasmBackend implements BackendEngine {
  /** Bridge identifier — surfaced for diagnostics. */
  readonly bridge: BridgeId
  /** Underlying TS engine — wrapped to satisfy the FFI-shaped surface. */
  readonly #graph: Graph
  /** Node-id-keyed registry of input handles for `commit` writes. */
  readonly #inputs = new Map<NodeId, InputNode<unknown>>()
  /**
   * Auto-registration cache for nodes referenced through `commit()`
   * that haven't been pre-registered via `__registerInput()`. Keeps
   * the FFI surface honest: the bridge will produce `Action` values
   * carrying writes keyed by `NodeId`, and the wrapper must be able
   * to resolve those ids without the caller having walked an explicit
   * `g.input()` call site for each one.
   *
   * Adopters who use the higher-level `Graph` surface go through
   * `g.input()` / `g.derived()` first and the registry is populated
   * by `__registerInput()`. Adopters who use `BackendEngine.commit`
   * directly (e.g. the cross-backend determinism gate's WASM-side
   * `World`) pre-register input handles through `__registerInput()`.
   */
  readonly #nodeRegistry = new Map<NodeId, Node<unknown>>()

  /**
   * Per-instance counter incremented every time
   * `evaluateStatechart()` delegates to the canonical evaluator.
   * Exposed only via the dev-test seam {@link __evalCountersForTests}
   * so the 0.9.0-readiness no-fallback property gate can assert the
   * delegation path is taken (and the now-removed synthetic-forbidden
   * fallback is never invoked).
   *
   * @internal
   */
  #evalDelegateCount = 0

  /**
   * Per-instance counter that MUST remain zero. The legacy
   * back-channel fallback (a synthetic-forbidden result with
   * `from='__backend-for-test-missing__'`) was removed in the
   * 0.9.0-readiness pass (issue #1122) because it masked real
   * divergence between the JS and WASM `evaluateStatechart`
   * implementations. The counter is retained as a forward-compat trip
   * wire: the no-fallback property gate asserts it is zero after every
   * trial so a future regression that re-introduces a silent fallback
   * fires the gate by construction.
   *
   * @internal
   */
  #syntheticFallbackCount = 0

  /**
   * C.4 (#1505) — validated per-graph batched-flush config, or
   * `undefined` when the adopter did not opt in. When `undefined` the
   * backend behaves byte-identically to dev `b15069fa` (no queue, the
   * pre-C.3 per-commit shadow path) — the load-bearing C.4 acceptance
   * property. When present, a {@link BatchedFlush} queue is built from
   * it the moment a marshaler mirror + bridge are primed
   * (F-marshal.5 / future real bridge).
   */
  readonly #batchedFlushConfig:
    | { afterN: number; intervalMs: number }
    | undefined

  /**
   * V2.1 (#1519) — the validated per-graph engine canonicality mode
   * (V2-DESIGN §2). `'rust-ssot'` (the default) makes the Rust
   * `commit_batch` post-state the UNCONDITIONAL canonical authority: the
   * batched-flush boundary applies it to the mirror and exposes its last
   * projected `Commit` as the adopter-facing return (§18A.8
   * fail-safe-removal — no per-flush byte-compare, no rollback, no
   * sticky-downgrade). `'js-ssot'` (the explicit floor opt, §18A.7
   * Criterion 5) keeps the wrapped TS engine canonical and the Rust
   * `commit_batch` result discarded into the shadow mirror —
   * byte-identical to dev `97da8420`.
   */
  readonly #engineMode: WasmEngineMode

  /**
   * #82 — the resolved retention-caps bag this backend threaded into its
   * wrapped TS `#graph` (or `undefined` when the adopter supplied neither
   * cap). Retained ONLY for the per-graph-params fidelity probe
   * ({@link __retentionCapsForTests}); the runtime consumer is the
   * constructor's `createCauslTs` call.
   */
  readonly #retentionCaps:
    | {
        readonly commitHistoryCap?: number
        readonly snapshotRetentionCap?: number
      }
    | undefined

  /**
   * lift-export (causl/causl-core-rs#170) — the graph name the IR uses as its
   * `graphId` foreign key (the adopter's `createCausl({ name })`). Stored so
   * the rust-ssot `exportModel` reroute can stamp every node / commit / event
   * with it, byte-identical to the wrapped TS engine's `graphId`.
   */
  readonly #graphName: string

  constructor(
    bridge: BridgeId,
    graphName: string,
    batchedFlush?: BatchedFlushOptions,
    engineMode: WasmEngineMode = DEFAULT_WASM_ENGINE_MODE,
    retentionCaps?: {
      readonly commitHistoryCap?: number
      readonly snapshotRetentionCap?: number
    },
  ) {
    this.bridge = bridge
    this.#graphName = graphName
    // FLIP (epic #31 / issue #33) — the WasmBackend's INTERNAL wrapped engine
    // is the pure-TS oracle / js-ssot SSOT (this class IS the wasm backend; its
    // `#graph` is the TS engine it wraps). Build it with `createCauslTs`, NOT
    // `createCausl`: post-FLIP `createCausl()` routes to the wasm engine when a
    // module is preloaded, and since `createCauslWasmSync` constructs a
    // `WasmBackend` while preloaded, a `createCausl()` here would re-enter the
    // wasm sync factory and recurse without bound. The TS floor is exactly what
    // this slot must be.
    //
    // lift-readat (causl/causl-core-rs#170) — thread the adopter's retention
    // caps into the wrapped TS engine so the same-timeline `#graph` oracle
    // mirrors the Rust engine's retention window. This is the js-ssot
    // reference the rust-ssot `readAt` / `snapshotAt` reroute is proven
    // byte-identical against (the seed-commit timeline is shared by both,
    // so the only variable is the retention bound — pin it to match).
    this.#graph = createCauslTs({
      name: graphName,
      ...(retentionCaps?.commitHistoryCap !== undefined
        ? { commitHistoryCap: retentionCaps.commitHistoryCap }
        : {}),
      ...(retentionCaps?.snapshotRetentionCap !== undefined
        ? { snapshotRetentionCap: retentionCaps.snapshotRetentionCap }
        : {}),
    })
    // V2.1 (#1519) — store the validated per-graph engine mode.
    // `instantiateBackend` resolves + validates the adopter-supplied
    // value via `resolveWasmEngineMode`; the default here keeps every
    // OTHER WasmBackend construction path (tests, the sync helper)
    // byte-identical to dev `97da8420` (V2-DESIGN §2.2).
    this.#engineMode = engineMode
    // #82 — retain the resolved retention-caps bag for the per-graph-params
    // fidelity probe (`__retentionCapsForTests`); the constructor otherwise
    // consumes it inline into the wrapped TS `#graph` above.
    this.#retentionCaps = retentionCaps
    // C.4 — validate + normalise the per-graph opt-in. Absent ⇒
    // undefined ⇒ byte-identical pre-C.3 path (load-bearing).
    if (batchedFlush !== undefined) {
      const afterN = batchedFlush.afterN ?? 1
      const intervalMs = batchedFlush.intervalMs ?? 16
      if (!Number.isInteger(afterN) || afterN < 1) {
        throw new RangeError(
          `createCausl({ batchedFlush }): afterN must be an integer >= 1 (got ${String(afterN)})`,
        )
      }
      if (!Number.isFinite(intervalMs) || intervalMs < 0) {
        throw new RangeError(
          `createCausl({ batchedFlush }): intervalMs must be a finite number >= 0 (got ${String(intervalMs)})`,
        )
      }
      this.#batchedFlushConfig = { afterN, intervalMs }
    } else {
      this.#batchedFlushConfig = undefined
    }
  }

  // =====================================================================
  // WIRE (epic #31 / issue #32) — authoritative Rust→wasm seam.
  // =====================================================================

  /**
   * Per-instance reference to the consolidated bridge's wasm-bindgen exports
   * object (the `{ apply_commands, read_cell_value, intern_string, ... }`
   * marshaled surface). `undefined` until the live `WebAssembly.instantiate`
   * path attaches it via {@link __attachWasmExportsForTests}.
   *
   * @internal
   */
  #wasmExports: WasmBridgeExports | undefined

  /**
   * WIRE — the authoritative wasm engine. When set, the four target adopter
   * ops (`commit` / `read` / `subscribe` / `now`) and derived registration
   * route through the REAL wasm engine as the source of truth (the engine is
   * injected into `createCausl({ injectedBackend })`); the wrapped TS `#graph`
   * is demoted to an optional oracle. `undefined` keeps the legacy Phase-1
   * shadow behaviour (TS engine SSOT).
   *
   * @internal
   */
  #authoritative: AuthoritativeWasmEngine | undefined

  /**
   * Attach a live (or mock) wasm-exports object to this backend so the
   * authoritative seam can route through `apply_commands` / `read_cell_value`
   * / … . The production loader ({@link createCauslWasmSync} /
   * {@link loadAuthoritativeWasm}) calls this once the live instance is
   * available.
   *
   * @internal
   */
  __attachWasmExportsForTests(exports: WasmBridgeExports | undefined): void {
    this.#wasmExports = exports
  }

  /**
   * WIRE — flip this WasmBackend to wasm-AUTHORITATIVE for the four target
   * ops. Requires a live wasm-exports surface carrying the full-fidelity
   * externs (`apply_commands`, `read_cell_value`, `intern_string`,
   * `read_interned_string`) AND the `causl-compute-imports.js` snippet module
   * (to install the `__causl_compute` / `__causl_fire` handlers).
   *
   * Throws if the exports / imports are incomplete so a mis-wired cutover
   * surfaces eagerly rather than silently falling back.
   *
   * @internal
   */
  __enableAuthoritativeWasm(imports: ComputeImportsModule): void {
    const ex = this.#wasmExports
    if (ex === undefined) {
      throw new Error(
        '@causl/client-ts/wasm: __enableAuthoritativeWasm() requires a live ' +
          'wasm-exports surface — call __attachWasmExportsForTests() or ' +
          'instantiate the bridge first.',
      )
    }
    const missing: string[] = []
    if (typeof ex.apply_commands !== 'function') missing.push('apply_commands')
    if (typeof ex.read_cell_value !== 'function')
      missing.push('read_cell_value')
    if (typeof ex.intern_string !== 'function') missing.push('intern_string')
    if (typeof ex.read_interned_string !== 'function')
      missing.push('read_interned_string')
    if (missing.length > 0) {
      throw new Error(
        `@causl/client-ts/wasm: __enableAuthoritativeWasm() requires the ` +
          `serde-free authoritative surface; missing: ${missing.join(', ')}. ` +
          `Rebuild the artefact with the wasm:build pipeline.`,
      )
    }
    // `register_value_buf` / `read_pool_value` are the value-POOL surface.
    // The authoritative codec ships every container as a CONTENT_HASH marker
    // whose real value stays JS-side in an unbounded NodeId cache, so the pool
    // is never reached in the cutover and is absent from the lean (serde-free)
    // production artefact. Bind the real externs when present; otherwise
    // install loud-fail shims so an (unreachable) pool access surfaces a
    // coherent diagnostic.
    const poolUnavailableShim =
      (name: string) =>
      (): never => {
        throw new Error(
          `@causl/client-ts/wasm: \`${name}\` is absent from the lean ` +
            `(serde-free) production artefact. The authoritative codec ships ` +
            `containers as CONTENT_HASH markers held in an unbounded NodeId ` +
            `cache, so the value pool is never reached in the cutover; ` +
            `reaching this path means a non-cutover code path or a ` +
            `cache-invariant violation.`,
        )
      }
    // mux-6b (causl-client#42) — reset the WHOLE wasm instance EXACTLY ONCE,
    // when its shared exports surface is first seen, NOT per engine. The
    // `__resetEngineState` / `__resetInternTable` / `__resetValuePool` externs
    // clear ALL `engine_id`s and the SHARED `INTERN_TABLE` / `VALUE_POOL`
    // (pre-mux whole-instance "fresh slate"), so calling them on every new
    // engine would WIPE the other live engines coexisting on this one
    // instance. With ONE shared instance per bridge multiplexed by
    // `engine_id`, each new engine simply gets its own lazily-created
    // `ENGINE_STATES` slot — no per-engine reset is needed (and the per-engine
    // `reset_engine_state_for` is absent from the lean artefact anyway). The
    // INTERN_TABLE / VALUE_POOL stay shared (correct — opaque monotonic
    // handles). `__resetValuePool` is optional (absent on the lean artefact).
    if (!sharedInstancesReset.has(ex)) {
      sharedInstancesReset.add(ex)
      ex.__resetEngineState?.()
      ex.__resetInternTable?.()
      ex.__resetValuePool?.()
    }
    const bridge: AuthoritativeBridge = {
      apply_commands: ex.apply_commands!,
      read_cell_value: ex.read_cell_value!,
      intern_string: ex.intern_string!,
      read_interned_string: ex.read_interned_string!,
      register_value_buf:
        typeof ex.register_value_buf === 'function'
          ? ex.register_value_buf
          : (poolUnavailableShim(
              'register_value_buf',
            ) as AuthoritativeBridge['register_value_buf']),
      read_pool_value:
        typeof ex.read_pool_value === 'function'
          ? ex.read_pool_value
          : (poolUnavailableShim(
              'read_pool_value',
            ) as AuthoritativeBridge['read_pool_value']),
      // promote-read (causl/causl-core-rs#169) — bind the §12 read-side
      // STRUCTURAL externs when the rebuilt artefact carries them; leave them
      // `undefined` on a legacy bridge (the AuthoritativeWasmEngine's
      // structural reads throw a coherent "rebuild" error if reached, and the
      // facade only reaches them under `engine: 'rust-ssot'`). Read-only — no
      // commit / write path is affected.
      ...(typeof ex.dependencies === 'function'
        ? { dependencies: ex.dependencies }
        : {}),
      ...(typeof ex.dependents === 'function'
        ? { dependents: ex.dependents }
        : {}),
      ...(typeof ex.commit_log === 'function'
        ? { commit_log: ex.commit_log }
        : {}),
      // #129 / causl/causl-core-rs#318 — bind the widened commit-log extern
      // when the rebuilt artefact carries it; leave it `undefined` on a
      // legacy bridge (the facade keeps the TS `commitHistory` ring and the
      // legacy `BeginCommit` body shapes — `ownsCommitLog()` reads `false`).
      ...(typeof ex.commit_log_meta === 'function'
        ? { commit_log_meta: ex.commit_log_meta }
        : {}),
      // causl-client#129 / causl/causl-core-rs#320 — bind the engine-owned
      // dry-run extern when the rebuilt artefact carries it; leave it
      // `undefined` on a legacy bridge (`simulatesDryRunFromRust()` reads
      // `false`, so the facade keeps the TS dry-run).
      ...(typeof ex.simulate_commands === 'function'
        ? { simulate_commands: ex.simulate_commands }
        : {}),
      ...(typeof ex.stats === 'function' ? { stats: ex.stats } : {}),
      // lift-readat (causl/causl-core-rs#170) — bind the §12.2 discriminated
      // time-travel read extern when the rebuilt artefact carries it; leave
      // it `undefined` on a legacy bridge (readAt/snapshotAt throw a coherent
      // "rebuild" error if reached under rust-ssot).
      ...(typeof ex.read_at_result === 'function'
        ? { read_at_result: ex.read_at_result }
        : {}),
      // lift-export (causl/causl-core-rs#170) — bind the §18A.3 deep
      // whole-graph `export_model` extern when the rebuilt artefact carries
      // it; leave it `undefined` on a legacy bridge (the facade keeps
      // exportModel on the wrapped TS closure rather than throwing).
      ...(typeof ex.export_model === 'function'
        ? { export_model: ex.export_model }
        : {}),
      // del-final (causl/causl-core-rs#170) — bind the per-node explain-metadata
      // extern (`node_meta`) when the rebuilt artefact carries it; leave it
      // `undefined` on a legacy bridge (buildExplanation keeps the per-node
      // timestamps + `via` tag on the TS `entries` map rather than throwing).
      ...(typeof ex.node_meta === 'function'
        ? { node_meta: ex.node_meta }
        : {}),
    }
    // promote-read — thread the per-graph engine mode so the engine's
    // structural-read facade gate (rust-ssot only) resolves locally.
    this.#authoritative = new AuthoritativeWasmEngine(
      bridge,
      imports,
      this.#engineMode,
    )
  }

  /**
   * WIRE — expose the live {@link AuthoritativeWasmEngine} so it can be
   * injected into the public `createCausl({ injectedBackend })` factory. The
   * engine has exactly the `InjectedBackend` structural shape. Returns
   * `undefined` when this backend is not authoritative.
   */
  getAuthoritativeEngine(): AuthoritativeWasmEngine | undefined {
    return this.#authoritative
  }

  /**
   * WIRE — `true` when this backend is wasm-authoritative.
   *
   * @internal
   */
  __isAuthoritativeForTests(): boolean {
    return this.#authoritative !== undefined
  }

  /**
   * C.4 (#1505) — the validated per-graph batched-flush config (or
   * `undefined` when the adopter did not opt in). Read by the C.4
   * byte-identity acceptance test and by future real-bridge wiring.
   *
   * @internal
   */
  __batchedFlushConfigForTests():
    | { afterN: number; intervalMs: number }
    | undefined {
    return this.#batchedFlushConfig
  }

  /**
   * V2.1 (#1519) — the validated per-graph engine canonicality mode
   * (V2-DESIGN §2). Read by the load-bearing V2.1 byte-identity
   * acceptance test (default ⇒ `'rust-ssot'`; explicit `'js-ssot'`
   * floor opt ⇒ byte-identical to dev `97da8420`).
   *
   * @internal
   */
  __engineModeForTests(): WasmEngineMode {
    return this.#engineMode
  }

  /**
   * #82 — the per-graph graph name this backend was constructed with (the
   * IR `graphId` foreign key). Read by the per-graph-params fidelity gate.
   *
   * @internal
   */
  __graphNameForTests(): string {
    return this.#graphName
  }

  /**
   * #82 — the resolved retention-caps bag threaded into the wrapped TS
   * `#graph` (or `undefined` when neither cap was supplied). Read by the
   * per-graph-params fidelity gate.
   *
   * @internal
   */
  __retentionCapsForTests():
    | {
        readonly commitHistoryCap?: number
        readonly snapshotRetentionCap?: number
      }
    | undefined {
    return this.#retentionCaps
  }

  get now(): GraphTime {
    return this.#graph.now
  }

  /**
   * Apply a precomputed map of input writes atomically.
   *
   * @param intent - Caller-supplied label retained on the
   *   {@link Commit} record.
   * @param writes - Map of `NodeId` → new value. Every id must have
   *   been registered via `__registerInput()` (or implicitly through
   *   the wrapped `Graph` if adopters reach for `__graph` directly).
   */
  commit(intent: string, writes: ReadonlyMap<NodeId, unknown>): Commit {
    // F-marshal.5 (#1468) — ROUTE COMMIT THROUGH THE MARSHALER. The
    // adopter-facing return value is still the TS graph's `Commit`
    // (the SSOT for `read` / `subscribe` / `snapshot` until those
    // adopters' methods land on the marshaler in F-marshal.7); the
    // marshaler call runs as a shadow contract assertion so the JS↔
    // WASM wire path is exercised on every commit.
    //
    // The shadow path is gated on the marshaler mirror being
    // initialised — the cross-backend determinism property test
    // primes it via `__primeMarshalerForTests` before each scenario
    // so the gate fires green-by-construction on Action::Commit only.
    // Other adopter paths see no behavioural change today.
    // §18A.8 fail-safe-removal (causl/causl-core-rs#169) — under
    // `engine: 'rust-ssot'` (the default) the wrapped TS `#graph.commit`
    // runs for its structural / invariant / disposal validation AND
    // remains the SSOT for `read` / `subscribe` / `exportModel` — but it
    // no longer SOURCES the adopter-facing return. The returned value
    // derives from the Rust post-state the flush applies unconditionally
    // (see the `return` site below); there is no per-flush byte-compare
    // oracle and no sticky-downgrade fail-safe. Under the `engine:
    // 'js-ssot'` floor opt `tsCommit` is the SSOT return.
    const tsCommit = this.#graph.commit(intent, (tx) => {
      for (const [id, value] of writes) {
        const handle = this.#inputs.get(id)
        if (handle === undefined) {
          throw new Error(
            `WasmBackend.commit(): no input registered for NodeId '${id}'. ` +
              `Use the wrapped Graph surface (via __graph()) or pre-register the ` +
              `input through __registerInput(id, handle).`,
          )
        }
        tx.set(handle, value)
      }
    })

    // C.3 (#1501) — BUFFERED shadow path. When a BatchedFlush queue is
    // primed, the per-commit shadow wire crossing is buffered and
    // flushed on a trigger (count this PR; time/manual/implicit in
    // C.3 PR 2/3) as a single `commit_batch` envelope. The
    // adopter-facing return is STILL the TS graph's synchronous
    // `Commit` (option-c doc §2.1 Answer C — only the wire crosses
    // batches, not the commit semantics). With the default afterN=1
    // (wired via createCausl in C.4) this is byte-identical to the
    // pre-C.3 per-commit shadow path (option-c doc §2.3 / §7).
    if (this.#batchedFlush !== undefined) {
      // The pre-batch base clock for the FIRST buffered commit is the
      // TS graph's PRE-commit clock (tsCommit.time - 1), exactly the
      // value the pre-C.3 per-commit path synced mirror.now to.
      this.#batchedFlush.enqueue(
        {
          intent,
          writes: writes as ReadonlyMap<NodeId, MarshalerJsonValue>,
        },
        (tsCommit.time as number) - 1,
      )
      // §18A.8 fail-safe-removal (causl/causl-core-rs#169) — the
      // FLUSH-BOUNDARY canonical commit. Under `engine: 'rust-ssot'` (the
      // default) with the synchronous `afterN === 1` window the `enqueue`
      // above flushed THIS commit synchronously and applied the Rust
      // post-state UNCONDITIONALLY, recording its last projected `Commit`
      // on `lastPromotedCommit`. Return the Rust-derived `Commit` as the
      // canonical authority — there is no per-flush byte-compare oracle and
      // no sticky-downgrade fail-safe; the cross-backend determinism gate is
      // the sole guarantee. When `lastPromotedCommit` is `undefined` (a
      // buffered `afterN > 1` window, a timer-deferred flush, or the
      // `engine: 'js-ssot'` floor opt) return `tsCommit`.
      if (this.#engineMode === 'rust-ssot') {
        const promoted = this.#batchedFlush.lastPromotedCommit
        if (promoted !== undefined) return promoted
      }
    } else if (this.#marshaler !== undefined) {
      // Pre-C.3 per-commit shadow path — preserved verbatim for the
      // F-marshal.5 gate that primes only the single-commit mirror.
      // Null-safe so adopters who never prime see no overhead.
      try {
        // Sync mirror.now to the TS graph's pre-commit clock so the
        // marshaler envelope's `state.now` matches what the SSOT TS
        // engine commit started from. The TS Graph mints a non-zero
        // starting `now` per warmup discipline; without this sync the
        // shadow path would diverge by exactly the warmup offset.
        this.#marshaler.now = (tsCommit.time as number) - 1 as GraphTime
        const envelope = marshalCommitEnvelope(
          this.#marshaler,
          intent,
          writes as ReadonlyMap<NodeId, MarshalerJsonValue>,
        )
        // The marshaler call is fire-and-forget: it pins the wire
        // shape but does not influence the returned Commit. The
        // bridge call returns a BridgeResult we apply to the mirror
        // so `mirror.now` / `mirror.inputs` track the TS graph.
        const bridgeResult = this.#marshalerBridge!.commit(
          envelope.state,
          envelope.action,
        ) as BridgeResult
        applyBridgeResult(this.#marshaler, bridgeResult)
      } catch (err) {
        // Surface shadow-path failures via the marshaler-error hook
        // so the cross-backend gate's assertion path sees them. Adopter
        // commits do not throw on shadow failures (the TS graph is
        // SSOT).
        this.#marshalerError = err as Error
      }
    }

    return tsCommit
  }

  /** C.3 (#1501) — BatchedFlush queue (buffered shadow path). */
  #batchedFlush: BatchedFlush | undefined

  /**
   * C.3 (#1501) — install a {@link BatchedFlush} queue so `commit()`
   * BUFFERS the shadow wire crossing instead of flushing per-commit.
   * The adopter-facing `commit()` return is unchanged (the TS graph's
   * synchronous `Commit`). When a queue is primed it SUPERSEDES the
   * pre-C.3 single-commit shadow path; the cross-backend determinism
   * gate's per-flush assertion (C.5) reads {@link __getBatchedFlushForTests}.
   *
   * @internal Test-only seam until C.4 wires it through `createCausl`.
   */
  __primeBatchedFlushForTests(queue: BatchedFlush): void {
    this.#batchedFlush = queue
  }

  /**
   * C.3 (#1501) — the installed {@link BatchedFlush} queue (or
   * `undefined`). The cross-backend determinism gate (C.5) reads
   * `.error` off this for its per-flush assertion path; implicit-flush
   * callers (C.3 PR 3) read it to force a flush before
   * `snapshot()` / `dispose()`.
   *
   * @internal
   */
  __getBatchedFlushForTests(): BatchedFlush | undefined {
    return this.#batchedFlush
  }

  /**
   * C.3 PR 2 (#1501) — manual flush escape hatch (option-c doc §2.2).
   *
   * Forces any buffered shadow commits across the WASM wire NOW. The
   * adopter calls this before navigation / before `snapshot()` / in
   * tests when they need the wire bytes to land synchronously rather
   * than waiting for the count or time trigger.
   *
   * A no-op (returns `[]`) when no `BatchedFlush` queue is installed
   * (the default until C.4 wires it through `createCausl`) or when the
   * buffer is empty — so adopters can always call `backend.flush()`
   * safely regardless of configuration.
   *
   * Returns the projected `Commit[]` the flush produced (empty when
   * nothing was buffered). This does NOT re-fire subscribers — under
   * Answer C subscriber dispatch already ran synchronously per commit
   * in the JS engine (option-c doc §4.2 choice (i)); the flush only
   * reconciles the WASM-side wire/mirror state.
   */
  flush(): Commit[] {
    if (this.#batchedFlush === undefined) return []
    return this.#batchedFlush.flush()
  }

  /**
   * C.3 PR 3 (#1501) — IMPLICIT flush. Any path that needs the
   * WASM-side state to reflect committed work forces a synchronous
   * flush of the buffered shadow window before it reads
   * (option-c doc §2.2 "Implicit (snapshot / read-from-WASM /
   * dispose)" row). Idempotent and null-safe: a no-op when no queue
   * is installed or the buffer is empty. Also cancels any armed time
   * trigger so a stale timer cannot re-flush an already-drained
   * window after the implicit flush already reconciled it.
   *
   * Under Answer C the JS engine is SSOT, so reads / subscriber
   * dispatch / `Commit` returns do NOT require a flush — only paths
   * that surface the WASM-side state (`snapshot()` shadows through the
   * marshaler per F-marshal.7; `dispose()` mutates the WASM-side
   * allocator) need the buffered window on the wire first
   * (option-c doc §2.2 final paragraph).
   */
  #implicitFlush(): void {
    // `BatchedFlush.flush()` cancels the pending time trigger
    // UNCONDITIONALLY (including on the buffer-empty early-return
    // path), so an implicit flush both drains the buffered window and
    // disarms any stale timer in one call. No-op + null-safe when no
    // queue is installed.
    this.#batchedFlush?.flush()
  }

  /**
   * F-marshal.5 (#1468) — install a marshaler mirror + bridge adapter
   * so `commit()` shadows the JS↔WASM wire path on every commit. The
   * cross-backend determinism gate uses this to exercise the marshaler
   * surface without changing adopter-facing semantics.
   *
   * @internal Test-only seam. Production paths leave the marshaler
   * dormant; F-marshal.7 promotes the marshaler from shadow to SSOT
   * for snapshot/hydrate.
   */
  __primeMarshalerForTests(
    mirror: WasmStateMirror,
    bridge: { commit(state: unknown, action: unknown): unknown },
  ): void {
    this.#marshaler = mirror
    this.#marshalerBridge = bridge
    this.#marshalerError = undefined
  }

  /**
   * C.4 (#1505) — install a {@link BatchedFlush} queue built from the
   * per-graph `batchedFlush` config (validated in the constructor)
   * against a primed mirror + bridge. When the adopter did NOT opt in
   * (`#batchedFlushConfig === undefined`) this is a NO-OP and the
   * backend keeps the pre-C.3 per-commit shadow path — the
   * load-bearing C.4 byte-identity property: default config is
   * byte-identical to dev `b15069fa`.
   *
   * Wiring path: the C.5 cross-backend determinism gate and future
   * real-bridge loader call this after priming the mirror so the
   * configured `afterN` / `intervalMs` take effect per-graph. The
   * `timer` parameter is injectable so the gate / tests drive the
   * time trigger deterministically.
   *
   * @internal Wired through `createCausl({ batchedFlush })` /
   * `loadWasmBackend({ batchedFlush })`; not an adopter-facing method.
   */
  __installBatchedFlushFromConfig(
    mirror: WasmStateMirror,
    bridge: BatchedFlushBridge,
    timer?: FlushTimer,
  ): BatchedFlush | undefined {
    if (this.#batchedFlushConfig === undefined) {
      // Adopter did not opt in — byte-identical pre-C.3 path. Do NOT
      // install a queue.
      return undefined
    }
    const { afterN, intervalMs } = this.#batchedFlushConfig
    // §18A.8 (causl/causl-core-rs#169) — thread the per-graph engine mode
    // into the queue so it applies the Rust post-state as the canonical
    // commit under the default `rust-ssot` and stays a pure shadow under
    // the explicit `js-ssot` floor opt. Pass `HOST_FLUSH_TIMER` explicitly
    // on the no-injected-timer branch so the `engineMode` positional is
    // reached without changing the default timer.
    const queue =
      timer !== undefined
        ? new BatchedFlush(
            mirror,
            bridge,
            afterN,
            intervalMs,
            timer,
            this.#engineMode,
          )
        : new BatchedFlush(
            mirror,
            bridge,
            afterN,
            intervalMs,
            HOST_FLUSH_TIMER,
            this.#engineMode,
          )
    this.#batchedFlush = queue
    return queue
  }

  /**
   * F-marshal.5 (#1468) — surface any error captured by the shadow
   * marshaler path. The cross-backend determinism gate calls this
   * after each command to assert the marshaler stays green; production
   * adopters never see this surface.
   *
   * @internal
   */
  __getMarshalerErrorForTests(): Error | undefined {
    return this.#marshalerError
  }

  /** F-marshal.5 (#1468) — JS-side mirror, populated by the gate's prime. */
  #marshaler: WasmStateMirror | undefined
  /** F-marshal.5 (#1468) — bridge adapter, populated by the gate's prime. */
  #marshalerBridge:
    | { commit(state: unknown, action: unknown): unknown }
    | undefined
  /** F-marshal.5 (#1468) — captured shadow-path error for test inspection. */
  #marshalerError: Error | undefined

  read(node: NodeId): unknown {
    const handle = this.#nodeRegistry.get(node)
    if (handle === undefined) {
      throw new Error(
        `WasmBackend.read(): no node registered for NodeId '${node}'.`,
      )
    }
    return this.#graph.read(handle)
  }

  subscribe<T>(node: NodeId, observer: Observer<T>): Unsubscribe {
    const handle = this.#nodeRegistry.get(node)
    if (handle === undefined) {
      throw new Error(
        `WasmBackend.subscribe(): no node registered for NodeId '${node}'.`,
      )
    }
    return this.#graph.subscribe(handle as Node<T>, observer)
  }

  subscribeCommits(observer: (commit: Commit) => void): Unsubscribe {
    return this.#graph.subscribeCommits(observer)
  }

  snapshot(): GraphSnapshot {
    // C.3 PR 3 (#1501) — implicit flush: snapshot() shadows through
    // the marshaler (F-marshal.7), so the buffered shadow window must
    // land on the WASM-side wire BEFORE the snapshot reads, or the
    // mirror would lag behind the TS graph by the un-flushed window
    // (option-c doc §2.2). The adopter-facing snapshot is still the TS
    // graph's (Answer C — TS engine is SSOT); the implicit flush only
    // reconciles the WASM-side mirror so a subsequent marshaler-routed
    // snapshot/hydrate sees committed work.
    this.#implicitFlush()
    return this.#graph.snapshot()
  }

  /**
   * #88 (PR #79 residual 2) — hydrate the wrapped TS `#graph` only.
   *
   * Unlike {@link snapshot}, this does NOT run {@link #implicitFlush} to
   * reconcile the WASM-side marshaler mirror. That asymmetry is INTENTIONAL
   * and safe because the WASM shadow is inert on every path that reaches
   * THIS method: `instantiateBackend()` (the `loadWasmBackend` core) never
   * calls `__enableAuthoritativeWasm` / `__primeBatchedFlushForTests` /
   * `__primeMarshalerForTests`, so `#authoritative`, the `#batchedFlush`
   * instance, and `#marshaler` are all `undefined` here — `commit`, `read`,
   * `snapshot` and `hydrate` all route through the same `#graph` SSOT, and
   * the hydrate is self-consistent with reads (pinned by
   * `wasm-legacy-backend-hydrate-consistency.test.ts`).
   *
   * The one production path that DOES enable the authoritative engine
   * (`createCauslWasm` / `createCauslWasmSync`) EXTRACTS it via
   * {@link getAuthoritativeEngine} and installs it as the graph's
   * `injectedBackend` — `Graph.hydrate` there routes through
   * `AuthoritativeWasmEngine.hydrate` (the #78/#79 `apply_commands` path,
   * pinned by `wasm-hydrate-ssot-parity`), NEVER this method. So no
   * adopter-reachable factory drives a live shadow through here.
   *
   * INVARIANT for future work: if a change ever activates a live shadow
   * (authoritative engine / primed batched-flush or marshaler) on the
   * `loadWasmBackend` path, this method must reconcile it — mirror
   * {@link snapshot}'s `this.#implicitFlush()` and route the hydrate through
   * the authoritative engine — or the mirror desyncs across a hydrate.
   */
  hydrate(snap: GraphSnapshot): void {
    this.#graph.hydrate(snap)
  }

  /**
   * Internal-API migration hydrate (issue #1090). Routes through
   * `@causl/client-ts/internal`'s `_migrateFrom(graph, snap)` so the
   * wrapped TS engine adopts the snapshot WITHOUT publishing the
   * synthetic `'hydrate'` commit record. The migration boundary
   * itself isn't a commit; `now` starts where the snapshot left off
   * and the §3 monotonicity invariant is preserved by the
   * fresh-graph precondition (`now === 0`, no commit history).
   *
   * @remarks
   * Used by the cross-backend determinism property test's migration
   * matrix so the (N+M)-commit pure-TS baseline and the JS → WASM
   * migrated engine compare byte-identical at literal IR level.
   * Adopter packages use `hydrate(snap)` — this method is reachable
   * only through the `__migrateFrom` accessor and is namespaced with
   * the `__` prefix to match the rest of the WasmBackend's
   * test/integration helpers (`__graph`, `__registerInput`, …).
   *
   * @internal
   */
  __migrateFrom(snap: GraphSnapshot): void {
    _migrateFromInternal(this.#graph, snap)
  }

  /**
   * lift-readat (causl/causl-core-rs#170) — whether the discriminated
   * historical reads (`readAt` / `snapshotAt`) resolve from the Rust
   * retention chain. `true` only under rust-ssot with the rebuilt
   * `read_at_result` extern present. The `graph.ts` facade gates its
   * readAt/snapshotAt reroute on this.
   */
  readsHistoryFromRust(): boolean {
    return (
      this.#engineMode === 'rust-ssot' &&
      this.#authoritative !== undefined &&
      this.#authoritative.hasReadAtResult()
    )
  }


  readAt(node: NodeId, time: GraphTime): RetentionResult<unknown> {
    // lift-readat (causl/causl-core-rs#170) — under rust-ssot the
    // discriminated historical read resolves from the Rust retention chain
    // (the §12.2 `read_at_result` extern), NOT the wrapped TS `#graph`
    // (whose `snapshotRetentionCap` is 0 — its retention is dead). The
    // Rust resolver reproduces the TS `readAt` decision tree byte-
    // identically; there is NO `#graph` consult on this path.
    const authoritative = this.#authoritative
    if (
      this.#engineMode === 'rust-ssot' &&
      authoritative !== undefined &&
      authoritative.hasReadAtResult()
    ) {
      return authoritative.readAt(node, time)
    }
    const handle = this.#nodeRegistry.get(node)
    if (handle === undefined) {
      throw new Error(
        `WasmBackend.readAt(): no node registered for NodeId '${node}'.`,
      )
    }
    return this.#graph.readAt(handle, time)
  }

  snapshotAt(time: GraphTime): RetentionResult<GraphSnapshot> {
    // lift-readat (#170) — route the discriminated historical snapshot
    // through the Rust retention window under rust-ssot. The retention
    // discriminant (retained vs evicted + oldestRetainedTime) and the
    // per-input values at `time` come from Rust; `schemaHash` is the
    // structural-identity digest sourced from the wrapped graph's current
    // snapshot (a registered-id-set concern, not a retention concern).
    const authoritative = this.#authoritative
    if (
      this.#engineMode === 'rust-ssot' &&
      authoritative !== undefined &&
      authoritative.hasReadAtResult()
    ) {
      return authoritative.snapshotAt(
        time,
        () => this.#graph.snapshot().schemaHash ?? '',
      )
    }
    return this.#graph.snapshotAt(time)
  }

  /**
   * lift-export (causl/causl-core-rs#170) — whether the whole-graph
   * `exportModel` IR resolves from the Rust §18A.3 deep export. `true` only
   * under rust-ssot with the rebuilt `export_model` extern present. The
   * `graph.ts` facade gates its exportModel reroute on this.
   */
  exportsModelFromRust(): boolean {
    return (
      this.#engineMode === 'rust-ssot' &&
      this.#authoritative !== undefined &&
      this.#authoritative.hasExportModel()
    )
  }

  exportModel(opts?: ExportModelOptions): CauslModel {
    // lift-export (causl/causl-core-rs#170) — under rust-ssot the whole
    // `CauslModel` IR resolves from the Rust §18A.3 deep export (nodes +
    // deps + commit-log-with-originatedAt + the IRSubscribe event stream),
    // NOT the wrapped TS `#graph`. The `graphId` is the WasmBackend's stored
    // graph name (the same name the wrapped TS engine carries); the only TS
    // here is the marshaling `serializable` shim over the Rust values. There
    // is NO `#graph` consult on this path. Falls back to the TS closure on a
    // legacy artefact (extern absent).
    //
    // #117 — thread `ExportModelOptions` (notably `maxCommits`) to whichever
    // arm serves the export so the commit-window / node set is honoured
    // identically to the js-ssot floor.
    const authoritative = this.#authoritative
    if (
      this.#engineMode === 'rust-ssot' &&
      authoritative !== undefined &&
      authoritative.hasExportModel()
    ) {
      return authoritative.exportModel(this.#graphName, opts)
    }
    return this.#graph.exportModel(opts)
  }

  dispose(node: NodeId): void {
    const handle = this.#nodeRegistry.get(node)
    if (handle === undefined) return
    // C.3 PR 3 (#1501) — implicit flush BEFORE disposal: dispose()
    // mutates the WASM-side allocator (Decision 4 — WASM-side
    // authoritative on disposed cells). A buffered shadow window that
    // still references this slot must land on the wire before the
    // slot is freed, or the deferred batch would marshal a write
    // against a slot the engine has since disposed
    // (option-c doc §2.2). The implicit flush drains the window first.
    this.#implicitFlush()
    // Disposal flows through the internal-dispatch registry on the
    // wrapped Graph; surfacing it here keeps the seam intact and
    // matches the `BackendEngine` interface shape.
    const { dispose } = (
      this.#graph as unknown as {
        readonly __causl_internal_dispatch?: { dispose: (n: Node<unknown>) => void }
      }
    ).__causl_internal_dispatch ?? { dispose: () => undefined }
    dispose(handle)
  }

  /**
   * mux-6 (causl-client#42) — tear down this backend's authoritative wasm
   * engine: drop its per-`engineId` compute/fire handlers from the sidecar
   * registry so a stale dispatch for its id becomes a no-op (a THREW
   * out-buffer for compute / a dropped firing for fire). Idempotent and safe
   * when this backend is not authoritative. Wired into the HMR-dispose seam
   * (`__resetWasmBackendCacheForTests`) and callable directly by adopters
   * that explicitly retire a wasm graph.
   *
   * @internal
   */
  disposeAuthoritativeEngine(): void {
    this.#authoritative?.dispose()
  }

  /**
   * SPEC §6 composite-statechart extension point (issue #1068,
   * deferred from #698). The Phase-1 `WasmBackend` wraps a TS engine
   * (see `createCausl` call in the constructor) so this method
   * delegates directly to the canonical `evaluateStatechart`
   * implementation that the `JsBackend.evaluateStatechart` op (PR
   * #1092) routes through — the same module backs both the JS and
   * WASM `BackendEngine.evaluateStatechart` Phase-1 paths so the two
   * are byte-identical by construction.
   *
   * @remarks
   * History. The pre-#1122 implementation reached into the wrapped
   * Graph via a back-channel accessor and fell back to a
   * synthetic-forbidden result (with
   * `from='__backend-for-test-missing__'`) when the back-channel was
   * absent. Per the Markbåge/Miller ship-verdict panel the
   * back-channel and the synthetic-forbidden fallback were both
   * removed for 0.9.0 (issue #1122): the back-channel was never set
   * on the wrapped `Graph` (every call hit the fallback in
   * production) and the synthetic result masked real divergence
   * between the JS and WASM evaluators. The canonical evaluator
   * shipped by issue #1068 / PR #1092 is the only path.
   *
   * The Phase-2 Sub-D work (EPIC #680) replaces this delegation with
   * a Rust-side `evaluate_statechart()` call consuming the
   * `engine-rs-core::statechart_reducers` enums (gated behind
   * `feature = "future"`; landed structurally by #1068). The wire
   * shape of the extension point is the same on both sides — the
   * cross-implementation determinism gates (#685, #1068, #1122)
   * verify the two implementations stay byte-equivalent.
   */
  evaluateStatechart(input: StatechartInput): StatechartResult {
    this.#evalDelegateCount += 1
    // Delegate through the canonical evaluator — the same module the
    // `JsBackendOps.evaluateStatechart` op installed by `createCausl`
    // calls (see `graph.ts:evaluateStatechart: (input) =>
    // evaluateStatechartImpl(input)`). The wasm-side seam's
    // `StatechartInput` / `StatechartResult` are structural mirrors of
    // the core-side `backend.ts` types; the cross-cast is safe and the
    // cross-implementation determinism gates pin byte-identity.
    return evaluateStatechartCanonical(
      input as unknown as Parameters<typeof evaluateStatechartCanonical>[0],
    ) as unknown as StatechartResult
  }

  /**
   * Dev/test-only accessor exposing the per-instance instrumentation
   * counters that back the no-fallback property gate (issue #1122).
   *
   * - `evalDelegateCount` — number of times `evaluateStatechart()`
   *   delegated to the canonical evaluator (increments on every
   *   invocation post-#1122).
   * - `syntheticFallbackCount` — MUST remain zero. The legacy
   *   synthetic-forbidden fallback path was removed in #1122; this
   *   counter is the forward-compat trip wire that fires if a future
   *   regression silently re-introduces a fallback.
   *
   * Namespaced under the `__` prefix to make it clear it is not part
   * of the supported public surface. Adopters program against the
   * `BackendEngine` interface alone.
   *
   * @internal
   */
  __evalCountersForTests(): {
    readonly evalDelegateCount: number
    readonly syntheticFallbackCount: number
  } {
    return {
      evalDelegateCount: this.#evalDelegateCount,
      syntheticFallbackCount: this.#syntheticFallbackCount,
    }
  }

  /**
   * Test/integration helper — return the wrapped `Graph`.
   *
   * @remarks
   * Not part of the supported public surface; reachable only through
   * the `__graph()` accessor on the `WasmBackend` instance so adopter
   * code that programs against `BackendEngine` alone cannot
   * accidentally reach in. The cross-backend determinism gate (#685)
   * and the migration round-trip suite (#687) use this to build a
   * `World`-shaped pair of engines that share a graphId.
   *
   * @internal
   */
  __graph(): Graph {
    return this.#graph
  }

  /**
   * Register an input handle so subsequent `commit({ id })` writes
   * can resolve the typed `Node<T>` they map to. Idempotent — calling
   * with an already-registered id is a no-op.
   *
   * @internal Used by the cross-backend determinism gate's
   * `World`-shaped adapter to keep the wrapper's id registry in
   * lockstep with the underlying `Graph`'s.
   */
  __registerInput(id: NodeId, handle: InputNode<unknown>): void {
    this.#inputs.set(id, handle)
    this.#nodeRegistry.set(id, handle)
  }

  /**
   * Register a derived handle for read/subscribe routing. Derived
   * nodes are not write targets so they bypass the `#inputs` map.
   *
   * @internal
   */
  __registerDerived(id: NodeId, handle: Node<unknown>): void {
    this.#nodeRegistry.set(id, handle)
  }
}

/**
 * Type guard — `true` when `engine` is a Phase-1 `WasmBackend` that
 * wraps a TS engine. Adopters who need to reach the wrapped `Graph`
 * for the migration round-trip (#687) or the cross-backend
 * determinism gate (#685) can guard on this before calling
 * `__graph()`.
 *
 * @internal The guard is a forward-compat affordance: once the
 * bridge artifacts wire a real Rust-driven engine, the `WasmBackend`
 * class is replaced by a bridge-routing implementation that no
 * longer exposes `__graph()`; this guard returns `false` for those
 * instances, letting callers branch cleanly.
 */
export function __isPhase1WasmBackendForTests(
  engine: BackendEngine,
): engine is BackendEngine & {
  readonly bridge: BridgeId
  __graph(): Graph
  __registerInput(id: NodeId, handle: InputNode<unknown>): void
  __registerDerived(id: NodeId, handle: Node<unknown>): void
  __migrateFrom(snap: GraphSnapshot): void
  __evalCountersForTests(): {
    readonly evalDelegateCount: number
    readonly syntheticFallbackCount: number
  }
} {
  return engine instanceof WasmBackend
}

/**
 * Synchronous Phase-1 `WasmBackend` constructor for tests that need
 * to mint a fresh per-trial engine inside a synchronous closure
 * (e.g. `fc.modelRun`'s setup callback, which fast-check invokes
 * synchronously per trial).
 *
 * The async `loadWasmBackend()` is the supported public path —
 * adopters should never reach for this helper. It exists because
 * the Phase-1 implementation has no `await`-able I/O (the wasm-pack
 * artifact is not loaded yet) and the cross-backend determinism gate
 * needs hermetic per-trial engines without an `await` boundary
 * that would force every fc.modelRun trial to become async.
 *
 * @internal
 */
export function __createWasmBackendSyncForTests(
  graphName: string,
  bridge: BridgeId = 'wasmgc-classic',
  batchedFlush?: BatchedFlushOptions,
  engine?: WasmEngineMode,
): BackendEngine & {
  readonly bridge: BridgeId
  __graph(): Graph
  __registerInput(id: NodeId, handle: InputNode<unknown>): void
  __registerDerived(id: NodeId, handle: Node<unknown>): void
  __migrateFrom(snap: GraphSnapshot): void
  __evalCountersForTests(): {
    readonly evalDelegateCount: number
    readonly syntheticFallbackCount: number
  }
} {
  // C.4 (#1505) — forward the per-graph batchedFlush opt-in. Default
  // (omitted) ⇒ byte-identical to dev b15069fa (load-bearing).
  //
  // V2.1 (#1519) — forward the per-graph engine canonicality opt-in.
  // Omitted ⇒ `resolveWasmEngineMode(undefined)` ⇒ `'js-ssot'` ⇒
  // byte-identical to dev `97da8420` (the load-bearing V2.1
  // acceptance property — V2-DESIGN §2.2). An unrecognised value
  // throws here exactly as it would on the `instantiateBackend` path.
  return new WasmBackend(
    bridge,
    graphName,
    batchedFlush,
    resolveWasmEngineMode(engine),
  )
}

/**
 * Streaming-instantiate with a non-streaming fallback for hosts
 * that serve `.wasm` with the wrong MIME type (S3, older nginx).
 *
 * `WebAssembly.instantiateStreaming` requires `Content-Type:
 * application/wasm`; the try/catch falls back to
 * `WebAssembly.instantiate(arrayBuffer)` which is MIME-agnostic.
 *
 * @internal exported for the CI streaming/non-streaming smoke test
 * matrix described in the #684 exit criterion.
 */
export async function loadStreaming(
  url: URL | string,
  imports: WebAssembly.Imports,
  fetchImpl: typeof fetch = fetch,
): Promise<WebAssembly.WebAssemblyInstantiatedSource> {
  const href = typeof url === 'string' ? url : url.href
  if (typeof WebAssembly.instantiateStreaming === 'function') {
    try {
      const resp = fetchImpl(href, { credentials: 'same-origin' })
      return await WebAssembly.instantiateStreaming(resp, imports)
    } catch {
      // MIME mismatch (`application/octet-stream` from S3 etc.) — fall through.
    }
  }
  const buf = await (await fetchImpl(href)).arrayBuffer()
  return WebAssembly.instantiate(buf, imports)
}
