/** The compute lambda for a derived: `(get) => value`. */
export type DerivedCompute = (get: (dep: NodeId) => unknown) => unknown

/**
 * causl/causl-client-ts#138 — the STABLE STRUCTURED TOKEN of the re-entrancy
 * verdict the bridge throws when a same-engine `apply_commands` re-enters its
 * own commit/notification frame (SPEC §18A.4 / E.6 option (a),
 * `ApplyCommandsError::Engine(RaceClass::CommitInProgress)`).
 *
 * The engine renders the verdict as `apply_commands error: Engine(<variant>…)`
 * followed by a free-form human tail. This module decodes it by matching the
 * `Engine(<variant>` discriminant with a trailing `\b` word boundary — NOT the
 * full `{:?}` Debug rendering. The word boundary is the load-bearing part:
 *   - it SURVIVES a Rust-side Debug change that adds a payload
 *     (`Engine(CommitInProgress { engine_id: 3 })`) or reflows the human tail,
 *     because `CommitInProgress` is still a whole token; yet
 *   - it correctly REFUSES a genuine variant RENAME
 *     (`Engine(CommitInProgressV2)`), which is a DIFFERENT verdict that must
 *     not silently masquerade as this one.
 *
 * The token is the FFI ABI between this repo and causl/causl-core-rs; it is
 * pinned against the real engine artefact by a cross-repo golden test
 * (`wasm-reentrant-verdict-token-138.test.ts`) so a Rust-side rename/format
 * change trips a loud RED here instead of silently downgrading the typed
 * {@link CommitInProgressError} to a raw `Error`. Companion causl-wasm#231
 * would let this be an out-of-band structured code rather than a Debug token.
 */
export const COMMIT_IN_PROGRESS_VERDICT_TOKEN =
  /^apply_commands error: Engine\(CommitInProgress\b/

/**
 * causl/causl-client-ts#103/#138 — the STABLE STRUCTURED TOKEN of the verdict
 * the bridge throws when a derived's `__causl_compute` lambda itself threw
 * (`ApplyCommandsError::Engine(ComputeThrew { reason })`). Matched with the
 * same `Engine(<variant>\b` discriminant + word boundary as
 * {@link COMMIT_IN_PROGRESS_VERDICT_TOKEN}. The bridge only re-inflates a typed
 * error from this verdict when the Rust-carried `reason` also contains the
 * {@link UNDECLARED_DEPENDENCY_MARKER} sentinel — every other compute throw (a
 * user lambda that genuinely threw) rethrows with its original message intact.
 */
export const COMPUTE_THREW_VERDICT_TOKEN =
  /^apply_commands error: Engine\(ComputeThrew\b/

/**
 * causl/causl-client-ts#129 (part 2): the STABLE STRUCTURED TOKEN of the verdict
 * the bridge throws when the engine's own §5.1 Phase-D Kahn drain detected a
 * derivation cycle in the affected sub-graph
 * (`ApplyCommandsError::Engine(RaceClass::CycleClosed { path })`, causl-wasm
 * `transition/cycle.rs`). Matched with the same `Engine(<variant>\b`
 * discriminant plus word boundary as {@link COMMIT_IN_PROGRESS_VERDICT_TOKEN}.
 *
 * With the #129 part-2 reduction the TS commit path elides its own structural
 * topo walk for a fully-mirrored backed graph and delegates cycle detection to
 * the backend, so this is the sole path a commit-time cycle surfaces on the
 * wasm engine. Decoding it into the typed {@link CycleError} keeps the two
 * backends type-identical at the adopter boundary: `catch (e) { if (e
 * instanceof CycleError) }` works the same whether the TS floor or the wasm
 * engine caught the cycle. Exercised by `wasm-cycle-verdict-129.test.ts` (a
 * fake bridge arms the exact verdict the real engine emits) so a Rust-side
 * rename or format change trips a loud RED here instead of silently
 * downgrading the typed error to a raw `Error`. Companion causl-wasm#231 would
 * carry the cycle PATH as an out-of-band structured code rather than the `{:?}`
 * Debug token this parses best-effort (see {@link parseCycleClosedPath}).
 */
export const CYCLE_CLOSED_VERDICT_TOKEN =
  /^apply_commands error: Engine\(CycleClosed\b/

/**
 * causl/causl-client-ts#138 — the structured discriminant the client decodes an
 * engine `apply_commands` REJECTION into. Every downstream decision in
 * {@link AuthoritativeWasmEngine.#applyCommands} switches on this typed value
 * instead of re-parsing the Rust Debug string inline at each arm, so the one
 * fragile string→discriminant step lives in exactly one audited, golden-pinned
 * place ({@link classifyEngineVerdict}).
 */
export type EngineVerdict =
  | 'commit-in-progress'
  | 'compute-threw'
  | 'cycle-closed'
  | 'other'

/**
 * causl/causl-client-ts#138 — the SINGLE place the engine's Debug-string
 * rejection verdict is turned into a typed {@link EngineVerdict} discriminant.
 * A wasm TRAP is not a clean rejection and must be classified BY THE CALLER
 * before this (a trap's message is not a verdict); this only sees non-trap
 * `Error`s. Anything that is not a recognised structured token classifies as
 * `'other'` and rethrows untouched.
 */
function classifyEngineVerdict(err: unknown): EngineVerdict {
  if (!(err instanceof Error)) return 'other'
  if (COMMIT_IN_PROGRESS_VERDICT_TOKEN.test(err.message))
    return 'commit-in-progress'
  if (COMPUTE_THREW_VERDICT_TOKEN.test(err.message)) return 'compute-threw'
  if (CYCLE_CLOSED_VERDICT_TOKEN.test(err.message)) return 'cycle-closed'
  return 'other'
}

/**
 * causl/causl-client-ts#129 (part 2): recover the cycle NodeId path from an
 * engine `Engine(CycleClosed { path: [...] })` verdict message, best-effort.
 * The engine renders the path as a `{:?}` Debug list of `NodeId { slot, gen }`
 * (causl-wasm `race_class.rs`); each `(slot, gen)` pair is mapped back to the
 * adopter NodeId via the engine's `slot:gen` reverse index (the SAME index
 * that decodes the commit changed-set). The verdict TYPE is already fixed by
 * {@link CYCLE_CLOSED_VERDICT_TOKEN}; this only reconstructs the PATH carried
 * by {@link CycleError}. Robust to Debug drift: a pair that does not resolve
 * (or a reflowed Debug format) yields a shorter (possibly empty) path, so the
 * typed {@link CycleError} still fires, it just names fewer nodes. Companion
 * causl-wasm#231 (a structured out-of-band cycle-path code) retires the parse.
 */
function parseCycleClosedPath(
  message: string,
  resolve: (slot: number, gen: number) => NodeId | undefined,
): readonly NodeId[] {
  const path: NodeId[] = []
  const re = /slot:\s*(\d+)\s*,\s*gen:\s*(\d+)/g
  let m: RegExpExecArray | null
  while ((m = re.exec(message)) !== null) {
    const id = resolve(Number(m[1]), Number(m[2]))
    if (id !== undefined) path.push(id)
  }
  return path
}

/**
 * causl/causl-client-ts#138 test seam — the raw, undecoded `message` of the most
 * recent NON-TRAP engine `apply_commands` rejection, captured the instant
 * before the client classifies it into a typed verdict. The cross-repo golden
 * test reads this to pin the structured verdict token the real engine artefact
 * emits, so a Rust-side Debug/rename change that would silently downgrade the
 * typed error is caught here as an ABI mismatch. @internal
 */
let lastRawEngineVerdict: string | undefined

/** @internal test seam (#138). */
export function __lastRawEngineVerdictForTests(): string | undefined {
  return lastRawEngineVerdict
}

/** @internal test seam (#138). */
export function __resetRawEngineVerdictForTests(): void {
  lastRawEngineVerdict = undefined
}

/**
 * promote-read (causl/causl-core-rs#169) — the engine canonicality mode the
 * {@link AuthoritativeWasmEngine} carries so the `graph.ts` read-side
 * structural facade can gate its reroute on `'rust-ssot'`. Declared
 * structurally here (a string-literal union) so this module does NOT import
 * `WasmEngineMode` from `./index.js` — `index.ts` imports THIS module, and a
 * reverse import would form a cycle. The values match `WasmEngineMode` 1:1.
 */
export type AuthoritativeEngineMode = 'js-ssot' | 'rust-ssot'

/**
 * One Phase-D Kahn-drain row, projected from a tag-6 `DerivedRecomputed`
 * diff record onto NodeId strings (the gen-bearing `(slot, gen)` wire
 * pairs are mapped back to NodeIds via the engine's `slot:gen` index, so
 * gen never enters the canonical comparison). The B.8 cross-bridge
 * sextuple gate compares this Rust-collected trace against the TS-side
 * `collectTsPhaseDTrace` emitter, NodeId-for-NodeId.
 *
 * @internal Cross-backend determinism gate surface (#1146).
 */
export interface RecomputeAffectedRow {
  /** 0-based ordinal within this commit's Kahn drain. */
  readonly stepIndex: number
  /** The derived recomputed (or cutoff-skipped) at this step. */
  readonly nodeId: NodeId
  /** Materialised pre-recompute value (decoded from the 12-byte record). */
  readonly valueBefore: unknown
  /** Materialised post-recompute value (`=== valueBefore` on a skip). */
  readonly valueAfter: unknown
  /** Dep NodeIds added this step (sorted ascending). */
  readonly depsAdded: readonly NodeId[]
  /** Dep NodeIds removed this step (sorted ascending). */
  readonly depsRemoved: readonly NodeId[]
}

/**
 * The wasm-bindgen extern surface the authoritative engine needs. A
 * structural subset of `WasmBridgeExports` so this module has no import
 * cycle with `index.ts`.
 */
export interface AuthoritativeBridge extends ValueBufBridge {
  /**
   * mux-2 (causl-client#42) — `apply_commands` now takes a leading
   * `engine_id u32` selecting the per-engine `ENGINE_STATE` slot the cmd
   * stream applies against (and keying its `(engine_id, NodeId)` fn-table /
   * observers). The TS engine passes its own minted `#engineId`.
   */
  readonly apply_commands: (
    engine_id: number,
    cmd_buf: Uint8Array,
  ) => Uint8Array
  /**
   * mux-2 — `read_cell_value` takes the same leading `engine_id u32` so a
   * read resolves against THIS engine's cells (not the default-0 slot).
   */
  readonly read_cell_value: (
    engine_id: number,
    slot: number,
    gen: number,
    is_input: boolean,
  ) => Uint8Array
  /**
   * promote-read (causl/causl-core-rs#169 ffi-1) — depth-1 static dependency
   * adjacency of `(slot, gen)` on `engine_id`, as an identity-pair buffer
   * (`(slot u32, gen u32)` LE pairs). Optional: present only on the rebuilt
   * artefact carrying the §12 structural externs; absent on legacy bridges.
   */
  readonly dependencies?: (
    engine_id: number,
    slot: number,
    gen: number,
  ) => Uint8Array
  /**
   * promote-read (ffi-1) — TRANSITIVE dependent closure of `(slot, gen)` on
   * `engine_id`, as an identity-pair buffer. NOTE: this is the transitive
   * closure; the depth-1 `dependents()` facade is derived structurally from
   * the per-engine dep adjacency (see {@link AuthoritativeWasmEngine.dependents}).
   */
  readonly dependents?: (
    engine_id: number,
    slot: number,
    gen: number,
  ) => Uint8Array
  /**
   * promote-read (ffi-2) — the per-engine commit log (intent / time /
   * changed nodes), oldest-first, as the self-describing commit-log buffer.
   */
  readonly commit_log?: (engine_id: number) => Uint8Array
  /**
   * #129 / causl/causl-core-rs#318 — the WIDENED per-engine commit log: the
   * §12.1 rows PLUS the eviction-horizon header pair
   * `(cap, total_commits_ever)` and the per-row hydrate-aware
   * `originated_at` column. Decoded by {@link decodeCommitLogMeta}.
   * Optional: present only on a #318-era artefact; its presence also
   * implies the `SetCommitLogCap` cmd-buf op and the 16-byte `BeginCommit`
   * body (they shipped together), so it doubles as the capability probe
   * for BOTH write-side wire widenings.
   */
  readonly commit_log_meta?: (engine_id: number) => Uint8Array
  /**
   * causl-client#129 / causl/causl-core-rs#320 — the engine-owned DRY-RUN of
   * a commit-window cmd-buf. Runs the exact `apply_commands` pipeline
   * (staged validation, Phase-B SameValue cutoff, Phase-D Kahn drain with
   * the REAL JS compute bridge) against a discarded clone of this engine's
   * state and returns the diff bytes the identical `apply_commands` call
   * would return — with ZERO observable engine effect: no clock tick, no
   * commit-log row, no retention, and the Phase-G/H queue is dropped, never
   * drained (no `__causl_fire` / `__causl_on_commit` crossings). Rejections
   * ride the same `apply_commands error:` token family, so the existing
   * verdict classifier decodes them with no new code paths. Optional:
   * present only on a #320-era artefact; the `graph.simulate` facade keeps
   * the TS dry-run when absent.
   */
  readonly simulate_commands?: (
    engine_id: number,
    cmd_buf: Uint8Array,
  ) => Uint8Array
  /**
   * promote-read (ffi-4) — the per-engine `EngineStats` telemetry snapshot,
   * as the fixed-width `STATS_FIELD_COUNT × u32` LE buffer.
   */
  readonly stats?: (engine_id: number) => Uint8Array
  /**
   * lift-readat (causl/causl-core-rs#170) — the DISCRIMINATED historical
   * read of `(slot, gen)` on `engine_id` at GraphTime `time`, as the
   * 24-byte `read_at_result` record (status + graph_time + value record).
   * Decoded by {@link decodeReadAtResult} into the exact
   * {@link RetentionResult} shape the TS `readAt` / `snapshotAt` return.
   * Optional: present only on the rebuilt artefact carrying the §12.2
   * discriminated time-travel extern; absent on legacy bridges.
   */
  readonly read_at_result?: (
    engine_id: number,
    slot: number,
    gen: number,
    time: bigint,
  ) => Uint8Array
  /**
   * lift-export (causl/causl-core-rs#170) — the §18A.3 DEEP whole-graph
   * export of `engine_id`: the whole `CauslModel` IR (nodes + deps +
   * commit-log WIDENED with the IR `time`, the hydrate-aware per-commit
   * `originatedAt`, and the `IRSubscribe` event stream), as the
   * self-describing `export_model` buffer. Decoded by
   * {@link decodeExportModel}. Optional: present only on the rebuilt
   * artefact carrying the §18A.3 deep-export extern; absent on legacy
   * bridges (the facade keeps `exportModel` on the wrapped TS closure).
   */
  readonly export_model?: (engine_id: number) => Uint8Array
  /**
   * del-final (causl/causl-core-rs#170) — the per-node EXPLAIN metadata of
   * `(slot, gen)` on `engine_id`: the structural `kind` + the `computedAt` /
   * `contributedAt` timestamps the TS `buildExplanation` previously sourced
   * from the `entries` map (the LAST TS-closure read `explain` carried), as
   * the 20-byte `node_meta` record. Decoded by {@link decodeNodeMeta}.
   * Optional: present only on the rebuilt artefact carrying the del-final
   * explain-timestamp extern; absent on legacy bridges (the facade keeps the
   * timestamps on the TS closure).
   */
  readonly node_meta?: (
    engine_id: number,
    slot: number,
    gen: number,
  ) => Uint8Array
  /**
   * #111 (causl/causl-core-rs#211) — free THIS engine's per-`engine_id` Rust
   * state on the shared wasm instance (its `ENGINE_STATES` slot: interned
   * value/pool refs, fn-table, observers). Called from
   * {@link AuthoritativeWasmEngine.dispose} when a graph is torn down, so a
   * retired per-widget / per-route graph reclaims its Rust slot instead of
   * growing `ENGINE_STATES` without bound. Optional: present only on the
   * artefact carrying the per-engine free extern; absent on a legacy bridge,
   * where dropping the JS handler registrations (mux-6) is the reclaimable
   * surface and the Rust slot is reclaimed only at instance teardown.
   */
  readonly dispose_engine?: (engine_id: number) => void
}

/**
 * The compute / fire handler installer surface (the
 * `causl-compute-imports.js` snippet the wasm-bindgen glue imports).
 */
export interface ComputeImportsModule {
  /**
   * mux-6 (causl-client#42) — register THIS engine's compute handler under
   * its `engineId`. The sidecar keeps a `Map<engineId, handler>` and
   * `__causl_compute(engineId, …)` dispatches to the matching entry, so two
   * live engines no longer overwrite each other's single global slot.
   */
  readonly __causl_set_compute_handler: (
    engineId: number,
    fn: (engineId: number, fnId: number, depsBuf: Uint8Array) => Uint8Array,
  ) => void
  /** mux-6 — register THIS engine's fire handler under its `engineId`. */
  readonly __causl_set_fire_handler: (
    engineId: number,
    fn: (firingsBuf: Uint8Array) => Uint8Array,
  ) => void
  /** mux-6 — drop this engine's compute handler (teardown / dispose). */
  readonly __causl_remove_compute_handler: (engineId: number) => void
  /** mux-6 — drop this engine's fire handler (teardown / dispose). */
  readonly __causl_remove_fire_handler: (engineId: number) => void
  /**
   * lift-subscribecommits (causl-wasm#170) — register THIS engine's
   * COMMIT-LEVEL handler under its `engineId`. The Rust apply path crosses
   * into `__causl_on_commit(engineId, commitBuf)` ONCE per commit (after the
   * Phase-G per-node firing); the sidecar dispatches to the matching entry,
   * so two live engines' commit observers never collide. Optional: present
   * only on the rebuilt sidecar carrying the commit-handler registry; absent
   * on a legacy artefact (the facade keeps `subscribeCommits` on the wrapped
   * TS closure).
   */
  readonly __causl_set_commit_handler?: (
    engineId: number,
    fn: (engineId: number, commitBuf: Uint8Array) => void,
  ) => void
  /**
   * lift-subscribecommits (causl-wasm#170) — drop this engine's commit-level
   * handler (teardown / dispose). A later `__causl_on_commit` for this id is
   * then a no-op.
   */
  readonly __causl_remove_commit_handler?: (engineId: number) => void
  /**
   * pre-fire (causl-wasm#189/#190) — register THIS engine's PRE-FIRE
   * handler under its `engineId`. The Rust apply path crosses into
   * `__causl_pre_fire(engineId, commitBuf)` once per commit BEFORE the
   * first Phase-G observer byte (per-commit crossing order
   * `__causl_pre_fire` → `__causl_fire` → `__causl_on_commit`; a
   * rolled-back batch delivers none of them). The record is byte-identical
   * to the `__causl_on_commit` Phase-H record — decode with the same
   * parser. Optional: present only on the cw#190+ sidecar; absent on a
   * legacy artefact (the facade keeps the post-`apply_commands` union
   * bump, so commit-boundary `nodeVersion` reads stay correct there —
   * only the in-frame corner needs this crossing).
   */
  readonly __causl_set_pre_fire_handler?: (
    engineId: number,
    fn: (engineId: number, commitBuf: Uint8Array) => void,
  ) => void
  /**
   * pre-fire (causl-wasm#189/#190) — drop this engine's pre-fire handler
   * (teardown / dispose). A later `__causl_pre_fire` for this id is then a
   * no-op.
   */
  readonly __causl_remove_pre_fire_handler?: (engineId: number) => void
  /**
   * gap-5 (causl-wasm#169; causl-client#102) — register THIS engine's
   * observer-ERROR handler under its `engineId`. `#onFire` catches a
   * throwing Phase-G subscriber and returns it in the §5.5 observer-errors
   * buffer; the Rust `apply_commands` error-hook then crosses ONCE per
   * surfaced `ObserverError` into `__causl_on_observer_error(engineId,
   * errBuf)`, and the sidecar dispatches to the matching entry — the
   * per-engine sink the adopter's `onObserverError` is reached through (the
   * same channel the TS floor delivers observer errors to). `errBuf` is the
   * single-error wire record (`err_count u32 = 1 | engine_id u32 | record`),
   * decoded with the same §5.5 parser. Optional: present only on the gap-5+
   * sidecar; absent on a legacy artefact (the facade then keeps observer
   * errors on the wrapped TS closure).
   */
  readonly __causl_set_error_handler?: (
    engineId: number,
    fn: (engineId: number, errBuf: Uint8Array) => void,
  ) => void
  /**
   * gap-5 (causl-wasm#169; causl-client#102) — drop this engine's
   * observer-error handler (teardown / dispose). A later
   * `__causl_on_observer_error` for this id is then a no-op (the error is
   * dropped — the engine has no live error channel).
   */
  readonly __causl_remove_error_handler?: (engineId: number) => void
  readonly __causl_reset_handlers?: () => void
}

/** Compute out-buffer status bytes (mirror of `compute_bridge::STATUS_*`). */
const STATUS_OK = 0
const STATUS_THREW = 1

/**
 * The default engine id the Rust bridge uses (`DEFAULT_ENGINE_ID` — the
 * `apply_commands_default` shim's slot). Kept only as the Rust default
 * constant; live engines mint their OWN id from {@link nextEngineId}.
 */
const DEFAULT_ENGINE_ID = 0

/**
 * R3 (causl-client#54) — the engine-internal commit intent the wasm engine
 * emits but the pure-TS engine has no analogue for: `'__seed'` is the
 * deferred-input-seed flush commit (`graph.ts` `flushSeed`). It must never
 * reach an adopter-facing surface — `subscribeCommits` delivery, `commitLog()`,
 * or `exportModel().commits` — because under js-ssot the adopter never observes
 * it (the seed commit drives the backend directly, bypassing the TS closure's
 * commit observers), so surfacing it under rust-ssot is a divergence. Filtering
 * it here makes rust-ssot match js-ssot (which never leaks it).
 */
const INTERNAL_SEED_INTENT = '__seed'

/**
 * R3 (causl-client#54) — centralized predicate for engine-internal commit
 * intents that must be filtered from every adopter-facing commit surface.
 * One predicate, three call-sites (`#onCommit`, `commitLog`, `exportModel`) so
 * the leak class is closed by default rather than patched per-mouth. Once the
 * eager-seed root fix (#59) removes the `'__seed'` commit at source this guard
 * becomes a no-op, but it stays as defense-in-depth against any future internal
 * intent.
 */
function isInternalCommitIntent(intent: string): boolean {
  return intent === INTERNAL_SEED_INTENT
}

/**
 * mux-5 (causl-client#42) — process-monotonic engine-id allocator. Each
 * {@link AuthoritativeWasmEngine} captures `nextEngineId++` at construction
 * and threads it through every `apply_commands(engine_id, …)` /
 * `read_cell_value(engine_id, …)` call and into its Subscribe records, so the
 * per-engine Rust `ENGINE_STATE` + `(engine_id, NodeId)` fn-table / observers
 * route to THIS engine. The first engine gets id 0 — the same slot the Rust
 * {@link DEFAULT_ENGINE_ID} names — which is harmless (it is still a distinct
 * per-engine slot keyed by the same integer). The allocator only ever
 * advances: it is NEVER reset (the #143 at-most-one-instance guard this
 * comment once paired with is retired — see below — so there is no reset
 * hook to keep in lockstep, and a monotonic id is what keeps retired and
 * live engines from ever aliasing a Rust `ENGINE_STATE` slot). Seeded at
 * {@link DEFAULT_ENGINE_ID} so the first engine claims the same integer slot
 * the Rust `apply_commands_default` shim uses (a distinct per-engine slot that
 * merely shares the id 0).
 */
let nextEngineId = DEFAULT_ENGINE_ID

/**
 * #127 — the set of POISONED shared wasm instances (bridges). A wasm32 Rust
 * panic is a trap: it aborts with no unwinding, so the engine's per-`engine_id`
 * `State` is left UNDEFINED (the derived arm may have `mem::take`'d it out of
 * its registry slot, stranding `State::default()`). Because the consolidated
 * bridge is instantiated ONCE and every {@link AuthoritativeWasmEngine} routes
 * through that single shared {@link AuthoritativeBridge}, a trap poisons the
 * instance for EVERY multiplexed engine — not just the one that trapped.
 *
 * Keyed on the bridge object identity, so the poison is scoped exactly to the
 * shared instance and a fresh instance (a new object) starts clean — no reset
 * hook is needed (a `WeakSet` also lets a GC'd bridge fall out). {@link
 * AuthoritativeWasmEngine.#applyCommands} adds the bridge here the instant a
 * trap is discriminated, and {@link AuthoritativeWasmEngine.#assertInstanceLive}
 * fails EVERY subsequent operation (commit / read / register / dispose /
 * subscribe) loud with a {@link WasmInstancePoisonedError} rather than let the
 * JS mirror silently diverge from the poisoned engine.
 */
const poisonedBridges = new WeakSet<AuthoritativeBridge>()

/**
 * #127 — discriminate a wasm TRAP (a `WebAssembly.RuntimeError` — the JS
 * surface of a Rust panic aborting via `unreachable` on wasm32) from a clean
 * engine REJECTION (a typed verdict string the bridge returns across the FFI,
 * rethrown as an ordinary `Error`). Only a trap leaves the engine's state
 * undefined; a rejection is a byte-identical §5.2 no-op the mirror can safely
 * roll back. Guarded for environments where `WebAssembly` is absent.
 */
function isWasmTrap(err: unknown): boolean {
  return (
    typeof WebAssembly !== 'undefined' &&
    typeof WebAssembly.RuntimeError === 'function' &&
    err instanceof WebAssembly.RuntimeError
  )
}

interface SlotEntry {
  readonly slot: number
  gen: number
  /** Whether this slot is an input (vs. a derived). Selects the read table. */
  readonly isInput: boolean
}

interface DerivedRegistration {
  readonly id: NodeId
  readonly slot: number
  readonly gen: number
  readonly fnId: number
  readonly deps: readonly NodeId[]
  readonly compute: DerivedCompute
}

const textDecoder = new TextDecoder()

// ======================================================================
// mux-6b/mux-7/mux-8 (epic causl-client#42) — UNBOUNDED authoritative
// coexistence. The #143 fail-closed at-most-one-instance guard is RETIRED.
//
// The loader now instantiates the consolidated bridge ONCE per bridge and
// routes every engine through that single shared instance, multiplexed by
// `engine_id`: the Rust `ENGINE_STATES` is an unbounded `BTreeMap` keyed by
// `engine_id`, `INTERN_TABLE` / `VALUE_POOL` are deliberately shared per-wasm
// instance (opaque monotonic handles), and the compute/fire handlers are a
// per-`engine_id` registry (mux-6). N engines therefore coexist live with
// ZERO cross-talk — proven by `wasm-multi-instance-independence.test.ts` at
// N=16. There is no longer a singleton to alias, so the prior #143
// at-most-one fail-closed epoch guard is retired entirely.

/**
 * The authoritative wasm engine. One instance per WasmBackend; owns the
 * slot registry, derived fn-table, observer registry, and the clock.
 */
export class AuthoritativeWasmEngine {
  readonly #bridge: AuthoritativeBridge
  readonly #imports: ComputeImportsModule

  /**
   * NodeId → stable `(slot, gen, isInput)` handle.
   *
   * SLOT DISCIPLINE (register_derived_p1.rs §"separate Vecs"): inputs and
   * deriveds live in SEPARATE engine Vecs but BOTH index by the raw slot
   * integer, so a slot can be both an input index and a derived index.
   * The cell-id tiebreaker in `read_during_recompute` / `get_value`
   * matches on the FULL generational `NodeId`, so an input and a derived
   * that collide on a slot are disambiguated by GENERATION. We therefore
   * mint inputs from one counter at gen 0 and deriveds from an
   * INDEPENDENT counter at gen 1 — a derived NodeId can never equal an
   * input NodeId, so the phantom default cells the engine's auto-extend
   * creates never shadow a real input dep (the cutover derived-deps bug).
   */
  readonly #slots = new Map<NodeId, SlotEntry>()
  /**
   * #165 — the REVERSE index of {@link #slots}: `${slot}:${gen}` -> NodeId.
   * The commit / fire / observer-error decode paths resolve a
   * Rust-reported `(slot, gen)` pair back to its NodeId through this map
   * ({@link #slotToIdIndex}). It was rebuilt O(N) from scratch on every
   * lookup, up to four times per commit; I now maintain it INCREMENTALLY
   * in lockstep with `#slots` (one `set` on registration, one `delete` on
   * disposal), so a lookup is O(1) and a commit does zero rebuild work. A
   * `(slot, gen)` key is unique per live entry (input slots carry gen 0,
   * derived slots {@link DERIVED_GEN} = 1, and each class draws slots from
   * its own monotonic counter), so this stays equivalent to the old full
   * rebuild's last-write-wins Map.
   */
  readonly #slotToId = new Map<string, NodeId>()
  #nextInputSlot = 0
  #nextDerivedSlot = 0
  #nextIntentId = 0
  #nextFnId = 0

  /** The generation deriveds are minted at (distinct from inputs' gen 0). */
  static readonly DERIVED_GEN = 1

  /** fn_id → derived registration (compute lambda + deps). */
  readonly #fnTable = new Map<number, DerivedRegistration>()
  /** derived slot → registration (for the fire/read deps-order mapping). */
  readonly #derivedBySlot = new Map<number, DerivedRegistration>()
  /**
   * del-final (causl/causl-core-rs#170) — the explain `via`-tag a derived was
   * registered with (`'live'` for a hot-swappable devtools node so `explain`
   * reports `via: 'live'`; `'commit-metadata'` for a Phase-F.5 metadata
   * derived). A devtools REGISTRATION attribute the Rust engine core does NOT
   * retain — this backend (which survives the §18A.3 TS-engine deletion) holds
   * it so {@link nodeMeta} can resolve `via` without the TS `entries` map.
   * Plain `derived(...)` callers are absent here → `via: 'derived'`.
   */
  readonly #derivedTags = new Map<NodeId, 'live' | 'commit-metadata'>()

  /**
   * causl-client#103 — dynamic-dep rewires discovered during a commit's
   * Phase-D recompute, keyed by derived NodeId → the new first-read-ordered
   * dep set. Populated by `#onCompute` when a recompute's tracked read set
   * diverges from the registered dep list, and drained in {@link commit}
   * once the `apply_commands` window has closed (re-registering inside it
   * would re-enter the commit). Empty between commits.
   */
  readonly #pendingRewires = new Map<NodeId, NodeId[]>()

  /**
   * causl-client#120 — the typed error captured host-side when a derived's
   * `__causl_compute` lambda threw. The compute runs in JS (behind the
   * `__causl_compute` FFI import), so `#onCompute` has the REAL thrown
   * object; only its Display string survives the crossing back through Rust
   * as the `Engine(ComputeThrew { reason })` verdict. `#onCompute` stashes
   * the normalised typed error here (via {@link asDerivedComputeError}) and
   * {@link #applyCommands} rethrows it when the matching verdict crosses
   * back — so the original throw surfaces as `cause` on a
   * {@link DerivedComputeError} (or the engine's own `CauslError`),
   * byte-identical to the TS floor, WITHOUT a Rust wire change. Cleared at
   * the start of every `apply_commands` and after it is consumed.
   */
  #pendingComputeThrow: unknown = undefined

  /** NodeId → observer set (Phase-G subscriber bridge). */
  readonly #observers = new Map<NodeId, Set<Observer<unknown>>>()
  /**
   * lift-subscribecommits (causl-wasm#170) — the commit-LEVEL observer set
   * (Phase-H). Fed by the Rust `__causl_on_commit` crossing once per commit
   * (after the Phase-G per-node firing), distinct from the per-NODE
   * `#observers`. Registration order is preserved (insertion-ordered `Set`),
   * so the fan-out matches the TS `commitObservers` dispatch order.
   */
  readonly #commitObservers = new Set<(commit: Commit) => void>()
  /**
   * pre-fire (causl-wasm#189/#190) — the SINGLE pre-fire changed-set
   * observer (the `graph.ts` facade's nodeVersion union-bump hook). Fed by
   * the Rust `__causl_pre_fire` crossing once per commit BEFORE the first
   * Phase-G observer byte, with the commit's authoritative changed-set
   * NodeIds. One slot, not a fan: the facade is the only consumer, and the
   * bump must run exactly once per commit.
   */
  #preFireObserver: ((changedNodes: readonly NodeId[]) => void) | undefined
  /**
   * gap-5 (causl-wasm#169; causl-client#102) — the SINGLE observer-error
   * sink (the `graph.ts` facade's `reportObserverError` hook). Fed by the
   * Rust `__causl_on_observer_error` crossing once per surfaced Phase-G
   * `ObserverError`, with the decoded `(error, ctx)` reconstructed from the
   * §5.5 single-error wire record. One slot, not a fan: the facade is the
   * only consumer, and it re-fans to the adopter's `onObserverError`.
   */
  #observerErrorObserver:
    | ((error: unknown, ctx: ObserverErrorContext) => void)
    | undefined
  /** Per-NodeId synthesised callback-id used in the Subscribe cmd record. */
  readonly #callbackIds = new Map<NodeId, number>()
  #nextCallbackId = 1

  /** Monotonic clock, advanced from the wasm Committed diff record. */
  #now: GraphTime = 0 as GraphTime

  /**
   * #78 — the accepted-hydrate breadcrumb: commit `time` → the snapshot
   * envelope's recorded time (`originatedAt`). LEGACY-ARTEFACT FALLBACK
   * ONLY since #129: a #318-era artefact persists `originated_at`
   * engine-side (the widened 16-byte `BeginCommit` body), so the
   * `commit_log_meta` / `export_model` wires carry the breadcrumb and this
   * map stays EMPTY (never written, never grows). On a legacy artefact
   * (no `commit_log_meta` extern, so no widened `BeginCommit` decode) the
   * pre-#129 behaviour is preserved: {@link hydrate} records the accepted
   * commit's `time → originatedAt` here and the backend-sourced mouths
   * ({@link #onCommit} Phase-H delivery, {@link exportModel}) stamp it
   * from this map, keeping them byte-identical to the TS reference's
   * hydrate-issued records. Written only on the ACCEPTED path (a rejected
   * hydrate records nothing).
   */
  readonly #hydrateOriginatedAt = new Map<GraphTime, GraphTime>()

  /**
   * #129 / causl/causl-core-rs#318 — the adopter `commitHistoryCap` LAST
   * threaded onto the engine's commit-log eviction horizon via
   * {@link setCommitHistoryCap} (the `SetCommitLogCap` cmd-buf op).
   * `undefined` until the facade threads it; {@link ownsCommitLog} arms
   * only once it is set, so the engine ring and the adopter-facing
   * `commitLog` window provably share ONE horizon before the facade
   * re-sources the log from here.
   */
  #commitLogCap: number | undefined

  /**
   * #252 / causl/causl-core-rs#321+#323 — the EFFECTIVE retention window
   * LAST threaded onto the engine's retention chain via
   * {@link setSnapshotRetentionCap} (the `SetSnapshotRetentionCap` cmd-buf
   * op, batched atomically with the `RetainDerivedRows` opt-in).
   * `undefined` until the facade threads it — or forever, on a legacy
   * artefact whose decoder rejects ops 14/15 ({@link ownsRetention} then
   * stays `false` and the facade keeps the TS floor's retention
   * byte-identically, fail-safe).
   */
  #snapshotRetentionCap: number | undefined

  /**
   * #129 — the PUBLISHED adopter-facing commitLog window (frozen
   * `readonly Commit[]`, oldest-first), maintained copy-on-write so the
   * facade's Phase-F.4 refresh never re-decodes the engine wire per
   * commit. `undefined` until the first {@link commitLogWindow} read
   * materialises it (zero per-commit cost for a graph with no commitLog
   * consumer); {@link commit} appends the just-accepted row when the
   * cache is fresh through the previous clock tick and drops it
   * otherwise (a cold reader then re-decodes the wire). Each append
   * allocates a FRESH frozen array, so a window published to a
   * subscriber is never mutated under it.
   */
  #commitLogWindowCache: readonly Commit[] | undefined
  /** #129 — the engine time {@link #commitLogWindowCache} is fresh through. */
  #commitLogWindowFreshAt: GraphTime = 0 as GraphTime

  /**
   * #78 — the IN-FLIGHT hydrate's `originatedAt`. Set for the duration of
   * {@link hydrate}'s `commit('hydrate', …)` call so the Phase-H
   * `__causl_on_commit` crossing (which fires DURING `apply_commands`,
   * before the {@link #hydrateOriginatedAt} entry exists) can stamp the
   * delivered {@link Commit}. `undefined` at every other moment; nested
   * same-engine commits cannot interleave (the #178 commit-window guard
   * rejects them before touching state).
   */
  #pendingHydrateOriginatedAt: GraphTime | undefined

  /**
   * The tag-6 `DerivedRecomputed` sextuple trace from the MOST RECENT
   * `commit()` — the authoritative Rust Phase-D Kahn drain, projected
   * onto NodeId strings. Read by {@link collectRustPhaseDTrace} for the
   * B.8 cross-bridge gate. Replaced wholesale every commit (the gate
   * drives one isolating commit, then reads).
   */
  #lastPhaseDTrace: readonly RecomputeAffectedRow[] = []

  /** Whether the compute/fire handlers have been installed. */
  #handlersInstalled = false

  /**
   * mux-5 (causl-client#42) — this engine's stable id, minted from the
   * module-level {@link nextEngineId} allocator at construction. Threaded
   * through every `apply_commands(engine_id, …)` / `read_cell_value(engine_id,
   * …)` call, stamped into the Subscribe cmd records, and used as the
   * `Map<engineId, handler>` key the mux-6 sidecar dispatches on. Distinct per
   * live engine, so N engines coexist on the ONE shared wasm instance with no
   * cross-talk (mux-6b/mux-7/mux-8 — the #143 at-most-one guard is retired).
   */
  readonly #engineId: number

  /**
   * promote-read (causl/causl-core-rs#169) — this engine's canonicality mode,
   * threaded from {@link WasmBackend} (`'js-ssot'` default | `'rust-ssot'`).
   * The READ-SIDE structural facade (`dependencies` / `dependents` /
   * `commitLog` / `stats`) in `graph.ts` consults THIS engine's structural
   * reads ONLY when this is `'rust-ssot'`; under `'js-ssot'` the facade stays
   * byte-identical on the TS closure (the V2.1 #1522 oracle invariant). Stored
   * here so the facade gate is a single field read, not a cross-module hop.
   */
  readonly #engineMode: AuthoritativeEngineMode

  /**
   * NodeId → current JS value cache. See {@link ValueHandleCache}.
   * Populated when the engine HOLDS the original JS value — on input
   * commit and on a derived's compute result — and served on `read()`,
   * on Phase-D dep resolution, and on Phase-G firing.
   *
   * AUTHORITATIVE for container values (feat/content-hash-values). The
   * engine now stores only a structural content-HASH for a container cell
   * (Array/Object), never the value itself, so the container value can
   * ONLY come from this cache — a miss is unrecoverable for a container.
   * The cache is therefore non-evicting for live (registered, non-
   * disposed) cells: capacity is unbounded so a live cell's value never
   * ages out. The live-cell set is bounded by the graph's node count
   * (exactly the values the JS engine would hold anyway). Scalars
   * (number/string/bool/null) still round-trip through the engine
   * losslessly, so a scalar cache miss remains safe; only the container
   * path depends on cache authority. Cleared on the value-pool reset (a
   * fresh engine — `__resetValuePool` in `__enableAuthoritativeWasm`),
   * which also resets the wasm side, keeping the two in lockstep.
   */
  readonly #valueCache = new ValueHandleCache<NodeId>(Number.MAX_SAFE_INTEGER)

  /**
   * #165 — the PER-ENGINE Temporal impl, snapshotted from the module-level
   * `setTemporalImpl` injection at CONSTRUCTION time and threaded through
   * every value decode this engine performs. Two engines constructed in
   * one realm, each injecting its own impl before its own construction
   * (the documented `setTemporalImpl` contract), therefore decode with
   * THEIR impl: a later injection for engine B no longer rewrites what
   * engine A reconstructs `Temporal.*` values with. `undefined` when
   * nothing was injected at construction — the decode then falls back to
   * the LIVE module-level injection, then `globalThis.Temporal`, so a
   * legacy late injection still takes effect (module-scoped, noted on
   * #165 as the residual sharing).
   */
  readonly #temporal: TemporalLike | undefined = currentTemporalImpl()

  /**
   * Per-input-node `Object.is` change-token state (SPEC §5.1 Phase B). For
   * each INPUT node that has carried a container value, holds the last
   * committed JS reference and a monotonic epoch counter. On commit the
   * epoch bumps ONLY when `!Object.is(prevRef, nextRef)`; the interned
   * marker (`inputEpochMarker(slot, epoch)`) is then identical for a
   * same-reference write (no-op) and distinct for a new reference
   * (propagate) — matching causl-ts's input cutoff exactly, in O(1)
   * instead of the O(rows) structural content-hash. DERIVED container
   * results keep the structural hash (SPEC §15.1). Reset in lockstep with
   * `#valueCache` (fresh engine / value-pool reset).
   */
  readonly #inputEpoch = new Map<NodeId, { ref: unknown; epoch: number }>()

  /**
   * #72 — the commit-window mirror journal. `commit()` opens one before
   * staging its writes and closes it in its `finally`; while open, every
   * {@link #cacheSet} records the id's PRIOR cache entry (or the MISS
   * sentinel) on first overwrite. When `apply_commands` throws — the
   * engine rolled the commit back byte-identically per SPEC §5.2 — the
   * catch arm replays the journal so the JS mirror (`#valueCache`) rolls
   * back the same way, instead of serving the never-committed value.
   * Saved/restored around nested windows (a re-entrant `commit()` from a
   * notification frame journals into its OWN map; the outer journal
   * survives for the outer catch). `undefined` outside any commit window
   * — non-commit cache writes (registration seeds, read fills) are
   * unjournaled by design: they mirror already-committed engine state.
   */
  #cacheJournal: Map<NodeId, unknown> | undefined = undefined

  /**
   * #72 — write-through to `#valueCache` that records the prior entry in
   * the open commit-window journal (first-overwrite-wins), so a rejected
   * commit can restore the exact pre-commit mirror. Outside a commit
   * window this is a plain `#valueCache.set`.
   */
  #cacheSet(id: NodeId, value: unknown): void {
    const journal = this.#cacheJournal
    if (journal !== undefined && !journal.has(id)) {
      journal.set(id, this.#valueCache.get(id))
    }
    this.#valueCache.set(id, value)
  }

  /**
   * cw#181+#182+#184 re-vendor — the commit time IN FLIGHT while this
   * engine's `apply_commands` commit window is open, `undefined` outside
   * one. `#now` mirrors the LAST decoded commit time and only advances
   * after `apply_commands` returns (the diff decode at the bottom of
   * {@link commit}), but Phase-G observer delivery (`__causl_fire`) and
   * any in-dispatch `subscribe()` initial fire happen DURING the window
   * — the TS reference stamps those with the POST-Phase-C clock (the
   * commit's own time). With GraphTime now owned exclusively by commits
   * (§5.1 — causl-wasm#180/#183: no lifecycle op ticks), the in-flight
   * time is exactly `#now + 1`. Saved at {@link commit} entry and
   * restored in its `finally` (#116, mirroring `#cacheJournal`): a
   * same-engine nested `commit()` from an outer commit's notification
   * frame IS re-entered here and rejects INSIDE its own window at the
   * causl-wasm#178 `apply_commands` guard — its `finally` must restore
   * the outer window's stamp, not null it, or the outer commit's
   * remaining Phase-G firings read the settled (past) `#now`.
   */
  #inFlightTime: GraphTime | undefined = undefined

  /**
   * The adopter-visible clock for observer delivery: the in-flight
   * commit time while this engine's commit window is open (Phase-G
   * fires, in-dispatch subscribe initial fires), else the settled
   * `#now`. Byte-identical to the TS reference's `now` at every
   * delivery seam.
   */
  #liveNow(): GraphTime {
    return this.#inFlightTime ?? this.#now
  }

  constructor(
    bridge: AuthoritativeBridge,
    imports: ComputeImportsModule,
    engineMode: AuthoritativeEngineMode = 'js-ssot',
  ) {
    this.#bridge = bridge
    this.#imports = imports
    // promote-read — store the canonicality mode so the read-side facade
    // gate is a single field read. Defaults to `'js-ssot'` so every existing
    // construction site (tests, the mux harness) stays byte-identical.
    this.#engineMode = engineMode
    // mux-5 — mint this engine's stable id BEFORE installing handlers, so the
    // per-id `Map<engineId, handler>` registration (mux-6) keys on it.
    // mux-6b/mux-7/mux-8 — N engines coexist live on the ONE shared wasm
    // instance, each isolated by its own `#engineId`; there is no longer an
    // at-most-one guard to claim.
    this.#engineId = nextEngineId
    nextEngineId += 1
    this.#installHandlers()
  }

  /** mux-5 — this engine's minted id (test/diagnostic surface). @internal */
  get engineId(): number {
    return this.#engineId
  }

  /**
   * #111 — `true` once {@link dispose} has torn this engine down (its
   * per-`engineId` handler registrations removed from the sidecar). Idempotent
   * teardown reads this; also a test/diagnostic surface.
   *
   * @internal
   */
  get disposed(): boolean {
    return !this.#handlersInstalled
  }

  /**
   * #111 — the sidecar handler module this engine's compute/fire/commit
   * handlers are registered in. Exposed so the lifecycle gate can drive the
   * sidecar's `__causl_compute` dispatch directly (the SAME singleton the
   * engine registered into) to prove a disposed engine's registration is gone.
   *
   * @internal test seam.
   */
  get __sidecarForTests(): ComputeImportsModule {
    return this.#imports
  }

  /**
   * #115 — the shared per-wasm-instance intern table this engine's cmd-buf
   * writes route through. Exposed so a retention test can probe the
   * monotonic `intern_string` id (an opaque, never-recycled handle) before
   * and after a workload to prove steady-state intern growth is bounded for
   * a bounded-live-state graph (an epoch/content-hash marker must not mint
   * one immortal interned string per commit).
   *
   * @internal test seam.
   */
  get __bridgeForTests(): AuthoritativeBridge {
    return this.#bridge
  }

  /**
   * promote-read (causl/causl-core-rs#169) — this engine's canonicality mode.
   * The `graph.ts` read-side structural facade reads this to decide whether
   * to route `dependencies` / `dependents` / `commitLog` / `stats` through
   * THIS engine's Rust externs (`'rust-ssot'`) or stay on the TS closure
   * (`'js-ssot'`, byte-identical).
   */
  get engineMode(): AuthoritativeEngineMode {
    return this.#engineMode
  }

  /**
   * Clear the value-handle cache (the value-pool reset / bridge reset).
   * A miss is always safe (falls back to `read_pool_value`), so this only
   * costs a later parse — never corrupts.
   *
   * @internal
   */
  __resetValueCache(): void {
    this.#valueCache.clear()
    this.#inputEpoch.clear()
  }

  get now(): GraphTime {
    return this.#now
  }

  // ====================================================================
  // Slot allocation
  // ====================================================================

  #slotFor(id: NodeId, isInput: boolean): SlotEntry {
    let entry = this.#slots.get(id)
    if (entry === undefined) {
      if (isInput) {
        entry = { slot: this.#nextInputSlot, gen: 0, isInput: true }
        this.#nextInputSlot += 1
      } else {
        entry = {
          slot: this.#nextDerivedSlot,
          gen: AuthoritativeWasmEngine.DERIVED_GEN,
          isInput: false,
        }
        this.#nextDerivedSlot += 1
      }
      this.#slots.set(id, entry)
      // #165 — keep the reverse `slot:gen -> id` index in lockstep so
      // `#slotToIdIndex()` never rebuilds. A fresh entry only ever ADDS a
      // key (the slot counters are monotonic), so this cannot clobber a
      // live sibling.
      this.#slotToId.set(`${entry.slot}:${entry.gen}`, id)
    }
    return entry
  }

  /** Look up an existing slot, or `undefined` if the id is unregistered. */
  #lookupSlot(id: NodeId): SlotEntry | undefined {
    return this.#slots.get(id)
  }

  // ====================================================================
  // Derived registration (Phase-D fn-table binding)
  // ====================================================================

  /**
   * Register a derived node: mint its slot, emit a `RegisterDerived`
   * cmd-buf record (binding `fn_id` + dep slots in the engine) and bind
   * the JS compute lambda in the fn-table the `__causl_compute` import
   * dispatches to.
   *
   * `deps` is the ORDERED dependency list — the engine drives Phase-D in
   * this order and passes dep values to `__causl_compute` in the same
   * order, so the compute lambda maps each dep value back to its NodeId
   * positionally.
   */
  registerDerived(
    id: NodeId,
    deps: readonly NodeId[],
    compute: DerivedCompute,
    tag?: 'live' | 'commit-metadata',
  ): void {
    // del-final (#170) — record the explain `via` tag (devtools registration
    // attribute) so `nodeMeta` can resolve `via` without the TS `entries` map.
    // Plain `derived(...)` passes `undefined` → absent here → `via: 'derived'`.
    if (tag !== undefined) this.#derivedTags.set(id, tag)
    const derivedEntry = this.#slotFor(id, false)
    // Inputs feeding a derived must already have slots (deps are
    // registered as inputs or upstream deriveds first). Mint on demand so
    // a dep that is itself a not-yet-written input still resolves to a
    // stable slot.
    const depHandles = deps.map((dep) => {
      const existing = this.#slots.get(dep)
      // A dep with no slot yet defaults to an input slot; if it is later
      // registered as a derived, registerDerived above will have minted
      // it as a derived slot first (the test registers deriveds in
      // topological order).
      const handle = existing ?? this.#slotFor(dep, true)
      return { dep, slot: handle.slot, gen: handle.gen }
    })

    const fnId = this.#nextFnId
    this.#nextFnId += 1
    const registration: DerivedRegistration = {
      id,
      slot: derivedEntry.slot,
      gen: derivedEntry.gen,
      fnId,
      deps,
      compute,
    }
    this.#fnTable.set(fnId, registration)
    this.#derivedBySlot.set(derivedEntry.slot, registration)

    const cmdBuf = encodeRegisterDerived(
      derivedEntry.slot,
      derivedEntry.gen,
      fnId,
      depHandles.map((d) => ({ slot: d.slot, gen: d.gen })),
    )
    // RegisterDerived runs outside a commit window — apply_commands
    // handles a lone RegisterDerived (count == 1 → no snapshot needed).
    // mux-5 — select THIS engine's slot; the apply-layer engine_id is the
    // authority that keys the `(engine_id, NodeId)` fn-table entry (the
    // RegisterDerived record itself carries no per-record engine_id — the
    // Rust decode does not read one).
    const diffBuf = this.#applyCommands(cmdBuf)
    decodeDiff(diffBuf) // surface malformed buffers as a coherent error

    // R1-interim eager-derived-materialization (SI-5, epic #53): the
    // RegisterDerived cmd only registers the fn + deps — the Rust engine does
    // NOT compute the derived's value until a later Phase-D (today, the __seed
    // commit). So a derived registered AFTER the seed flush (e.g. an external
    // BYO-graph derived composing over already-materialised grid nodes) has a
    // default-null cell and `read()` returns null until the next commit. Mirror
    // the TS engine's eager `computeDerivedIterative`: run the compute NOW
    // against the current dep values and cache the result, so a read before any
    // commit returns the computed value. The next commit's Phase-D (#onFire /
    // #onCompute) refreshes the cache. (Deleted by the Rust eager-derived root
    // fix #59.)
    try {
      const value = compute((depId) => this.read(depId))
      this.#cacheSet(id, value)
    } catch {
      // A registration-time compute throw (e.g. a dep not yet materialised)
      // leaves the cache empty — read falls back to the wasm cell / the next
      // commit's recompute, mirroring the TS engine tolerating an eager throw.
    }
  }

  // ====================================================================
  // Authoritative commit
  // ====================================================================

  /**
   * Drive `apply_commands` against THIS engine's registry slot, decoding
   * the structured engine race verdict the bridge throws
   * (causl/causl-core-rs#178) into the SAME typed error the TS reference
   * engine raises — so the two backends are type-identical at the
   * adopter boundary. The one decodable verdict today is
   * `Engine(CommitInProgress)`: a same-engine re-entrant
   * `apply_commands` inside its own commit/notification frame (SPEC
   * §5.1 / E.6 option (a)) surfaces as {@link CommitInProgressError},
   * byte-identical to the TS engine's same-graph re-entrancy throw
   * (`graph.ts` `commitInternal`'s `committing` guard). Any other throw
   * (malformed cmd-buf, wiring bug) rethrows untouched.
   */
  /**
   * #127 — fail loud if this engine's shared wasm instance has been poisoned
   * by a prior trap. The poison is instance-scoped ({@link poisonedBridges}
   * keys on the bridge object), so this fails EVERY engine multiplexed on a
   * poisoned instance, not just the one that trapped. Throws a fresh
   * {@link WasmInstancePoisonedError} with no `cause` (the original trap's
   * `cause` rode on the throw from the engine that trapped).
   */
  #assertInstanceLive(): void {
    if (poisonedBridges.has(this.#bridge)) {
      throw new WasmInstancePoisonedError()
    }
  }

  #applyCommands(
    cmdBuf: Uint8Array,
    // #129 — the engine entry point to drive. Defaults to the live
    // `apply_commands`; `simulate()` passes the `simulate_commands` dry-run
    // extern instead so the ENTIRE verdict-classification path below (trap
    // poisoning, `CommitInProgress` / `CycleClosed` / `ComputeThrew`
    // re-inflation, the host-captured compute-throw identity) is shared
    // verbatim between the live and dry-run pipelines — the engine renders
    // both with the same `apply_commands error:` token family by design
    // (causl/causl-core-rs#320).
    entry: (engine_id: number, cmd_buf: Uint8Array) => Uint8Array = (
      engine_id,
      cmd_buf,
    ) => this.#bridge.apply_commands(engine_id, cmd_buf),
  ): Uint8Array {
    // #127 — refuse to drive a POISONED shared instance. A prior trap left
    // the engine's state undefined; the mirror can no longer be trusted, so
    // every subsequent mutation fails loud rather than corrupt it further.
    this.#assertInstanceLive()
    // causl-client#120 — clear any stale host-captured compute throw before
    // this window so a verdict from THIS `apply_commands` never rethrows a
    // previous commit's error.
    this.#pendingComputeThrow = undefined
    try {
      return entry(this.#engineId, cmdBuf)
    } catch (err) {
      // #127 — a wasm TRAP (a Rust panic aborting via `unreachable`, surfaced
      // as `WebAssembly.RuntimeError`) is NOT a clean §5.2 rejection: wasm32
      // has no unwinding, so the engine's state is undefined and the SHARED
      // instance may be corrupt for every engine multiplexed on it. Poison the
      // instance and throw the typed {@link WasmInstancePoisonedError} (with
      // the trap as `cause`) — BEFORE the CommitInProgress / ComputeThrew
      // re-inflation (a trap is neither) and, critically, so `commit()`'s catch
      // does NOT replay its mirror-rollback journal claiming an atomicity this
      // path cannot honour.
      if (isWasmTrap(err)) {
        this.#pendingComputeThrow = undefined
        poisonedBridges.add(this.#bridge)
        throw new WasmInstancePoisonedError(err)
      }
      // #138 — a clean (non-trap) engine rejection. Capture the raw verdict
      // for the cross-repo golden token pin, then decode it ONCE into a typed
      // discriminant so each arm below switches on structure, not Debug text.
      if (err instanceof Error) lastRawEngineVerdict = err.message
      const verdict = classifyEngineVerdict(err)
      if (verdict === 'commit-in-progress') {
        this.#pendingComputeThrow = undefined
        throw new CommitInProgressError()
      }
      // causl-client#129 (part 2): the engine's own §5.1 Phase-D Kahn drain
      // detected a derivation cycle and rejected the commit with a
      // byte-identical rollback (`Engine(CycleClosed { path })`, causl-wasm
      // `transition/cycle.rs`). Re-inflate the SAME typed {@link CycleError}
      // the TS floor throws so the two backends are type-identical: with the
      // #129 part-2 reduction the TS commit path delegates cycle detection to
      // the backend for a fully-mirrored graph, so THIS is the path a
      // commit-time cycle surfaces on the wasm engine. The PATH is recovered
      // best-effort from the Debug-rendered verdict via the slot->NodeId
      // reverse index; the error TYPE is fixed by the golden-pinned token
      // regardless.
      if (verdict === 'cycle-closed' && err instanceof Error) {
        this.#pendingComputeThrow = undefined
        throw new CycleError(
          parseCycleClosedPath(err.message, this.#slotGenResolver()),
        )
      }
      // causl-client#120 — a derived's `__causl_compute` lambda threw. The
      // compute ran in JS, so `#onCompute` captured the REAL thrown object
      // (normalised to the shared error taxonomy via
      // {@link asDerivedComputeError}) and stashed it in
      // `#pendingComputeThrow` before returning the THREW out-buffer to the
      // engine; only the Display string survived the `Engine(ComputeThrew {
      // reason })` crossing back through Rust. Rethrow the host-captured
      // typed error so the ORIGINAL throw surfaces as `cause` on a
      // `DerivedComputeError` (a user throw) — or as its own `CauslError`
      // (an engine verdict such as `UndeclaredDependencyError`) — identical
      // to the TS floor, WITHOUT losing the JS error identity across the FFI.
      if (verdict === 'compute-threw' && err instanceof Error) {
        const stashed = this.#pendingComputeThrow
        this.#pendingComputeThrow = undefined
        if (stashed !== undefined) throw stashed
        // Fallback (no host-captured throw — e.g. a ComputeThrew minted by
        // the engine itself, not by a user lambda): preserve the historical
        // marker re-inflation so an unresolvable dynamic read still surfaces
        // as the typed `UndeclaredDependencyError`.
        if (err.message.includes(UNDECLARED_DEPENDENCY_MARKER)) {
          const m = err.message.match(
            /derived '([^']*)' read dependency '([^']*)'/,
          )
          throw new UndeclaredDependencyError(
            (m?.[1] ?? '') as NodeId,
            (m?.[2] ?? '') as NodeId,
          )
        }
      }
      this.#pendingComputeThrow = undefined
      throw err
    }
  }

  /**
   * Stage a writes map into the per-(slot, gen) shape `buildCommitCmdBuf`
   * consumes, mirroring the values into `#valueCache` (journaled — the
   * caller's `#cacheJournal` window is already open) and minting the
   * per-(slot, epoch) container change tokens (journaled first-bump-wins
   * into `epochJournal`). Shared verbatim between the live {@link commit}
   * and the {@link simulate} dry-run so the two encode byte-identical
   * cmd-bufs from the same writes.
   */
  #stageWrites(
    writes: ReadonlyMap<NodeId, unknown>,
    epochJournal: Map<NodeId, { ref: unknown; epoch: number } | undefined>,
  ): Map<
    string,
    { slot: number; gen: number; value: unknown; containerMarker?: string }
  > {
    const slotWrites = new Map<
      string,
      { slot: number; gen: number; value: unknown; containerMarker?: string }
    >()
    for (const [id, rawValue] of writes) {
      // #165 — the value domain has no `undefined`: `packInlineValue`
      // already encodes it as the NULL wire record, so the JS mirror must
      // STORE `null` too. Without this, `read` (a `#valueCache` hit,
      // serving the retained `undefined`) and any wire-decoded read
      // (`readAt`, a cache miss) disagree on the same cell — and diverge
      // from the TS floor, whose `tx.set` applies the same collapse. The
      // other non-JSON scalars (bigint / symbol / function) stay retained
      // verbatim: they back the `serializable: false` export contract.
      const value = rawValue === undefined ? null : rawValue
      const entry = this.#slotFor(id, true)
      // SPEC §5.1 Phase B — an INPUT container write cuts off by `Object.is`.
      // Mint a per-(slot, epoch) change token (O(1)) instead of the O(rows)
      // structural content-hash: bump the epoch ONLY when the reference
      // changed, so a same-reference write reuses its token (a no-op) and a
      // new reference gets a distinct token (propagates) — matching
      // causl-ts. Compare the ORIGINAL adopter reference (the same one
      // cached below); tagged-type encoding clones, so comparing the tagged
      // form would spuriously bump every commit.
      let containerMarker: string | undefined
      if (value !== null && typeof value === 'object') {
        const prev = this.#inputEpoch.get(id)
        let epoch: number
        if (prev === undefined || !Object.is(prev.ref, value)) {
          // #72 — journal the pre-commit epoch entry (first-bump-wins)
          // so a rejected commit restores the last COMMITTED cutoff
          // baseline instead of leaving the never-committed reference
          // as the `Object.is` comparand.
          if (!epochJournal.has(id)) epochJournal.set(id, prev)
          epoch = (prev?.epoch ?? 0) + 1
          this.#inputEpoch.set(id, { ref: value, epoch })
        } else {
          epoch = prev.epoch
        }
        containerMarker = inputEpochMarker(entry.slot, epoch)
      }
      slotWrites.set(id, {
        slot: entry.slot,
        gen: entry.gen,
        value,
        ...(containerMarker !== undefined ? { containerMarker } : {}),
      })
      // Cache the committed input value (the original JS reference) BEFORE
      // apply_commands so Phase-D dep resolution and the post-commit
      // read() serve it without a wasm read + JSON.parse. This must happen
      // before apply_commands because __causl_compute fires DURING it.
      this.#cacheSet(id, value)
    }
    return slotWrites
  }

  /**
   * causl-client#129 / causl/causl-core-rs#320 — whether the engine-owned
   * dry-run entry point is available on this artefact. The `graph.simulate`
   * facade gates its reroute on this (plus its own fully-mirrored dynamic
   * guard); a legacy artefact keeps the TS dry-run.
   */
  hasSimulateCommands(): boolean {
    return this.#bridge.simulate_commands !== undefined
  }

  /**
   * causl-client#129 — the {@link InjectedBackend.simulatesDryRunFromRust}
   * capability probe. `true` only under rust-ssot AND with the rebuilt
   * `simulate_commands` extern present; the `graph.ts` facade gates the
   * `graph.simulate` reroute on this (plus its fully-mirrored dynamic
   * guard), keeping the TS dry-run for js-ssot and legacy artefacts.
   */
  simulatesDryRunFromRust(): boolean {
    return this.#engineMode === 'rust-ssot' && this.hasSimulateCommands()
  }

  /**
   * causl-client#129 (write-SSOT cutover) — whether the ENGINE (+ this
   * backend's `#valueCache` mirror) owns the committed input values, so the
   * TS closure can stop publishing staged writes onto its outer input cells
   * (the Phase A-C publication deletion / the AC2 retention drop). `true`
   * only under rust-ssot when EVERY remaining TS-cell consumer has an
   * engine-side (or backend-cache) resolution on this artefact:
   *
   *   - `simulate_commands` (cw#320) — the TS dry-run walk reads live
   *     cells; the reroute replaces it;
   *   - `read_at_result` (cw#170/#198) — historical input reads +
   *     `snapshotAt` resolve from the Rust retention chain;
   *   - `export_model` (cw#170) — the TS `exportModel` fallback reads
   *     cells;
   *   - `node_meta` (cw#170 del-final) — the structural explain reroute
   *     (`explainsTimestampsFromRust`) is armed, so `explain` keeps only
   *     its #83 TS-mirror STAMP reads (`lastWriteTime`, preserved by the
   *     gated Phase C.5) and no VALUE reads.
   *
   * Everything else re-sources from this backend's `#valueCache` (the
   * write-through mirror that also owns `read()` reference identity), which
   * the commit path keeps byte-identical to the TS floor's cell.
   */
  ownsWriteCells(): boolean {
    return (
      this.#engineMode === 'rust-ssot' &&
      this.hasSimulateCommands() &&
      this.hasReadAtResult() &&
      this.hasExportModel() &&
      this.#bridge.node_meta !== undefined
    )
  }

  /**
   * causl-client#129 — build the `graph.simulate` reroute closure over the
   * engine-closure hooks. The BODY lives on the wasm subpath
   * (`./simulate-facade.js`) so the main-bundle `createCausl` cell stays
   * inside its SPEC §14.2.2 budget; `graph.ts` supplies only the small
   * context bag and delegates. Returns `undefined` when this engine cannot
   * own the dry-run (js-ssot, or a legacy artefact without the
   * causl/causl-core-rs#320 extern) — the facade then keeps the TS dry-run.
   */
  buildSimulateReroute(
    ctx: SimulateRerouteContext,
  ): ((intent: string, run: (tx: Tx) => void) => SimulateResult) | undefined {
    if (!this.simulatesDryRunFromRust()) return undefined
    return buildSimulateRerouteImpl(
      ctx,
      (intent, writes) => this.simulate(intent, writes),
      (id) => this.read(id),
    )
  }

  /**
   * causl-client#129 (write-SSOT cutover) — engine-owned DRY-RUN of the
   * commit the same `writes` map would produce, via the
   * causl/causl-core-rs#320 `simulate_commands` extern. Encodes the SAME
   * commit-window cmd-buf {@link commit} encodes (same staging: `undefined`
   * collapse, container change-token minting, `#valueCache` write-through
   * so the Phase-D `__causl_compute` crossings resolve staged dep values
   * cache-first exactly as on the live commit), drives the engine's cloned
   * dry-run pipeline, and returns the decoded prediction.
   *
   * OBSERVER-INVISIBLE BY CONSTRUCTION, on every exit path (success,
   * predicted rejection, wiring error):
   *
   *   - the ENGINE's registry slot is byte-untouched (cw#320: the clone is
   *     discarded; no clock tick, no commit-log row, no retention, zero
   *     Phase-G/H crossings);
   *   - the JS MIRROR rolls back unconditionally: every `#cacheSet` this
   *     call performed (the staging loop AND the dry-run compute crossings)
   *     is replayed from the journal, every container-epoch bump is
   *     restored, and any dynamic-dep rewires the dry-run compute
   *     discovered are DISCARDED (the TS floor's `simulate` rolls back
   *     `deps` the same way);
   *   - `#nextIntentId` is NOT consumed: the dry-run rides the id the NEXT
   *     real commit will use, predicting exactly that commit;
   *   - the `#lastPhaseDTrace` diagnostic is NOT overwritten.
   *
   * @returns the predicted commit time and changed `(slot, gen)`-mapped
   *  NodeIds, in DIFF order (engine Phase-B/D emission order — the same
   *  order {@link commit} would publish for the identical writes).
   * @throws the SAME typed errors the live {@link commit} path throws for
   *  the same rejection (`CommitInProgressError`, `CycleError`, the
   *  host-identity `DerivedComputeError`, `WasmInstancePoisonedError`) —
   *  the facade surfaces them on the `SimulateResult` failed arm.
   */
  simulate(
    intent: string,
    writes: ReadonlyMap<NodeId, unknown>,
  ): { time: GraphTime; changedNodes: readonly NodeId[] } {
    const extern = this.#bridge.simulate_commands
    if (extern === undefined) {
      throw new Error(
        'AuthoritativeWasmEngine.simulate(): the `simulate_commands` extern ' +
          'is absent from this bridge. Callers must gate on ' +
          'hasSimulateCommands().',
      )
    }
    // #72-shape journals, opened for the WHOLE dry-run window and replayed
    // UNCONDITIONALLY in the finally arm (the dry-run promise: the mirror
    // after `simulate` returns is byte-identical to the pre-call moment).
    const parentJournal = this.#cacheJournal
    const cacheJournal = new Map<NodeId, unknown>()
    this.#cacheJournal = cacheJournal
    const epochJournal = new Map<
      NodeId,
      { ref: unknown; epoch: number } | undefined
    >()
    // Dynamic-dep rewires discovered by the dry-run's compute crossings are
    // prediction-internal: the engine state they were derived against is
    // discarded, so draining them would rebind edges against a state the
    // engine never reached. Save the (normally empty) pending set and
    // restore it wholesale.
    const parentRewires = new Map(this.#pendingRewires)
    let diffBuf: Uint8Array
    try {
      const slotWrites = this.#stageWrites(writes, epochJournal)
      // Ride the id the NEXT real commit will use WITHOUT consuming it, so
      // a simulate is invisible to the subsequent commit's wire bytes.
      const cmdBuf = buildCommitCmdBuf(
        this.#nextIntentId,
        slotWrites,
        this.#bridge,
        intent,
        undefined,
      )
      diffBuf = this.#applyCommands(cmdBuf, extern)
    } finally {
      // Unconditional mirror rollback — success and rejection alike. The
      // engine's slot was never mutated (cw#320), so the mirror must roll
      // back on BOTH arms to stay byte-identical to it.
      for (const [id, prev] of cacheJournal) {
        if (prev === ValueHandleCache.MISS) this.#valueCache.delete(id)
        else this.#valueCache.set(id, prev)
      }
      for (const [id, prev] of epochJournal) {
        if (prev === undefined) this.#inputEpoch.delete(id)
        else this.#inputEpoch.set(id, prev)
      }
      this.#pendingRewires.clear()
      for (const [id, deps] of parentRewires) this.#pendingRewires.set(id, deps)
      this.#cacheJournal = parentJournal
    }
    const records = decodeDiff(diffBuf)
    const committed = findCommitted(records)
    const slotToId = this.#slotToIdIndex()
    const changedNodes: NodeId[] = []
    for (const rec of findChangedNodes(records)) {
      const id = slotToId.get(`${rec.slot}:${rec.gen}`)
      // Same #128 fail-loud policy as `commit()`: a predicted changed cell
      // with no registered NodeId can only mean the JS slot index desynced
      // from the engine.
      if (id === undefined) {
        throw new Error(
          `AuthoritativeWasmEngine.simulate(): the engine predicted a ` +
            `changed cell (slot ${rec.slot}, gen ${rec.gen}) with no ` +
            `registered NodeId in the slot:gen index. This can only mean ` +
            `the JS slot index has desynced from the Rust engine; refusing ` +
            `to silently drop it from the prediction.`,
        )
      }
      changedNodes.push(id)
    }
    return {
      time: (committed !== undefined
        ? Number(committed.time)
        : this.#now + 1) as GraphTime,
      changedNodes,
    }
  }

  /**
   * Commit input writes authoritatively through the wasm engine. The
   * wasm-produced diff drives the returned `Commit` (time, changed-set)
   * and Phase-G fires the registered observers of the changed nodes.
   */
  commit(intent: string, writes: ReadonlyMap<NodeId, unknown>): Commit {
    // #72 — open the commit-window mirror journal. The staged input
    // values MUST land in `#valueCache` before `apply_commands` (Phase-D
    // `__causl_compute` resolves dep values from the cache DURING it), so
    // mirror-atomicity is a ROLLBACK on the throw path, not a move-after-
    // success: while the window is open every `#cacheSet` (the staging
    // loop below AND the compute/fire crossings inside `apply_commands`)
    // records the prior entry, and `#inputEpoch` bumps record theirs in
    // `epochJournal`. A nested commit from a notification frame saves and
    // restores the outer journal around its own window.
    const parentJournal = this.#cacheJournal
    const cacheJournal = new Map<NodeId, unknown>()
    this.#cacheJournal = cacheJournal
    // #116 — save the parent in-flight clock (mirroring `#cacheJournal`).
    // A nested commit issued from THIS commit's Phase-G/H frame that the
    // causl-wasm#178 guard rejects must RESTORE the outer window's
    // `#inFlightTime` in its `finally`, not null it — otherwise the outer
    // commit's remaining firings read the settled `#now`, one tick behind
    // the committing tick.
    const parentInFlightTime = this.#inFlightTime
    const epochJournal = new Map<
      NodeId,
      { ref: unknown; epoch: number } | undefined
    >()
    let diffBuf: Uint8Array
    try {
      const slotWrites = this.#stageWrites(writes, epochJournal)

      const intentId = this.#nextIntentId
      this.#nextIntentId += 1
      // promote-commit (causl/causl-core-rs#169) — transmit the adopter's REAL
      // intent STRING into the cmd-buf's `BeginCommit` (interned through the
      // bridge intern table) so the Rust commit-log `intent` matches the
      // adopter's, instead of the synthesised `cmd-intent-{intent_id}`. The
      // numeric `intentId` still rides for the engine's change-token derivation
      // (additive widening). This unblocks promote-read's deferred commitLog
      // routing: the Rust `commit_log` extern now carries the real intent.
      //
      // #129 / causl/causl-core-rs#318 — a hydrate-issued commit additionally
      // rides the snapshot's recorded time in the widened 16-byte
      // `BeginCommit` body, so the ENGINE persists the `originatedAt`
      // breadcrumb on its `CommitRecord` (returned by `commit_log_meta` /
      // `export_model`) and no TS-side time→originatedAt map is needed.
      // Gated on the #318 artefact capability: a legacy decoder rejects the
      // 16-byte body, so on a legacy artefact the legacy 4/8-byte shapes are
      // emitted byte-identically and the map fallback covers the breadcrumb.
      const cmdBuf = buildCommitCmdBuf(
        intentId,
        slotWrites,
        this.#bridge,
        intent,
        this.#persistsOriginatedAt() && intent === 'hydrate'
          ? this.#pendingHydrateOriginatedAt
          : undefined,
      )
      // mux-5 — apply this commit against THIS engine's slot. The compute /
      // fire crossings it triggers carry the same engine_id back (mux-6).
      //
      // cw#182/#184 — stamp the in-flight commit time (§5.1: commits own
      // GraphTime exclusively, so this commit's time is exactly `#now + 1`)
      // for the duration of the window: the Phase-G `__causl_fire` handler
      // and any in-dispatch `subscribe()` initial fire deliver it, matching
      // the TS reference's post-Phase-C `now`. Cleared in the window's
      // `finally` (rejection path included — a rejected commit never fires).
      this.#inFlightTime = (this.#now + 1) as GraphTime
      diffBuf = this.#applyCommands(cmdBuf)
    } catch (err) {
      // #127 — a wasm TRAP poisoned the shared instance mid-mutation. wasm32
      // has no unwinding, so the engine's state is UNDEFINED — NOT the
      // byte-identical §5.2 no-op the journal replay below assumes. Replaying
      // it would falsely assert atomicity AND actively diverge the mirror from
      // the poisoned engine. Rethrow the typed poison untouched; the instance
      // is dead and every subsequent op fails loud, so the never-committed
      // staged mirror values are unreachable rather than silently served.
      if (err instanceof WasmInstancePoisonedError) throw err
      // #72 — the engine rejected the commit and rolled itself back
      // byte-identically (SPEC §5.2 — a rejected commit is a perfect
      // no-op; Phases G/H never fired). Replay the journals so the JS
      // mirror rolls back the same way: restore each touched cache entry
      // to its pre-commit value (deleting entries that did not exist)
      // and each bumped `#inputEpoch` entry to the last COMMITTED
      // baseline. The typed rethrow (`CommitInProgressError` for the
      // causl-wasm#178 re-entrancy verdict) already happened in
      // `#applyCommands`.
      for (const [id, prev] of cacheJournal) {
        if (prev === ValueHandleCache.MISS) this.#valueCache.delete(id)
        else this.#valueCache.set(id, prev)
      }
      for (const [id, prev] of epochJournal) {
        if (prev === undefined) this.#inputEpoch.delete(id)
        else this.#inputEpoch.set(id, prev)
      }
      throw err
    } finally {
      this.#cacheJournal = parentJournal
      // #116 — restore the PARENT in-flight clock (not unconditionally
      // `undefined`): at top level the parent is `undefined` (window
      // closes), but a nested rejected commit from an outer commit's
      // notification frame must leave the outer window's `#now + 1` stamp
      // intact for its remaining Phase-G firings / in-dispatch fires.
      this.#inFlightTime = parentInFlightTime
    }
    // Decode OUTSIDE the rollback scope: `apply_commands` returned, so the
    // engine committed — a (hypothetical) malformed diff buffer must
    // surface as a decode error WITHOUT rolling the mirror back out from
    // under a commit the engine already applied.
    const records = decodeDiff(diffBuf)

    // causl-client#103 — drain the dynamic-dep rewires this commit's Phase-D
    // recompute discovered. This runs AFTER `apply_commands` returned (the
    // commit window is closed; `#cacheJournal` is restored to the parent),
    // so `registerDerived`'s own `apply_commands` is a legal top-level call
    // rather than a re-entrant one. Re-registering rebinds the derived's slot
    // to the widened/rewired edge set so the NEXT commit that touches a newly
    // tracked dep fires it — the two-sided §10.3 rewiring the interim
    // client-side lift provides ahead of the out-buffer tracked-reads
    // discriminant (causl-wasm#217). The stale fn-table binding is dropped so
    // a derived that rewires every commit does not leak fn ids.
    if (this.#pendingRewires.size > 0) {
      const rewires = [...this.#pendingRewires]
      this.#pendingRewires.clear()
      for (const [id, deps] of rewires) {
        const slot = this.#lookupSlot(id)
        if (slot === undefined) continue
        const prev = this.#derivedBySlot.get(slot.slot)
        if (prev === undefined) continue
        this.registerDerived(id, deps, prev.compute, this.#derivedTags.get(id))
        // registerDerived minted a fresh fn id + rebound the slot; retire the
        // superseded fn-table entry (the slot index already points at the new
        // registration).
        if (this.#fnTable.get(prev.fnId) === prev) this.#fnTable.delete(prev.fnId)
      }
    }

    const committed = findCommitted(records)
    if (committed !== undefined) {
      // The wasm clock is the SSOT; advance our mirror to it.
      this.#now = Number(committed.time) as GraphTime
    }

    // Map changed (slot, gen) back to NodeIds for the adopter-facing
    // changed-set and the Phase-G firing. Inputs and deriveds can share a
    // slot integer (disambiguated by gen), so key the reverse index by
    // `slot:gen`.
    const slotToId = this.#slotToIdIndex()
    const changed = findChangedNodes(records)
    const changedNodes: NodeId[] = []
    for (const rec of changed) {
      const id = slotToId.get(`${rec.slot}:${rec.gen}`)
      // #128 — a Rust-reported changed cell whose `(slot, gen)` pair has NO
      // entry in this engine's live `slot:gen` index can ONLY mean the JS
      // slot index has desynced from the Rust engine (every slot the engine
      // can report changed was minted here). Silently dropping it would let a
      // genuine engine-reported change vanish from the adopter-facing Commit
      // with zero signal, masking the desync. Fail LOUD instead — same policy
      // as the container-residency read miss (`read()` above).
      if (id === undefined) {
        throw new Error(
          `AuthoritativeWasmEngine.commit(): the engine reported a changed ` +
            `cell (slot ${rec.slot}, gen ${rec.gen}) with no registered ` +
            `NodeId in the slot:gen index. This can only mean the JS slot ` +
            `index has desynced from the Rust engine; refusing to silently ` +
            `drop it from the commit's changed-set.`,
        )
      }
      changedNodes.push(id)
    }

    // B.8 (#1146) — collect the authoritative Rust Phase-D sextuple
    // trace. Each tag-6 `DerivedRecomputed` record carries the node and
    // every dep as a gen-bearing `(slot, gen)` pair; map each back to a
    // NodeId via the same `slot:gen` index used for the changed-set.
    // Unlike the adopter-facing changed-set (which fails loud on a missing
    // pair, #128), this OPTIONAL diagnostic trace skips any pair absent
    // from the live index: the dep deltas can name transient / rewired
    // edges the recompute discovered, and a dropped trace row is a
    // diagnostics gap, not a lost adopter-visible change. The value columns
    // decode through the canonical 12-byte value-buf decoder, so a NUMBER
    // round-trips its full f64 bits and a container surfaces the cached
    // value (scalar-only for the v1 gate workload).
    const trace: RecomputeAffectedRow[] = []
    for (const rec of findRecomputed(records)) {
      const nodeId = slotToId.get(`${rec.slot}:${rec.gen}`)
      if (nodeId === undefined) continue
      const depsAdded: NodeId[] = []
      for (const d of rec.depsAdded) {
        const depId = slotToId.get(`${d.slot}:${d.gen}`)
        if (depId !== undefined) depsAdded.push(depId)
      }
      const depsRemoved: NodeId[] = []
      for (const d of rec.depsRemoved) {
        const depId = slotToId.get(`${d.slot}:${d.gen}`)
        if (depId !== undefined) depsRemoved.push(depId)
      }
      trace.push({
        stepIndex: rec.stepIndex,
        nodeId,
        valueBefore: this.#materializeTraceValue(nodeId, rec.before),
        valueAfter: this.#materializeTraceValue(nodeId, rec.after),
        depsAdded,
        depsRemoved,
      })
    }
    // causl-wasm#286 — the value-payload-gated tag-10 `DerivedUnchanged`
    // rows are the OTHER half of the Kahn-drain trace: a cutoff-skip /
    // SameValue iteration whose derived value did NOT change and whose dep
    // set did NOT flip. Pre-gating these arrived as tag-6 rows with
    // `value_before == value_after` and empty dep deltas; the engine now
    // drops both value columns and both dep-delta columns to save the wire.
    // Reconstruct the same trace row: the node value is unchanged from what
    // the mirror holds, so materialise before == after from the live cell
    // (the identical code path tag-6 uses for its two value columns), and
    // the dep deltas are empty by construction. Skip any pair absent from
    // the live slot:gen index, matching the tag-6 diagnostic policy.
    for (const rec of findUnchanged(records)) {
      const nodeId = slotToId.get(`${rec.slot}:${rec.gen}`)
      if (nodeId === undefined) continue
      const value = this.#materializeUnchangedTraceValue(nodeId, rec.slot, rec.gen)
      trace.push({
        stepIndex: rec.stepIndex,
        nodeId,
        valueBefore: value,
        valueAfter: value,
        depsAdded: [],
        depsRemoved: [],
      })
    }
    // Restore the single-stream Kahn-drain order the pre-gating tag-6
    // stream carried: `step_index` is a unique 0-based ordinal within this
    // commit's drain, so sorting by it re-interleaves the tag-6 and tag-10
    // rows into their emission order.
    trace.sort((a, b) => a.stepIndex - b.stepIndex)
    this.#lastPhaseDTrace = trace

    // #129 — maintain the published commitLog window cache incrementally.
    // Only when a consumer has materialised it (`!== undefined`): a graph
    // with no commitLog reader pays nothing per commit. Fresh-through the
    // previous tick (commits own GraphTime exclusively, so this commit is
    // exactly `previous + 1`): append the just-accepted row copy-on-write
    // and evict past the threaded cap — byte-identical to the wholesale
    // wire rebuild a stale cache falls back to (the parity gate
    // `wasm-commitlog-ssot-parity-129.test.ts` pins incremental == cold).
    // Stale (a Tick jump, or reads that lapsed): drop the cache so the
    // next read re-decodes the wire.
    if (this.#commitLogWindowCache !== undefined && this.#commitLogCap !== undefined) {
      const cap = this.#commitLogCap
      if (cap === 0) {
        // Retention disabled: the window is permanently the frozen [].
        this.#commitLogWindowFreshAt = this.#now
      } else if (this.#commitLogWindowFreshAt === this.#now - 1) {
        const prev = this.#commitLogWindowCache
        const row = Object.freeze({
          time: this.#now,
          intent,
          changedNodes: Object.freeze(changedNodes.slice()) as readonly NodeId[],
          // The engine persisted the same breadcrumb via the widened
          // BeginCommit body this commit rode (see the encode above).
          originatedAt:
            intent === 'hydrate' && this.#persistsOriginatedAt()
              ? this.#pendingHydrateOriginatedAt
              : undefined,
        }) as Commit
        this.#commitLogWindowCache = Object.freeze(
          prev.length >= cap
            ? [...prev.slice(prev.length - cap + 1), row]
            : [...prev, row],
        ) as readonly Commit[]
        this.#commitLogWindowFreshAt = this.#now
      } else {
        this.#commitLogWindowCache = undefined
      }
    }

    // Phase G — subscriber firing happens inside apply_commands via the
    // __causl_fire import handler (wired in #installHandlers), which fires
    // the registered observers of the changed nodes exactly once. The
    // diff's changed-set drives the adopter-facing Commit.
    return {
      time: this.#now,
      intent,
      changedNodes,
      originatedAt: undefined,
    }
  }

  /**
   * #78 (causl-client) — the {@link InjectedBackend.hydrate} op: apply a
   * snapshot's input writes as ONE `'hydrate'`-labelled commit through
   * the SAME {@link commit} body (cmd-buf → `apply_commands` → diff) —
   * exactly one clock tick, Phase-D recompute, Rust commit-log row,
   * retention row, Phase G/H firing, and the same #178 commit-window
   * rejection surface (typed {@link CommitInProgressError}; a throw
   * means the engine applied NOTHING and the mirror journal rolled
   * back, §5.2).
   *
   * `originatedAt` is the snapshot envelope's recorded time. On a
   * #318-era artefact the Rust pipeline PERSISTS it (#129): `commit`
   * rides it in the widened 16-byte cmd-buf `BeginCommit` body, so the
   * `commit_log_meta` / `export_model` wires return it and every
   * backend-sourced mouth ({@link #onCommit} Phase-H delivery,
   * {@link exportModel}, {@link commitLogWindow}) publishes it straight
   * off the wire — byte-identical to the TS reference, which publishes
   * `originatedAt: snap.time` on hydrate-issued records. On a LEGACY
   * artefact (no `commit_log_meta` extern, so the widened body would be
   * rejected) this backend records the accepted commit's
   * `time → originatedAt` in {@link #hydrateOriginatedAt} and the mouths
   * stamp it from that map, exactly as before #129. The transient
   * {@link #pendingHydrateOriginatedAt} covers the in-flight Phase-H
   * crossing (it fires DURING `apply_commands`, before the map entry
   * exists). One map entry per accepted hydrate — hydrates are
   * boot/persistence-restore events, so growth is negligible.
   */
  hydrate(writes: ReadonlyMap<NodeId, unknown>, originatedAt: GraphTime): Commit {
    // #116 — save the parent breadcrumb (mirroring `commit`'s
    // `#inFlightTime`): a nested rejected `hydrate()` from within the
    // outer hydrate's frame must RESTORE the outer window's
    // `#pendingHydrateOriginatedAt`, not null it, so the outer hydrate's
    // in-flight Phase-H delivery keeps `originatedAt` (§5.3).
    const parentPendingHydrateOriginatedAt = this.#pendingHydrateOriginatedAt
    this.#pendingHydrateOriginatedAt = originatedAt
    try {
      const committed = this.commit('hydrate', writes)
      // #129 — on a #318-era artefact the breadcrumb was persisted
      // ENGINE-side (the widened `BeginCommit` body `commit` emitted), so
      // the map stays empty; on a legacy artefact record it TS-side as
      // before so `#onCommit` / `exportModel` keep publishing it.
      if (!this.#persistsOriginatedAt()) {
        this.#hydrateOriginatedAt.set(committed.time, originatedAt)
      }
      return {
        time: committed.time,
        intent: committed.intent,
        changedNodes: committed.changedNodes,
        originatedAt,
      }
    } finally {
      this.#pendingHydrateOriginatedAt = parentPendingHydrateOriginatedAt
    }
  }

  #slotToIdIndex(): Map<string, NodeId> {
    // #165 — O(1): return the incrementally-maintained reverse index
    // instead of rebuilding it O(N) here (this ran up to four times per
    // commit). `#slots` is never mutated between the callers' reads within
    // a single decode pass, and every caller treats the returned map as
    // read-only (`.get()` only), so handing back the live map is safe.
    return this.#slotToId
  }

  /**
   * Decode a 12-byte value record from a tag-6 row into a materialised JS
   * value for the B.8 trace. Scalars (NUMBER full-f64-bits, BOOL, NULL,
   * STRING_ID) round-trip through the canonical decoder. A container
   * record decodes to {@link CONTENT_HASH_FROM_CACHE} (the engine holds
   * only the structural hash); resolve it from the live value cache by
   * NodeId — the v1 gate workload is scalar-only, so this fallback is
   * never exercised, but it keeps the row materialised rather than
   * leaking the sentinel symbol into the canonical comparison.
   */
  #materializeTraceValue(nodeId: NodeId, record: Uint8Array): unknown {
    const decoded = decodeValueRecord(record, 0, this.#bridge, this.#temporal)
    if (decoded === CONTENT_HASH_FROM_CACHE) {
      const cached = this.#valueCache.get(nodeId)
      return cached === ValueHandleCache.MISS ? undefined : cached
    }
    return decoded
  }

  /**
   * causl-wasm#286 — materialise the before/after value for a tag-10
   * `DerivedUnchanged` row. The lean record carries NO value column (a
   * cutoff-skip did not change the value), so read the derived's CURRENT
   * 12-byte value record from the live cell and run it through the same
   * {@link #materializeTraceValue} decoder the tag-6 value columns use.
   * `value_before == value_after` for a skip, so the caller reuses this
   * single materialisation for both columns.
   */
  #materializeUnchangedTraceValue(
    nodeId: NodeId,
    slot: number,
    gen: number,
  ): unknown {
    // A `DerivedUnchanged` row is always a derived cell (isInput = false).
    const record = this.#bridge.read_cell_value(this.#engineId, slot, gen, false)
    return this.#materializeTraceValue(nodeId, record)
  }

  /**
   * B.8 (#1146) — read the authoritative Rust Phase-D sextuple trace
   * collected during the most recent {@link commit}. Empty until a
   * commit runs Phase D. The cross-bridge gate asserts this is non-empty
   * for a multi-derived workload before comparing it (NodeId-canonical)
   * against the TS-side `collectTsPhaseDTrace` emitter.
   *
   * @internal
   */
  collectRustPhaseDTrace(): readonly RecomputeAffectedRow[] {
    return this.#lastPhaseDTrace
  }

  // ====================================================================
  // Read projection
  // ====================================================================

  /**
   * Read a node's CURRENT value from wasm at full fidelity (inputs and
   * deriveds). Returns the decoded JS value.
   *
   * Serves the cached current value (skipping `read_cell_value` + the
   * O(rows) `JSON.parse`) when present; on a miss decodes from wasm and
   * caches the result so the next read is fast.
   */
  read(id: NodeId): unknown {
    // #127 — a read on a POISONED instance would serve the JS mirror, which
    // has silently diverged from the trap-corrupted engine. Fail loud instead.
    this.#assertInstanceLive()
    const entry = this.#lookupSlot(id)
    if (entry === undefined) {
      throw new Error(
        `AuthoritativeWasmEngine.read(): no node registered for NodeId '${id}'.`,
      )
    }
    const cached = this.#valueCache.get(id)
    if (cached !== ValueHandleCache.MISS) return cached
    // mux-5 — read from THIS engine's cell table (engine_id-first arg).
    const record = this.#bridge.read_cell_value(
      this.#engineId,
      entry.slot,
      entry.gen,
      entry.isInput,
    )
    const value = decodeValueRecord(record, 0, this.#bridge, this.#temporal)
    if (value === CONTENT_HASH_FROM_CACHE) {
      // The engine returned a content-hash record but the value is not in
      // the cache — unrecoverable for a container (the engine holds only
      // the hash). For a live cell this cannot happen (the cache is
      // authoritative + non-evicting for live cells); reaching here means
      // a disposed / never-populated container cell was read.
      throw new Error(
        `AuthoritativeWasmEngine.read(): NodeId '${id}' is a content-hash ` +
          `container cell whose value is absent from the read cache (the ` +
          `engine holds only the structural hash). This indicates a read of ` +
          `a disposed or never-committed container cell.`,
      )
    }
    this.#cacheSet(id, value)
    return value
  }

  /** Whether a NodeId is registered (input or derived). */
  has(id: NodeId): boolean {
    return this.#slots.has(id)
  }

  /** Register an input id so reads resolve before the first commit. */
  registerInput(id: NodeId, initial?: unknown): void {
    const entry = this.#slotFor(id, true)
    if (initial !== undefined) {
      // R1 (causl/causl-client-ts#59) — eager direct-write seed. Emit a SeedInput
      // cmd-buf record that materialises the wasm input cell OUTSIDE any commit
      // window (no clock tick / commit-log row / fire), replacing the deferred
      // `__seed` commit that leaked onto adopter surfaces (epic #53). Mirror
      // `commit()`'s container-epoch minting so the first real user commit's
      // Object.is cutoff has a correct baseline, and cache the original JS
      // reference so a pre-commit `read` (and Phase-D dep resolution during a
      // subsequent Materialize) serves it without a wasm read.
      let containerMarker: string | undefined
      if (initial !== null && typeof initial === 'object') {
        const prev = this.#inputEpoch.get(id)
        const epoch =
          prev === undefined || !Object.is(prev.ref, initial)
            ? (prev?.epoch ?? 0) + 1
            : prev.epoch
        this.#inputEpoch.set(id, { ref: initial, epoch })
        containerMarker = inputEpochMarker(entry.slot, epoch)
      }
      const { kind: k, inline } = packInlineValue(
        initial,
        this.#bridge,
        containerMarker,
      )
      const cmdBuf = encodeSeedInput(entry.slot, entry.gen, k, inline)
      const diffBuf = this.#applyCommands(cmdBuf)
      decodeDiff(diffBuf)
      this.#cacheSet(id, initial)
    } else {
      // No-op: the slot is minted lazily; first commit materialises it.
      void entry
    }
  }

  /**
   * #101 — retire node `id`. Crosses the FFI (emits the cmd-buf `Dispose`
   * record so the Rust engine retires the node) and drops every per-node
   * marshalling entry so the node is fully released host-side:
   *
   *   - `#fnTable` / `#derivedBySlot` — unbinds the disposed derived's compute
   *     lambda so it is never run again (the ghost-recompute leak),
   *   - `#valueCache` / `#inputEpoch` — releases the retained container value
   *     + the input change-token state so neither pins the engine's lifetime,
   *   - `#callbackIds` / `#observers` — drops the Phase-G subscriber bridge
   *     state, `#derivedTags` the explain `via` record,
   *   - `#slots` — so {@link has} reports `false` and the facade read/subscribe
   *     seams fall through to the TS floor's {@link NodeDisposedError}.
   *
   * Idempotent; a no-op for an id this engine does not own. An input and a
   * derived may collide on the raw slot integer (distinct generations), so the
   * `#derivedBySlot` / `#fnTable` teardown is gated on `!entry.isInput` AND an
   * `id` match — disposing the input must not evict the colliding derived.
   *
   * @internal
   */
  disposeNode(id: NodeId): void {
    const entry = this.#slots.get(id)
    if (entry === undefined) return
    // Cross the FFI: retire the node in the Rust engine (op 3 Dispose). The
    // `handle` is this engine's slot for the node; `decodeDiff` surfaces a
    // malformed diff buffer as a coherent error (an empty diff is expected).
    const diffBuf = this.#applyCommands(encodeDispose(entry.slot))
    decodeDiff(diffBuf)
    // Release the compute-lambda binding for a disposed derived. Gated on
    // `!isInput` + `reg.id === id` so an input sharing the slot integer with a
    // derived (same slot, distinct gen) never cross-drops the derived.
    if (!entry.isInput) {
      const reg = this.#derivedBySlot.get(entry.slot)
      if (reg !== undefined && reg.id === id) {
        this.#fnTable.delete(reg.fnId)
        this.#derivedBySlot.delete(entry.slot)
      }
    }
    this.#derivedTags.delete(id)
    this.#valueCache.delete(id)
    this.#inputEpoch.delete(id)
    this.#callbackIds.delete(id)
    this.#observers.delete(id)
    this.#slots.delete(id)
    // #165 — drop this node's reverse `slot:gen -> id` key in lockstep. The
    // key is unique to the disposed entry (see `#slotToId`), so this frees
    // exactly the retired node and never a live sibling's slot.
    this.#slotToId.delete(`${entry.slot}:${entry.gen}`)
  }

  /**
   * R1 (causl/causl-client-ts#59) — run the non-committing Phase-D materialise
   * pass. Emits a `Materialize` cmd-buf op; the bridge runs `recompute_affected`
   * over the eagerly-seeded graph, computing every derived's wasm cell value via
   * the JS compute callback WITHOUT a commit (no clock tick / commit-log row /
   * Phase-G fire). Idempotent on a settled graph (a second call recomputes to
   * the same values). Called by the facade once, lazily, at the first
   * `read`/`subscribe`/`exportModel` so the deriveds + their wasm cells are
   * materialised before any structural read (`exportModel`/`dependencies`)
   * consults them. Replaces the old deferred `__seed` commit flush.
   */
  materialize(): void {
    const cmdBuf = encodeMaterialize()
    const diffBuf = this.#applyCommands(cmdBuf)
    decodeDiff(diffBuf) // surface malformed buffers; the recompute is in-place
  }

  // ====================================================================
  // promote-read (causl/causl-core-rs#169) — read-side STRUCTURAL surface.
  //
  // Each method decodes the corresponding §12 Rust extern buffer into the
  // shape the `graph.ts` facade returns, projecting the wire-level
  // generational `(slot, gen)` handles back onto canonical NodeId strings
  // via the SAME `#slotToIdIndex` used for the commit changed-set. Routed
  // from the facade ONLY under `engineMode === 'rust-ssot'`.
  // ====================================================================

  /**
   * §12.1 — the depth-1 static dependency adjacency of `id` (a derived),
   * decoded from the `dependencies(engine_id, slot, gen)` extern. An input
   * (or an unregistered / disposed id) yields `[]`, matching the facade's
   * `dependenciesOf` for an input. The result is in the encoder's adjacency
   * order; the facade sorts for its diffable projection.
   *
   * @throws if the rebuilt structural extern is absent from the bridge.
   */
  dependencies(id: NodeId): readonly NodeId[] {
    const entry = this.#lookupSlot(id)
    if (entry === undefined) return Object.freeze([])
    const extern = this.#bridge.dependencies
    if (extern === undefined) {
      throw new Error(
        'AuthoritativeWasmEngine.dependencies(): the `dependencies` extern ' +
          'is absent from this bridge (legacy artefact). Rebuild with the §12 ' +
          'structural read surface.',
      )
    }
    const buf = extern(this.#engineId, entry.slot, entry.gen)
    // Return the facade's diffable lex-sorted frozen projection directly, so
    // the `graph.ts` reroute branch is a thin gated delegation (main-bundle
    // byte hygiene — the sort/freeze lives here on the wasm subpath).
    return Object.freeze(decodeNodeIdPairs(buf, this.#slotGenResolver()).sort())
  }

  /**
   * §12.1 — the DEPTH-1 dependents of `id` (the reverse-edge view the facade
   * `dependentsOf` returns), structurally derived from the per-engine dep
   * adjacency.
   *
   * IMPORTANT (ffi-1 note): the Rust `dependents` extern is the TRANSITIVE
   * closure, NOT depth-1; routing it here would over-report. There is no
   * depth-1 `dependents` extern. The depth-1 reverse edge is exactly
   * "every registered derived `d` such that `id ∈ dependencies(d)`", so we
   * resolve it from the depth-1 `dependencies` extern over the engine's live
   * deriveds — every consulted buffer is the Rust-authoritative dep
   * adjacency, so the result is resolved FROM the Rust side (not the TS
   * closure) while matching the facade's depth-1 semantics exactly.
   */
  dependents(id: NodeId): readonly NodeId[] {
    if (!this.#slots.has(id)) return Object.freeze([])
    const extern = this.#bridge.dependencies
    if (extern === undefined) {
      throw new Error(
        'AuthoritativeWasmEngine.dependents(): the `dependencies` extern ' +
          '(used to derive the depth-1 reverse edge) is absent from this ' +
          'bridge (legacy artefact). Rebuild with the §12 structural reads.',
      )
    }
    const resolve = this.#slotGenResolver()
    const out: NodeId[] = []
    // Walk the engine's registered deriveds; a derived whose depth-1 dep set
    // contains `id` is a depth-1 dependent. `#derivedBySlot` holds exactly
    // the live deriveds (registered via `registerDerived`).
    for (const reg of this.#derivedBySlot.values()) {
      const buf = extern(this.#engineId, reg.slot, reg.gen)
      const deps = decodeNodeIdPairs(buf, resolve)
      if (deps.includes(id)) out.push(reg.id)
    }
    // Facade's diffable lex-sorted frozen projection (sort/freeze here, off
    // the main bundle).
    return Object.freeze(out.sort())
  }

  /**
   * lift-explain (causl/causl-core-rs#170) — whether this engine resolves the
   * `explain` lineage TOPOLOGY (node kind + depth-1 deps) from the Rust
   * structural surface. `true` only when `engineMode === 'rust-ssot'` AND the
   * rebuilt `dependencies` extern is present (the same extern `explainNode`
   * decodes). The facade gates the `buildExplanation` topology reroute on this
   * so a legacy artefact keeps the whole walk on the TS closure.
   */
  explainsLineageFromRust(): boolean {
    return (
      this.#engineMode === 'rust-ssot' &&
      typeof this.#bridge.dependencies === 'function'
    )
  }

  /**
   * lift-explain (causl/causl-core-rs#170) — §12.1 the lineage TOPOLOGY of `id`
   * for one frame of the `explain` walk: the structural `kind` (input vs
   * derived, from the per-engine input/derived slot registry) and the depth-1
   * dep adjacency (from the `dependencies` extern — `[]` for an input). Both
   * come from the Rust side, so `buildExplanation`'s tree SHAPE no longer
   * consults the TS `#graph` `entries` map under rust-ssot.
   *
   * An id the engine does not own (unregistered / disposed out from under the
   * walk) returns `undefined`, letting the walker emit the same defensive
   * `cycle` marker the TS closure does (`if (!entry) return cycle`). The deps
   * are returned lex-sorted (the `dependencies` extern already sorts), matching
   * the TS walk's `Array.from(entry.deps).sort()` iteration order.
   *
   * @throws if the rebuilt `dependencies` extern is absent (gated away by
   *  {@link explainsLineageFromRust} on a legacy artefact).
   */
  explainNode(
    id: NodeId,
  ): { readonly kind: 'input' | 'derived'; readonly deps: readonly NodeId[] } | undefined {
    const entry = this.#lookupSlot(id)
    if (entry === undefined) return undefined
    // Inputs have no upstream by construction — match `dependenciesOf`'s
    // `entry.kind === 'input' ⇒ []` short-circuit WITHOUT consulting the
    // extern (an input slot has no dep adjacency record).
    if (entry.isInput) return { kind: 'input', deps: Object.freeze([]) }
    // Derived — depth-1 deps from the `dependencies` extern (already the
    // facade's lex-sorted frozen projection).
    return { kind: 'derived', deps: this.dependencies(id) }
  }

  /**
   * del-final (causl/causl-core-rs#170) — whether this engine resolves the
   * `explain` per-node TIMESTAMPS (`computedAt` / `contributedAt`) and the
   * `via` tag from the Rust `node_meta` extern. `true` only when
   * `engineMode === 'rust-ssot'` AND the rebuilt `node_meta` extern is present.
   * The facade gates the `buildExplanation` timestamp/`via` reroute on this so
   * a legacy artefact (no `node_meta`) keeps them on the TS `entries` map. This
   * is the LAST TS-closure read `explain` carried — with it true, no
   * `buildExplanation` field reads the TS `entries` under rust-ssot.
   */
  explainsTimestampsFromRust(): boolean {
    return (
      this.#engineMode === 'rust-ssot' &&
      typeof this.#bridge.node_meta === 'function'
    )
  }

  /**
   * del-final (causl/causl-core-rs#170) — the per-node EXPLAIN metadata of `id`
   * for one `explain` frame: the structural `kind`, the `computedAt` /
   * `contributedAt` timestamps (from the Rust `node_meta` extern — the input
   * `lastWriteTime` / the derived `lastTime`), and the `via` `tag` (from this
   * backend's registration-time {@link registerDerived} record, which the Rust
   * core does not retain). Composes the Rust-authoritative timestamps with the
   * devtools tag so `buildExplanation` reads NO field off the TS `entries` map.
   *
   * An id the engine no longer owns resolves to `kind: 'missing'` (both
   * timestamps `0`), letting the walker skip it exactly as the TS closure's
   * `if (!childEntry) continue` does.
   *
   * @throws if the rebuilt `node_meta` extern is absent (gated away by
   *  {@link explainsTimestampsFromRust} on a legacy artefact).
   */
  nodeMeta(id: NodeId): DecodedNodeMeta & {
    readonly tag: 'live' | 'commit-metadata' | undefined
  } {
    const extern = this.#bridge.node_meta
    if (extern === undefined) {
      throw new Error(
        'AuthoritativeWasmEngine.nodeMeta(): the `node_meta` extern is ' +
          'absent from this bridge (legacy artefact). Rebuild with the ' +
          'del-final explain-timestamp extern.',
      )
    }
    const slot = this.#lookupSlot(id)
    if (slot === undefined) {
      // Unowned — mirror the Rust MISSING discriminant without a wasm hop.
      return { kind: 'missing', computedAt: 0 as GraphTime, contributedAt: 0 as GraphTime, tag: undefined }
    }
    const decoded = decodeNodeMeta(extern(this.#engineId, slot.slot, slot.gen))
    return { ...decoded, tag: this.#derivedTags.get(id) }
  }

  /**
   * §12.1 — the per-engine commit log (intent / time / changed nodes),
   * oldest-first, decoded from the `commit_log(engine_id)` extern. The
   * facade's `commitLog` derived publishes the most-recent-first `Commit[]`;
   * this returns the wire shape and the facade adapts ordering / `Commit`
   * fields.
   *
   * @throws if the rebuilt structural extern is absent from the bridge.
   */
  commitLog(): readonly DecodedCommitLogRecord[] {
    const extern = this.#bridge.commit_log
    if (extern === undefined) {
      throw new Error(
        'AuthoritativeWasmEngine.commitLog(): the `commit_log` extern is ' +
          'absent from this bridge (legacy artefact). Rebuild with the §12 ' +
          'structural read surface.',
      )
    }
    const buf = extern(this.#engineId)
    // R3 (#54) — drop engine-internal commits (the `'__seed'` flush) from the
    // adopter-facing log, matching js-ssot's TS-closure commit log.
    //
    // #78 note — `DecodedCommitLogRecord` carries NO `originatedAt` (the
    // legacy `commit_log` wire never did). Since #129 the adopter-facing
    // `commitLog` facade re-sources from {@link commitLogWindow} (the #318
    // `commit_log_meta` wire, which DOES carry the persisted breadcrumb)
    // under the ownership gate; this legacy extern remains for js-ssot /
    // legacy-artefact diagnostics.
    return decodeCommitLog(buf, this.#bridge, this.#slotGenResolver()).filter(
      (c) => !isInternalCommitIntent(c.intent),
    )
  }

  /**
   * #129 / causl/causl-core-rs#318 — whether the #318 write-side wire
   * widenings are available on this artefact: the `commit_log_meta` extern,
   * the `SetCommitLogCap` cmd-buf op, and the 16-byte `BeginCommit` body
   * (they shipped together, so the extern's presence probes all three).
   */
  #persistsOriginatedAt(): boolean {
    return this.#bridge.commit_log_meta !== undefined
  }

  /**
   * #129 / causl/causl-core-rs#318 — thread the adopter's `commitHistoryCap`
   * onto the engine's commit-log eviction horizon (`State::commit_log_cap`)
   * via the `SetCommitLogCap` cmd-buf op, replacing the engine's hardcoded
   * `Some(1024)` default. `cap = 0` disables engine-side commit-log
   * retention entirely (matching the facade's cap-0 "no observable
   * history" contract, and freeing the default-cap ring's memory).
   *
   * Called by the `graph.ts` facade ONCE at construction, with the SAME
   * resolved cap that gates Phases F/F.4/F.6, so the engine ring and the
   * adopter-facing `commitLog` window share ONE horizon. No-op on a legacy
   * artefact (the op would be rejected by the old decoder); the facade
   * then keeps the TS ring because {@link ownsCommitLog} stays `false`.
   */
  setCommitHistoryCap(cap: number): void {
    if (!this.#persistsOriginatedAt()) return
    // A cap outside the u32 wire range (or a non-integer) is a SILENT
    // no-op, not a throw: the engine keeps its default horizon and
    // {@link ownsCommitLog} stays false, so the facade's TS ring remains
    // authoritative — fail-safe, and byte-identical to the floor for the
    // (contract-violating) exotic cap. `0xfffffffe` is the top threadable
    // value; `u32::MAX` is the meta wire's UNBOUNDED sentinel.
    if (!Number.isInteger(cap) || cap < 0 || cap > 0xfffffffe) return
    const diffBuf = this.#applyCommands(encodeSetCommitLogCap(cap))
    decodeDiff(diffBuf) // surface malformed buffers; the cap rewrite is in-place
    this.#commitLogCap = cap
  }

  /**
   * #129 — `true` when the ENGINE is the single source of truth for the
   * adopter-facing `commitLog` window: rust-ssot mode, a #318-era artefact
   * (the `commit_log_meta` extern + persisted `originated_at`), AND the
   * adopter's `commitHistoryCap` already threaded onto the engine horizon
   * via {@link setCommitHistoryCap}. The `graph.ts` facade gates the TS
   * Phase-F ring-append deletion and the `commitLog` re-source on this, so
   * a legacy artefact or a js-ssot graph keeps the TS ring byte-identically.
   */
  ownsCommitLog(): boolean {
    return (
      this.#engineMode === 'rust-ssot' &&
      this.#persistsOriginatedAt() &&
      this.#commitLogCap !== undefined
    )
  }

  /**
   * #252 / causl/causl-core-rs#321+#323 — thread the adopter's EFFECTIVE
   * retention window (`commitHistoryCap > 0 ? snapshotRetentionCap : 0`,
   * resolved by the facade) onto the engine's retention-chain eviction
   * horizon (`State::commit_history_cap`, the `SetSnapshotRetentionCap`
   * cmd-buf op), and opt in to derived-row retention (`RetainDerivedRows`)
   * in the SAME atomic batch, replacing the engine's hardcoded 1024
   * default. Called by the `graph.ts` facade ONCE at construction, with
   * the SAME resolved window that gates the TS floor's Phase F.6, so the
   * engine chain and the adopter-facing `readAt` / `snapshotAt` window
   * provably share ONE horizon for inputs AND deriveds.
   *
   * Unlike {@link setCommitHistoryCap} (whose #318 artefact co-shipped the
   * `commit_log_meta` extern probe) the #321/#323 ops shipped with NO new
   * extern, so artefact support is probed by APPLYING the batch: a legacy
   * decoder rejects op 14/15 as `UnknownOp` and the whole batch rolls back
   * atomically — the catch arm leaves {@link ownsRetention} disarmed and
   * the facade keeps the TS floor's retention byte-identically (fail-safe).
   */
  setSnapshotRetentionCap(cap: number): void {
    // A cap outside the u32 wire range (or a non-integer) is a SILENT
    // no-op, mirroring `setCommitHistoryCap`: the engine keeps its default
    // horizon and `ownsRetention` stays false, so the TS floor remains
    // authoritative for the (contract-violating) exotic cap.
    if (!Number.isInteger(cap) || cap < 0 || cap > 0xfffffffe) return
    const batch = new Uint8Array(16)
    batch.set(encodeRetainDerivedRows(true), 0)
    batch.set(encodeSetSnapshotRetentionCap(cap), 8)
    try {
      const diffBuf = this.#applyCommands(batch)
      decodeDiff(diffBuf) // surface malformed buffers; the rewrites are in-place
    } catch {
      // Legacy artefact — the decoder rejected op 14/15 and the batch
      // rolled back whole. Ownership stays disarmed; the facade keeps the
      // TS retention path.
      return
    }
    this.#snapshotRetentionCap = cap
  }

  /**
   * #252 — `true` when the ENGINE is the single source of truth for the
   * `readAt` / `snapshotAt` retention window: rust-ssot mode, the §12.2
   * `read_at_result` extern present, AND the adopter's effective window
   * already threaded (with the derived-row opt-in) via
   * {@link setSnapshotRetentionCap}. The `graph.ts` facade gates the TS
   * Phase-F.6 delta-build deletion and the derived `readAt` reroute on
   * this, so a legacy artefact or a js-ssot graph keeps the TS floor
   * byte-identically.
   */
  ownsRetention(): boolean {
    return (
      this.#engineMode === 'rust-ssot' &&
      this.#snapshotRetentionCap !== undefined &&
      this.hasReadAtResult()
    )
  }

  /**
   * #129 / causl/causl-core-rs#318 — the PUBLISHED adopter-facing
   * commit-log window: frozen `readonly Commit[]`, oldest-first, rows
   * carrying the REAL adopter intent, the commit time, the hydrate-aware
   * `originatedAt` breadcrumb, and the authoritative changed set (inputs
   * + mirrored deriveds). Sourced from the `commit_log_meta(engine_id)`
   * extern, with the {@link #commitLogWindowCache} copy-on-write cache
   * making the per-commit consumer path O(1) amortised (no wire decode).
   * Engine-internal rows (the legacy `'__seed'` flush; eliminated at
   * source by #59, filtered here as defence-in-depth) never surface.
   * Because {@link setCommitHistoryCap} threaded the adopter cap, the
   * window is exactly the rows the TS `commitHistory` ring would have
   * held — the `graph.ts` facade publishes it VERBATIM.
   *
   * @throws if the #318 extern is absent from the bridge (legacy artefact —
   *   callers must gate on {@link ownsCommitLog}).
   */
  commitLogWindow(): readonly Commit[] {
    const extern = this.#bridge.commit_log_meta
    if (extern === undefined) {
      throw new Error(
        'AuthoritativeWasmEngine.commitLogWindow(): the `commit_log_meta` ' +
          'extern is absent from this bridge (legacy artefact). Rebuild ' +
          'with the causl/causl-core-rs#318 commit-log API.',
      )
    }
    // Serve the copy-on-write cache while it is fresh (see the maintenance
    // in {@link commit}) — repeated reads on a quiescent engine are O(1)
    // and referentially stable, and a per-commit consumer never re-decodes
    // the wire.
    if (
      this.#commitLogWindowCache !== undefined &&
      this.#commitLogWindowFreshAt === this.#now
    ) {
      return this.#commitLogWindowCache
    }
    const meta = decodeCommitLogMeta(
      extern(this.#engineId),
      this.#bridge,
      this.#slotGenResolver(),
    )
    const rows = meta.records
      .filter((c) => !isInternalCommitIntent(c.intent))
      .map(
        (row) =>
          // Always-set the optional `originatedAt` slot (#703 Win 5 /
          // #760) so every published row shares the floor's monomorphic
          // hidden class.
          Object.freeze({
            time: row.time as GraphTime,
            intent: row.intent,
            changedNodes: Object.freeze(row.changedNodes) as readonly NodeId[],
            originatedAt: row.originatedAt as GraphTime | undefined,
          }) as Commit,
      )
    this.#commitLogWindowCache = Object.freeze(rows) as readonly Commit[]
    this.#commitLogWindowFreshAt = this.#now
    return this.#commitLogWindowCache
  }

  /**
   * §12.2 — the per-engine telemetry counters, decoded from the
   * `stats(engine_id)` extern. The 7 counters are the subset of
   * `EngineTelemetry` the Rust core tracks; the facade merges them with the
   * TS-closure-only fields (commit observers, entries map size, …).
   *
   * @throws if the rebuilt structural extern is absent from the bridge.
   */
  stats(): DecodedStats {
    const extern = this.#bridge.stats
    if (extern === undefined) {
      throw new Error(
        'AuthoritativeWasmEngine.stats(): the `stats` extern is absent from ' +
          'this bridge (legacy artefact). Rebuild with the §12 structural ' +
          'read surface.',
      )
    }
    return decodeStats(extern(this.#engineId))
  }

  /**
   * lift-export (causl/causl-core-rs#170) — §18A.3 the whole `CauslModel`
   * IR, decoded from the `export_model(engine_id)` extern. RUST-AUTHORITATIVE
   * under rust-ssot: the nodes (+ values + dep adjacency), commit-log (+ the
   * hydrate-aware `originatedAt`), `time`, and the `IRSubscribe` event stream
   * all come from Rust — there is NO wrapped TS `#graph` consult.
   *
   * The `graphId` is supplied by the caller (the `graph.ts` facade's closure
   * `graphId`, sourced from the adopter's `createCausl({ name })`) — a
   * marshaling-layer concern (the adopter's graph name), NOT engine state.
   * It stamps every node / commit / event and synthesises the single default
   * `scopes` entry, byte-identical to the TS `exportModel`.
   *
   * The node VALUE + the `serializable` verdict are the THIN marshaling shim
   * (`JSON.stringify` round-trip) the §18A.3 lift sanctions: it runs over the
   * ENGINE's own value surface ({@link read} — the marshaling value cache
   * holding the original adopter reference, or the decoded Rust value), NOT
   * the `#graph`. A non-serialisable input (function / symbol) was marshaled
   * to Rust as a NULL value record, but the original reference survives in
   * the value cache — so the shim's verdict is `false` and the value `null`,
   * byte-identical to the TS `serialiseSafely` / `isSerializable` pair.
   *
   * @param graphId - The adopter's graph name (the IR foreign key on every
   *   node / commit / event), supplied by the facade.
   * @param opts - Caller-supplied {@link ExportModelOptions}; `maxCommits`
   *   (default 100) bounds the exported commit-log window byte-identically to
   *   the TS floor's `commitHistory.slice(-maxCommits)`. `captureCallGraph`
   *   is accepted but — like the TS floor — not yet emitted (`IRCommit.callGraph`
   *   is reserved).
   * @throws if the rebuilt `export_model` extern is absent from the bridge.
   */
  exportModel(graphId: string, opts?: ExportModelOptions): CauslModel {
    const extern = this.#bridge.export_model
    if (extern === undefined) {
      throw new Error(
        'AuthoritativeWasmEngine.exportModel(): the `export_model` extern is ' +
          'absent from this bridge (legacy artefact). Rebuild with the §18A.3 ' +
          'deep-export read surface.',
      )
    }
    const decoded: DecodedExportModel = decodeExportModel(
      extern(this.#engineId),
      this.#bridge,
      this.#slotGenResolver(),
      this.#temporal,
    )

    // Index the Rust wire cells by NodeId. The wire emits all inputs then all
    // deriveds in slot order, but the TS floor's `exportModel` emits nodes in
    // REGISTRATION order (`entries` Map insertion order, interleaving inputs
    // and deriveds), so we replay `#slots` — which is populated in the SAME
    // registration order via `registerInput` / `registerDerived` — and resolve
    // each node's value / deps from these maps. (#117)
    const inputCells = new Map<NodeId, DecodedExportCell>()
    for (const cell of decoded.inputs) inputCells.set(cell.id, cell)
    const derivedCells = new Map<NodeId, DecodedExportCell>()
    for (const cell of decoded.deriveds) derivedCells.set(cell.id, cell)

    const nodes: IRNode[] = []
    // Walk `#slots` in registration order (input/derived interleaved). The
    // value + `serializable` verdict run over the ENGINE's own value surface
    // (the marshaling value cache / Rust value), NOT the `#graph`.
    for (const [id, entry] of this.#slots) {
      if (entry.isInput) {
        // A never-seeded input (registered with `initial === undefined`) has
        // NO Rust cell — it never emitted a `SeedInput`. It is still a
        // registered node the TS floor exports, so materialise it from the
        // slot registry with its (undefined) value. `#exportValueFor` resolves
        // `undefined` (cache MISS + no decoded value), matching the js-ssot
        // floor's `value: e.value` (undefined) / `serializable: true`. (#117)
        const cell = inputCells.get(id)
        const value = this.#exportValueFor(id, cell?.value)
        const serializable = isExportSerializable(value)
        const node: IRInput = {
          kind: 'input',
          id,
          graphId,
          value: serializable ? value : null,
          serializable,
        }
        nodes.push(node)
      } else {
        // Deriveds — deps are the Rust forward adjacency; the TS exportModel
        // SORTS them (`Array.from(e.deps).sort()`), so mirror that.
        // `conditionalDeps` is always `[]` (the TS exportModel emits `[]`).
        const cell = derivedCells.get(id)
        const value = this.#exportValueFor(id, cell?.value)
        const serializable = isExportSerializable(value)
        const node: IRDerived = {
          kind: 'derived',
          id,
          graphId,
          deps: cell ? [...cell.deps].sort() : [],
          conditionalDeps: [],
          value: serializable ? value : null,
          serializable,
        }
        nodes.push(node)
      }
    }

    // Commits — oldest-first, each carrying the hydrate-aware `originatedAt`
    // (always-set the optional slot to keep the V8 hidden class stable, the
    // #703 Win 5 / #760 discipline the TS in-memory IRCommit row follows).
    // R3 (#54) — exclude engine-internal commits (the `'__seed'` flush) from the
    // exported IR commit log, matching the js-ssot TS-closure exportModel.
    // #78 — hydrate-issued rows decode the wire column as NONE (cmd-buf
    // commits carry no `originated_at`); stamp the snapshot time from the
    // accepted-hydrate map so the exported IR matches the TS reference.
    // #117 — honour the `maxCommits` window (default 100) byte-identically to
    // the TS floor's `commitHistory.slice(-maxCommits)`: filter the
    // engine-internal `__seed` rows FIRST (the TS `commitHistory` never holds
    // them), then keep the most recent `maxCommits` user commits (oldest-first
    // within the window).
    const maxCommits = opts?.maxCommits ?? 100
    const commits: IRCommit[] = decoded.commits
      .filter((c) => !isInternalCommitIntent(c.intent))
      .map((c) => ({
        time: c.time,
        graphId,
        intent: c.intent,
        changedNodes: c.changedNodes,
        originatedAt:
          c.originatedAt ??
          this.#hydrateOriginatedAt.get(c.time as GraphTime),
      }))
      .slice(-maxCommits)

    // Events — the `IRSubscribe` stream in subscribe-call order. The TS
    // exportModel mints a fresh `id` per export (`${graphId}:s.${++seq}`),
    // pins `scopeId` to the default scope, and falls back `callbackSite` to
    // `'<unknown>'` — all marshaling-layer constants, byte-identical here.
    const defaultScopeId = `${graphId}:default`
    let seq = 0
    const events: IREvent[] = decoded.events.map((e) => {
      seq += 1
      return {
        kind: 'subscribe',
        graphId,
        id: `${graphId}:s.${seq}`,
        scopeId: defaultScopeId,
        target: e.target,
        callbackSite: '<unknown>',
        time: e.subscribedAt,
      }
    })

    // Scopes — the single default infinite scope every TS export emits.
    const scopes: IRScope[] = [
      {
        id: `${graphId}:default`,
        kind: 'infinite',
        lifetime: { origin: 'graph-construct', terminator: 'process-exit' },
      },
    ]

    return {
      schema: CAUSL_MODEL_SCHEMA,
      time: decoded.time,
      nodes,
      commits,
      events,
      scopes,
      bridges: [],
    }
  }

  /**
   * lift-export (#170) — whether the rebuilt `export_model` extern is present
   * on this bridge. The facade gates the rust-ssot `exportModel` reroute on
   * this so a legacy artefact (no §18A.3 deep-export extern) falls back to the
   * wrapped TS `#graph` rather than throwing.
   */
  hasExportModel(): boolean {
    return typeof this.#bridge.export_model === 'function'
  }

  /**
   * lift-export (#170) — the {@link InjectedBackend.exportsModelFromRust}
   * capability probe. `true` only under rust-ssot AND with the rebuilt
   * `export_model` extern present, so the `graph.ts` facade reroutes
   * `exportModel` to the Rust deep export (otherwise it keeps it on the TS
   * closure).
   */
  exportsModelFromRust(): boolean {
    return this.#engineMode === 'rust-ssot' && this.hasExportModel()
  }

  /**
   * lift-export (#170) — resolve the EXPORT value for a node: prefer the
   * marshaling value cache (the ORIGINAL adopter reference — load-bearing for
   * the `serializable` verdict on a value that marshaled to Rust as a NULL
   * record, e.g. a function / symbol input, or a container served from the
   * cache rather than its content-hash). Falls back to the decoded Rust value
   * record (a scalar that round-trips exactly). A `CONTENT_HASH` sentinel
   * always resolves through the cache. This is the §18A.3 marshaling
   * boundary — it does NOT consult the wrapped TS `#graph` engine state.
   */
  #exportValueFor(id: NodeId, decodedValue: unknown): unknown {
    const cached = this.#valueCache.get(id)
    if (cached !== ValueHandleCache.MISS) return cached
    // A CONTENT_HASH record with no cache entry is a container whose value
    // the engine holds only as a structural hash — surface `undefined`
    // rather than the sentinel symbol (matching the read-cache miss arm).
    if (decodedValue === CONTENT_HASH_FROM_CACHE) return undefined
    return decodedValue
  }

  /**
   * lift-readat (causl/causl-core-rs#170) — §12.2 the DISCRIMINATED
   * historical read of `id` at GraphTime `time`, decoded from the
   * `read_at_result(engine_id, slot, gen, time)` extern into the exact
   * {@link RetentionResult} shape the TS `readAt(node, t)` returns.
   *
   * The Rust resolver reproduces the TS decision tree — §3 Behavior-domain
   * check (`t < registrationTime`) → retention-window check → genesis-seed
   * fallback → retained value — so the discriminant (`retained` value +
   * `time`, or `evicted` + `oldestRetainedTime`) is byte-identical to the
   * pure-TS oracle. An unregistered id surfaces as `evicted` with
   * `oldestRetainedTime: 0` (the slot was never minted; there is no
   * history to resolve), matching a never-written genesis node.
   *
   * @throws if the rebuilt `read_at_result` extern is absent from the bridge.
   */
  readAt(id: NodeId, time: GraphTime): RetentionResult<unknown> {
    const extern = this.#requireReadAtResult()
    const entry = this.#lookupSlot(id)
    if (entry === undefined) {
      // The slot was never minted on this engine — no history to resolve.
      // Mirrors a never-registered genesis node: outside the domain with
      // the earliest reachable time at 0.
      return { status: 'evicted', oldestRetainedTime: 0 as GraphTime }
    }
    const buf = extern(
      this.#engineId,
      entry.slot,
      entry.gen,
      BigInt(time),
    )
    const result = decodeReadAtResult(buf, this.#bridge, this.#temporal)
    // #100 — a retained CONTAINER input row decodes to the internal
    // CONTENT_HASH_FROM_CACHE sentinel (the engine holds only the structural
    // hash, never a copy of the container). Never hand that sentinel symbol
    // to the adopter where a `T` was promised: recover the value from the
    // host-side cache when the row is still the live one, else fail LOUD with
    // a typed error naming the residency limitation.
    if (result.status === 'retained' && result.value === CONTENT_HASH_FROM_CACHE) {
      const recovered = this.#recoverRetainedContainer(id, entry, buf)
      if (recovered !== undefined) {
        return { status: 'retained', value: recovered.value, time: result.time }
      }
      throw new RetainedValueUnavailableError(id, time)
    }
    return result
  }

  /**
   * #100 — the trailing 12-byte value record of a `read_at_result` buffer
   * begins at offset 12. Resolve the retained container row's per-(slot,
   * epoch) change token back to its marker STRING so
   * {@link #recoverRetainedContainer} can decide whether the retained row is
   * still the live reference. Returns `undefined` for any non-container row
   * (the caller only asks after seeing the sentinel, so this is
   * defence-in-depth).
   *
   * #221/#115 — the authoritative INPUT container path now carries the token
   * INLINE as an `INPUT_EPOCH` record: the packed `(slot, epoch)` payload is
   * the little-endian u64 at record byte 4 (buffer offset 16), and the marker
   * is rebuilt from it with NO intern lookup (nothing was interned). The
   * legacy `CONTENT_HASH` arm (an interned marker `StringId` at the same
   * offset, resolved via `read_interned_string`) is retained for any
   * structural content-hash container row.
   */
  #contentHashRowMarker(buf: Uint8Array): string | undefined {
    if (buf.length < READ_AT_RESULT_RECORD_LEN) return undefined
    const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
    const rowKind = view.getUint8(12)
    if (rowKind === kind.INPUT_EPOCH) {
      return inputEpochMarkerForPacked(view.getBigUint64(16, true))
    }
    if (rowKind === kind.CONTENT_HASH) {
      const strId = view.getUint32(16, true)
      return this.#bridge.read_interned_string(strId >>> 0) ?? undefined
    }
    return undefined
  }

  /**
   * #100 — recover a retained CONTAINER input value the engine stored only as
   * a content-hash marker. The host-side `#valueCache` holds ONLY the CURRENT
   * reference, so a historical row is recoverable iff it is still the live
   * one — detected by comparing the row's per-(slot, epoch) change token
   * (`inputEpochMarker`) to the current epoch's token. On a match the cached
   * container IS the value at that row; on a mismatch (or a missing cache
   * entry) the historical value is genuinely gone. Returns `{ value }` when
   * recoverable, `undefined` otherwise (the caller decides: throw for
   * `readAt`, omit for the `snapshotAt` envelope).
   */
  #recoverRetainedContainer(
    id: NodeId,
    entry: SlotEntry,
    buf: Uint8Array,
  ): { readonly value: unknown } | undefined {
    const rowMarker = this.#contentHashRowMarker(buf)
    const cur = this.#inputEpoch.get(id)
    if (
      rowMarker !== undefined &&
      cur !== undefined &&
      inputEpochMarker(entry.slot, cur.epoch) === rowMarker
    ) {
      const cached = this.#valueCache.get(id)
      if (cached !== ValueHandleCache.MISS) return { value: cached }
    }
    return undefined
  }

  /**
   * lift-readat (causl/causl-core-rs#170) — §12.2 the historical
   * {@link GraphSnapshot} projection at GraphTime `time`, as a
   * {@link RetentionResult}. The retention discriminant (retained vs
   * evicted + `oldestRetainedTime`) is resolved FROM the Rust retention
   * window — byte-identical to the TS `snapshotAt(t)`. The retained arm's
   * envelope is materialised by reading every registered input's value at
   * `time` from the SAME Rust `read_at_result` extern, filtered to
   * JSON-serialisable values (matching the TS `snapshot()` / `snapshotAt()`
   * `isSerializable` gate). `schemaHash` is sourced from `computeSchemaHash`
   * — a structural-identity digest over the registered id-set, NOT a
   * retention concern.
   *
   * The window discriminant is node-INDEPENDENT (the TS `snapshotAt`
   * evicts purely on `t < oldest` / empty-buffer → `now`, with no per-node
   * §3 domain check), so it is read from a genesis-registered input probe
   * (`registered_at == 0`, whose `read_at_result` evicted arm carries the
   * window front exactly). A graph with no inputs has an empty retention
   * window; the probe-less fallback returns `evicted { now }`, matching the
   * TS empty-buffer arm.
   *
   * @throws if the rebuilt `read_at_result` extern is absent from the bridge.
   * @throws {@link RetainedValueUnavailableError} #114 — when a retained
   *  CONTAINER input in the window can no longer be recovered host-side (its
   *  reference has since changed). The envelope fails LOUD rather than
   *  silently omitting the input, symmetric to {@link readAt}'s #100 arm.
   */
  snapshotAt(
    time: GraphTime,
    computeSchemaHash: () => string = () => '',
  ): RetentionResult<GraphSnapshot> {
    const extern = this.#requireReadAtResult()
    // Resolve the node-independent retention-window discriminant via the
    // lowest-slot input probe. Inputs are registered at genesis on the
    // WasmBackend path (`registered_at == 0`), so the probe's `read_at_result`
    // never trips the §3 domain check — its evicted arm carries the window
    // front (the TS `retainedSnapshots[0].time`) exactly.
    const probe = this.#firstInputSlot()
    if (probe === undefined) {
      // No inputs — the TS snapshotAt empty-buffer arm returns
      // `evicted { now }`.
      return { status: 'evicted', oldestRetainedTime: this.#now }
    }
    const probeBuf = extern(this.#engineId, probe.slot, probe.gen, BigInt(time))
    const probeResult = decodeReadAtResult(probeBuf, this.#bridge, this.#temporal)
    if (probeResult.status === 'evicted') {
      return { status: 'evicted', oldestRetainedTime: probeResult.oldestRetainedTime }
    }
    // In-window: materialise every registered input's value at `time`.
    const inputs: Record<NodeId, unknown> = {}
    for (const [nodeId, entry] of this.#slots) {
      if (!entry.isInput) continue
      const buf = extern(this.#engineId, entry.slot, entry.gen, BigInt(time))
      const r = decodeReadAtResult(buf, this.#bridge, this.#temporal)
      if (r.status !== 'retained') continue
      // The §12.2 snapshot envelope carries only JSON-serialisable inputs
      // (the TS `snapshotAt` `isSerializable` gate); the value-pool /
      // intern decoders already produce plain JSON here. #100/#114 — a
      // retained CONTAINER input decodes to the CONTENT_HASH_FROM_CACHE
      // sentinel (the engine holds only its structural hash, never a copy).
      // Arrays/objects ARE serialisable and the js-ssot floor INCLUDES them,
      // so recover the live reference from the host cache and carry the real
      // container (matching the floor's envelope). When the historical
      // container is no longer the live reference it is genuinely gone
      // host-side: fail LOUD with the same typed arm `readAt` uses (#100)
      // rather than SILENTLY OMIT it — a silent drop lost the entire dataset
      // from a `snapshotAt` -> persist -> `hydrate` round-trip with no signal
      // (#114). Never leak the sentinel symbol into the envelope either way.
      if (r.value === CONTENT_HASH_FROM_CACHE) {
        const recovered = this.#recoverRetainedContainer(nodeId, entry, buf)
        if (recovered === undefined) {
          throw new RetainedValueUnavailableError(nodeId, time)
        }
        inputs[nodeId] = recovered.value
        continue
      }
      inputs[nodeId] = r.value
    }
    return {
      status: 'retained',
      time: probeResult.time,
      value: {
        schema: 1,
        time: probeResult.time,
        inputs,
        schemaHash: computeSchemaHash(),
      },
    }
  }

  /**
   * lift-readat (#170) — whether the rebuilt `read_at_result` extern is
   * present on this bridge. The facade gates the rust-ssot readAt /
   * snapshotAt reroute on this so a legacy artefact (no §12.2 discriminated
   * extern) falls back to the wrapped TS `#graph` rather than throwing.
   */
  hasReadAtResult(): boolean {
    return typeof this.#bridge.read_at_result === 'function'
  }

  /**
   * lift-readat (#170) — the {@link InjectedBackend.readsHistoryFromRust}
   * capability probe. `true` only under rust-ssot AND with the rebuilt
   * `read_at_result` extern present, so the `graph.ts` facade reroutes
   * `readAt` / `snapshotAt` to the Rust retention chain (otherwise it keeps
   * the reads on the TS closure). This engine is the actual `injectedBackend`
   * passed to `createCausl({ injectedBackend })`, so the facade calls this
   * method directly.
   */
  readsHistoryFromRust(): boolean {
    return this.#engineMode === 'rust-ssot' && this.hasReadAtResult()
  }

  /**
   * lift-readat (#170) — resolve the `read_at_result` extern or throw the
   * legacy-artefact diagnostic. Shared by {@link readAt} / {@link snapshotAt}.
   */
  #requireReadAtResult(): NonNullable<AuthoritativeBridge['read_at_result']> {
    const extern = this.#bridge.read_at_result
    if (extern === undefined) {
      throw new Error(
        'AuthoritativeWasmEngine.readAt()/snapshotAt(): the `read_at_result` ' +
          'extern is absent from this bridge (legacy artefact). Rebuild with ' +
          'the §12.2 discriminated time-travel read surface.',
      )
    }
    return extern
  }

  /**
   * lift-readat (#170) — the registered input slot with the lowest slot
   * index (the genesis-registered window probe for {@link snapshotAt}), or
   * `undefined` when the engine has no inputs.
   */
  #firstInputSlot(): SlotEntry | undefined {
    let best: SlotEntry | undefined
    for (const entry of this.#slots.values()) {
      if (!entry.isInput) continue
      if (best === undefined || entry.slot < best.slot) best = entry
    }
    return best
  }

  /**
   * Build a `(slot, gen) → NodeId | undefined` resolver over the live slot
   * registry — the structural-decoder counterpart of {@link #slotToIdIndex}
   * (which keys on the `"slot:gen"` string). One Map is built per call; the
   * structural reads are devtools-grade (not on a commit hot path).
   */
  #slotGenResolver(): (slot: number, gen: number) => NodeId | undefined {
    const idx = this.#slotToIdIndex()
    return (slot, gen) => idx.get(`${slot}:${gen}`)
  }

  // ====================================================================
  // Subscriber bridge (Phase G)
  // ====================================================================

  /**
   * Register a JS observer keyed by NodeId. On commit the wasm
   * `__causl_fire` dispatch fires it exactly once when the node changed.
   * Returns an unsubscribe thunk.
   */
  subscribe<T>(id: NodeId, observer: Observer<T>): Unsubscribe {
    let set = this.#observers.get(id)
    if (set === undefined) {
      set = new Set()
      this.#observers.set(id, set)
    }
    set.add(observer as Observer<unknown>)

    // Tell the engine this node has a subscriber so Phase-G fires it.
    const entry = this.#lookupSlot(id)
    if (entry !== undefined) {
      const callbackId = this.#callbackIdFor(id)
      // mux-5 — stamp THIS engine's id into the Subscribe record (route
      // through the shared `encodeSubscribe` encoder) AND apply against this
      // engine's slot, so Phase-G fires under the right `(engine_id, NodeId)`
      // observer set.
      const cmdBuf = encodeSubscribe(
        entry.slot,
        entry.gen,
        this.#engineId,
        callbackId,
      )
      const diffBuf = this.#applyCommands(cmdBuf)
      decodeDiff(diffBuf)

      // R2 (causl-client#57) — synchronous initial fire, mirroring the TS
      // engine (`graph.ts:5868`, `sub.hasFired = true`): deliver the node's
      // CURRENT value once at subscribe time so the subscriber sees the
      // present state, not only future commits. Rust `Action::Subscribe`
      // registers but never fires (`phase_step.rs:708-738`), so without this
      // a rust-ssot subscriber misses its initial notification (the
      // use-deferred-private-causl-setup / use-causl-subscription failures).
      // Backend-owned branch ONLY — the TS-fallback path (explain / commitLog
      // nodes) already gets the TS initial fire, so firing here would
      // double-fire them. The value is materialised: the facade flushes
      // deferred seeds before this `subscribe` runs (the `read`/`subscribe`
      // seams in graph.ts). Wrapped in try/catch so a throwing observer can't
      // abort registration (mirrors the Phase-G `#onFire` discipline).
      // The stamped time is `#liveNow()`: for an IN-DISPATCH registration
      // (a subscribe from inside a Phase-G/H frame — admitted at the wasm
      // boundary since causl-wasm#181) the settled `#now` still holds the
      // PRE-commit time, while the TS reference stamps the notifying
      // commit's own time; the in-flight window time matches it.
      try {
        ;(observer as Observer<unknown>)(this.read(id), this.#liveNow())
      } catch (err) {
        // #152 — a faulty initial-fire observer must not abort subscribe, but
        // the throw is NOT swallowed: route it through the facade's
        // observer-error sink (the `graph.ts` `reportObserverError` hook)
        // stamped `{ source: 'subscribe-initial', nodeId, time }`, byte-
        // identical to the TS floor (`graph.ts` single-node initial fire) so
        // the authoritative engine surfaces initial-fire observer errors the
        // same telemetry the fallback host gets (§5.1 Amendment 5 report-and-
        // continue). The original JS throw is delivered directly here — no
        // Rust round trip — so the adopter sees the real error object, not a
        // reconstructed message copy (this fire runs in JS, outside the
        // `apply_commands` Phase-G channel `#onObserverError` decodes).
        const sink = this.#observerErrorObserver
        if (sink !== undefined) {
          try {
            sink(err, {
              source: 'subscribe-initial',
              nodeId: id,
              time: this.#liveNow(),
            })
          } catch {
            // The error-delivery sink is a side-effect; a throwing facade
            // handler must never abort registration (mirrors `#onObserverError`).
          }
        }
        // Sink unwired (legacy artefact without the observer-error channel):
        // fall through — registration still completes, matching the prior
        // report-and-continue discipline.
      }
    }

    return () => {
      const s = this.#observers.get(id)
      if (s !== undefined) {
        s.delete(observer as Observer<unknown>)
        if (s.size === 0) this.#observers.delete(id)
      }
    }
  }

  #callbackIdFor(id: NodeId): number {
    let cid = this.#callbackIds.get(id)
    if (cid === undefined) {
      cid = this.#nextCallbackId
      this.#nextCallbackId += 1
      this.#callbackIds.set(id, cid)
    }
    return cid
  }

  // ====================================================================
  // Compute / fire handlers (the __causl_compute / __causl_fire imports)
  // ====================================================================

  #installHandlers(): void {
    if (this.#handlersInstalled) return
    // mux-6 — register THIS engine's handlers under its `#engineId` in the
    // sidecar's per-id registry, so two live engines no longer overwrite each
    // other's single global slot. The sidecar dispatches `__causl_compute` /
    // `__causl_fire` to the entry matching the firing's engine_id.
    this.#imports.__causl_set_compute_handler(
      this.#engineId,
      (engineId, fnId, depsBuf) => this.#onCompute(engineId, fnId, depsBuf),
    )
    this.#imports.__causl_set_fire_handler(this.#engineId, (firingsBuf) =>
      this.#onFire(firingsBuf),
    )
    // lift-subscribecommits (causl-wasm#170) — register THIS engine's
    // commit-LEVEL handler under its `#engineId` in the sidecar's per-id
    // registry (mirroring `#onFire`), so two live engines' commit observers
    // never collide. The sidecar crosses `__causl_on_commit` here once per
    // commit (after Phase-G). Guarded: a legacy sidecar without the
    // commit-handler registry leaves the channel unwired (the facade keeps
    // `subscribeCommits` on the wrapped TS closure).
    this.#imports.__causl_set_commit_handler?.(this.#engineId, (engineId, commitBuf) =>
      this.#onCommit(engineId, commitBuf),
    )
    // pre-fire (causl-wasm#189/#190) — register THIS engine's pre-fire
    // handler so the commit's changed set crosses BEFORE the first
    // Phase-G observer byte. The facade's nodeVersion union bump moves
    // here (from the post-`apply_commands` arm) so an observer reading
    // `stats().nodeVersion(node)` from inside a Phase-G/H frame sees the
    // post-bump counter — byte-identical to the TS reference (#1242 runs
    // pre-Phase-G there). Guarded: a legacy sidecar without the pre-fire
    // registry leaves the channel unwired and the facade's post-apply
    // union bump remains the (commit-boundary-correct) fallback.
    this.#imports.__causl_set_pre_fire_handler?.(this.#engineId, (engineId, commitBuf) =>
      this.#onPreFire(engineId, commitBuf),
    )
    // gap-5 (causl-wasm#169; causl-client#102) — register THIS engine's
    // observer-error handler so a throwing Phase-G subscriber (caught +
    // encoded by `#onFire`, then re-delivered by the Rust apply error-hook)
    // reaches the adopter's `onObserverError`, byte-identical to the TS
    // floor. Guarded: a legacy sidecar without the error-handler registry
    // leaves the channel unwired (the facade keeps observer errors on the
    // wrapped TS closure).
    this.#imports.__causl_set_error_handler?.(this.#engineId, (engineId, errBuf) =>
      this.#onObserverError(engineId, errBuf),
    )
    this.#handlersInstalled = true
  }

  /**
   * mux-6 — tear down this engine: remove its compute/fire handlers from the
   * sidecar's per-id registry so a stale dispatch for its `#engineId` is a
   * no-op (returns a THREW out-buffer for compute / drops the firing for
   * fire). Idempotent. Wired into the {@link WasmBackend} teardown.
   *
   * @internal
   */
  dispose(): void {
    if (!this.#handlersInstalled) return
    this.#imports.__causl_remove_compute_handler(this.#engineId)
    this.#imports.__causl_remove_fire_handler(this.#engineId)
    // lift-subscribecommits — drop this engine's commit-level handler so a
    // stale `__causl_on_commit` for its `#engineId` is a no-op. Guarded for
    // the legacy sidecar (no commit-handler registry).
    this.#imports.__causl_remove_commit_handler?.(this.#engineId)
    // pre-fire — drop this engine's pre-fire handler so a stale
    // `__causl_pre_fire` for its `#engineId` is a no-op. Guarded for the
    // legacy sidecar (no pre-fire registry).
    this.#imports.__causl_remove_pre_fire_handler?.(this.#engineId)
    // gap-5 — drop this engine's observer-error handler so a stale
    // `__causl_on_observer_error` for its `#engineId` is a no-op. Guarded
    // for the legacy sidecar (no error-handler registry).
    this.#imports.__causl_remove_error_handler?.(this.#engineId)
    this.#handlersInstalled = false
    // #111 (causl/causl-core-rs#211) — free THIS engine's Rust state on the
    // shared wasm instance. Guarded: a legacy artefact without the per-engine
    // free extern reclaims the slot only at instance teardown; the handler
    // removal above is the dominant reclaimable surface either way.
    this.#bridge.dispose_engine?.(this.#engineId)
    // #111 — drop the JS-side retained caches so even a stale reference to this
    // engine object (outliving the graph) stops pinning the unbounded
    // `#valueCache` / `#fnTable` / `#observers` the leak grew. Safe: every
    // read path guards on `#handlersInstalled` being live via the facade, and
    // a disposed engine is never dispatched to (its sidecar entries are gone).
    this.#valueCache.clear()
    this.#inputEpoch.clear()
    this.#fnTable.clear()
    this.#derivedBySlot.clear()
    this.#observers.clear()
    this.#commitObservers.clear()
    this.#callbackIds.clear()
  }

  /**
   * The `__causl_compute` handler: recompute one derived. `depsBuf` is a
   * value buffer of the dep values in engine `deps` order; returns the
   * §5.4 out-buffer (status byte + value record + read-deps, or status
   * byte + thrown message).
   */
  #onCompute(engineId: number, fnId: number, depsBufView: Uint8Array): Uint8Array {
    // mux-6 — the sidecar dispatched this crossing by engine_id, so the id it
    // passes MUST be ours. A mismatch means the per-id registry misrouted (a
    // wiring bug) — surface it as a THREW out-buffer rather than running the
    // wrong engine's compute body against another engine's fn-table.
    if (engineId !== this.#engineId) {
      return encodeThrew(
        `__causl_compute routed engine_id ${engineId} to engine ` +
          `${this.#engineId} (per-engineId dispatch mismatch)`,
      )
    }
    const registration = this.#fnTable.get(fnId)
    if (registration === undefined) {
      return encodeThrew(`no compute lambda bound for fn_id ${fnId}`)
    }
    // Resolve each dep value: serve the cached current value (skipping the
    // O(rows) read_pool_value + JSON.parse) when present, decoding from
    // the engine-supplied `depsBuf` only on a miss. Every dep is either an
    // input just committed (cached in `commit` before apply_commands) or
    // an upstream derived already recomputed this pass (cached by its own
    // encodeComputeOk below) — so on the hot path every dep hits.
    const depValues = new Map<NodeId, unknown>()
    let depsBuf: Uint8Array | undefined
    for (let i = 0; i < registration.deps.length; i++) {
      const dep = registration.deps[i]!
      const cached = this.#valueCache.get(dep)
      if (cached !== ValueHandleCache.MISS) {
        depValues.set(dep, cached)
        continue
      }
      // MISS — decode this dep from the engine-supplied buffer. CRITICAL:
      // `depsBufView` aliases WASM linear memory; decoding a container dep
      // calls back into the bridge (`read_pool_value`), which can GROW the
      // memory and DETACH this view (length → 0). Copy to a JS-owned
      // buffer the first time we need it.
      if (depsBuf === undefined) depsBuf = depsBufView.slice()
      const off = i * VALUE_BUF_RECORD_LEN
      if (off + VALUE_BUF_RECORD_LEN > depsBuf.length) break
      const decoded = decodeValueRecord(depsBuf, off, this.#bridge, this.#temporal)
      if (decoded === CONTENT_HASH_FROM_CACHE) {
        // A container dep encoded as a content-hash, but its value is not
        // cached. Every container dep is either an input just committed
        // (cached in `commit` before apply_commands) or an upstream
        // derived already recomputed + cached this pass, so a live
        // container dep ALWAYS hits the cache above. Reaching here means
        // the dep's value was never populated — a registration/topology
        // bug, surfaced as a compute throw rather than a silent miss.
        return encodeThrew(
          `derived '${registration.id}' dep '${dep}' is a content-hash ` +
            `container whose value is absent from the read cache`,
        )
      }
      this.#cacheSet(dep, decoded)
      depValues.set(dep, decoded)
    }
    // causl-client#103 — track EVERY read this recompute performs, in
    // first-read order (the §5.1 Amendment-6 dep-set the Phase-D recompute
    // re-captures). A read OUTSIDE the statically-declared set is a
    // legitimate dynamic rewire (§10.3): resolve its value from the live
    // graph rather than throwing, and (below) queue a re-registration of
    // the widened/rewired edge set so subsequent commits fire correctly.
    // The one read that cannot be honoured is a node that is not registered
    // on the graph at all — that surfaces as the typed
    // {@link UndeclaredDependencyError} (engine-independent), not a raw Error.
    const readOrder: NodeId[] = []
    const seen = new Set<NodeId>()
    const get = (dep: NodeId): unknown => {
      if (!seen.has(dep)) {
        seen.add(dep)
        readOrder.push(dep)
      }
      if (depValues.has(dep)) return depValues.get(dep)
      if (this.#lookupSlot(dep) === undefined) {
        throw new UndeclaredDependencyError(registration.id, dep)
      }
      const v = this.read(dep)
      depValues.set(dep, v)
      return v
    }
    let value: unknown
    try {
      value = registration.compute(get)
    } catch (err) {
      // causl-client#120 — the compute lambda ran in JS, so `err` is the
      // REAL thrown object. Normalise it to the shared error taxonomy (a
      // host throw → typed `DerivedComputeError` carrying the original as
      // `cause`; an engine-emitted `CauslError` such as
      // `UndeclaredDependencyError` passes through) and stash it so
      // `#applyCommands` can rethrow the SAME object when the
      // `Engine(ComputeThrew)` verdict crosses back — the JS error identity
      // is preserved across the FFI without a Rust wire change. Only the
      // Display string is what actually crosses to Rust.
      const typed = asDerivedComputeError(registration.id, err)
      this.#pendingComputeThrow = typed
      return encodeThrew(typed.message)
    }
    // If the read-tracked set diverged from the registered dep list, queue a
    // rewire (drained after the commit window closes — re-registering DURING
    // `apply_commands` would re-enter it). Order-sensitive: the wasm bridge
    // maps dep values positionally, so a reorder is also a rewire.
    const rewired =
      readOrder.length !== registration.deps.length ||
      readOrder.some((d, i) => registration.deps[i] !== d)
    if (rewired) this.#pendingRewires.set(registration.id, readOrder.slice())
    // Cache the derived's result (the original JS reference) so the
    // post-commit read() and any downstream dep resolution serve it
    // without a wasm round-trip. encodeComputeOk still mints the wasm
    // value record (the engine remains the SSOT and runs its cutoff).
    this.#cacheSet(registration.id, value)
    // mux-6/mux-4 ABI mirror — echo THIS engine's id into the OK out-buffer
    // (between the status byte and the value record) so the Rust decoder
    // re-qualifies the read-deps to the right engine.
    return encodeComputeOk(this.#engineId, value, this.#bridge)
  }

  /**
   * The `__causl_fire` handler: fire THIS engine's subscriber batch.
   * `firingsBuf` is the §5.5 record stream the mux-6 sidecar already
   * GROUPED to this engine (`count u32 | records…`), each record carrying a
   * leading `engine_id u32` (== `this.#engineId`), then node_slot, node_gen,
   * observer-id, value-record. Fires each registered observer exactly once
   * with the node's new value; returns the mux-4 §5.5 observer-errors buffer
   * (`err_count u32 | engine_id u32 | records…`).
   */
  #onFire(firingsBufView: Uint8Array): Uint8Array {
    // Copy off WASM linear memory first — decoding firing values calls
    // back into the bridge (`read_pool_value` / `read_interned_string`),
    // which can grow + detach a memory-aliased view (see `#onCompute`).
    const firingsBuf = firingsBufView.slice()
    // #139 — parse the batch into its records up front. `decodeFireBatch`
    // throws a typed `StructuralDecodeError` on a MID-BATCH truncation (the
    // old inline `break` silently fired only the prefix that fit and dropped
    // the truncated tail, masking encoder/decoder drift with no signal).
    const records = decodeFireBatch(firingsBuf)
    const slotToId = this.#slotToIdIndex()
    const errors: {
      slot: number
      gen: number
      observer: string
      message: string
    }[] = []

    for (const { nodeSlot, nodeGen, observerId, valueOffset } of records) {
      const id = slotToId.get(`${nodeSlot}:${nodeGen}`)
      if (id === undefined) {
        // #139 — a fired node whose `(slot, gen)` the live slot→id index no
        // longer resolves (disposed / stale-gen) is dropped; count it in
        // debug mode so slot-table drift is observable.
        noteUnresolvedPairDrop()
        continue
      }
      const observerSet = this.#observers.get(id)
      if (observerSet === undefined) continue
      // Serve the fired node's value from the cache (it was just written
      // by the input commit / its compute result), skipping the O(rows)
      // JSON.parse of the firing record. Fall back to decoding the record
      // on a miss.
      let value = this.#valueCache.get(id)
      if (value === ValueHandleCache.MISS) {
        const decoded = decodeValueRecord(
          firingsBuf,
          valueOffset,
          this.#bridge,
          this.#temporal,
        )
        if (decoded === CONTENT_HASH_FROM_CACHE) {
          // A fired container node whose value is not cached — cannot
          // reconstruct from the hash record. For a live cell the value
          // was cached on its commit / compute, so this is unreachable;
          // skip firing with a bad value rather than crash the batch.
          continue
        }
        value = decoded
        this.#cacheSet(id, value)
      }
      // cw#182/#184 — deliver the COMMIT'S time (`#liveNow()`), not the
      // settled `#now`: `__causl_fire` crosses DURING `apply_commands`,
      // before the diff decode advances `#now`, and the TS reference
      // stamps Phase-G observers with the post-Phase-C clock. With the
      // engine clock now commit-owned (§5.1), the in-flight window time
      // IS the commit's time.
      const fireTime = this.#liveNow()
      for (const observer of observerSet) {
        try {
          observer(value, fireTime)
        } catch (err) {
          errors.push({
            slot: nodeSlot,
            gen: nodeGen,
            observer: observerId,
            message: err instanceof Error ? err.message : String(err),
          })
        }
      }
    }

    return encodeObserverErrors(this.#engineId, errors)
  }

  /**
   * lift-subscribecommits (causl-wasm#170) — the `__causl_on_commit`
   * handler: Phase H. The Rust apply path crosses here ONCE per commit,
   * AFTER the Phase-G per-node firing (`#onFire`), carrying the §5.5 commit
   * record (`time | intent | changedNodes | originatedAt`). Decode it into
   * the adopter-facing {@link Commit} shape and fan it out to the registered
   * commit observers in registration order — the exact dispatch the TS
   * `commitObservers` / `phaseH_dispatchCommitObservers` performs.
   *
   * The `engineId` the sidecar passes MUST be ours (it dispatched by
   * engine_id); a mismatch means the per-id registry misrouted (a wiring
   * bug) — skip rather than fire a sibling engine's commit. A throw inside
   * an observer is swallowed (the channel is a post-commit side-effect; the
   * commit already happened), mirroring the Phase-G fire's per-observer
   * try/catch and the sidecar's swallow-on-throw discipline.
   */
  #onCommit(engineId: number, commitBufView: Uint8Array): void {
    if (engineId !== this.#engineId) return
    if (this.#commitObservers.size === 0) return
    // Copy off WASM linear memory first — decoding the intent value record
    // calls back into the bridge (`read_interned_string`), which can grow +
    // detach a memory-aliased view (see `#onFire` / `#onCompute`).
    const commitBuf = commitBufView.slice()
    const decoded = decodeCommitRecord(commitBuf, this.#bridge, this.#slotGenResolver())
    // R3 (#54) — never deliver an engine-internal commit (the `'__seed'`
    // deferred-input-seed flush) to adopter commit observers. js-ssot never
    // surfaces it; filtering here keeps rust-ssot byte-identical.
    if (isInternalCommitIntent(decoded.intent)) return
    // The §5.1 #703/#760 discipline: always set the optional `originatedAt`
    // slot (explicit `undefined` for a live commit) so the published Commit
    // matches the TS engine's monomorphic hidden class byte-for-byte.
    //
    // #78 — a hydrate-issued commit crosses here with the wire column
    // decoding `NONE` (cmd-buf commits carry no `originated_at`); stamp it
    // from the in-flight hydrate breadcrumb so the Phase-H delivery is
    // byte-identical to the TS reference's (`originatedAt: snap.time`).
    // The `intent` guard is defence-in-depth: only `hydrate()` sets the
    // pending slot, and no other same-engine commit can interleave (#178).
    const commit: Commit = {
      time: decoded.time as GraphTime,
      intent: decoded.intent,
      changedNodes: decoded.changedNodes,
      originatedAt:
        decoded.originatedAt !== undefined
          ? (decoded.originatedAt as GraphTime)
          : decoded.intent === 'hydrate'
            ? (this.#pendingHydrateOriginatedAt ??
              this.#hydrateOriginatedAt.get(decoded.time as GraphTime))
            : undefined,
    }
    for (const observer of this.#commitObservers) {
      try {
        observer(commit)
      } catch {
        // The commit-observer fan is a post-commit side-effect (Phase H);
        // a throwing observer must not abort the batch or trap back into the
        // Rust pipeline. Swallow it (the TS engine routes it to
        // reportObserverError; here the throw is dropped — the commit
        // already settled, and the sidecar also swallows a handler throw).
      }
    }
  }

  /**
   * lift-subscribecommits (causl-wasm#170) — register a commit-LEVEL
   * observer (Phase H). On every commit the Rust `__causl_on_commit`
   * crossing fires it exactly once with the just-published {@link Commit},
   * AFTER the per-node Phase-G firing. Mirrors the per-node {@link subscribe}
   * unsubscribe discipline: the returned thunk removes this observer; a
   * removed observer never fires again. Registration order is preserved
   * (insertion-ordered `Set`), so multiple commit observers fan out in the
   * order they were added.
   */
  subscribeCommits(observer: (commit: Commit) => void): Unsubscribe {
    this.#commitObservers.add(observer)
    return () => {
      this.#commitObservers.delete(observer)
    }
  }

  /**
   * lift-subscribecommits (#170) — whether the rebuilt sidecar carries the
   * commit-level handler registry (`__causl_set_commit_handler`). The facade
   * gates the rust-ssot `subscribeCommits` reroute on this so a legacy
   * artefact (no commit channel) falls back to the wrapped TS `#graph`.
   */
  hasCommitChannel(): boolean {
    return typeof this.#imports.__causl_set_commit_handler === 'function'
  }

  /**
   * lift-subscribecommits (#170) — the {@link InjectedBackend.firesCommitsFromRust}
   * capability probe. `true` only under rust-ssot AND with the rebuilt
   * commit-handler registry present, so the `graph.ts` facade reroutes
   * `subscribeCommits` to the Rust Phase-H channel (otherwise it keeps it on
   * the TS closure).
   */
  firesCommitsFromRust(): boolean {
    return this.#engineMode === 'rust-ssot' && this.hasCommitChannel()
  }

  /**
   * pre-fire (causl-wasm#189/#190) — whether this engine delivers the
   * commit's changed set BEFORE the first Phase-G observer byte (the
   * `__causl_pre_fire` crossing; sidecar registry present). When `false`
   * (legacy artefact) the facade's post-`apply_commands` union bump remains
   * the fallback — commit-boundary `nodeVersion` reads stay byte-identical
   * there; only the in-frame corner needs the crossing.
   */
  deliversPreFireChangedSet(): boolean {
    return typeof this.#imports.__causl_set_pre_fire_handler === 'function'
  }

  /**
   * pre-fire (causl-wasm#189/#190) — register the facade's pre-fire
   * changed-set observer (the #71 nodeVersion union-bump hook). Called once
   * at graph construction; the observer fires once per accepted commit,
   * inside `apply_commands`, strictly before any Phase-G/H observer byte,
   * with the commit's authoritative changed-set NodeIds (engine-internal
   * commits filtered, matching the Phase-H delivery discipline).
   */
  onPreFireChangedSet(observer: (changedNodes: readonly NodeId[]) => void): void {
    this.#preFireObserver = observer
  }

  /**
   * The `__causl_pre_fire` handler: decode the pre-fire record (the wire
   * shape is byte-identical to the `__causl_on_commit` Phase-H record) and
   * hand the commit's changed-set NodeIds to the facade observer. Mirrors
   * `#onCommit`'s discipline: engine-id guard, copy off linear memory
   * before decoding (the intent decode calls back into the bridge), and
   * the R3 internal-intent filter (an engine-internal commit must never
   * bump adopter-facing counters — js-ssot never surfaces one). A throw
   * inside the observer is swallowed sidecar-side (#190), but guard here
   * too: the delivery channel must never trap the pipeline.
   */
  #onPreFire(engineId: number, commitBufView: Uint8Array): void {
    if (engineId !== this.#engineId) return
    if (this.#preFireObserver === undefined) return
    const commitBuf = commitBufView.slice()
    const decoded = decodeCommitRecord(commitBuf, this.#bridge, this.#slotGenResolver())
    if (isInternalCommitIntent(decoded.intent)) return
    if (decoded.changedNodes.length === 0) return
    try {
      this.#preFireObserver(decoded.changedNodes)
    } catch {
      // Counter bookkeeping must never abort the commit pipeline; the
      // sidecar swallows too — this is defence-in-depth.
    }
  }

  /**
   * gap-5 (causl-wasm#169; causl-client#102) — register the facade's
   * observer-error sink. Called once at graph construction; the observer
   * fires once per surfaced Phase-G `ObserverError`, delivered by the Rust
   * `__causl_on_observer_error` crossing, with the reconstructed
   * `(error, ctx)` the facade re-fans to the adopter's `onObserverError`.
   * Single slot — the facade is the only consumer.
   */
  onObserverError(
    observer: (error: unknown, ctx: ObserverErrorContext) => void,
  ): void {
    this.#observerErrorObserver = observer
  }

  /**
   * gap-5 (causl-wasm#169; causl-client#102) — the
   * `__causl_on_observer_error` handler. The Rust `apply_commands`
   * error-hook crosses here ONCE per surfaced Phase-G `ObserverError` (the
   * throws `#onFire` caught and returned in the §5.5 observer-errors buffer,
   * re-stamped with the dispatch `engine_id` and routed back out through the
   * hook). `errBuf` is the single-error wire record (`err_count u32 = 1 |
   * engine_id u32 | slot u32 | gen u32 | observer_len u32 | observer |
   * message_len u32 | message`), decoded with the SAME §5.5 layout
   * {@link encodeObserverErrors} writes.
   *
   * The original JS throw cannot survive the Rust round trip (only its
   * message crosses the boundary), so the reconstructed `Error(message)`
   * carries the same message the TS floor reports; the offending NodeId is
   * resolved from the `(slot, gen)` pair via the live slot→id index, and the
   * `time` is the commit's in-flight tick (`#liveNow()`, matching the
   * Phase-G fire stamp and the TS reference's `now`). Mirrors `#onFire`'s
   * discipline: engine-id guard, copy off linear memory before decoding, and
   * a per-delivery try/catch (the sidecar swallows a handler throw too —
   * defence-in-depth so the sink can never trap the commit pipeline).
   */
  #onObserverError(engineId: number, errBufView: Uint8Array): void {
    if (engineId !== this.#engineId) return
    const observer = this.#observerErrorObserver
    if (observer === undefined) return
    // Copy off WASM linear memory first (mirrors `#onFire` / `#onCommit`);
    // the buffer is self-contained (observer + message bytes are inline),
    // but the discipline keeps the decode robust against a detach.
    const errBuf = errBufView.slice()
    if (errBuf.length < 8) return // need err_count u32 + engine_id u32.
    const view = new DataView(errBuf.buffer, errBuf.byteOffset, errBuf.byteLength)
    const count = view.getUint32(0, true)
    // buffer-level engine_id at [4..8] is informational (the sidecar already
    // dispatched this batch to us by engine_id); skip it.
    let pos = 8
    const slotToId = this.#slotToIdIndex()
    const time = this.#liveNow()
    for (let i = 0; i < count; i++) {
      if (pos + 8 > errBuf.length) break
      const slot = view.getUint32(pos, true)
      const gen = view.getUint32(pos + 4, true)
      pos += 8
      if (pos + 4 > errBuf.length) break
      const observerLen = view.getUint32(pos, true)
      pos += 4
      if (pos + observerLen > errBuf.length) break
      // The observer id is carried for symmetry with the encode side; the
      // §12 `ObserverErrorContext` keys provenance on the NodeId, so it is
      // decoded to advance `pos` but not surfaced.
      pos += observerLen
      if (pos + 4 > errBuf.length) break
      const messageLen = view.getUint32(pos, true)
      pos += 4
      if (pos + messageLen > errBuf.length) break
      const message = textDecoder.decode(errBuf.subarray(pos, pos + messageLen))
      pos += messageLen
      const nodeId = slotToId.get(`${slot}:${gen}`)
      // `exactOptionalPropertyTypes`: omit `nodeId` entirely when the
      // `(slot, gen)` pair does not resolve (rather than set it `undefined`),
      // matching the §12 `ObserverErrorContext` optional-key contract.
      const ctx: ObserverErrorContext =
        nodeId === undefined
          ? { source: 'node-subscriber', time }
          : { source: 'node-subscriber', nodeId, time }
      try {
        observer(new Error(message), ctx)
      } catch {
        // The error-delivery sink is a post-commit side-effect; a throwing
        // facade handler must never trap back into the Rust commit pipeline
        // (the commit already settled — Phase G is post-commit). Swallow it;
        // the sidecar swallows too — defence-in-depth.
      }
    }
  }
}

// ======================================================================
// Wire helpers
// ======================================================================

const textEncoder = new TextEncoder()

// mux-5 — the Subscribe record is now encoded via the shared
// `encodeSubscribe(slot, gen, engineId, callbackId)` in `cmd-buf.ts` (stamping
// THIS engine's id), replacing the former local `encodeSubscribeRecord` that
// hardcoded `DEFAULT_ENGINE_ID`.

/** Build a STATUS_THREW compute out-buffer (§5.4). */
function encodeThrew(message: string): Uint8Array {
  const msgBytes = textEncoder.encode(message)
  const out = new Uint8Array(1 + 4 + msgBytes.length)
  const view = new DataView(out.buffer)
  out[0] = STATUS_THREW
  writeU32Checked(
    view,
    1,
    msgBytes.length,
    'STATUS_THREW::message_len',
    'compute-out',
    'compute-out',
  )
  out.set(msgBytes, 5)
  return out
}

/**
 * Build a STATUS_OK compute out-buffer (§5.4, mux-4 layout): status byte +
 * `engine_id u32` (LE) + value record + `read_dep_count u32` (0).
 *
 * The `read_dep_count` slot stays 0 pending the out-buffer tracked-reads
 * discriminant (causl-wasm#217): rather than report the widened dynamic
 * read set to the Rust engine through this slot, the client tracks reads in
 * `#onCompute` and re-registers the rewired edge set after the commit closes
 * (causl-client#103). That interim lift makes conditional-read rewiring
 * §10.3-correct on the wasm path; the slot is filled once the engine
 * consumes it natively.
 *
 * mux-4 ABI mirror (causl-client#42): the `engine_id u32` is inserted
 * IMMEDIATELY AFTER the status byte and BEFORE the 12-byte value record —
 * `status u8(0) | engine_id u32 | value_record(12) | read_dep_count u32`. The
 * echoed `engineId` MUST equal the id `__causl_compute(engineId, …)` was
 * invoked with (the rebuilt Rust `decode_compute_out_ok` reads it to
 * re-qualify read-deps; a wrong / absent id mis-routes them). `STATUS_THREW`
 * is UNCHANGED (see {@link encodeThrew} — no engine_id).
 */
function encodeComputeOk(
  engineId: number,
  value: unknown,
  bridge: ValueBufBridge,
): Uint8Array {
  const valueRecord = encodeValueBuf(value, bridge)
  const out = new Uint8Array(1 + 4 + VALUE_BUF_RECORD_LEN + 4)
  const view = new DataView(out.buffer)
  out[0] = STATUS_OK
  writeU32Checked(view, 1, engineId, 'COMPUTE_OUT::engine_id', 'compute-out')
  out.set(valueRecord, 1 + 4)
  // read_dep_count u32 (0) at offset 1 + 4 + 12 — already zero.
  return out
}

/**
 * Build a §5.5 observer-errors buffer (mux-4 layout):
 * `err_count u32 | engine_id u32 | records…`.
 *
 * mux-4 ABI mirror (causl-client#42): the buffer-level `engine_id u32` is
 * inserted IMMEDIATELY AFTER `err_count` and BEFORE the first record. A fire
 * batch is per-engine, so the throw-attribution tag is buffer-level; the
 * rebuilt Rust `decode_observer_errors` reads `buf[4..8]` for it (and treats
 * a <8-byte buffer as zero errors). The engine RE-STAMPS with the dispatch
 * engine_id, but a faithful encoder writes the engine it ran under.
 */
function encodeObserverErrors(
  engineId: number,
  errors: readonly {
    slot: number
    gen: number
    observer: string
    message: string
  }[],
): Uint8Array {
  const parts: number[] = []
  // `checkU32` names-and-checks the count/length/id against the u32 cap
  // BEFORE the byte-decomposition, so an overflow throws a named
  // WireFieldOverflowError rather than silently wrapping; the `& 0xff` /
  // `>>> N` extraction then provably operates on a checked u32 and is
  // byte-identical for in-range values.
  const pushU32 = (n: number, field: string): void => {
    checkU32(n, field, 'observer-errors', 'observer-errors')
    parts.push(n & 0xff, (n >>> 8) & 0xff, (n >>> 16) & 0xff, (n >>> 24) & 0xff)
  }
  const pushStr = (s: string, field: string): void => {
    const bytes = textEncoder.encode(s)
    pushU32(bytes.length, field)
    for (let i = 0; i < bytes.length; i++) parts.push(bytes[i]!)
  }
  pushU32(errors.length, 'observer-errors::count')
  // mux-4 — buffer-level engine_id, immediately after err_count.
  pushU32(engineId, 'observer-errors::engine_id')
  for (const e of errors) {
    pushU32(e.slot, 'observer-errors::slot')
    pushU32(e.gen, 'observer-errors::gen')
    pushStr(e.observer, 'observer-errors::observer_len')
    pushStr(e.message, 'observer-errors::message_len')
  }
  return Uint8Array.from(parts)
}

/**
 * lift-export (causl/causl-core-rs#170) — the THIN `serializable`-verdict
 * shim the §18A.3 export runs over a Rust-provided node value. A copy of the
 * TS engine's `isSerializable` (`packages/core/src/graph.ts`) — JSON-safe
 * primitives pass, functions / symbols fail, everything else is probed with
 * a `JSON.stringify` round-trip (cycles / BigInt fail). This is the
 * marshaling boundary the lift sanctions as a thin TS shim: it operates on
 * VALUES (the engine's marshaling value surface), NOT engine state.
 */
function isExportSerializable(value: unknown): boolean {
  if (value === null || value === undefined) return true
  const t = typeof value
  if (t === 'number' || t === 'string' || t === 'boolean') return true
  if (t === 'function' || t === 'symbol') return false
  try {
    JSON.stringify(value)
    return true
  } catch {
    return false
  }
}

// Re-export the value-kind constants so callers can branch on them.
export { kind }
